[110001] = {id = 110001, name = "Julius", head = "10001", type = 5, title = "Appreciation\u{0020}for\u{0020}Your\u{0020}Guidance", txt = "By\u{0020}the\u{0020}time\u{0020}you\u{0020}read\u{0020}this\u{0020}email,\u{0020}I\u{0020}should\u{0020}have\u{0020}already\u{0020}left\u{0020}the\u{0020}branch.\nOh,\u{0020}it's\u{0020}not\u{0020}a\u{0020}transfer\u{0020}or\u{0020}a\u{0020}mission...\u{0020}I\u{0020}just\u{0020}took\u{0020}a\u{0020}half-day\u{0020}off\u{0020}to\u{0020}visit\u{0020}my\u{0020}mother.\nI\u{0020}didn't\u{0020}tell\u{0020}Charlissa\u{0020}or\u{0020}the\u{0020}others\u{0020}about\u{0020}it.\u{0020}It\u{0020}didn't\u{0020}seem\u{0020}necessary,\u{0020}as\u{0020}it's\u{0020}only\u{0020}a\u{0020}short\u{0020}leave,\u{0020}and\u{0020}I\u{0020}won't\u{0020}be\u{0020}gone\u{0020}long.\u{0020}But\u{0020}if\u{0020}they\u{0020}happen\u{0020}to\u{0020}find\u{0020}out\u{0020}and\u{0020}even\u{0020}come\u{0020}to\u{0020}you,\u{0020}Navigator,\u{0020}please\u{0020}apologize\u{0020}on\u{0020}my\u{0020}behalf.\u{0020}I\u{0020}will\u{0020}bring\u{0020}back\u{0020}gifts.\u{0020}Of\u{0020}course,\u{0020}one\u{0020}for\u{0020}you\u{0020}as\u{0020}well.\u{0020}Please\u{0020}don't\u{0020}rush\u{0020}to\u{0020}refuse.\u{0020}Who\u{0020}says\u{0020}the\u{0020}birthday\u{0020}girl\u{0020}can\u{0020}only\u{0020}receive\u{0020}gifts\u{0020}and\u{0020}not\u{0020}give\u{0020}them,\u{0020}right?\u{0020}Besides,\u{0020}this\u{0020}is\u{0020}just\u{0020}my\u{0020}small\u{0020}gesture\u{0020}of\u{0020}appreciation.\nIn\u{0020}the\u{0020}coming\u{0020}year,\u{0020}I\u{0020}look\u{0020}forward\u{0020}to\u{0020}working\u{0020}with\u{0020}you,\u{0020}Navigator.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
