[11000201] = {id = 11000201, name = "Hanke", head = "10002", type = 5, title = "Be\u{0020}at\u{0020}Your\u{0020}Door\u{0020}in\u{0020}5!", txt = "Hey\u{0020}Navigator!\u{0020}You\u{0020}know\u{0020}what\u{0020}day\u{0020}it\u{0020}is?\u{0020}The\u{0020}day\u{0020}I'm\u{0020}feeling\u{0020}generous\u{0020}and\u{0020}planning\u{0020}on\u{0020}treating\u{0020}everyone\u{0020}to\u{0020}whatever\u{0020}they\u{0020}want.\u{0020}No\u{0020}way\u{0020}you'd\u{0020}miss\u{0020}this,\u{0020}right?\nNone\u{0020}of\u{0020}that\u{0020}mushy,\u{0020}sugar-loaded\u{0020}cake\u{0020}nonsense.\u{0020}I'm\u{0020}talking\u{0020}booze,\u{0020}meat,\u{0020}and\u{0020}zero\u{0020}self-control!\u{0020}Don't\u{0020}care\u{0020}about\u{0020}the\u{0020}cost,\u{0020}don't\u{0020}care\u{0020}about\u{0020}the\u{0020}hangover.\u{0020}This\u{0020}is\u{0020}exactly\u{0020}what\u{0020}I\u{0020}saved\u{0020}up\u{0020}all\u{0020}those\u{0020}mercenary\u{0020}paychecks\u{0020}for.\nNot\u{0020}one\u{0020}for\u{0020}long\u{0020}emails\u{0020}(and\u{0020}neither\u{0020}are\u{0020}you),\u{0020}so\u{0020}I'll\u{0020}cut\u{0020}this\u{0020}short:\u{0020}I'm\u{0020}coming\u{0020}to\u{0020}drag\u{0020}you\u{0020}out\u{0020}for\u{0020}the\u{0020}real\u{0020}celebration.\u{0020}Be\u{0020}at\u{0020}your\u{0020}door\u{0020}in\u{0020}5!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000202] = {id = 11000202, name = "Hanke", head = "10002", type = 5, title = "This\u{0020}Is\u{0020}Bad,\u{0020}This\u{0020}Is\u{0020}Really\u{0020}Bad!", txt = "This\u{0020}is\u{0020}bad.\u{0020}This\u{0020}is\u{0020}really\u{0020}bad.\u{0020}There\u{0020}probably\u{0020}is\u{0020}not\u{0020}anything\u{0020}worse\u{0020}than\u{0020}this!\nIs\u{0020}today\u{0020}not\u{0020}my\u{0020}birthday?\u{0020}So\u{0020}I\u{0020}was\u{0020}planning\u{0020}to\u{0020}drink\u{0020}with\u{0020}you\u{0020}all\u{0020}the\u{0020}way\u{0020}until\u{0020}dawn\u{0020}tomorrow...\u{0020}That\u{0020}was\u{0020}what\u{0020}I\u{0020}had\u{0020}in\u{0020}mind!\nBut\u{0020}when\u{0020}I\u{0020}opened\u{0020}the\u{0020}fridge\u{0020}just\u{0020}now,\u{0020}it\u{0020}was\u{0020}completely\u{0020}empty.\u{0020}It\u{0020}was\u{0020}even\u{0020}emptier\u{0020}than\u{0020}my\u{0020}wallet\u{0020}before\u{0020}payday--\u{0020}though\u{0020}we\u{0020}use\u{0020}electronic\u{0020}currency,\u{0020}of\u{0020}course.\nThere\u{0020}was\u{0020}not\u{0020}even\u{0020}a\u{0020}single\u{0020}can\u{0020}of\u{0020}alcohol\u{0020}in\u{0020}the\u{0020}fridge.\u{0020}I\u{0020}got\u{0020}so\u{0020}mad\u{0020}that\u{0020}I\u{0020}almost\u{0020}split\u{0020}it\u{0020}in\u{0020}half...\u{0020}Anyway,\u{0020}before\u{0020}today\u{0020}is\u{0020}over,\u{0020}let\u{0020}us\u{0020}go\u{0020}clean\u{0020}out\u{0020}the\u{0020}bar's\u{0020}entire\u{0020}stock.\nWe\u{0020}absolutely\u{0020}cannot\u{0020}let\u{0020}this\u{0020}once-a-year\u{0020}day\u{0020}be\u{0020}missing\u{0020}the\u{0020}scent\u{0020}of\u{0020}alcohol!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110003] = {id = 110003, name = "Morimura\u{0020}Kinosuke", head = "10003", type = 5, title = "I\u{0020}Don't\u{0020}Like\u{0020}Birthdays", txt = "生日……我對這種用來哄小孩的事情不感興趣。\n你應該是了解我的，我不想把時間浪費這種無意義的事情上。\n……本來是這麼想的。\n但不知火說和親近的人過生日可以鍛煉精神——無論怎麼聽都像是在哄人——總之，我來找你，你老實待在房間裡，我馬上就到。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000301] = {id = 11000301, name = "Morimura\u{0020}Kinosuke", head = "10003", type = 5, title = "I\u{0020}Don't\u{0020}Like\u{0020}Birthdays", txt = "Birthdays...\u{0020}I'm\u{0020}not\u{0020}one\u{0020}for\u{0020}these\u{0020}childish\u{0020}celebrations.\nYou\u{0020}know\u{0020}me\u{0020}well\u{0020}enough\u{0020}by\u{0020}now.\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}waste\u{0020}my\u{0020}time\u{0020}on\u{0020}something\u{0020}so\u{0020}pointless.\n...That's\u{0020}how\u{0020}I've\u{0020}always\u{0020}felt.\nBut\u{0020}then\u{0020}Shiranui\u{0020}mentioned\u{0020}that\u{0020}celebrating\u{0020}with\u{0020}close\u{0020}friends\u{0020}is\u{0020}supposed\u{0020}to\u{0020}strengthen\u{0020}the\u{0020}spirit—sounds\u{0020}like\u{0020}a\u{0020}load\u{0020}of\u{0020}nonsense\u{0020}to\u{0020}me.\u{0020}Still,\u{0020}here\u{0020}I\u{0020}am.\u{0020}Stay\u{0020}in\u{0020}your\u{0020}room,\u{0020}and\u{0020}I'll\u{0020}be\u{0020}there\u{0020}shortly.\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000302] = {id = 11000302, name = "Morimura\u{0020}Kinosuke", head = "10003", type = 5, title = "A\u{0020}Nightmare\u{0020}on\u{0020}My\u{0020}Birthday", txt = "Navigator,\u{0020}Captain\u{0020}and\u{0020}the\u{0020}others\u{0020}didn't\u{0020}bother\u{0020}you,\u{0020}did\u{0020}they?\u{0020}Or...\u{0020}did\u{0020}they\u{0020}already\u{0020}tell\u{0020}you\u{0020}about\u{0020}me?\u{0020}\nAnyway,\u{0020}early\u{0020}this\u{0020}morning\u{0020}they\u{0020}were\u{0020}knocking\u{0020}on\u{0020}my\u{0020}door,\u{0020}saying\u{0020}they\u{0020}wanted\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday...\u{0020}\nBut\u{0020}I\u{0020}didn't\u{0020}open\u{0020}the\u{0020}door\u{0020}for\u{0020}them.\u{0020}I\u{0020}didn't\u{0020}meet\u{0020}them,\u{0020}didn't\u{0020}even\u{0020}talk\u{0020}to\u{0020}them.\u{0020}\nThey'd\u{0020}never\u{0020}guess\u{0020}the\u{0020}reason\u{0020}is\u{0020}just\u{0020}because\u{0020}I\u{0020}had\u{0020}a\u{0020}nightmare...\u{0020}a\u{0020}bad\u{0020}nightmare...\u{0020}\nEven\u{0020}with\u{0020}friends\u{0020}you're\u{0020}close\u{0020}to,\u{0020}there\u{0020}are\u{0020}still\u{0020}things\u{0020}you\u{0020}can't\u{0020}say.\u{0020}\nYou\u{0020}were\u{0020}in\u{0020}that\u{0020}nightmare\u{0020}too,\u{0020}so...\u{0020}so...\u{0020}anyway...\u{0020}I\u{0020}was\u{0020}hoping\u{0020}you\u{0020}could\u{0020}talk\u{0020}to\u{0020}me\u{0020}a\u{0020}bit\u{0020}about\u{0020}the\u{0020}relationship\u{0020}between\u{0020}dreams\u{0020}and\u{0020}reality,\u{0020}or\u{0020}something\u{0020}like\u{0020}that...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110004] = {id = 110004, name = "D-b2", head = "10004", type = 5, title = "Her\u{0020}Birthday", txt = "Startup\u{0020}confirmed.\u{0020}Authentication\u{0020}initiated...\u{0020}Startup\u{0020}complete.\nGreetings,\u{0020}Navigator.\nMy\u{0020}database\u{0020}shows\u{0020}a\u{0020}human's\u{0020}birthday\u{0020}holds\u{0020}significant\u{0020}meaning\u{0020}for\u{0020}that\u{0020}individual.\nAs\u{0020}a\u{0020}mass-produced\u{0020}unit,\u{0020}I\u{0020}guess\u{0020}my\u{0020}production\u{0020}date\u{0020}could\u{0020}be\u{0020}considered\u{0020}my\u{0020}birthday.\u{0020}I\u{0020}could\u{0020}even\u{0020}track\u{0020}it\u{0020}down\u{0020}to\u{0020}the\u{0020}exact\u{0020}second,\u{0020}even\u{0020}further\u{0020}corrected\u{0020}based\u{0020}on\u{0020}the\u{0020}Earth's\u{0020}rotation.\nBut\u{0020}I\u{0020}would\u{0020}rather\u{0020}treat\u{0020}this\u{0020}day\u{0020}as\u{0020}my\u{0020}birthday.\u{0020}Even\u{0020}if\u{0020}that\u{0020}girl's\u{0020}soul\u{0020}has\u{0020}long\u{0020}since\u{0020}faded,\u{0020}leaving\u{0020}behind\u{0020}only\u{0020}what\u{0020}remains:\u{0020}an\u{0020}empty\u{0020}shell\u{0020}called\u{0020}D-b2.\nToday\u{0020}is\u{0020}her\u{0020}birthday.\u{0020}I'd\u{0020}like\u{0020}to\u{0020}invite\u{0020}you\u{0020}to\u{0020}celebrate\u{0020}it\u{0020}with\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110005] = {id = 110005, name = "Hualian", head = "10005", type = 5, title = "100\u{0020}Kicks\u{0020}Filled\u{0020}with\u{0020}Love\u{0020}Every\u{0020}Day", txt = "Lately,\u{0020}I've\u{0020}been\u{0020}completely\u{0020}lost\u{0020}in\u{0020}the\u{0020}world\u{0020}of\u{0020}martial\u{0020}arts\u{0020}books.\u{0020}It\u{0020}wasn't\u{0020}until\u{0020}Sister\u{0020}Huameng\u{0020}reminded\u{0020}me\u{0020}that\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday\u{0020}that\u{0020}I\u{0020}realized\u{0020}how\u{0020}much\u{0020}time\u{0020}I've\u{0020}wasted\u{0020}neglecting\u{0020}my\u{0020}training.\nBut\u{0020}as\u{0020}they\u{0020}say,\u{0020}\"It's\u{0020}never\u{0020}too\u{0020}late\u{0020}to\u{0020}make\u{0020}up\u{0020}for\u{0020}lost\u{0020}time,\"\u{0020}so\u{0020}I've\u{0020}decided\u{0020}to\u{0020}start\u{0020}a\u{0020}new\u{0020}daily\u{0020}routine!\u{0020}From\u{0020}now\u{0020}on,\u{0020}I'll\u{0020}greet\u{0020}each\u{0020}new\u{0020}day\u{0020}with\u{0020}100\u{0020}kicks\u{0020}filled\u{0020}with\u{0020}love—love\u{0020}for\u{0020}nature,\u{0020}love\u{0020}for\u{0020}martial\u{0020}arts,\u{0020}and,\u{0020}of\u{0020}course,\u{0020}love\u{0020}for\u{0020}you,\u{0020}Navigator.\u{0020}Yes,\u{0020}that's\u{0020}right.\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}oversee\u{0020}my\u{0020}training\u{0020}as\u{0020}I\u{0020}complete\u{0020}my\u{0020}daily\u{0020}100\u{0020}kicks,\u{0020}and\u{0020}when\u{0020}you're\u{0020}ready,\u{0020}I'll\u{0020}deliver\u{0020}my\u{0020}full-strength\u{0020}strike\u{0020}to\u{0020}you.\nThis\u{0020}is\u{0020}my\u{0020}birthday\u{0020}wish.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000501] = {id = 11000501, name = "Hualian", head = "10005", type = 5, title = "100\u{0020}Kicks\u{0020}Filled\u{0020}with\u{0020}Love\u{0020}Every\u{0020}Day", txt = "Lately,\u{0020}I've\u{0020}been\u{0020}completely\u{0020}lost\u{0020}in\u{0020}the\u{0020}world\u{0020}of\u{0020}martial\u{0020}arts\u{0020}books.\u{0020}It\u{0020}wasn't\u{0020}until\u{0020}Sister\u{0020}Huameng\u{0020}reminded\u{0020}me\u{0020}that\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday\u{0020}that\u{0020}I\u{0020}realized\u{0020}how\u{0020}much\u{0020}time\u{0020}I've\u{0020}wasted\u{0020}neglecting\u{0020}my\u{0020}training.\nBut\u{0020}as\u{0020}they\u{0020}say,\u{0020}\"It's\u{0020}never\u{0020}too\u{0020}late\u{0020}to\u{0020}make\u{0020}up\u{0020}for\u{0020}lost\u{0020}time,\"\u{0020}so\u{0020}I've\u{0020}decided\u{0020}to\u{0020}start\u{0020}a\u{0020}new\u{0020}daily\u{0020}routine!\u{0020}From\u{0020}now\u{0020}on,\u{0020}I'll\u{0020}greet\u{0020}each\u{0020}new\u{0020}day\u{0020}with\u{0020}100\u{0020}kicks\u{0020}filled\u{0020}with\u{0020}love—love\u{0020}for\u{0020}nature,\u{0020}love\u{0020}for\u{0020}martial\u{0020}arts,\u{0020}and,\u{0020}of\u{0020}course,\u{0020}love\u{0020}for\u{0020}you,\u{0020}Navigator.\u{0020}Yes,\u{0020}that's\u{0020}right.\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}oversee\u{0020}my\u{0020}training\u{0020}as\u{0020}I\u{0020}complete\u{0020}my\u{0020}daily\u{0020}100\u{0020}kicks,\u{0020}and\u{0020}when\u{0020}you're\u{0020}ready,\u{0020}I'll\u{0020}deliver\u{0020}my\u{0020}full-strength\u{0020}strike\u{0020}to\u{0020}you.\nThis\u{0020}is\u{0020}my\u{0020}birthday\u{0020}wish.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000502] = {id = 11000502, name = "Hualian", head = "10005", type = 5, title = "On\u{0020}Your\u{0020}Birthday,\u{0020}You\u{0020}Should\u{0020}Be\u{0020}Extra\u{0020}Vigilant", txt = "Another\u{0020}year\u{0020}has\u{0020}passed\u{0020}in\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye.\u{0020}The\u{0020}memories\u{0020}of\u{0020}last\u{0020}year's\u{0020}birthday\u{0020}celebration\u{0020}still\u{0020}linger\u{0020}in\u{0020}my\u{0020}mind,\u{0020}and\u{0020}now\u{0020}a\u{0020}new\u{0020}birthday\u{0020}has\u{0020}arrived.\nBirthdays\u{0020}are\u{0020}joyous\u{0020}occasions,\u{0020}but\u{0020}hidden\u{0020}within\u{0020}the\u{0020}joy\u{0020}lies\u{0020}potential\u{0020}danger.\u{0020}From\u{0020}what\u{0020}I\u{0020}know,\u{0020}extraordinary\u{0020}events\u{0020}often\u{0020}occur\u{0020}at\u{0020}birthday\u{0020}parties.\nA\u{0020}disciple's\u{0020}sworn\u{0020}enemy\u{0020}might\u{0020}come\u{0020}seeking\u{0020}revenge;\u{0020}a\u{0020}knight\u{0020}riding\u{0020}a\u{0020}divine\u{0020}eagle\u{0020}might\u{0020}present\u{0020}three\u{0020}grand\u{0020}gifts;\u{0020}or\u{0020}someone\u{0020}might\u{0020}visit\u{0020}under\u{0020}the\u{0020}guise\u{0020}of\u{0020}offering\u{0020}birthday\u{0020}wishes,\u{0020}only\u{0020}to\u{0020}challenge\u{0020}for\u{0020}the\u{0020}title\u{0020}of\u{0020}martial\u{0020}arts\u{0020}alliance\u{0020}leader...\u{0020}these\u{0020}are\u{0020}all\u{0020}classic\u{0020}scenarios.\u{0020}To\u{0020}ensure\u{0020}my\u{0020}birthday\u{0020}doesn't\u{0020}become\u{0020}a\u{0020}victim\u{0020}of\u{0020}such\u{0020}classic\u{0020}tropes,\u{0020}I've\u{0020}decided\u{0020}to\u{0020}double\u{0020}my\u{0020}martial\u{0020}arts\u{0020}training\u{0020}time\u{0020}today.\nI'll\u{0020}have\u{0020}to\u{0020}trouble\u{0020}you,\u{0020}Navigator,\u{0020}to\u{0020}accompany\u{0020}me\u{0020}for\u{0020}practice.\u{0020}This\u{0020}is\u{0020}my\u{0020}birthday\u{0020}wish,\u{0020}and\u{0020}I\u{0020}thank\u{0020}you\u{0020}in\u{0020}advance!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110006] = {id = 110006, name = "Celine", head = "10006", type = 5, title = "Day\u{0020}of\u{0020}Joy\u{0020}and\u{0020}Sorrow", txt = "終於又到了今天，這個人生中最悲痛的日子，初次與母親分別的日子。\n不管是誰，長大後成為了多麼堅強的人，初來世間都會哭聲連天，可是在之後的很多年裏，每到生日卻又興高采烈…這難道不是人類強大精神力的一種證明嗎？同樣具有化悲為喜能力的我，總是對此有所共鳴。\n不過直到現在，我還是更願度過和首個誕生日有著相同體驗的日子，那種悲痛讓我懷念。\n為今晚而訂的蛋糕上，我特意插了許多紅燭，想必蠟液一定會因那時的快樂而變得滾燙。如果對此有興趣，還請navigator快點過來；當然…要是覺得不妥，也歡迎大力責罵、懲罰我喲~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000601] = {id = 11000601, name = "Celine", head = "10006", type = 5, title = "A\u{0020}Day\u{0020}of\u{0020}Joy\u{0020}and\u{0020}Sorrow", txt = "At\u{0020}last,\u{0020}the\u{0020}day\u{0020}has\u{0020}come\u{0020}—\u{0020}the\u{0020}most\u{0020}sorrowful\u{0020}day\u{0020}of\u{0020}my\u{0020}life,\u{0020}the\u{0020}day\u{0020}I\u{0020}first\u{0020}parted\u{0020}from\u{0020}my\u{0020}mother.\nNo\u{0020}matter\u{0020}how\u{0020}strong\u{0020}one\u{0020}becomes\u{0020}over\u{0020}time,\u{0020}we\u{0020}all\u{0020}enter\u{0020}this\u{0020}world\u{0020}with\u{0020}cries\u{0020}of\u{0020}helplessness.\u{0020}Yet,\u{0020}as\u{0020}the\u{0020}years\u{0020}go\u{0020}by,\u{0020}our\u{0020}birthdays\u{0020}are\u{0020}filled\u{0020}with\u{0020}joy.\u{0020}Isn't\u{0020}this\u{0020}a\u{0020}testament\u{0020}to\u{0020}the\u{0020}strength\u{0020}of\u{0020}the\u{0020}human\u{0020}spirit?\u{0020}I,\u{0020}too,\u{0020}possess\u{0020}the\u{0020}ability\u{0020}to\u{0020}turn\u{0020}sorrow\u{0020}into\u{0020}joy,\u{0020}and\u{0020}I\u{0020}can't\u{0020}help\u{0020}but\u{0020}feel\u{0020}deeply\u{0020}connected\u{0020}to\u{0020}this\u{0020}idea.\nBut\u{0020}even\u{0020}now,\u{0020}I'd\u{0020}rather\u{0020}relive\u{0020}the\u{0020}emotions\u{0020}of\u{0020}my\u{0020}first\u{0020}birthday,\u{0020}as\u{0020}that\u{0020}sadness\u{0020}is\u{0020}something\u{0020}I\u{0020}hold\u{0020}dear\u{0020}and\u{0020}long\u{0020}for.\nFor\u{0020}tonight,\u{0020}I've\u{0020}ordered\u{0020}a\u{0020}cake\u{0020}with\u{0020}plenty\u{0020}of\u{0020}red\u{0020}candles.\u{0020}I\u{0020}imagine\u{0020}the\u{0020}wax\u{0020}will\u{0020}melt,\u{0020}heated\u{0020}by\u{0020}the\u{0020}joy\u{0020}of\u{0020}the\u{0020}moment\u{0020}—\u{0020}perhaps\u{0020}even\u{0020}in\u{0020}ways\u{0020}that\u{0020}might\u{0020}stir\u{0020}up\u{0020}something\u{0020}more...\u{0020}intriguing.\u{0020}If\u{0020}that\u{0020}catches\u{0020}your\u{0020}interest,\u{0020}come\u{0020}over\u{0020}quickly,\u{0020}Navigator.\u{0020}Of\u{0020}course,\u{0020}if\u{0020}you're\u{0020}uncomfortable,\u{0020}feel\u{0020}free\u{0020}to\u{0020}scold\u{0020}or\u{0020}punish\u{0020}me\u{0020}however\u{0020}you\u{0020}see\u{0020}fit~\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000602] = {id = 11000602, name = "Celine", head = "10006", type = 5, title = "Please\u{0020}Whip\u{0020}Me\u{0020}as\u{0020}Much\u{0020}as\u{0020}You\u{0020}Like", txt = "The\u{0020}darkness\u{0020}before\u{0020}dawn\u{0020}is\u{0020}the\u{0020}darkest,\u{0020}and\u{0020}the\u{0020}day\u{0020}before\u{0020}a\u{0020}birthday\u{0020}is\u{0020}the\u{0020}longest.\u{0020}\nOver\u{0020}the\u{0020}past\u{0020}twenty-four\u{0020}hours,\u{0020}I've\u{0020}come\u{0020}to\u{0020}understand\u{0020}that\u{0020}deeply.\u{0020}\nCan\u{0020}you\u{0020}understand\u{0020}the\u{0020}impatience\u{0020}I\u{0020}felt\u{0020}as\u{0020}I\u{0020}stared\u{0020}at\u{0020}the\u{0020}time,\u{0020}waiting\u{0020}and\u{0020}waiting\u{0020}for\u{0020}it\u{0020}to\u{0020}finally\u{0020}reach\u{0020}00:00?\u{0020}If\u{0020}it's\u{0020}you,\u{0020}then\u{0020}surely\u{0020}you\u{0020}can.\u{0020}\nNow,\u{0020}at\u{0020}last,\u{0020}the\u{0020}second\u{0020}day\u{0020}has\u{0020}begun...\u{0020}and\u{0020}at\u{0020}last,\u{0020}my\u{0020}birthday\u{0020}is\u{0020}here.\u{0020}\nI\u{0020}long\u{0020}for\u{0020}you\u{0020}to\u{0020}bring\u{0020}me\u{0020}pain\u{0020}as\u{0020}you\u{0020}did\u{0020}before,\u{0020}and\u{0020}to\u{0020}bring\u{0020}me\u{0020}joy.\u{0020}\nPlease\u{0020}whip\u{0020}me,\u{0020}scold\u{0020}me...\u{0020}use\u{0020}your\u{0020}hands\u{0020}to\u{0020}reach\u{0020}places\u{0020}no\u{0020}one\u{0020}has\u{0020}ever\u{0020}touched,\u{0020}and\u{0020}make\u{0020}even\u{0020}my\u{0020}soul\u{0020}tremble,\u{0020}Navigator.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110007] = {id = 110007, name = "Uki", head = "10007", type = 5, title = "Bridal\u{0020}Training\u{0020}for\u{0020}My\u{0020}Birthday", txt = "If\u{0020}I\u{0020}may\u{0020}ask\u{0020}something\u{0020}a\u{0020}bit\u{0020}bold...\u{0020}does\u{0020}the\u{0020}idea\u{0020}of\u{0020}celebrating\u{0020}someone's\u{0020}birthday\u{0020}interest\u{0020}you,\u{0020}Navigator?\nAs\u{0020}you\u{0020}know,\u{0020}I've\u{0020}long\u{0020}been\u{0020}engaged\u{0020}in\u{0020}bridal\u{0020}training,\u{0020}working\u{0020}hard\u{0020}to\u{0020}become\u{0020}a\u{0020}wonderful\u{0020}wife\u{0020}someday.\u{0020}And\u{0020}besides\u{0020}everyday\u{0020}chores,\u{0020}special\u{0020}occasions\u{0020}like\u{0020}birthdays\u{0020}are\u{0020}essential\u{0020}practice.\u{0020}After\u{0020}all,\u{0020}preparing\u{0020}a\u{0020}grand\u{0020}feast\u{0020}for\u{0020}the\u{0020}family\u{0020}is\u{0020}a\u{0020}wife's\u{0020}duty,\u{0020}don't\u{0020}you\u{0020}think?\nToday\u{0020}happens\u{0020}to\u{0020}be\u{0020}my\u{0020}birthday.\u{0020}If\u{0020}you\u{0020}wouldn't\u{0020}mind...\u{0020}could\u{0020}you\u{0020}play\u{0020}the\u{0020}role\u{0020}of\u{0020}my\u{0020}husband\u{0020}for\u{0020}the\u{0020}day?\u{0020}Just\u{0020}like\u{0020}a\u{0020}game\u{0020}of\u{0020}make-believe!\u{0020}Nothing\u{0020}real!\u{0020}And\u{0020}you'll\u{0020}get\u{0020}to\u{0020}enjoy\u{0020}delicious\u{0020}food\u{0020}too.\u{0020}Sounds\u{0020}nice,\u{0020}doesn't\u{0020}it?\u{0020}If\u{0020}you\u{0020}do...\u{0020}I'll\u{0020}be\u{0020}waiting\u{0020}in\u{0020}my\u{0020}room.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000701] = {id = 11000701, name = "Uki", head = "10007", type = 5, title = "Wedding\u{0020}Rehearsal", txt = "Navigator,\u{0020}do\u{0020}you\u{0020}have\u{0020}some\u{0020}time?\u{0020}I\u{0020}made\u{0020}an\u{0020}outfit\u{0020}for\u{0020}you\u{0020}and\u{0020}would\u{0020}like\u{0020}you\u{0020}to\u{0020}try\u{0020}it\u{0020}on\u{0020}to\u{0020}see\u{0020}whether\u{0020}it\u{0020}fits.\nIt\u{0020}is\u{0020}not\u{0020}anything\u{0020}strange,\u{0020}just\u{0020}a\u{0020}men's\u{0020}formal\u{0020}suit,\u{0020}especially\u{0020}suited\u{0020}for...\u{0020}wearing\u{0020}at\u{0020}a\u{0020}wedding.\u{0020}I\u{0020}also\u{0020}made\u{0020}a\u{0020}wedding\u{0020}dress\u{0020}for\u{0020}myself.\nActually,\u{0020}I\u{0020}would\u{0020}like\u{0020}you\u{0020}to\u{0020}rehearse\u{0020}what\u{0020}a\u{0020}wedding\u{0020}would\u{0020}be\u{0020}like\u{0020}with\u{0020}me.\u{0020}The\u{0020}word\u{0020}\"bride\"\u{0020}can\u{0020}be\u{0020}said\u{0020}to\u{0020}exist\u{0020}for\u{0020}weddings\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\u{0020}A\u{0020}wedding\u{0020}is\u{0020}the\u{0020}brightest\u{0020}moment\u{0020}for\u{0020}a\u{0020}bride,\u{0020}and\u{0020}I\u{0020}do\u{0020}not\u{0020}want\u{0020}to\u{0020}make\u{0020}a\u{0020}fool\u{0020}of\u{0020}myself\u{0020}at\u{0020}my\u{0020}own\u{0020}wedding.\nThe\u{0020}reason\u{0020}I\u{0020}chose\u{0020}today\u{0020}is\u{0020}because\u{0020}I\u{0020}hope\u{0020}Navigator\u{0020}will\u{0020}not\u{0020}refuse\u{0020}this\u{0020}tiny\u{0020}birthday\u{0020}wish\u{0020}of\u{0020}mine,\u{0020}since\u{0020}it\u{0020}is\u{0020}my\u{0020}birthday.\u{0020}Hehe,\u{0020}this\u{0020}is\u{0020}also\u{0020}something\u{0020}I\u{0020}learned\u{0020}from\u{0020}bride\u{0020}training--\u{0020}the\u{0020}little\u{0020}bit\u{0020}of\u{0020}scheming\u{0020}a\u{0020}wife\u{0020}should\u{0020}have.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110008] = {id = 110008, name = "Dolores", head = "10008", type = 5, title = "New\u{0020}Year,\u{0020}My\u{0020}Birthday", txt = "January\u{0020}1st,\u{0020}the\u{0020}first\u{0020}day\u{0020}of\u{0020}the\u{0020}new\u{0020}year.\u{0020}I\u{0020}don't\u{0020}think\u{0020}you\u{0020}know...\u{0020}but\u{0020}January\u{0020}1st\u{0020}is\u{0020}also\u{0020}my\u{0020}birthday.\nSometimes\u{0020}I\u{0020}think,\u{0020}\"If\u{0020}my\u{0020}birthday\u{0020}and\u{0020}New\u{0020}Year's\u{0020}Day\u{0020}are\u{0020}the\u{0020}same\u{0020}day,\u{0020}there\u{0020}will\u{0020}be\u{0020}one\u{0020}less\u{0020}memorable\u{0020}day\u{0020}in\u{0020}the\u{0020}year\u{0020}for\u{0020}me.\"\u{0020}Such\u{0020}thoughts\u{0020}used\u{0020}to\u{0020}bother\u{0020}me\u{0020}when\u{0020}I\u{0020}was\u{0020}little.\nOh,\u{0020}but\u{0020}now\u{0020}I\u{0020}think\u{0020}that\u{0020}the\u{0020}overlap\u{0020}makes\u{0020}my\u{0020}birthday\u{0020}and\u{0020}New\u{0020}Year's\u{0020}Day\u{0020}more\u{0020}special,\u{0020}for\u{0020}example\u{0020}-\u{0020}I\u{0020}get\u{0020}to\u{0020}have\u{0020}my\u{0020}birthday\u{0020}cake\u{0020}on\u{0020}New\u{0020}Year's\u{0020}Day.\nIn\u{0020}the\u{0020}same\u{0020}sense,\u{0020}I\u{0020}can\u{0020}make\u{0020}the\u{0020}day\u{0020}memorable\u{0020}-\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}my\u{0020}special\u{0020}day\u{0020}with\u{0020}you,\u{0020}so\u{0020}that\u{0020}your\u{0020}day\u{0020}will\u{0020}be\u{0020}special\u{0020}too.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000801] = {id = 11000801, name = "Dolores", head = "10008", type = 5, title = "A\u{0020}Special\u{0020}New\u{0020}Year's\u{0020}Day", txt = "Happy\u{0020}New\u{0020}Year,\u{0020}Navigator!\u{0020}Did\u{0020}you\u{0020}know?\u{0020}January\u{0020}1st\u{0020}isn't\u{0020}just\u{0020}the\u{0020}start\u{0020}of\u{0020}a\u{0020}new\u{0020}year—it's\u{0020}also\u{0020}my\u{0020}birthday.\u{0020}\nWhen\u{0020}I\u{0020}was\u{0020}little,\u{0020}I\u{0020}used\u{0020}to\u{0020}wonder:\u{0020}\"If\u{0020}my\u{0020}birthday\u{0020}and\u{0020}New\u{0020}Year's\u{0020}fall\u{0020}on\u{0020}the\u{0020}same\u{0020}day,\u{0020}does\u{0020}that\u{0020}mean\u{0020}I\u{0020}have\u{0020}one\u{0020}less\u{0020}special\u{0020}day\u{0020}to\u{0020}celebrate?\"\u{0020}It\u{0020}used\u{0020}to\u{0020}bother\u{0020}me\u{0020}back\u{0020}then.\u{0020}\nBut\u{0020}as\u{0020}I\u{0020}grew\u{0020}up,\u{0020}I\u{0020}realized\u{0020}how\u{0020}unique\u{0020}this\u{0020}actually\u{0020}is.\u{0020}Having\u{0020}my\u{0020}birthday\u{0020}and\u{0020}New\u{0020}Year's\u{0020}together\u{0020}makes\u{0020}both\u{0020}days\u{0020}feel\u{0020}even\u{0020}more\u{0020}special.\u{0020}It's\u{0020}not\u{0020}every\u{0020}day\u{0020}you\u{0020}get\u{0020}to\u{0020}enjoy\u{0020}a\u{0020}birthday\u{0020}cake\u{0020}while\u{0020}celebrating\u{0020}the\u{0020}start\u{0020}of\u{0020}a\u{0020}brand-new\u{0020}year!\nAnd\u{0020}here's\u{0020}the\u{0020}best\u{0020}part:\u{0020}special\u{0020}moments\u{0020}don't\u{0020}just\u{0020}happen—they're\u{0020}created.\u{0020}So,\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}my\u{0020}joy\u{0020}with\u{0020}you\u{0020}today\u{0020}and\u{0020}make\u{0020}this\u{0020}day\u{0020}just\u{0020}as\u{0020}memorable\u{0020}for\u{0020}you\u{0020}as\u{0020}it\u{0020}is\u{0020}for\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000802] = {id = 11000802, name = "Dolores", head = "10008", type = 5, title = "Happy\u{0020}New\u{0020}Year,\u{0020}and\u{0020}Happy\u{0020}Birthday", txt = "Happy\u{0020}New\u{0020}Year!\u{0020}In\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye,\u{0020}another\u{0020}year\u{0020}has\u{0020}passed.\u{0020}Over\u{0020}the\u{0020}past\u{0020}year,\u{0020}I\u{0020}have\u{0020}been\u{0020}constantly\u{0020}occupied\u{0020}with\u{0020}matters\u{0020}concerning\u{0020}the\u{0020}squad,\u{0020}leaving\u{0020}us\u{0020}with\u{0020}far\u{0020}fewer\u{0020}opportunities\u{0020}to\u{0020}sit\u{0020}down\u{0020}and\u{0020}talk\u{0020}at\u{0020}length.\nI\u{0020}wonder\u{0020}how\u{0020}you\u{0020}have\u{0020}been\u{0020}lately,\u{0020}Navigator.\u{0020}At\u{0020}this\u{0020}moment\u{0020}of\u{0020}bidding\u{0020}farewell\u{0020}to\u{0020}the\u{0020}old\u{0020}year\u{0020}and\u{0020}welcoming\u{0020}the\u{0020}new\u{0020}-\u{0020}and\u{0020}as\u{0020}it\u{0020}also\u{0020}happens\u{0020}to\u{0020}be\u{0020}my\u{0020}birthday\u{0020}-\u{0020}I\u{0020}find\u{0020}myself\u{0020}wishing\u{0020}to\u{0020}spend\u{0020}some\u{0020}time\u{0020}with\u{0020}you,\u{0020}to\u{0020}welcome\u{0020}the\u{0020}coming\u{0020}year\u{0020}together.\nWith\u{0020}that\u{0020}in\u{0020}mind,\u{0020}I\u{0020}would\u{0020}like\u{0020}to\u{0020}sincerely\u{0020}invite\u{0020}you\u{0020}to\u{0020}attend\u{0020}my\u{0020}New\u{0020}Year\u{0020}birthday\u{0020}party.\u{0020}Let\u{0020}us\u{0020}offer\u{0020}our\u{0020}wishes\u{0020}together:\u{0020}that\u{0020}every\u{0020}moment\u{0020}of\u{0020}the\u{0020}new\u{0020}year\u{0020}be\u{0020}filled\u{0020}with\u{0020}hope,\u{0020}and\u{0020}that\u{0020}every\u{0020}step\u{0020}we\u{0020}take\u{0020}leads\u{0020}us\u{0020}closer\u{0020}to\u{0020}the\u{0020}future\u{0020}we\u{0020}seek.\nI\u{0020}look\u{0020}forward\u{0020}to\u{0020}your\u{0020}reply\u{0020}and\u{0020}sincerely\u{0020}hope\u{0020}to\u{0020}receive\u{0020}good\u{0020}news\u{0020}of\u{