[110009] = {id = 110009, name = "Morgan\u{0020}Le\u{0020}Fay", head = "10009", type = 5, title = "The\u{0020}World's\u{0020}Magic", txt = "If\u{0020}magic\u{0020}is\u{0020}all\u{0020}about\u{0020}bringing\u{0020}people\u{0020}unexpected\u{0020}and\u{0020}inexplicable\u{0020}surprises,\u{0020}then\u{0020}perhaps\u{0020}the\u{0020}very\u{0020}act\u{0020}of\u{0020}life's\u{0020}creation\u{0020}is\u{0020}the\u{0020}grandest\u{0020}magic\u{0020}this\u{0020}world\u{0020}has\u{0020}ever\u{0020}performed.\nNo\u{0020}one\u{0020}knows\u{0020}what\u{0020}the\u{0020}future\u{0020}holds,\u{0020}nor\u{0020}can\u{0020}we\u{0020}truly\u{0020}understand\u{0020}where\u{0020}we\u{0020}came\u{0020}from—but\u{0020}isn't\u{0020}that\u{0020}what\u{0020}makes\u{0020}it\u{0020}so\u{0020}enchanting?\u{0020}If\u{0020}you\u{0020}strip\u{0020}away\u{0020}the\u{0020}mystery,\u{0020}the\u{0020}magic\u{0020}disappears\u{0020}with\u{0020}it.\u{0020}So,\u{0020}just\u{0020}for\u{0020}today,\u{0020}let's\u{0020}not\u{0020}dwell\u{0020}upon\u{0020}it.\u{0020}Let's\u{0020}simply\u{0020}revel\u{0020}in\u{0020}the\u{0020}magic\u{0020}that's\u{0020}been\u{0020}cast\u{0020}upon\u{0020}us\u{0020}and\u{0020}the\u{0020}miracle\u{0020}of\u{0020}existence\u{0020}itself!\nEverything\u{0020}is\u{0020}ready\u{0020}for\u{0020}tonight's\u{0020}private\u{0020}magic\u{0020}performance.\u{0020}Navigator,\u{0020}I'll\u{0020}be\u{0020}expecting\u{0020}you\u{0020}in\u{0020}my\u{0020}room.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11000901] = {id = 11000901, name = "Morgan\u{0020}Le\u{0020}Fay", head = "10009", type = 5, title = "Morgan\u{0020}Le\u{0020}Fay's\u{0020}Magic\u{0020}Show", txt = "Navigator,\u{0020}hello!\nLately,\u{0020}I've\u{0020}been\u{0020}practicing\u{0020}a\u{0020}special\u{0020}magic\u{0020}performance\u{0020}so\u{0020}I\u{0020}can\u{0020}give\u{0020}everyone\u{0020}a\u{0020}surprise\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}but\u{0020}it\u{0020}always\u{0020}feels\u{0020}like\u{0020}something\u{0020}is\u{0020}missing...\nLater...\u{0020}I\u{0020}finally\u{0020}figured\u{0020}it\u{0020}out...\u{0020}the\u{0020}most\u{0020}wonderful\u{0020}part\u{0020}of\u{0020}magic\u{0020}isn't\u{0020}the\u{0020}props\u{0020}or\u{0020}the\u{0020}technique,\u{0020}but\u{0020}performing\u{0020}it\u{0020}together\u{0020}with\u{0020}someone\u{0020}special.\nSo,\u{0020}I'd\u{0020}like\u{0020}to\u{0020}invite\u{0020}you\u{0020}to\u{0020}be\u{0020}my\u{0020}partner\u{0020}and\u{0020}create\u{0020}magic\u{0020}that\u{0020}belongs\u{0020}to\u{0020}us\u{0020}together\u{0020}on\u{0020}stage.\nDon't\u{0020}worry,\u{0020}you\u{0020}won't\u{0020}need\u{0020}any\u{0020}amazing\u{0020}skills.\u{0020}I'll\u{0020}teach\u{0020}you\u{0020}step\u{0020}by\u{0020}step.\nAs\u{0020}long\u{0020}as\u{0020}you're\u{0020}willing\u{0020}to\u{0020}reach\u{0020}out\u{0020}your\u{0020}hand,\u{0020}weave\u{0020}light\u{0020}and\u{0020}shadow\u{0020}together\u{0020}with\u{0020}me,\u{0020}and\u{0020}witness\u{0020}those\u{0020}breathtaking\u{0020}moments,\u{0020}then\u{0020}this\u{0020}performance\u{0020}will\u{0020}surely\u{0020}become\u{0020}the\u{0020}most\u{0020}perfect\u{0020}kind\u{0020}of\u{0020}magic.\nWould\u{0020}you\u{0020}be\u{0020}willing?\u{0020}If\u{0020}so,\u{0020}let\u{0020}me\u{0020}know.\u{0020}I'll\u{0020}have\u{0020}everything\u{0020}prepared\u{0020}and\u{0020}will\u{0020}be\u{0020}waiting\u{0020}for\u{0020}you\u{0020}----\u{0020}your\u{0020}magic\u{0020}partner,\u{0020}Morgan\u{0020}Le\u{0020}Fay.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
