[11001001] = {id = 11001001, name = "Alaita", head = "10010", type = 5, title = "I\u{0020}Am\u{0020}the\u{0020}Surprise", txt = "After\u{0020}receiving\u{0020}this\u{0020}letter,\u{0020}please\u{0020}make\u{0020}sure\u{0020}to\u{0020}read\u{0020}its\u{0020}contents\u{0020}in\u{0020}an\u{0020}environment\u{0020}where\u{0020}no\u{0020}one\u{0020}else\u{0020}is\u{0020}around,\u{0020}especially\u{0020}where\u{0020}Captain\u{0020}Dolores\u{0020}is\u{0020}not\u{0020}present.\nMm,\u{0020}I\u{0020}trust\u{0020}that\u{0020}after\u{0020}reading\u{0020}the\u{0020}opening,\u{0020}you\u{0020}will\u{0020}not\u{0020}open\u{0020}this\u{0020}letter\u{0020}in\u{0020}public.\u{0020}That\u{0020}is\u{0020}how\u{0020}much\u{0020}I\u{0020}trust\u{0020}you,\u{0020}Navigator.\nAll\u{0020}right,\u{0020}Navigator,\u{0020}you\u{0020}must\u{0020}be\u{0020}curious\u{0020}what\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}you.\nI\u{0020}will\u{0020}not\u{0020}keep\u{0020}you\u{0020}guessing--\n--Today\u{0020}is\u{0020}the\u{0020}birthday\u{0020}of\u{0020}\"Siren,\"\u{0020}and\u{0020}I\u{0020}have\u{0020}decided\u{0020}to\u{0020}entrust\u{0020}this\u{0020}precious\u{0020}day\u{0020}to\u{0020}you.\nNow,\u{0020}please\u{0020}return\u{0020}to\u{0020}your\u{0020}room.\u{0020}A\u{0020}surprise\u{0020}will\u{0020}be\u{0020}waiting\u{0020}for\u{0020}you\u{0020}there.\nYes,\u{0020}it\u{0020}is\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110011] = {id = 110011, name = "Jacksui", head = "10011", type = 5, title = "A\u{0020}birthday\u{0020}spent\u{0020}with\u{0020}my\u{0020}brother.", txt = "Brother,\u{0020}I\u{0020}checked\u{0020}the\u{0020}screening\u{0020}schedules\u{0020}for\u{0020}every\u{0020}cinema\u{0020}in\u{0020}the\u{0020}Danube,\u{0020}and\u{0020}guess\u{0020}what?\u{0020}They're\u{0020}all\u{0020}packed\u{0020}with\u{0020}those\u{0020}generic,\u{0020}factory-made\u{0020}blockbusters!\u{0020}Just\u{0020}reading\u{0020}the\u{0020}summaries\u{0020}makes\u{0020}me\u{0020}bored.\u{0020}It's\u{0020}my\u{0020}birthday,\u{0020}after\u{0020}all,\u{0020}and\u{0020}I\u{0020}was\u{0020}hoping\u{0020}we\u{0020}could\u{0020}watch\u{0020}a\u{0020}cult\u{0020}film\u{0020}together...\nBut\u{0020}then\u{0020}I\u{0020}had\u{0020}an\u{0020}idea—since\u{0020}the\u{0020}theaters\u{0020}are\u{0020}flooded\u{0020}with\u{0020}soulless\u{0020}movies,\u{0020}why\u{0020}don't\u{0020}we\u{0020}create\u{0020}our\u{0020}own\u{0020}masterpiece\u{0020}and\u{0020}shake\u{0020}up\u{0020}the\u{0020}industry?\u{0020}Hmm...\u{0020}How\u{0020}about\u{0020}we\u{0020}call\u{0020}it\u{0020}\"A\u{0020}Birthday\u{0020}Spent\u{0020}with\u{0020}My\u{0020}Brother\"?\u{0020}The\u{0020}story\u{0020}doesn't\u{0020}even\u{0020}need\u{0020}to\u{0020}match\u{0020}the\u{0020}title—I\u{0020}just\u{0020}really\u{0020}like\u{0020}how\u{0020}it\u{0020}sounds.\nIf\u{0020}you're\u{0020}ready\u{0020}to\u{0020}star\u{0020}in\u{0020}this\u{0020}groundbreaking\u{0020}film,\u{0020}brother,\u{0020}come\u{0020}find\u{0020}me.\u{0020}I'm\u{0020}sure\u{0020}we'll\u{0020}win\u{0020}this\u{0020}year's\u{0020}Best\u{0020}Newcomer\u{0020}Award\u{0020}together~\n\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001101] = {id = 11001101, name = "Jacksui", head = "10011", type = 5, title = "Today,\u{0020}We\u{0020}Master\u{0020}B\u{0020}Movies", txt = "Navigator-nisan...\u{0020}what\u{0020}kind\u{0020}of\u{0020}movie\u{0020}do\u{0020}you\u{0020}think\u{0020}suits\u{0020}a\u{0020}birthday\u{0020}celebration?\u{0020}I\u{0020}think\u{0020}any\u{0020}genre\u{0020}works\u{0020}as\u{0020}long\u{0020}as\u{0020}it's\u{0020}a\u{0020}B-movie.\u{0020}Westerns,\u{0020}romance,\u{0020}gangsters,\u{0020}horror,\u{0020}supernatural,\u{0020}sci-fi...\u{0020}Hmm...\u{0020}maybe\u{0020}horror\u{0020}isn't\u{0020}ideal...\u{0020}I've\u{0020}already\u{0020}prepared\u{0020}a\u{0020}ton\u{0020}of\u{0020}snacks.\u{0020}So\u{0020}come\u{0020}to\u{0020}my\u{0020}room,\u{0020}okay?\u{0020}We'll\u{0020}watch\u{0020}movies\u{0020}under\u{0020}the\u{0020}covers...\u{0020}Critique\u{0020}terrible\u{0020}films...\u{0020}Sleep\u{0020}when\u{0020}we're\u{0020}tired...\u{0020}Eat\u{0020}when\u{0020}we\u{0020}wake\u{0020}up...\nI\u{0020}want\u{0020}to\u{0020}spend\u{0020}this\u{0020}birthday\u{0020}in\u{0020}a\u{0020}way\u{0020}that\u{0020}feels\u{0020}pointless\u{0020}and\u{0020}meaningful\u{0020}at\u{0020}the\u{0020}same\u{0020}time.\u{0020}What\u{0020}do\u{0020}you\u{0020}think?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110012] = {id = 110012, name = "Gloria", head = "10012", type = 5, title = "To\u{0020}My\u{0020}One\u{0020}and\u{0020}Only\u{0020}Confidant", txt = "What\u{0020}is\u{0020}a\u{0020}birthday?\u{0020}A\u{0020}celebration\u{0020}of\u{0020}one's\u{0020}birth?\u{0020}A\u{0020}ritual\u{0020}to\u{0020}congratulate\u{0020}oneself\u{0020}on\u{0020}growing\u{0020}another\u{0020}year\u{0020}older?\u{0020}It\u{0020}puzzles\u{0020}me\u{0020}deeply.\nI've\u{0020}never\u{0020}found\u{0020}sense\u{0020}in\u{0020}the\u{0020}joy\u{0020}of\u{0020}a\u{0020}\"birthday.\"\u{0020}For\u{0020}classmates\u{0020}lost\u{0020}in\u{0020}such\u{0020}happiness,\u{0020}I\u{0020}can\u{0020}only\u{0020}offer\u{0020}them\u{0020}hesitant\u{0020}applause.\nUntil\u{0020}I\u{0020}met\u{0020}you.\nThis\u{0020}morning,\u{0020}when\u{0020}I\u{0020}heard\u{0020}your\u{0020}well-wishes,\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}I\u{0020}thought...\u{0020}perhaps\u{0020}celebrating\u{0020}a\u{0020}birthday\u{0020}really\u{0020}is\u{0020}something\u{0020}nice.\nAh,\u{0020}how\u{0020}embarrassing.\u{0020}Starting\u{0020}off\u{0020}with\u{0020}such\u{0020}negativity...\u{0020}But\u{0020}you,\u{0020}Navigator,\u{0020}are\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}has\u{0020}ever\u{0020}tried\u{0020}to\u{0020}know\u{0020}me.\u{0020}So\u{0020}I\u{0020}believe...\u{0020}you\u{0020}will\u{0020}see\u{0020}me\u{0020}for\u{0020}who\u{0020}I\u{0020}am\u{0020}and\u{0020}accept\u{0020}me\u{0020}no\u{0020}matter\u{0020}what.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001201] = {id = 11001201, name = "Gloria", head = "10012", type = 5, title = "To\u{0020}the\u{0020}One\u{0020}I\u{0020}Understand,\u{0020}Who\u{0020}Understands\u{0020}Me", txt = "Please\u{0020}forgive\u{0020}me\u{0020}for\u{0020}contacting\u{0020}you\u{0020}in\u{0020}advance\u{0020}and\u{0020}sending\u{0020}this\u{0020}reply\u{0020}before\u{0020}I\u{0020}have\u{0020}even\u{0020}received\u{0020}your\u{0020}birthday\u{0020}wishes,\u{0020}Navigator.\u{0020}I\u{0020}do\u{0020}so\u{0020}because\u{0020}I\u{0020}am\u{0020}certain\u{0020}they\u{0020}will\u{0020}arrive\u{0020}right\u{0020}on\u{0020}time.\nI\u{0020}am\u{0020}sure\u{0020}you\u{0020}can\u{0020}understand\u{0020}my\u{0020}impatience.\u{0020}A\u{0020}full\u{0020}year\u{0020}has\u{0020}passed\u{0020}since\u{0020}our\u{0020}last\u{0020}birthday\u{0020}celebration,\u{0020}and\u{0020}I\u{0020}have\u{0020}accumulated\u{0020}many\u{0020}things\u{0020}I\u{0020}wish\u{0020}to\u{0020}share\u{0020}with\u{0020}you.\u{0020}I\u{0020}also\u{0020}hope\u{0020}to\u{0020}hear\u{0020}your\u{0020}true\u{0020}feelings.\u{0020}A\u{0020}one-sided\u{0020}pursuit\u{0020}of\u{0020}understanding\u{0020}is\u{0020}not\u{0020}ideal;\u{0020}mutual\u{0020}understanding\u{0020}is\u{0020}my\u{0020}ultimate\u{0020}goal.\nI\u{0020}hope\u{0020}that,\u{0020}after\u{0020}today,\u{0020}our\u{0020}understanding\u{0020}of\u{0020}one\u{0020}another\u{0020}will\u{0020}reach\u{0020}an\u{0020}even\u{0020}deeper\u{0020}level.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110013] = {id = 110013, name = "Lilith", head = "10013", type = 5, title = "Just\u{0020}Give\u{0020}Me\u{0020}a\u{0020}Little\u{0020}More\u{0020}Time...", txt = "I've\u{0020}finally\u{0020}figured\u{0020}it\u{0020}out.\u{0020}Skadi\u{0020}is\u{0020}an\u{0020}idiot.\u{0020}A\u{0020}complete,\u{0020}absolute\u{0020}idiot.\nShe's\u{0020}been\u{0020}going\u{0020}on\u{0020}and\u{0020}on\u{0020}since\u{0020}this\u{0020}morning\u{0020}about\u{0020}throwing\u{0020}me\u{0020}the\u{0020}perfect\u{0020}birthday.\u{0020}Has\u{0020}she\u{0020}seriously\u{0020}forgotten\u{0020}how\u{0020}to\u{0020}understand\u{0020}plain\u{0020}human\u{0020}speech?\u{0020}Haven't\u{0020}I\u{0020}made\u{0020}it\u{0020}clear\u{0020}already?\u{0020}I\u{0020}hate\u{0020}birthdays.\nForget\u{0020}Fleur\u{0020}and\u{0020}Gia.\u{0020}I\u{0020}can't\u{0020}believe\u{0020}she\u{0020}even\u{0020}managed\u{0020}to\u{0020}rope\u{0020}Morgan\u{0020}into\u{0020}this\u{0020}whole\u{0020}party\u{0020}nonsense.\u{0020}...Fine.\u{0020}I'll\u{0020}admit\u{0020}it.\u{0020}She\u{0020}probably\u{0020}meant\u{0020}well.\u{0020}It's\u{0020}not\u{0020}like\u{0020}she's\u{0020}smart\u{0020}enough\u{0020}to\u{0020}scheme\u{0020}just\u{0020}to\u{0020}annoy\u{0020}me.\nBut\u{0020}still...\u{0020}Right\u{0020}now,\u{0020}I\u{0020}just\u{0020}can't\u{0020}bring\u{0020}myself\u{0020}to\u{0020}celebrate\u{0020}anything.\u{0020}Not\u{0020}yet.\u{0020}Give\u{0020}me\u{0020}a\u{0020}little\u{0020}more\u{0020}time,\u{0020}okay?\n\n...Ugh.\u{0020}My\u{0020}head's\u{0020}pounding.\nNavigator,\u{0020}if\u{0020}you're\u{0020}reading\u{0020}this,\u{0020}come\u{0020}find\u{0020}me.\u{0020}You're\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}might\u{0020}be\u{0020}able\u{0020}to\u{0020}rein\u{0020}them\u{0020}in.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001301] = {id = 11001301, name = "Lilith", head = "10013", type = 5, title = "I\u{0020}Need\u{0020}to\u{0020}See\u{0020}a\u{0020}Doctor", txt = "Ever\u{0020}since\u{0020}I\u{0020}woke\u{0020}up\u{0020}this\u{0020}morning,\u{0020}a\u{0020}voice\u{0020}has\u{0020}been\u{0020}making\u{0020}a\u{0020}constant\u{0020}racket\u{0020}inside\u{0020}my\u{0020}head:\u{0020}\"Today\u{0020}is\u{0020}an\u{0020}important\u{0020}day\u{0020}for\u{0020}you.\u{0020}Please\u{0020}be\u{0020}happy.\u{0020}Happy\u{0020}birthday.\"\nAt\u{0020}first,\u{0020}I\u{0020}thought\u{0020}it\u{0020}was\u{0020}a\u{0020}voice\u{0020}perceived\u{0020}through\u{0020}Synesthesia,\u{0020}because\u{0020}it\u{0020}felt\u{0020}very\u{0020}familiar\u{0020}to\u{0020}me.\nBut\u{0020}after\u{0020}listening\u{0020}carefully,\u{0020}I\u{0020}realized\u{0020}it\u{0020}was\u{0020}not\u{0020}a\u{0020}voice\u{0020}I\u{0020}knew.\nI\u{0020}am\u{0020}certain\u{0020}that\u{0020}I\u{0020}am\u{0020}the\u{0020}only\u{0020}person\u{0020}aboard\u{0020}the\u{0020}Danube\u{0020}Ark\u{0020}today...\u{0020}the\u{0020}only\u{0020}person\u{0020}celebrating\u{0020}a\u{0020}birthday.\nNavigator,\u{0020}to\u{0020}further\u{0020}determine\u{0020}whether\u{0020}this\u{0020}is\u{0020}a\u{0020}sign\u{0020}that\u{0020}my\u{0020}condition--[Pseudo-Synesthesia]--is\u{0020}worsening,\u{0020}please\u{0020}take\u{0020}me\u{0020}to\u{0020}see\u{0020}a\u{0020}\"professional\"\u{0020}doctor.\nIncidentally--Morgan\u{0020}Le\u{0020}Fay,\u{0020}Skadi,\u{0020}and\u{0020}Fleur\u{0020}are\u{0020}holding\u{0020}a\u{0020}birthday\u{0020}party\u{0020}for\u{0020}me...\u{0020}Please\u{0020}come\u{0020}quickly,\u{0020}and\u{0020}take\u{0020}me\u{0020}away\u{0020}after\u{0020}the\u{0020}party\u{0020}is\u{0020}over.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110014] = {id = 110014, name = "Korowin", head = "10014", type = 5, title = "My\u{0020}Birthday,\u{0020}Your\u{0020}Gift", txt = "Dear\u{0020}Navigator,\nIt's\u{0020}been\u{0020}a\u{0020}while\u{0020}since\u{0020}we\u{0020}last\u{0020}met.\u{0020}I\u{0020}hope\u{0020}you've\u{0020}been\u{0020}well.\nToday\u{0020}is\u{0020}my\u{0020}birthday,\u{0020}but\u{0020}I'm\u{0020}not\u{0020}writing\u{0020}to\u{0020}ask\u{0020}for\u{0020}a\u{0020}gift.\u{0020}Actually,\u{0020}it's\u{0020}the\u{0020}opposite;\u{0020}I'd\u{0020}like\u{0020}to\u{0020}give\u{0020}you\u{0020}something.\nAs\u{0020}you\u{0020}know,\u{0020}I'm\u{0020}not\u{0020}exactly\u{0020}on\u{0020}the\u{0020}best\u{0020}terms\u{0020}with\u{0020}my\u{0020}family.\u{0020}But\u{0020}somehow,\u{0020}Father\u{0020}found\u{0020}out\u{0020}I'm\u{0020}at\u{0020}Ember\u{0020}and\u{0020}sent\u{0020}over...\u{0020}Well,\u{0020}everything.\u{0020}Clothes,\u{0020}jewellery,\u{0020}accessories.\u{0020}None\u{0020}of\u{0020}which\u{0020}I\u{0020}needed.\u{0020}I\u{0020}let\u{0020}Iliya\u{0020}sell\u{0020}most\u{0020}of\u{0020}it\u{0020}for\u{0020}cash.\u{0020}There\u{0020}are\u{0020}some\u{0020}things\u{0020}that\u{0020}are\u{0020}harder\u{0020}to\u{0020}get\u{0020}rid\u{0020}of...\u{0020}We\u{0020}just\u{0020}had\u{0020}to\u{0020}split\u{0020}among\u{0020}ourselves.\nWhile\u{0020}sorting\u{0020}through\u{0020}it\u{0020}all,\u{0020}it\u{0020}occurred\u{0020}to\u{0020}me:\u{0020}Would\u{0020}Navigator\u{0020}have\u{0020}any\u{0020}use\u{0020}for\u{0020}these?\u{0020}So\u{0020}I\u{0020}picked\u{0020}out\u{0020}a\u{0020}few\u{0020}things\u{0020}for\u{0020}you.\u{0020}I\u{0020}hope\u{0020}they\u{0020}come\u{0020}in\u{0020}handy.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001401] = {id = 11001401, name = "Korowin", head = "10014", type = 5, title = "Running\u{0020}Away\u{0020}from\u{0020}Home", txt = "Dear\u{0020}Navigator,\u{0020}just\u{0020}as\u{0020}the\u{0020}title\u{0020}of\u{0020}this\u{0020}mail\u{0020}says,\u{0020}I\u{0020}have\u{0020}run\u{0020}away\u{0020}from\u{0020}home\u{0020}again.\u{0020}This\u{0020}time,\u{0020}however,\u{0020}my\u{0020}home\u{0020}has\u{0020}become\u{0020}\"Ember.\"\nIt\u{0020}started\u{0020}two\u{0020}days\u{0020}ago,\u{0020}when\u{0020}I\u{0020}picked\u{0020}up\u{0020}a\u{0020}\"puppy\"\u{0020}outside.\u{0020}I\u{0020}swear\u{0020}I\u{0020}really\u{0020}thought\u{0020}it\u{0020}was\u{0020}just\u{0020}an\u{0020}ordinary\u{0020}white\u{0020}puppy\u{0020}and\u{0020}never\u{0020}considered\u{0020}the\u{0020}possibility\u{0020}of\u{0020}a\u{0020}\"polar\u{0020}bear\u{0020}cub.\"\u{0020}Anyway,\u{0020}it\u{0020}gave\u{0020}Iliya\u{0020}quite\u{0020}a\u{0020}shock,\u{0020}and\u{0020}she\u{0020}told\u{0020}me\u{0020}to\u{0020}hurry\u{0020}and\u{0020}send\u{0020}this\u{0020}little\u{0020}life\u{0020}back.\u{0020}I\u{0020}could\u{0020}not\u{0020}bear\u{0020}to\u{0020}leave\u{0020}this\u{0020}little\u{0020}one\u{0020}alone\u{0020}out\u{0020}in\u{0020}the\u{0020}wild,\u{0020}so\u{0020}I\u{0020}had\u{0020}no\u{0020}choice\u{0020}but\u{0020}to\u{0020}run\u{0020}away\u{0020}from\u{0020}home\u{0020}together\u{0020}with\u{0020}it.\nI\u{0020}was\u{0020}wondering\u{0020}whether\u{0020}this\u{0020}little\u{0020}one\u{0020}might\u{0020}be\u{0020}a\u{0020}birthday\u{0020}gift\u{0020}from\u{0020}heaven.\u{0020}Maybe\u{0020}it\u{0020}got\u{0020}lost,\u{0020}or\u{0020}maybe,\u{0020}like\u{0020}me,\u{0020}it\u{0020}is\u{0020}a\u{0020}child\u{0020}who\u{0020}ran\u{0020}away\u{0020}from\u{0020}home.\nIf\u{0020}I\u{0020}ever\u{0020}get\u{0020}lost\u{0020}someday,\u{0020}I\u{0020}really\u{0020}hope\u{0020}Navigator\u{0020}will\u{0020}be\u{0020}the\u{0020}one\u{0020}to\u{0020}pick\u{0020}me\u{0020}up!\u{0020}Oh\u{0020}no,\u{0