[11001601] = {id = 11001601, name = "Anan", head = "10016", type = 5, title = "Sensei,\u{0020}I\u{0020}Learned\u{0020}It!", txt = "Sensei,\u{0020}do\u{0020}you\u{0020}remember?\nOn\u{0020}my\u{0020}birthday\u{0020}last\u{0020}year,\u{0020}I\u{0020}said\u{0020}I\u{0020}wanted\u{0020}to\u{0020}learn\u{0020}how\u{0020}to\u{0020}cook.\u{0020}Sensei\u{0020}should\u{0020}still\u{0020}remember\u{0020}that,\u{0020}right?\nAlthough\u{0020}Anan\u{0020}is\u{0020}very\u{0020}clumsy,\u{0020}and\u{0020}it\u{0020}took\u{0020}me\u{0020}a\u{0020}long\u{0020}time\u{0020}to\u{0020}learn,\u{0020}just\u{0020}yesterday,\u{0020}I\u{0020}finally\u{0020}satisfied\u{0020}Master\u{0020}Tenten!\nIn\u{0020}short,\u{0020}for\u{0020}this\u{0020}year's\u{0020}birthday,\u{0020}please\u{0020}taste\u{0020}the\u{0020}wasabi\u{0020}honey\u{0020}mille-feuille\u{0020}hamburger\u{0020}steak\u{0020}I\u{0020}made,\u{0020}personally\u{0020}taught\u{0020}by\u{0020}Master\u{0020}Tenten!\u{0020}Please,\u{0020}you\u{0020}have\u{0020}to\u{0020}come!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
