[11001701] = {id = 11001701, name = "Rosalind", head = "10017", type = 5, title = "An\u{0020}Unfortunate\u{0020}Piece\u{0020}of\u{0020}News", txt = "Greetings,\u{0020}Navigator.\nI\u{0020}presume\u{0020}you\u{0020}must\u{0020}be\u{0020}racking\u{0020}your\u{0020}brains\u{0020}right\u{0020}now,\u{0020}trying\u{0020}to\u{0020}prepare\u{0020}a\u{0020}birthday\u{0020}gift\u{0020}for\u{0020}me.\nHowever,\u{0020}the\u{0020}unfortunate\u{0020}news\u{0020}is\u{0020}that\u{0020}this\u{0020}year\u{0020}the\u{0020}family's\u{0020}business\u{0020}has\u{0020}run\u{0020}into\u{0020}a\u{0020}slight\u{0020}problem.\u{0020}One\u{0020}of\u{0020}the\u{0020}enterprises\u{0020}we\u{0020}painstakingly\u{0020}managed\u{0020}has\u{0020}fallen\u{0020}into\u{0020}a\u{0020}financial\u{0020}crisis\u{0020}and\u{0020}now\u{0020}faces\u{0020}the\u{0020}difficult\u{0020}situation\u{0020}of\u{0020}dissolution\u{0020}and\u{0020}restructuring.\u{0020}Of\u{0020}course,\u{0020}for\u{0020}the\u{0020}Rothschild\u{0020}family,\u{0020}with\u{0020}its\u{0020}vast\u{0020}wealth\u{0020}and\u{0020}assets,\u{0020}this\u{0020}is\u{0020}nothing\u{0020}more\u{0020}than\u{0020}a\u{0020}small\u{0020}ripple\u{0020}on\u{0020}a\u{0020}calm\u{0020}sea.\nAnd\u{0020}as\u{0020}this\u{0020}crisis\u{0020}happens\u{0020}to\u{0020}coincide\u{0020}with\u{0020}my\u{0020}birthday,\u{0020}as\u{0020}the\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}family,\u{0020}I\u{0020}must\u{0020}show\u{0020}a\u{0020}certain\u{0020}degree\u{0020}of\u{0020}responsibility.\u{0020}Therefore,\u{0020}I\u{0020}took\u{0020}the\u{0020}initiative\u{0020}to\u{0020}petition\u{0020}the\u{0020}family\u{0020}to\u{0020}cancel\u{0020}the\u{0020}originally\u{0020}planned\u{0020}lavish\u{0020}and\u{0020}extravagant\u{0020}banquet,\u{0020}sparing\u{0020}those\u{0020}unnecessary\u{0020}expenses.\u{0020}As\u{0020}a\u{0020}result,\u{0020}I\u{0020}now\u{0020}find\u{0020}myself\u{0020}with\u{0020}some\u{0020}rare\u{0020}free\u{0020}time.\nI\u{0020}recall\u