[11001802] = {id = 11001802, name = "Lyfa", head = "10018", type = 5, title = "Master,\u{0020}This\u{0020}Is\u{0020}a\u{0020}Big\u{0020}Problem!!", txt = "This\u{0020}is\u{0020}a\u{0020}big\u{0020}problem!\u{0020}A\u{0020}huge\u{0020}problem!\u{0020}Miss\u{0020}Lyfa\u{0020}is\u{0020}facing\u{0020}an\u{0020}unprecedented\u{0020}major\u{0020}crisis!\u{0020}\nWhile\u{0020}everyone\u{0020}has\u{0020}a\u{0020}different\u{0020}definition\u{0020}of\u{0020}a\u{0020}\"major\u{0020}crisis,\"\u{0020}and\u{0020}even\u{0020}the\u{0020}same\u{0020}person\u{0020}might\u{0020}judge\u{0020}the\u{0020}severity\u{0020}of\u{0020}the\u{0020}same\u{0020}situation\u{0020}differently\u{0020}depending\u{0020}on\u{0020}the\u{0020}time\u{0020}and\u{0020}circumstances,\u{0020}no\u{0020}matter\u{0020}how\u{0020}you\u{0020}look\u{0020}at\u{0020}it,\u{0020}for\u{0020}me,\u{0020}this\u{0020}is\u{0020}\"Miss\u{0020}Lyfa's\u{0020}major\u{0020}crisis!\"\u{0020}\nIn\u{0020}short,\u{0020}Miss\u{0020}Lyfa\u{0020}overslept!\u{0020}The\u{0020}planned\u{0020}birthday\u{0020}dinner\u{0020}can't\u{0020}be\u{0020}prepared\u{0020}in\u{0020}time!\u{0020}The\u{0020}image\u{0020}of\u{0020}the\u{0020}\"perfect\u{0020}maid\"\u{0020}is\u{0020}about\u{0020}to\u{0020}be\u{0020}ruined!\u{0020}I'm\u{0020}going\u{0020}to\u{0020}be\u{0020}laughed\u{0020}at\u{0020}by\u{0020}the\u{0020}First\u{0020}Guards\u{0020}Squad!\u{0020}\nPlease\u{0020}help\u{0020}think\u{0020}of\u{0020}a\u{0020}solution,\u{0020}Master!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110019] = {id = 110019, name = "Nozomi", head = "10019", type = 5, title = "I\u{0020}Want\u{0020}to\u{0020}Hear\u{0020}You\u{0020}Play\u{0020}and\u{0020}Sing\u{0020}Too", txt = "My\u{0020}birthday,\u{0020}huh...\nI\u{0020}remember\u{0020}back\u{0020}when\u{0020}I\u{0020}was\u{0020}in\u{0020}a\u{0020}band,\u{0020}I\u{0020}used\u{0020}to\u{0020}get\u{0020}tons\u{0020}of\u{0020}gifts\u{0020}from\u{0020}fans\u{0020}every\u{0020}birthday\u{0020}-\u{0020}I\u{0020}mean,\u{0020}from\u{0020}my\u{0020}bandmates.\u{0020}After\u{0020}all,\u{0020}my\u{0020}talent\u{0020}was\u{0020}right\u{0020}there\u{0020}for\u{0020}everyone\u{0020}to\u{0020}see.\u{0020}Being\u{0020}just\u{0020}an\u{0020}ordinary\u{0020}person\u{0020}and\u{0020}getting\u{0020}completely\u{0020}overshadowed\u{0020}by\u{0020}the\u{0020}brilliance\u{0020}of\u{0020}geniuses\u{0020}during\u{0020}performances\u{0020}was\u{0020}only\u{0020}natural.\u{0020}So\u{0020}in\u{0020}the\u{0020}end,\u{0020}only\u{0020}my\u{0020}friends\u{0020}and\u{0020}family\u{0020}ever\u{0020}really\u{0020}remembered\u{0020}my\u{0020}birthday.\nAlright,\u{0020}enough\u{0020}of\u{0020}that\u{0020}gloomy\u{0020}stuff.\u{0020}It\u{0020}just\u{0020}suddenly\u{0020}occurred\u{0020}to\u{0020}me\u{0020}that\u{0020}you\u{0020}were\u{0020}always\u{0020}the\u{0020}one\u{0020}listening\u{0020}to\u{0020}me\u{0020}play\u{0020}and\u{0020}sing\u{0020}from\u{0020}the\u{0020}sidelines\u{0020}before,\u{0020}right?\u{0020}Today,\u{0020}we\u{0020}can\u{0020}switch\u{0020}things\u{0020}around.\u{0020}The\u{0020}sheet\u{0020}music\u{0020}for\u{0020}\"Happy\u{0020}Birthday\"\u{0020}is\u{0020}not\u{0020}difficult\u{0020}anyway,\u{0020}so\u{0020}you\u{0020}should\u{0020}be\u{0020}able\u{0020}to\u{0020}pick\u{0020}it\u{0020}up\u{0020}quickly.\nAs\u{0020}for\u{0020}instruments\u{0020}-\u{0020}drums,\u{0020}guitar,\u{0020}saxophone,\u{0020}violin,\u{0020}piano...\u{0020}well,\u{0020}I\u{0020}can\u{0020}play\u{0020}and\u{0020}teach\u{0020}pretty\u{0020}much\u{0020}all\u{0020}the\u{0020}common\u{0020}ones,\u{0020}so\u{0020}just\u{0020}pick\u{0020}whichever\u{0020}one\u{0020}you\u{0020}want\u{0020}to\u{0020}try.\nOnce\u{0020}you\u{0020}have\u{0020}decided,\u{0020}remember\u{0020}to\u{0020}write\u{0020}back\u{0020}to\u{0020}me.\u{0020}I\u{0020}will\u{0020}tune\u{0020}it\u{0020}first,\u{0020}then\u{0020}bring\u{0020}it\u{0020}with\u{0020}me\u{0020}when\u{0020}I\u{0020}come\u{0020}to\u{0020}see\u{0020}you.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11001901] = {id = 11001901, name = "Nozomi", head = "10019", type = 5, title = "“向世界展示結束希的樂隊”", txt = "祝我今天生日快樂！！！嘿嘿……終於能大聲地說出這句話了。\n生日真是一個很神奇的日子呢。對我而言期待著生日的那些日子會很開心，過生日的時候當然是最很開心的時候，過完之後這份開心還會繼續陪伴我一段時間，所以我想我的生日是以一個月為單位計算的。\n那麼來做一些有意義的事情吧，為了紀念這一天要來和我來組建“一日樂隊”嗎？名字就叫“向世界展示結束希生日的時候很開心樂隊”，主打歌是我們兩人的生日快樂歌，嘿嘿……這首歌送給你也送我。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110020] = {id = 110020, name = "Mirai", head = "10020", type = 5, title = "Such\u{0020}a\u{0020}Popular\u{0020}Day", txt = "Hey,\u{0020}Mister\u{0020}Pervert,\u{0020}could\u{0020}you\u{0020}come\u{0020}over\u{0020}to\u{0020}my\u{0020}place\u{0020}and\u{0020}celebrate\u{0020}my\u{0020}birthday\u{0020}with\u{0020}me…?\u{0020}Since\u{0020}New\u{0020}Year's\u{0020}and\u{0020}my\u{0020}birthday\u{0020}happen\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}Mom\u{0020}and\u{0020}Dad\u{0020}prepared\u{0020}tons\u{0020}of\u{0020}food\u{0020}I\u{0020}love.\u{0020}There's\u{0020}no\u{0020}way\u{0020}I\u{0020}can\u{0020}finish\u{0020}it\u{0020}all\u{0020}by\u{0020}myself!\u{0020}I\u{0020}highly\u{0020}recommend\u{0020}you\u{0020}come\u{0020}try\u{0020}Mom's\u{0020}signature\u{0020}dishes!\u{0020}\nOh,\u{0020}and\u{0020}you'll\u{0020}also\u{0020}get\u{0020}to\u{0020}see\u{0020}me\u{0020}wearing\u{0020}something\u{0020}really,\u{0020}really\u{0020}cute.\u{0020}It's\u{0020}a\u{0020}brand-new\u{0020}outfit\u{0020}that\u{0020}Mister\u{0020}Pervert\u{0020}has\u{0020}never\u{0020}ever\u{0020}seen\u{0020}before~\u{0020}Being\u{0020}able\u{0020}to\u{0020}see\u{0020}me\u{0020}like\u{0020}this\u{0020}means\u{0020}Mister\u{0020}Pervert\u{0020}is\u{0020}the\u{0020}happiest\u{0020}person\u{0020}in\u{0020}the\u{0020}whole\u{0020}world,\u{0020}you\u{0020}know~\u{0020}\nSo\u{0020}hurry\u{0020}up\u{0020}and\u{0020}come\u{0020}already!\u{0020}I'll\u{0020}be\u{0020}waiting\u{0020}for\u{0020}you!\u{0020}Everyone's\u{0020}happy\u{0020}to\u{0020}have\u{0020}Mister\u{0020}Pervert\u{0020}here\u{0020}too!\u{0020}(But\u{0020}still\u{0020}not\u{0020}as\u{0020}popular\u{0020}as\u{0020}me.\u{0020}I\u{0020}guess\u{0020}Mister\u{0020}Pervert\u{0020}is\u{0020}second\u{0020}most\u{0020}popular!)", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110021] = {id = 110021, name = "Cynthia", head = "10021", type = 5, title = "兩人的信", txt = "是辛米亞提議寫信的。\n我跟她說了生日的事情，也準備了禮物，結果卻被反問為什麼特地巨大化找她……當然是想要和她一起慶生啊……\n今天是我的生日，也是辛米亞，明明說好了的……每年都這麼問，辛米亞是大傻蛋！\n辛西婭把紙和筆扔給我後就不理我了……\n她應該為我著想一下，這麽大的身體該怎麽寫字嘛……\n巨大化後她和我說了很多有關於你的事情。她很喜歡你，我能聽出來。那麼相比於我，今天這個難得的日子，她更應該和你呆在一起才對。\n可是不管怎麼勸說，她都不肯取消巨大化。我只好提議寫信。\n你看到這封信後，來帶她去過一個難忘的生日吧。navigator，拜託了。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002101] = {id = 11002101, name = "Cynthia", head = "10021", type = 5, title = "三人慶生！", txt = "對於“倆人一體”的我們來說，生日是同一天是理所當然的。\n但是，navigator你也是知道的……通常情況下，“辛西婭”和“辛米亞”是沒辦法一起度過生日的，除非……\n好啦，我就不裝神弄鬼啦，總之現在是辛米亞，也就是我在寫信！\n今年的我們決定和navigator你一起度過生日，為了實現這一目的，辛西婭特地申請了巡邏任務。\n接下來只要你同意，我們就可以用巡邏任務當做三人慶生的方式啦！\n雖然這樣做有點瀆職……但只要任務也好好完成就會被原諒吧？\nnavigator，快來，這時候的我們應該已經準備萬全了！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002102] = {id = 11002102, name = "Cynthia", head = "10021", type = 5, title = "A\u{0020}Letter\u{0020}from\u{0020}Two", txt = "Cynemia\u{0020}made\u{0020}me\u{0020}write\u{0020}this.\nI\u{0020}told\u{0020}her\u{0020}it's\u{0020}our\u{0020}birthday,\u{0020}even\u{0020}got\u{0020}gifts...\u{0020}Then\u{0020}she\u{0020}asked\u{0020}why\u{0020}I\u{0020}went\u{0020}through\u{0020}the\u{0020}trouble\u{0020}of\u{0020}gigantifying\u{0020}just\u{0020}to\u{0020}find\u{0020}her...\u{0020}Well,\u{0020}obviously\u{0020}because\u{0020}I\u{0020}wanted\u{0020}to\u{0020}celebrate\u{0020}with\u{0020}her!\nIt's\u{0020}my\u{0020}day\u{0020}and\u{0020}hers.\u{0020}We\u{0020}agreed\u{0020}on\u{0020}this!\u{0020}She\u{0020}asks\u{0020}the\u{0020}same\u{0020}question\u{0020}every\u{0020}year...\u{0020}Cynemia's\u{0020}an\u{0020}idiot!\n\n\n\u{0020}ynthia\u{0020}tossed\u{0020}me\u{0020}paper\u{0020}and\u{0020}pen,\u{0020}then\u{0020}ignored\u{0020}me...\nShe\u{0020}really\u{0020}should've\u{0020}thought\u{0020}about\u{0020}how\u{0020}hard\u{0020}it\u{0020}is\u{0020}to\u{0020}write\u{0020}with\u{0020}this\u{0020}big\u{0020}body...\nWhile\u{0020}giant,\u{0020}she\u{0020}talked\u{0020}about\u{0020}you\u{0020}nonstop.\u{0020}I\u{0020}can\u{0020}tell,\u{0020}she\u{0020}really\u{0020}likes\u{0020}you.\u{0020}So\u{0020}today,\u{0020}of\u{0020}all\u{0020}days,\u{0020}she\u{0020}should\u{0020}be\u{0020}with\u{0020}you,\u{0020}not\u{0020}me.\nBut\u{0020}she\u{0020}refuses\u{0020}to\u{0020}shrink\u{0020}back,\u{0020}no\u{0020}matter\u{0020}how\u{0020}I\u{0020}tried\u{0020}to\u{0020}convince\u{0020}her.\u{0020}Hence\u{0020}this\u{0020}letter.\nNavigator,\u{0020}after\u{0020}reading\u{0020}this,\u{0020}take\u{0020}her\u{0020}out\u{0020}and\u{0020}give\u{0020}her\u{0020}a\u{0020}memorable\u{0020}birthday.\u{0020}Please.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002103] = {id = 11002103, name = "Cynthia", head = "10021", type = 5, title = "A\u{0020}Birthday\u{0020}Celebration\u{0020}for\u{0020}Three!", txt = "For\u{0020}the\u{0020}two\u{0020}of\u{0020}us,\u{0020}who\u{0020}are\u{0020}\"two\u{0020}in\u{0020}one\",\u{0020}it\u{0020}is\u{0020}only\u{0020}natural\u{0020}that\u{0020}our\u{0020}birthday\u{0020}falls\u{0020}on\u{0020}the\u{0020}same\u{0020}day.\nBut\u{0020}you\u{0020}know\u{0020}this\u{0020}too,\u{0020}Navigator...\u{0020}under\u{0020}normal\u{0020}circumstances,\u{0020}\"Cynthia\"\u{0020}and\u{0020}\"Cynemia\"\u{0020}cannot\u{0020}spend\u{0020}their\u{0020}birthday\u{0020}together,\u{0020}unless...\nAlright,\u{0020}I\u{0020}will\u{0020}stop\u{0020}being\u{0020}all\u{0020}mysterious.\u{0020}Anyway,\u{0020}right\u{0020}now\u{0020}it\u{0020}is\u{0020}Cynemia\u{0020}-\u{0020}that\u{0020}is,\u{0020}me\u{0020}-\u{0020}writing\u{0020}this\u{0020}letter!\nThis\u{0020}year,\u{0020}we\u{0020}decided\u{0020}to\u{0020}spend\u{0020}our\u{0020}birthday\u{0020}together\u{0020}with\u{0020}you,\u{0020}Navigator,\u{0020}and\u{0020}to\u{0020}make\u{0020}that\u{0020}happen,\u{0020}Cynthia\u{0020}specially\u{0020}applied\u{0020}for\u{0020}a\u{0020}patrol\u{0020}mission.\nNow,\u{0020}as\u{0020}long\u{0020}as\u{0020}you\u{0020}agree,\u{0020}we\u{0020}can\u{0020}use\u{0020}the\u{0020}patrol\u{0020}mission\u{0020}as\u{0020}our\u{0020}way\u{0020}of\u{0020}celebrating\u{0020}the\u{0020}birthday\u{0020}together,\u{0020}the\u{0020}three\u{0020}of\u{0020}us!\nAlthough\u{0020}doing\u{0020}this\u{0020}is\u{0020}a\u{0020}bit\u{0020}of\u{0020}a\u{0020}dereliction\u{0020}of\u{0020}duty...\u{0020}as\u{0020}long\u{0020}as\u{0020}we\u{0020}complete\u{0020}the\u{0020}mission\u{0020}properly\u{0020}too,\u{0020}we\u{0020}will\u{0020}probably\u{0020}be\u{0020}forgiven,\u{0020}right?\nNavigator,\u{0020}come\u{0020}on,\u{0020}hurry\u{0020}over\u{0020}-\u{0020}by\u{0020}this\u{0020}time,\u{0020}we\u{0020}should\u{0020}already\u{0020}be\u{0020}fully\u{0020}prepared!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110022] = {id = 110022, name = "Fafnir", head = "10022", type = 5, title = "The\u{0020}Evil\u{0020}Dragon\u{0020}and\u{0020}Chocolate\u{0020}Mousse", txt = "I\u{0020}did\u{0020}not\u{0020}expect\u{0020}retribution\u{0020}to\u{0020}fall\u{0020}upon\u{0020}me\u{0020}so\u{0020}quickly.\u{0020}It\u{0020}is\u{0020}already\u{0020}too\u{0020}late\u{0020}for\u{0020}words\u{0020}of\u{0020}repentance.\u{0020}Although\u{0020}I\u{0020}briefly\u{0020}ended\u{0020}up\u{0020}in\u{0020}the\u{0020}same\u{0020}awkward\u{0020}situation\u{0020}as\u{0020}Mel,\u{0020}whose\u{0020}birthday\u{0020}was\u{0020}yesterday,\u{0020}the\u{0020}three\u{0020}of\u{0020}them\u{0020}were\u{0020}still\u{0020}rather\u{0020}overestimating\u{0020}themselves\u{0020}if\u{0020}they\u{0020}thought\u{0020}they\u{0020}could\u{0020}tame\u{0020}an\u{0020}evil\u{0020}dragon\u{0020}on\u{0020}their\u{0020}own.\u{0020}A\u{0020}fierce\u{0020}battle\u{0020}was\u{0020}unavoidable,\u{0020}and\u{0020}even\u{0020}now\u{0020}my\u{0020}arms\u{0020}are\u{0020}still\u{0020}somewhat\u{0020}numb.\u{0020}Fortunately,\u{0020}I\u{0020}managed\u{0020}to\u{0020}leave\u{0020}the\u{0020}training\u{0020}grounds\u{0020}before\u{0020}losing\u{0020}control\u{0020}completely.\nDuring\u{0020}this\u{0020}once-a-year\u{0020}birthday\u{0020}time,\u{0020}I\u{0020}can\u{0020}feel\u{0020}the\u{0020}evil\u{0020}dragon\u{0020}within\u{0020}my\u{0020}heart\u{0020}growing\u{0020}restless,\u{0020}and\u{0020}only\u{0020}cake\u{0020}can\u{0020}soothe\u{0020}it.\u{0020}The\u{0020}evil\u{0020}dragon\u{0020}told\u{0020}me\u{0020}she\u{0020}wants\u{0020}to\u{0020}eat\u{0020}chocolate\u{0020}mousse\u{0020}cake,\u{0020}drizzled\u{0020}with\u{0020}a\u{0020}sweet\u{0020}syrup\u{0020}made\u{0020}from\u{0020}whipped\u{0020}cream,\u{0020}honey,\u{0020}and\u{0020}crushed\u{0020}hazelnuts,\u{0020}paired\u{0020}with\u{0020}a\u{0020}cup\u{0020}of\u{0020}hot\u{0020}cocoa\u{0020}dusted\u{0020}generously\u{0020}with\u{0020}chocolate\u{0020}powder.\nThe\u{0020}evil\u{0020