[11002301] = {id = 11002301, name = "Mo", head = "10023", type = 5, title = "Sweater\u{0020}or\u{0020}Scarf?", txt = "I\u{0020}don't\u{0020}want\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday,\u{0020}Mo.\u{0020}Every\u{0020}birthday\u{0020}means\u{0020}I'm\u{0020}another\u{0020}year\u{0020}older,\u{0020}Mo.\u{0020}Especially\u{0020}since\u{0020}a\u{0020}year\u{0020}on\u{0020}Earth\u{0020}is\u{0020}so\u{0020}short,\u{0020}it\u{0020}feels\u{0020}like\u{0020}life\u{0020}is\u{0020}slipping\u{0020}away\u{0020}in\u{0020}a\u{0020}flash,\u{0020}Mo.\u{0020}\nBirth,\u{0020}aging,\u{0020}sickness,\u{0020}and\u{0020}death...\u{0020}I\u{0020}really\u{0020}wish\u{0020}I\u{0020}could\u{0020}change\u{0020}the\u{0020}laws\u{0020}of\u{0020}nature,\u{0020}Mo.\u{0020}But\u{0020}even\u{0020}if\u{0020}I\u{0020}could\u{0020}slow\u{0020}down\u{0020}aging,\u{0020}there's\u{0020}still\u{0020}sickness\u{0020}and\u{0020}death\u{0020}to\u{0020}overcome,\u{0020}Mo.\u{0020}Still,\u{0020}I\u{0020}don't\u{0020}really\u{0020}have\u{0020}the\u{0020}right\u{0020}to\u{0020}complain,\u{0020}Mo.\u{0020}After\u{0020}all,\u{0020}I'm\u{0020}not\u{0020}so\u{0020}old\u{0020}that\u{0020}I\u{0020}have\u{0020}one\u{0020}foot\u{0020}in\u{0020}the\u{0020}grave\u{0020}yet,\u{0020}Mo.\u{0020}\nBy\u{0020}the\u{0020}way,\u{0020}I\u{0020}wanted\u{0020}to\u{0020}ask\u{0020}you,\u{0020}Navigator,\u{0020}do\u{0020}you\u{0020}prefer\u{0020}sweaters\u{0020}or\u{0020}scarves...\u{0020}Maybe\u{0020}it's\u{0020}because\u{0020}of\u{0020}the\u{0020}season,\u{0020}but\u{0020}lately\u{0020}I've\u{0020}been\u{0020}shedding\u{0020}a\u{0020}lot\u{0020}of\u{0020}fur,\u{0020}Mo.\u{0020}I've\u{0020}collected\u{0020}enough\u{0020}to\u{0020}make\u{0020}a\u{0020}piece\u{0020}of\u{0020}clothing,\u{0020}Mo.\u{0020}Since\u{0020}I\u{0020}have\u{0020}nothing\u{0020}to\u{0020}do\u{0020}right\u{0020}now\u{0020}anyway,\u{0020}I\u{0020}have\u{0020}plenty\u{0020}of\u{0020}time\u{0020}to\u{0020}knit.\u{0020}You've\u{0020}never\u{0020}worn\u{002