_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002601] = {id = 11002601, name = "Nastya", head = "10026", type = 5, title = "Concert\u{0020}Invitation", txt = "You\u{0020}didn't\u{0020}forget\u{0020}what\u{0020}day\u{0020}it\u{0020}is\u{0020}today...\u{0020}right?\nGo\u{0020}on,\u{0020}guess\u{0020}how\u{0020}I'm\u{0020}celebrating\u{0020}this\u{0020}year.\u{0020}Actually,\u{0020}never\u{0020}mind.\u{0020}With\u{0020}that\u{0020}pea-sized\u{0020}brain\u{0020}of\u{0020}yours,\u{0020}even\u{0020}if\u{0020}you\u{0020}squeezed\u{0020}it\u{0020}dry\u{0020}you'd\u{0020}never\u{0020}come\u{0020}up\u{0020}with\u{0020}an\u{0020}idea\u{0020}as\u{0020}brilliant\u{0020}as\u{0020}mine.\u{0020}I'm\u{0020}having\u{0020}Sins\u{0020}sing\u{0020}\"Happy\u{0020}Birthday\"\u{0020}to\u{0020}me,\u{0020}and\u{0020}not\u{0020}just\u{0020}one.\u{0020}A\u{0020}whole\u{0020}group.\nA\u{0020}choir\u{0020}of\u{0020}massive,\u{0020}vicious\u{0020}monsters\u{0020}singing\u{0020}for\u{0020}my\u{0020}birthday.\u{0020}Just\u{0020}imagining\u{0020}it\u{0020}is\u{0020}enough\u{0020}to\u{0020}move\u{0020}a\u{0020}girl\u{0020}to\u{0020}tears.\nThe\u{0020}choir\u{0020}is\u{0020}already\u{0020}assembled.\u{0020}We\u{0020}even\u{0020}have\u{0020}a\u{0020}Major\u{0020}one\u{0020}acting\u{0020}as\u{0020}the\u{0020}lead\u{0020}vocalist.\u{0020}Now\u{0020}we\u{0020}just\u{0020}need\u{0020}a\u{0020}conductor.\u{0020}And\u{0020}really,\u{0020}who\u{0020}could\u{0020}be\u{0020}more\u{0020}suitable\u{0020}than\u{0020}you,\u{0020}my\u{0020}Navigator?\nDon't\u{0020}worry\u{0020}about\u{0020}safety.\u{0020}They\u{0020}are\u{0020}just\u{0020}lab\u{0020}test\u{0020}animals\u{0020}anyway.\u{0020}We'll\u{0020}be\u{0020}listening\u{0020}to\u{0020}this...\u{0020}exquisite\u{0020}performance\u{0020}together\u{0020}in\u{0020}a\u{0020}perfectly\u{0020}safe,\u{0020}quiet\u{0020}room.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
