[110028] = {id = 110028, name = "Mojun", head = "10028", type = 5, title = "Looking\u{0020}Forward\u{0020}to\u{0020}Tomorrow's\u{0020}Meeting", txt = "I\u{0020}hope\u{0020}this\u{0020}letter\u{0020}finds\u{0020}you\u{0020}well.\nEvery\u{0020}year\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}my\u{0020}old\u{0020}students\u{0020}come\u{0020}to\u{0020}visit.\u{0020}That\u{0020}many\u{0020}have\u{0020}already\u{0020}made\u{0020}their\u{0020}mark\u{0020}in\u{0020}the\u{0020}world\u{0020}truly\u{0020}gladdens\u{0020}my\u{0020}heart.\nHowever,\u{0020}today,\u{0020}amidst\u{0020}the\u{0020}celebration,\u{0020}someone\u{0020}said\u{0020}that\u{0020}my\u{0020}recent\u{0020}lectures\u{0020}seem\u{0020}less\u{0020}severe\u{0020}than\u{0020}before,\u{0020}and\u{0020}asked\u{0020}if\u{0020}I\u{0020}had\u{0020}something\u{0020}happy\u{0020}to\u{0020}share.\u{0020}At\u{0020}the\u{0020}time,\u{0020}I\u{0020}did\u{0020}not\u{0020}respond,\u{0020}thinking\u{0020}it\u{0020}was\u{0020}merely\u{0020}a\u{0020}jest\u{0020}not\u{0020}to\u{0020}be\u{0020}taken\u{0020}seriously.\u{0020}Only\u{0020}after\u{0020}their\u{0020}departure,\u{0020}upon\u{0020}reflection,\u{0020}I\u{0020}realized\u{0020}there\u{0020}might\u{0020}indeed\u{0020}be\u{0020}some\u{0020}truth\u{0020}to\u{0020}it.\nNavigator,\u{0020}I\u{0020}think\u{0020}it's\u{0020}all\u{0020}because\u{0020}of\u{0020}you.\nSince\u{0020}we\u{0020}met,\u{0020}the\u{0020}gentleness\u{0020}with\u{0020}which\u{0020}you\u{0020}guide\u{0020}the\u{0020}Drivers,\u{0020}and\u{0020}that\u{0020}remarkable\u{0020}patience\u{0020}capable\u{0020}of\u{0020}shaping\u{0020}even\u{0020}the\u{0020}most\u{0020}unpromising\u{0020}material\u{0020}into\u{0020}excellence,\u{0020}has\u{0020}revealed\u{0020}to\u{0020}me\u{0020}an\u{0020}alternative\u{0020}approach\u{0020}to\u{0020}teaching,\u{0020}and\u{0020}that\u{0020}I\u{0020}failed\u{0020}to\u{0020}recognize\u{0020}this\u{0020}sooner\u{0020}fills\u{0020}me\u{0020}with\u{0020}regret,\u{0020}though\u{0020}fortunately\u{0020}not\u{0020}too\u{0020}late.\u{0020}Thus,\u{0020}I'm\u{0020}writing\u{0020}it\u{0020}to\u{0020}capture\u{0020}these\u{0020}thoughts,\u{0020}yet\u{0020}words\u{0020}fail\u{0020}me.\u{0020}I\u{0020}can\u{0020}only\u{0020}hope\u{0020}to\u{0020}complete\u{0020}this\u{0020}conversation\u{0020}in\u{0020}person.\u{0020}Might\u{0020}you\u{0020}have\u{0020}time\u{0020}to\u{0020}meet\u{0020}tomorrow?\n\nI\u{0020}look\u{0020}forward\u{0020}to\u{0020}your\u{0020}reply.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110029] = {id = 110029, name = "Lily", head = "10029", type = 5, title = "I'll\u{0020}Do\u{0020}My\u{0020}Best\u{0020}for\u{0020}the\u{0020}Birthday!", txt = "The\u{0020}one\u{0020}who\u{0020}always\u{0020}looked\u{0020}after\u{0020}us...\u{0020}isn't\u{0020}here\u{0020}anymore.\u{0020}And\u{0020}Levi\u{0020}never\u{0020}cares\u{0020}about\u{0020}birthdays.\u{0020}So\u{0020}this\u{0020}time,\u{0020}I\u{0020}have\u{0020}to\u{0020}step\u{0020}up!\nNavigator,\u{0020}please\u{0020}help\u{0020}me!\u{0020}Let's\u{0020}throw\u{0020}a\u{0020}birthday\u{0020}banquet\u{0020}that\u{0020}everyone\u{0020}can\u{0020}enjoy!\nLevi\u{0020}would\u{0020}probably\u{0020}like\u{0020}something\u{0020}romantic...\u{0020}And\u{0020}Miss\u{0020}Chiaki...\u{0020}Oh,\u{0020}an\u{0020}ice\u{0020}cream\u{0020}burger\u{0020}would\u{0020}be\u{0020}nice,\u{0020}right?\nWhat\u{0020}about\u{0020}you,\u{0020}Navigator?\u{0020}What\u{0020}kind\u{0020}of\u{0020}party\u{0020}would\u{0020}you\u{0020}like?\u{0020}Please\u{0020}reply\u{0020}ASAP!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11002901] = {id = 11002901, name = "Lily", head = "10029", type = 5, title = "I\u{0020}Hope\u{0020}We\u{0020}Can\u{0020}All\u{0020}Celebrate\u{0020}Together\u{0020}Again\u{0020}This\u{0020}Year", txt = "You\u{0020}must\u{0020}have\u{0020}been\u{0020}especially\u{0020}busy\u{0020}lately,\u{0020}Navigator...\u{0020}Mm,\u{0020}even\u{0020}if\u{0020}you\u{0020}don't\u{0020}say\u{0020}anything,\u{0020}I\u{0020}know.\nWhether\u{0020}aboard\u{0020}the\u{0020}Kyushu\u{0020}Ark\u{0020}or\u{0020}the\u{0020}Danube\u{0020}Ark,\u{0020}rumors\u{0020}have\u{0020}been\u{0020}circulating\u{0020}among\u{0020}the\u{0020}Drivers\u{0020}about\u{0020}how\u{0020}you've\u{0020}been\u{0020}working\u{0020}behind\u{0020}the\u{0020}scenes.\nAnd\u{0020}it\u{0020}isn't\u{0020}just\u{0020}you.\u{0020}Miss\u{0020}Chiaki...\u{0020}Ahem--Chiaki,\u{0020}and\u{0020}Miss\u{0020}Starry\u{0020}too,\u{0020}must\u{0020}be\u{0020}traveling\u{0020}all\u{0020}over\u{0020}the\u{0020}world\u{0020}to\u{0020}fulfill\u{0020}their\u{0020}respective\u{0020}missions.\nAt\u{0020}times\u{0020}like\u{0020}these,\u{0020}I\u{0020}find\u{0020}myself\u{0020}thinking\u{0020}that\u{0020}\"birthdays\"\u{0020}are\u{0020}truly\u{0020}a\u{0020}wonderful\u{0020}invention.\u{0020}Thanks\u{0020}to\u{0020}\"birthdays,\"\u{0020}I\u{0020}have\u{0020}an\u{0020}excuse\u{0020}to\u{0020}bring\u{0020}everyone\u{0020}together.\nThis\u{0020}year,\u{0020}Levi\u{0020}and\u{0020}I\u{0020}will\u{0020}be\u{0020}waiting\u{0020}aboard\u{0020}the\u{0020}Ark\u{0020}for\u{0020}everyone\u{0020}to\u{0020}return!\nPlease\u{0020}make\u{0020}sure\u{0020}you\u{0020}come!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110030] = {id = 110030, name = "Farnese", head = "10030", type = 5, title = "權當一次考驗", txt = "誠如您所知，今天是我的生日，根據蘭特家族的傳統，我會回自己出生時的那座莊園赴宴，重遊那座春意盎然的花園。\n不過所謂宴會，其實也只是種說法罷了，對於家族內部成員而言，我們更愛叫它“派對”，因為這裡不會邀請陌生人，也沒有社交場合那種繁文縟節，它只為開心而存在。\n我很想邀請您一同參加這場派對，但又考慮到我們家族樹敵不少，塔斯卡尼不算太平，只能看您自己如何決定……或者，就當是我對您勇氣的一點小小考驗也好？呵呵，總之，啟程的專機已經備好，如有意願還望盡快回復。\n期待與您一起分享主廚最拿手的那道墨魚汁燴墨魚。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003001] = {id = 11003001, name = "Farnese", head = "10030", type = 5, title = "Consider\u{0020}It\u{0020}a\u{0020}Test\u{0020}of\u{0020}Courage", txt = "As\u{0020}you\u{0020}may\u{0020}already\u{0020}know,\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday.\u{0020}According\u{0020}to\u{0020}the\u{0020}Lante\u{0020}family\u{0020}tradition,\u{0020}I\u{0020}will\u{0020}be\u{0020}returning\u{0020}to\u{0020}the\u{0020}manor\u{0020}of\u{0020}my\u{0020}birth\u{0020}to\u{0020}attend\u{0020}a\u{0020}banquet\u{0020}and\u{0020}take\u{0020}a\u{0020}stroll\u{0020}through\u{0020}the\u{0020}lush\u{0020}garden\u{0020}that\u{0020}welcomes\u{0020}the\u{0020}arrival\u{0020}of\u{0020}spring.\nThat\u{0020}said,\u{0020}the\u{0020}word\u{0020}\"banquet\"\u{0020}is\u{0020}a\u{0020}bit\u{0020}of\u{0020}an\u{0020}understatement.\u{0020}For\u{0020}family\u{0020}members,\u{0020}we\u{0020}prefer\u{0020}to\u{0020}call\u{0020}it\u{0020}a\u{0020}\"party,\"\u{0020}as\u{0020}no\u{0020}outsiders\u{0020}are\u{0020}invited,\u{0020}and\u{0020}there\u{0020}are\u{0020}no\u{0020}formalities\u{0020}to\u{0020}speak\u{0020}of.\u{0020}It's\u{0020}simply\u{0020}a\u{0020}gathering\u{0020}meant\u{0020}for\u{0020}enjoyment.\nI\u{0020}would\u{0020}be\u{0020}delighted\u{0020}to\u{0020}have\u{0020}you\u{0020}join\u{0020}us\u{0020}for\u{0020}this\u{0020}celebration,\u{0020}but\u{0020}considering\u{0020}our\u{0020}family\u{0020}has\u{0020}its\u{0020}fair\u{0020}share\u{0020}of\u{0020}enemies,\u{0020}and\u{0020}Tuscany\u{0020}is\u{0020}hardly\u{0020}a\u{0020}peaceful\u{0020}place,\u{0020}the\u{0020}decision\u{0020}is\u{0020}entirely\u{0020}up\u{0020}to\u{0020}you…\u{0020}Or,\u{0020}perhaps,\u{0020}you\u{0020}could\u{0020}see\u{0020}it\u{0020}as\u{0020}a\u{0020}small\u{0020}test\u{0020}of\u{0020}your\u{0020}courage?\u{0020}Heh.\u{0020}Either\u{0020}way,\u{0020}the\u{0020}private\u{0020}jet\u{0020}is\u{0020}ready,\u{0020}and\u{0020}should\u{0020}you\u{0020}wish\u{0020}to\u{0020}join,\u{0020}I\u{0020}would\u{0020}appreciate\u{0020}a\u{0020}prompt\u{0020}reply.\nI\u{0020}look\u{0020}forward\u{0020}to\u{0020}sharing\u{0020}the\u{0020}chef's\u{0020}signature\u{0020}dish—squid\u{0020}in\u{0020}squid\u{0020}ink\u{0020}sauce—with\u{0020}you.\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003002] = {id = 11003002, name = "Farnese", head = "10030", type = 5, title = "A\u{0020}Strange\u{0020}Smell\u{0020}Before\u{0020}the\u{0020}Party\u{0020}Begins", txt = "When\u{0020}a\u{0020}9x19mm\u{0020}pistol\u{0020}round\u{0020}pierced\u{0020}the\u{0020}manor's\u{0020}green\u{0020}leaves,\u{0020}the\u{0020}gunpowder\u{0020}hanging\u{0020}in\u{0020}the\u{0020}air\u{0020}stabbed\u{0020}my\u{0020}nose\u{0020}like\u{0020}a\u{0020}sudden\u{0020}needle,\u{0020}and\u{0020}I\u{0020}understood\u{0020}that\u{0020}this\u{0020}year's\u{0020}birthday\u{0020}party\u{0020}was\u{0020}destined\u{0020}to\u{0020}be\u{0020}spoiled\u{0020}by\u{0020}someone\u{0020}with\u{0020}no\u{0020}sense\u{0020}of\u{0020}occasion.\u{0020}\nAs\u{0020}you\u{0020}know,\u{0020}my\u{0020}family\u{0020}isn't\u{0020}exactly\u{0020}welcome\u{0020}in\u{0020}Tuscany.\u{0020}There\u{0020}are\u{0020}always\u{0020}blind\u{0020}fools\u{0020}who\u{0020}try\u{0020}every\u{0020}possible\u{0020}way\u{0020}to\u{0020}make\u{0020}trouble\u{0020}for\u{0020}us.\u{0020}\nDon't\u{0020}worry,\u{0020}the\u{0020}party\u{0020}will\u{0020}still\u{0020}be\u{0020}held\u{0020}on\u{0020}time,\u{0020}and\u{0020}the\u{0020}invitation\u{0020}I\u{0020}sent\u{0020}you\u{0020}remains\u{0020}valid.\u{0020}\nWhen\u{0020}your\u{0020}private\u{0020}aircraft\u{0020}touches\u{0020}down,\u{0020}I\u{0020}will\u{0020}personally\u{0020}greet\u{0020}you\u{0020}and\u{0020}show\u{0020}you\u{0020}the\u{0020}highest\u{0020}level\u{0020}of\u{0020}hospitality\u{0020}the\u{0020}Lante\u{0020}family\u{0020}can\u{0020}offer.\u{0020}\nIt's\u{0020}just\u{0020}a\u{0020}shame\u{0020}that\u{0020}the\u{0020}smell\u{0020}of\u{0020}gunpowder\u{0020}likely\u{0020}won't\u{0020}fade\u{0020}so\u{0020}quickly.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110031] = {id = 110031, name = "Ophelia", head = "10031", type = 5, title = "Awaiting\u{0020}Your\u{0020}Reply", txt = "Sorry\u{0020}to\u{0020}interrupt...\u{0020}but\u{0020}I\u{0020}was\u{0020}wondering\u{0020}if\u{0020}you\u{0020}might\u{0020}have\u{0020}some\u{0020}free\u{0020}time\u{0020}today,\u{0020}Navigator.\nIt's\u{0020}nothing\u{0020}particularly\u{0020}special,\u{0020}really.\u{0020}My\u{0020}family\u{0020}suddenly\u{0020}called\u{0020}to\u{0020}wish\u{0020}me\u{0020}a\u{0020}happy\u{0020}birthday,\u{0020}which\u{0020}reminded\u{0020}me\u{0020}of\u{0020}it.\u{0020}When\u{0020}I\u{0020}was\u{0020}younger,\u{0020}Grandma\u{0020}would\u{0020}prepare\u{0020}a\u{0020}big\u{0020}feast\u{0020}and\u{0020}never\u{0020}let\u{0020}me\u{0020}help\u{0020}in\u{0020}the\u{0020}kitchen,\u{0020}saying\u{0020}Mom\u{0020}and\u{0020}Dad\u{0020}had\u{0020}it\u{0020}covered.\u{0020}I\u{0020}only\u{0020}needed\u{0020}to\u{0020}enjoy...\u{0020}But\u{0020}this\u{0020}year,\u{0020}when\u{0020}I\u{0020}suggested\u{0020}returning\u{0020}home,\u{0020}they\u{0020}insisted\u{0020}I\u{0020}stay\u{0020}here\u{0020}and\u{0020}enjoy\u{0020}celebrating\u{0020}with\u{0020}friends,\u{0020}saying\u{0020}it's\u{0020}important\u{0020}to\u{0020}have\u{0020}a\u{0020}birthday\u{0020}party\u{0020}in\u{0020}the\u{0020}city.\nSo,\u{0020}I\u{0020}thought\u{0020}of\u{0020}you,\u{0020}Navigator.\u{0020}I\u{0020}recall\u{0020}you\u{0020}once\u{0020}mentioned\u{0020}taking\u{0020}me\u{0020}to\u{0020}the\u{0020}shopping\u{0020}street,\u{0020}to\u{0020}the\u{0020}amusement\u{0020}park,\u{0020}or\u{0020}maybe\u{0020}to\u{0020}the\u{0020}movies...\u{0020}But\u{0020}honestly,\u{0020}I'd\u{0020}be\u{0020}happy\u{0020}doing\u{0020}anything\u{0020}as\u{0020}long\u{0020}as\u{0020}I\u{0020}have\u{0020}you\u{0020}with\u{0020}me.\u{0020}Of\u{0020}course,\u{0020}if\u{0020}you're\u{0020}busy,\u{0020}that's\u{0020}perfectly\u{0020}fine.\u{0020}I'll\u{0020}wait\u{0020}for\u{0020}your\u{0020}reply.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110032] = {id = 110032, name = "Christina", head = "10032", type = 5, title = "已經沒有多餘的時間了", txt = "非常糟糕……今天竟然是我的生日，但是這一周我已經沒有多餘的時間了，就連透支的部分也沒有了。\n今天晚上還有一組數據沒有測，果然過生日對我這種人來說太浪費時間……有辦法了，navigator要不要來實驗室和我一起過？剛好我這裏有一份基於尼姆比斯能的有趣報告，如果實驗順利的話，晚上還能吃到我親自做的蛋糕呢。你不好奇嗎？用尼姆比斯能幻化出的草莓蛋糕會是什麼味道。\n不過也只能僅此一次了，畢竟用珍貴的能源來生成廉價的蛋糕，太過於奢侈了……聽起來還有點不符合我審美夢幻色彩。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
