[110033] = {id = 110033, name = "Courant", head = "10033", type = 5, title = "About\u{0020}That\u{0020}Birthday\u{0020}Message\u{0020}You\u{0020}Sent", txt = "Since\u{0020}you\u{0020}sent\u{0020}me\u{0020}a\u{0020}birthday\u{0020}message...\u{0020}Sorry,\u{0020}it\u{0020}was\u{0020}my\u{0020}oversight.\u{0020}I\u{0020}forgot\u{0020}to\u{0020}explain\u{0020}the\u{0020}situation\u{0020}beforehand.\nAlthough\u{0020}my\u{0020}file\u{0020}does\u{0020}indeed\u{0020}show\u{0020}that\u{0020}my\u{0020}birthday\u{0020}is\u{0020}today,\u{0020}the\u{0020}truth\u{0020}is,\u{0020}since\u{0020}the\u{0020}Driver\u{0020}has\u{0020}to\u{0020}fill\u{0020}in\u{0020}the\u{0020}form,\u{0020}I\u{0020}just\u{0020}randomly\u{0020}pick\u{0020}a\u{0020}date.\nWell,\u{0020}it\u{0020}wasn't\u{0020}entirely\u{0020}random.\u{0020}At\u{0020}least,\u{0020}the\u{0020}lab\u{0020}records\u{0020}show\u{0020}I\u{0020}was\u{0020}born\u{0020}around\u{0020}November.\u{0020}So\u{0020}it's\u{0020}not\u{0020}really\u{0020}a\u{0020}lie;\u{0020}the\u{0020}month\u{0020}is\u{0020}correct.\nMaybe\u{0020}you're\u{0020}curious\u{0020}why\u{0020}it's\u{0020}not\u{0020}the\u{0020}31st,\u{0020}or\u{0020}the\u{0020}15th,\u{0020}but\u{0020}the\u{0020}1st.\u{0020}The\u{0020}reason\u{0020}is\u{0020}simple.\nIt's\u{0020}easy\u{0020}to\u{0020}remember.\u{0020}The\u{0020}first\u{0020}day\u{0020}of\u{0020}the\u{0020}month.\nThough\u{0020}honestly...\u{0020}the\u{0020}day\u{0020}we\u{0020}first\u{0020}met\u{0020}is\u{0020}probably\u{0020}more\u{0020}memorable\u{0020}than\u{0020}any\u{0020}birthday.\u{0020}And\u{0020}more\u{0020}meaningful\u{0020}too.\u{0020}You\u{0020}know\u{0020}what?\u{0020}I'm\u{0020}going\u{0020}to\u{0020}get\u{0020}my\u{0020}file\u{0020}changed.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
