[110035] = {id = 110035, name = "Hurley", head = "10035", type = 5, title = "No\u{0020}Bailing!!!", txt = "By\u{0020}the\u{0020}time\u{0020}you\u{0020}read\u{0020}this,\u{0020}I\u{0020}bet\u{0020}you\u{0020}already\u{0020}know.\u{0020}Yes,\u{0020}today's\u{0020}my\u{0020}birthday!\u{0020}My\u{0020}first\u{0020}birthday\u{0020}since\u{0020}joining\u{0020}AEGIS!\nYeah,\u{0020}yeah,\u{0020}I\u{0020}know\u{0020}you've\u{0020}probably\u{0020}been\u{0020}to\u{0020}tons\u{0020}of\u{0020}birthday\u{0020}parties,\u{0020}thinking,\u{0020}\"Pfft,\u{0020}it's\u{0020}just\u{0020}Hurley's\u{0020}birthday,\u{0020}no\u{0020}big\u{0020}deal.\"\u{0020}BUT!\u{0020}Today's\u{0020}my\u{0020}day,\u{0020}and\u{0020}it\u{0020}matters\u{0020}to\u{0020}me!\nAs\u{0020}for\u{0020}the\u{0020}guest\u{0020}list...\u{0020}You,\u{0020}the\u{0020}Boss,\u{0020}that\u{0020}grumpy\u{0020}Prisoner,\u{0020}Starry,\u{0020}and...\u{0020}oh\u{0020}right,\u{0020}my\u{0020}squadmates\u{0020}too!\nIf\u{0020}you\u{0020}wanna\u{0020}invite\u{0020}anyone\u{0020}else,\u{0020}go\u{0020}ahead.\u{0020}I\u{0020}got\u{0020}a\u{0020}massive\u{0020}cake\u{0020}and\u{0020}enough\u{0020}steak\u{0020}to\u{0020}feed\u{0020}an\u{0020}army.\u{0020}No\u{0020}way\u{0020}we're\u{0020}running\u{0020}out!\nNO\u{0020}BAILING.\u{0020}Receiving\u{0020}the\u{0020}mail\u{0020}means\u{0020}you\u{0020}agree\u{0020}to\u{0020}come!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003501] = {id = 11003501, name = "Hurley", head = "10035", type = 5, title = "I\u{0020}See...\u{0020}So\u{0020}This\u{0020}Is\u{0020}Happiness", txt = "When\u{0020}we're\u{0020}children,\u{0020}we\u{0020}all\u{0020}wonder\u{0020}about\u{0020}questions\u{0020}like\u{0020}this,\u{0020}don't\u{0020}we--\"What\u{0020}is\u{0020}happiness?\"\nOf\u{0020}course\u{0020}I\u{0020}did\u{0020}too...\u{0020}I\u{0020}imagined\u{0020}that\u{0020}\"Mom\u{0020}was\u{0020}actually\u{0020}just\u{0020}hiding\u{0020}somewhere,\"\u{0020}or\u{0020}that\u{0020}\"the\u{0020}lottery\u{0020}ticket\u{0020}I\u{0020}bought\u{0020}every\u{0020}week\u{0020}would\u{0020}win\u{0020}the\u{0020}jackpot.\"\u{0020}If\u{0020}either\u{0020}of\u{0020}those\u{0020}things\u{0020}really\u{0020}happened,\u{0020}that\u{0020}would\u{0020}definitely\u{0020}be\u{0020}\"happiness,\"\u{0020}right?\nNow\u{0020}I'm\u{0020}a\u{0020}mature\u{0020}adult...\u{0020}Don't\u{0020}laugh!\u{0020}I'm\u{0020}already\u{0020}an\u{0020}elite\u{0020}Driver,\u{0020}one\u{0020}in\u{0020}ten\u{0020}thousand!\u{0020}Of\u{0020}course\u{0020}that\u{0020}makes\u{0020}me\u{0020}an\u{0020}\"adult\"!\nSo\u{0020}my\u{0020}understanding\u{0020}of\u{0020}\"happiness\"\u{0020}has\u{0020}grown\u{0020}much\u{0020}deeper...\u{0020}In\u{0020}other\u{0020}words,\u{0020}is\u{0020}there\u{0020}anything\u{0020}happier\u{0020}than\u{0020}getting\u{0020}my\u{0020}paycheck\u{0020}on\u{0020}my\u{0020}birthday?\nHehe,\u{0020}dinner's\u{0020}on\u{0020}me\u{0020}today,\u{0020}so\u{0020}you\u{0020}can\u{0020}thank\u{0020}me\u{0020}properly\u{0020}in\u{0020}your\u{0020}heart!\nHurry\u{0020}up\u{0020}and\u{0020}get\u{0020}here.\u{0020}I\u{0020}still\u{0020}have\u{0020}to\u{0020}contact\u{0020}Loki\u{0020}and\u{0020}the\u{0020}others!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110036] = {id = 110036, name = "Charlissa", head = "10036", type = 5, title = "READ\u{0020}IT", txt = "Finally,\u{0020}my\u{0020}birthday\u{0020}is\u{0020}here.\u{0020}What\u{0020}a\u{0020}wait.\nHmph,\u{0020}don't\u{0020}get\u{0020}me\u{0020}wrong.\u{0020}It's\u{0020}not\u{0020}like\u{0020}I\u{0020}am\u{0020}looking\u{0020}forward\u{0020}to\u{0020}it.\u{0020}I\u{0020}just\u{0020}want\u{0020}to\u{0020}get\u{0020}it\u{0020}over\u{0020}with\u{0020}already.\u{0020}Since\u{0020}three\u{0020}days\u{0020}ago—no,\u{0020}a\u{0020}whole\u{0020}week,\u{0020}even\u{0020}a\u{0020}month\u{0020}ago—I've\u{0020}been\u{0020}bombarded\u{0020}with\u{0020}my\u{0020}parents'\u{0020}affection\u{0020}and\u{0020}my\u{0020}friends'\u{0020}teasing.\u{0020}Honestly,\u{0020}I'm\u{0020}sick\u{0020}of\u{0020}birthdays.\nEvery\u{0020}year,\u{0020}my\u{0020}birthday\u{0020}gets\u{0020}hijacked\u{0020}by\u{0020}someone\u{0020}else's\u{0020}plans.\u{0020}Lavish\u{0020}dinners\u{0020}at\u{0020}high-end\u{0020}restaurants,\u{0020}shopping\u{0020}for\u{0020}luxury\u{0020}cars—do\u{0020}people\u{0020}seriously\u{0020}think\u{0020}that's\u{0020}what\u{0020}a\u{0020}birthday\u{0020}is\u{0020}about?\u{0020}Shouldn't\u{0020}it\u{0020}be\u{0020}about\u{0020}what\u{0020}want\u{0020}to\u{0020}do\u{0020}for\u{0020}once?\u{0020}\nSo,\u{0020}all\u{0020}I\u{0020}want\u{0020}is\u{0020}to\u{0020}treat\u{0020}it\u{0020}as\u{0020}any\u{0020}other\u{0020}normal\u{0020}day.\u{0020}That's\u{0020}my\u{0020}birthday\u{0020}wish.\u{0020}Plain\u{0020}and\u{0020}simple.\u{0020}Not\u{0020}that\u{0020}I\u{0020}ask\u{0020}you\u{0020}for\u{0020}help,\u{0020}but,\u{0020}Navigator,\u{0020}you\u{0020}keep\u{0020}me\u{0020}company\u{0020}as\u{0020}usual.\u{0020}You\u{0020}can\u{0020}manage\u{0020}that,\u{0020}right?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003601] = {id = 11003601, name = "Charlissa", head = "10036", type = 5, title = "I\u{0020}Never\u{0020}Believed\u{0020}in\u{0020}Legends", txt = "Navigator,\u{0020}ahem,\u{0020}have\u{0020}you\u{0020}ever\u{0020}heard\u{0020}of\u{0020}a\u{0020}place\u{0020}called\u{0020}the\u{0020}\"Thorn\u{0020}Arch\"?\u{0020}Supposedly,\u{0020}it's\u{0020}where\u{0020}a\u{0020}cursed\u{0020}alchemist\u{0020}and\u{0020}a\u{0020}villager\u{0020}fell\u{0020}in\u{0020}love\u{0020}and\u{0020}died\u{0020}for\u{0020}each\u{0020}other\u{0020}long\u{0020}ago.\u{0020}They\u{0020}say\u{0020}that\u{0020}anyone\u{0020}who\u{0020}goes\u{0020}there\u{0020}will\u{0020}become\u{0020}a\u{0020}couple...\nThat\u{0020}has\u{0020}to\u{0020}be\u{0020}a\u{0020}lie,\u{0020}a\u{0020}marketing\u{0020}scheme\u{0020}made\u{0020}to\u{0020}fool\u{0020}young\u{0020}men\u{0020}and\u{0020}women.\nI\u{0020}bought\u{0020}some\u{0020}related\u{0020}materials\u{0020}about\u{0020}it\u{0020}from\u{0020}Dr.\u{0020}Red.\u{0020}Can\u{0020}you\u{0020}come\u{0020}with\u{0020}me\u{0020}to\u{0020}expose\u{0020}the\u{0020}truth?\nOh,\u{0020}right...\u{0020}could\u{0020}you\u{0020}cover\u{0020}the\u{0020}travel\u{0020}expenses\u{0020}for\u{0020}now?\u{0020}I'll\u{0020}pay\u{0020}you\u{0020}back\u{0020}when\u{0020}I\u{0020}get\u{0020}my\u{0020}salary\u{0020}next\u{0020}month!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110037] = {id = 110037, name = "Kraz", head = "10037", type = 5, title = "My\u{0020}Choice", txt = "Actually,\u{0020}today\u{0020}is\u{0020}not\u{0020}my\u{0020}birthday.\u{0020}In\u{0020}truth,\u{0020}I\u{0020}do\u{0020}not\u{0020}know\u{0020}what\u{0020}day\u{0020}my\u{0020}birthday\u{0020}should\u{0020}be.\nThe\u{0020}day\u{0020}I\u{0020}entered\u{0020}the\u{0020}orphanage?\u{0020}The\u{0020}day\u{0020}I\u{0020}was\u{0020}adopted\u{0020}by\u{0020}the\u{0020}old\u{0020}couple?\u{0020}Or\u{0020}the\u{0020}day\u{0020}I\u{0020}was\u{0020}actually\u{0020}born?\u{0020}I\u{0020}remember\u{0020}none\u{0020}of\u{0020}them.\u{0020}They\u{0020}were\u{0020}all\u{0020}abandoned.\nAs\u{0020}for\u{0020}my\u{0020}current\u{0020}\"birthday,\"\u{0020}can\u{0020}you\u{0020}guess\u{0020}why\u{0020}I\u{0020}chose\u{0020}today?\nYou\u{0020}must\u{0020}be\u{0020}thinking\u{0020}that\u{0020}this\u{0020}day\u{0020}must\u{0020}be\u{0020}very\u{0020}meaningful\u{0020}to\u{0020}me,\u{0020}and\u{0020}that\u{0020}perhaps\u{0020}something\u{0020}important\u{0020}and\u{0020}unforgettable\u{0020}happened\u{0020}on\u{0020}this\u{0020}day\u{0020}in\u{0020}some\u{0020}past\u{0020}year.\nTo\u{0020}tell\u{0020}you\u{0020}the\u{0020}truth,\u{0020}nothing\u{0020}happened.\u{0020}Looking\u{0020}back\u{0020}across\u{0020}dozens\u{0020}of\u{0020}todays,\u{0020}nothing\u{0020}good,\u{0020}bad,\u{0020}important,\u{0020}accidental,\u{0020}exciting,\u{0020}unforgettable,\u{0020}or\u{0020}tearful\u{0020}ever\u{0020}happened.\nBut\u{0020}today\u{0020}still\u{0020}holds\u{0020}a\u{0020}certain\u{0020}special\u{0020}meaning.\u{0020}That\u{0020}meaning\u{0020}lies\u{0020}in\u{0020}the\u{0020}fact\u{0020}that\u{0020}I\u{0020}chose\u{0020}my\u{0020}\"birthday,\"\u{0020}rather\u{0020}than\u{0020}my\u{0020}\"birthday\"\u{0020}choosing\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110038] = {id = 110038, name = "Hlokk", head = "10038", type = 5, title = "\"Your\u{0020}Answer\"", txt = "So,\u{0020}the\u{0020}time\u{0020}has\u{0020}come\u{0020}again.\u{0020}I’ve\u{0020}heard\u{0020}that\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch,\u{0020}there’s\u{0020}a\u{0020}tradition\u{0020}of\u{0020}writing\u{0020}to\u{0020}the\u{0020}Navigator\u{0020}on\u{0020}their\u{0020}birthday.\nA\u{0020}bit\u{0020}odd,\u{0020}but...\u{0020}I\u{0020}suppose\u{0020}traditions\u{0020}deserve\u{0020}some\u{0020}respect.\u{0020}\nHonestly,\u{0020}it’s\u{0020}a\u{0020}pain.\u{0020}Still,\u{0020}it’s\u{0020}not\u{0020}as\u{0020}bad\u{0020}as\u{0020}writing\u{0020}a\u{0020}self-critique,\u{0020}I’ll\u{0020}give\u{0020}it\u{0020}that.\nI\u{0020}do\u{0020}wonder\u{0020}though—don’t\u{0020}you\u{0020}get\u{0020}tired\u{0020}reading\u{0020}all\u{0020}these\u{0020}letters?\u{0020}I\u{0020}can\u{0020}already\u{0020}guess\u{0020}most\u{0020}of\u{0020}them\u{0020}are\u{0020}just\u{0020}birthday\u{0020}party\u{0020}invites.\u{0020}Everyone’s\u{0020}got\u{0020}their\u{0020}eyes\u{0020}on\u{0020}you,\u{0020}and\u{0020}no\u{0020}one’s\u{0020}about\u{0020}to\u{0020}let\u{0020}a\u{0020}day\u{0020}like\u{0020}this\u{0020}slip\u{0020}by.\nAs\u{0020}for\u{0020}me,\u{0020}you\u{0020}know\u{0020}how\u{0020}it\u{0020}is.\u{0020}I\u{0020}don’t\u{0020}care\u{0020}much\u{0020}who\u{0020}I\u{0020}spend\u{0020}my\u{0020}birthday\u{0020}with.\u{0020}If\u{0020}I’ve\u{0020}got\u{0020}time,\u{0020}I’m\u{0020}out\u{0020}fishing—birthday\u{0020}or\u{0020}not.\u{0020}But\u{0020}still...\u{0020}just\u{0020}out\u{0020}of\u{0020}curiosity.\u{0020}If\u{0020}I\u{0020}were\u{0020}the\u{0020}one\u{0020}to\u{0020}send\u{0020}an\u{0020}invitation—what\u{0020}would\u{0020}your\u{0020}answer\u{0020}be?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11003801] = {id = 11003801, name = "Hlokk", head = "10038", type = 5, title = "Birthday\u{0020}and\u{0020}the\u{0020}Sea", txt = "I\u{0020}just\u{0020}received\u{0020}the\u{0020}best\u{0020}birthday\u{0020}gift\u{0020}in\u{0020}the\u{0020}world--catching\u{0020}a\u{0020}shark\u{0020}with\u{0020}my\u{0020}own\u{0020}hands\u{0020}on\u{0020}my\u{0020}birthday.\nYou\u{0020}cannot\u{0020}possibly\u{0020}imagine\u{0020}how\u{0020}strong\u{0020}that\u{0020}shark\u{0020}was.\u{0020}It\u{0020}nearly\u{0020}broke\u{0020}free\u{0020}several\u{0020}times,\u{0020}but\u{0020}fortunately,\u{0020}my\u{0020}technique\u{0020}was\u{0020}solid\u{0020}enough\u{0020}that\u{0020}I\u{0020}did\u{0020}not\u{0020}let\u{0020}it\u{0020}get\u{0020}away.\u{0020}Fishing\u{0020}is\u{0020}not\u{0020}just\u{0020}a\u{0020}contest\u{0020}of\u{0020}strength.\nThere\u{0020}was\u{0020}also\u{0020}a\u{0020}little\u{0020}accident\u{0020}along\u{0020}the\u{0020}way--that\u{0020}shark\u{0020}actually\u{0020}turned\u{0020}its\u{0020}head\u{0020}and\u{0020}bit\u{0020}at\u{0020}the\u{0020}side\u{0020}of\u{0020}the\u{0020}boat,\u{0020}so\u{0020}I\u{0020}knocked\u{0020}it\u{0020}back\u{0020}with\u{0020}the\u{0020}shoe\u{0020}I\u{0020}threw.\u{0020}If\u{0020}you\u{0020}had\u{0020}been\u{0020}there\u{0020}beside\u{0020}me\u{0020}at\u{0020}the\u{0020}time,\u{0020}Navigator,\u{0020}perhaps\u{0020}I\u{0020}could\u{0020}have\u{0020}saved\u{0020}myself\u{0020}one\u{0020}shoe.\nAside\u{0020}from\u{0020}using\u{0020}my\u{0020}birthday\u{0020}as\u{0020}an\u{0020}excuse\u{0020}to\u{0020}share\u{0020}my\u{0020}shark-fishing\u{0020}achievement,\u{0020}I\u{0020}am\u{0020}writing\u{0020}this\u{0020}email\u{0020}because\u{0020}I\u{0020}also\u{0020}want\u{0020}to\u{0020}maintain\u{0020}the\u{0020}precarious\u{0020}superior-subordinate\u{0020}relationship\u{0020}between\u{0020}us.\nStill,\u{0020}I\u{0020}always\u{0020}feel\u{0020}that\u{0020}there\u{0020}is\u{0020}some\u{0020}invisible\u{0020}bond\u{0020}between\u{0020}us,\u{0020}like\u{0020}a\u{0020}fishing\u{0020}line,\u{0020}tying\u{0020}us\u{0020}tightly\u{0020}together.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110039] = {id = 110039, name = "Harriet", head = "10039", type = 5, title = "Birthday\u{0020}Discount\u{0020}at\u{0020}the\u{0020}Gym", txt = "Hey,\u{0020}Navigator,\u{0020}I\u{0020}have\u{0020}some\u{0020}good\u{0020}news\u{0020}for\u{0020}you.\nWhen\u{0020}I\u{0020}went\u{0020}to\u{0020}renew\u{0020}my\u{0020}gym\u{0020}membership\u{0020}today,\u{0020}I\u{0020}happened\u{0020}to\u{0020}catch\u{0020}a\u{0020}store\u{0020}promotion\u{0020}-\u{0020}on\u{0020}your\u{0020}birthday,\u{0020}you\u{0020}can\u{0020}get\u{0020}a\u{0020}discounted\u{0020}gym\u{0020}membership,\u{0020}and\u{0020}it\u{0020}can\u{0020}also\u{0020}be\u{0020}used\u{0020}for\u{0020}friends,\u{0020}family,\u{0020}or\u{0020}relatives.\u{0020}I\u{0020}took\u{0020}one\u{0020}look\u{0020}and\u{0020}thought,\u{0020}isn't\u{0020}today\u{0020}my\u{0020}birthday?\u{0020}So\u{0020}without\u{0020}a\u{0020}second\u{0020}thought,\u{0020}I\u{0020}got\u{0020}a\u{0020}membership\u{0020}card\u{0020}for\u{0020}you\u{0020}too,\u{0020}Navigator,\u{0020}because\u{0020}I\u{0020}remembered\u{0020}that\u{0020}you\u{0020}mentioned\u{0020}before\u{0020}that\u{0020}you\u{0020}wanted\u{0020}to\u{0020}build\u{0020}some\u{0020}muscle.\nFrom\u{0020}now\u{0020}on,\u{0020}we\u{0020}can\u{0020}work\u{0020}out\u{0020}together!\u{0020}Do\u{0020}not\u{0020}worry,\u{0020}with\u{0020}me\u{0020}around,\u{0020}it\u{0020}will\u{0020}not\u{0020}even\u{0020}take\u{0020}half\u{0020}a\u{0020}year\u{0020}for\u{0020}you\u{0020}to\u{0020}build\u{0020}a\u{0020}strong,\u{0020}muscular\u{0020}body\u{0020}too.\nI\u{0020}am\u{0020}on\u{0020}my\u{0020}way\u{0020}to\u{0020}deliver\u{0020}your\u{0020}membership\u{0020}card\u{0020}right\u{0020}now,\u{0020}so\u{0020}get\u{0020}yourself\u{0020}ready.\u{0020}Today\u{0020}I\u{0020}am\u{0020}taking\u{0020}you\u{0020}to\u{0020}the\u{0020}gym\u{0020}so\u{0020}we\u{0020}can\u{0020}work\u{0020}on\u{0020}those\u{0020}muscles\u{0020}-\u{0020}let\u{0020}us\u{0020}start\u{0020}with\u{0020}ten\u{0020}sets\u{0020}of\u{0020}squats\u{0020}and\u{0020}push-ups.\nCelebrating\u{0020}a\u{0020}birthday\u{0020}at\u{0020}the\u{0020}gym\u{0020}sounds\u{0020}pretty\u{0020}fun,\u{0020}does\u{0020}it\u{0020}not?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[110043] = {id = 110043, name = "Hikari", head = "10043", type = 5, title = "A\u{0020}Letter\u{0020}from\u{0020}Another\u{0020}Universe", txt = "When\u{0020}I\u{0020}opened\u{0020}my\u{0020}eyes\u{0020}today,\u{0020}Dad\u{0020}wasn't\u{0020}there\u{0020}by\u{0020}my\u{0020}bedside.\u{0020}Could\u{0020}Dad\u{0020}have\u{0020}forgotten?\nCould\u{0020}that\u{0020}really\u{0020}happen?\u{0020}Could\u{0020}there\u{0020}really\u{0020}be\u{0020}a\u{0020}father\u{0020}who\u{0020}doesn't\u{0020}remember\u{0020}his\u{0020}own\u{0020}daughter's\u{0020}birthday?\nThat's\u{0020}impossible,\u{0020}right?\u{0020}It\u{0020}could\u{0020}never\u{0020}happen.\u{0020}Absolutely\u{0020}not.\nMaybe\u{0020}the\u{0020}barrier\u{0020}between\u{0020}universes\u{0020}is\u{0020}stopping\u{0020}Dad\u{0020}from\u{0020}reaching\u{0020}Hikari's\u{0020}universe.\nIf\u{0020}that's\u{0020}the\u{0020}case,\u{0020}I'll\u{0020}forgive\u{0020}Dad.\u{0020}But\u{0020}Dad\u{0020}can\u{0020}be\u{0020}late;\u{0020}he\u{0020}is\u{0020}absolutely\u{0020}not\u{0020}allowed\u{0020}to\u{0020}be\u{0020}absent.\nJust\u{0020}watch.\u{0020}I'll\u{0020}use\u{0020}the\u{0020}lingering\u{0020}power\u{0020}of\u{0020}the\u{0020}universe's\u{0020}will\u{0020}to\u{0020}bring\u{0020}Dad\u{0020}here.\nFinally,\u{0020}Dad\u{0020}and\u{0020}I\u{0020}can\u{0020}be\u{0020}together\u{0020}again.\u{0020}I\u{0020}can't\u{0020}wait\u{0020}to\u{0020}see\u{0020}what\u{0020}birthday\u{0020}present\u{0020}Dad\u{0020}has\u{0020}prepared\u{0020}for\u{0020}me.\nActually,\u{0020}I'd\u{0020}rather\u{0020}have\u{0020}Dad\u{0020}be\u{0020}my\u{0020}present\u{0020}and\u{0020}stay\u{0020}here\u{0020}with\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111000] = {id = 111000, name = "Charlissa", head = "11000", type = 5, title = "看內容", txt = "終於到生日這天了，真讓本小姐等得煎熬呢。\n哼，是不是開始誤會了？我當然不是指期待，而是希望早點翻過這一頁，畢竟從生日的前三天、前一周、前一個月開始，爸媽沉重的親情、身邊朋友的調侃就都鬧個不停，讓我早就對生日厭煩了。\n以往的每個生日我都不能做自己喜歡做的事，而是按照家人安排好的行程計劃，不是到哪家高級餐廳就是去選購豪車，可生日的意義難道不是壽星本人開心才好嗎？\n所以，今天我只想正常度過一天，我的生日願望就是這樣而已。這不是求助，但navigator，我希望至少你能一如既往地陪著我，沒問題吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111001] = {id = 111001, name = "Alice", head = "11001", type = 5, title = "An\u{0020}Invitation\u{0020}to\u{0020}Tea", txt = "This\u{0020}year,\u{0020}my\u{0020}family\u{0020}entrusted\u{0020}me\u{0020}with\u{0020}planning\u{0020}my\u{0020}birthday\u{0020}celebration\u{0020}from\u{0020}start\u{0020}to\u{0020}finish—a\u{0020}deliberate\u{0020}trial\u{0020}meant\u{0020}to\u{0020}test\u{0020}me\u{0020}in\u{0020}every\u{0020}way.\u{0020}I\u{0020}know\u{0020}full\u{0020}well\u{0020}that\u{0020}this\u{0020}is\u{0020}a\u{0020}necessary\u{0020}step\u{0020}toward\u{0020}becoming\u{0020}the\u{0020}next\u{0020}head\u{0020}of\u{0020}the\u{0020}household.\u{0020}To\u{0020}lead\u{0020}our\u{0020}family\u{0020}is\u{0020}to\u{0020}wield\u{0020}more\u{0020}than\u{0020}knowledge\u{0020}and\u{0020}a\u{0020}sword.\u{0020}It\u{0020}requires\u{0020}initiative,\u{0020}leadership,\u{0020}and\u{0020}the\u{0020}kind\u{0020}of\u{0020}resolve\u{0020}that\u{0020}doesn't\u{0020}waver\u{0020}under\u{0020}pressure.\nAs\u{0020}captain\u{0020}of\u{0020}the\u{0020}driver\u{0020}squad,\u{0020}I\u{0020}believe\u{0020}these\u{0020}same\u{0020}qualities\u{0020}are\u{0020}invaluable\u{0020}in\u{0020}battle\u{0020}as\u{0020}well.\u{0020}I've\u{0020}been\u{0020}deeply\u{0020}engaged\u{0020}in\u{0020}the\u{0020}preparations\u{0020}until\u{0020}quite\u{0020}recently,\u{0020}and\u{0020}I\u{0020}regret\u{0020}not\u{0020}sending\u{0020}word\u{0020}to\u{0020}you\u{0020}sooner.\nThat\u{0020}being\u{0020}said,\u{0020}I\u{0020}now\u{0020}extend\u{0020}a\u{0020}formal\u{0020}invitation:\u{0020}The\u{0020}birthday\u{0020}tea\u{0020}party\u{0020}of\u{0020}Alice\u{0020}Claretia\u{0020}will\u{0020}be\u{0020}held\u{0020}today\u{0020}and\u{0020}continue\u{0020}throughout\u{0020}the\u{0020}day.\u{0020}I\u{0020}would\u{0020}be\u{0020}honored\u{0020}to\u{0020}have\u{0020}you\u{0020}there\u{0020}as\u{0020}my\u{0020}guest.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100101] = {id = 11100101, name = "Alice", head = "11001", type = 5, title = "A\u{0020}Noble's\u{0020}Private\u{0020}Tutor", txt = "Have\u{0020}you\u{0020}ever\u{0020}considered\u{0020}what\u{0020}\"perfection\"\u{0020}means?\nI\u{0020}am\u{0020}not\u{0020}asking\u{0020}this\u{0020}to\u{0020}challenge\u{0020}or\u{0020}test\u{0020}you.\u{0020}I\u{0020}simply\u{0020}wish\u{0020}to\u{0020}discuss\u{0020}the\u{0020}matter\u{0020}with\u{0020}you.\nLet\u{0020}us\u{0020}give\u{0020}it\u{0020}proper\u{0020}thought.\u{0020}If\u{0020}\"perfection\"\u{0020}means\u{0020}being\u{0020}capable\u{0020}of\u{0020}anything,\u{0020}then\u{0020}it\u{0020}is\u{0020}something\u{0020}no\u{0020}human\u{0020}could\u{0020}attain\u{0020}even\u{0020}after\u{0020}devoting\u{0020}an\u{0020}entire\u{0020}lifetime\u{0020}to\u{0020}the\u{0020}pursuit.\u{0020}Even\u{0020}I\u{0020}can\u{0020}only\u{0020}accomplish\u{0020}what\u{0020}lies\u{0020}within\u{0020}my\u{0020}abilities.\nBut\u{0020}if\u{0020}\"perfection\"\u{0020}merely\u{0020}means\u{0020}performing\u{0020}flawlessly\u{0020}at\u{0020}the\u{0020}things\u{0020}one\u{0020}already\u{0020}knows\u{0020}how\u{0020}to\u{0020}do,\u{0020}would\u{0020}that\u{0020}fragile\u{0020}\"perfection\"\u{0020}not\u{0020}shatter\u{0020}the\u{0020}moment\u{0020}one\u{0020}entered\u{0020}an\u{0020}unfamiliar\u{0020}field?\nI\u{0020}would\u{0020}like\u{0020}to\u{0020}spend\u{0020}the\u{0020}day\u{0020}discussing\u{0020}this\u{0020}with\u{0020}you.\u{0020}Therefore,\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}I\u{0020}intend\u{0020}to\u{0020}hire\u{0020}you,\u{0020}Navigator,\u{0020}as\u{0020}my\u{0020}private\u{0020}tutor.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111002] = {id = 111002, name = "Kokorokami", head = "11002", type = 5, title = "Invitation", txt = "Today\u{0020}marks\u{0020}the\u{0020}birth\u{0020}of\u{0020}the\u{0020}divinity,\u{0020}the\u{0020}moment\u{0020}my\u{0020}duty\u{0020}as\u{0020}a\u{0020}savior\u{0020}is\u{0020}bestowed\u{0020}upon\u{0020}me.\u{0020}To\u{0020}instill\u{0020}hope,\u{0020}to\u{0020}illuminate\u{0020}the\u{0020}path\u{0020}with\u{0020}faith.\u{0020}Such\u{0020}is\u{0020}everything\u{0020}that\u{0020}explains\u{0020}my\u{0020}existence.\nThough\u{0020}we\u{0020}have\u{0020}never\u{0020}fought\u{0020}side\u{0020}by\u{0020}side,\u{0020}I\u{0020}have\u{0020}long\u{0020}heard\u{0020}tales\u{0020}of\u{0020}you.\u{0020}You\u{0020}are\u{0020}to\u{0020}the\u{0020}drivers\u{0020}as\u{0020}Kokorokami\u{0020}is\u{0020}to\u{0020}the\u{0020}faithful,\u{0020}a\u{0020}beacon\u{0020}that\u{0020}cuts\u{0020}through\u{0020}the\u{0020}fog,\u{0020}offering\u{0020}peace\u{0020}within\u{0020}our\u{0020}reach.\nMy\u{0020}fate\u{0020}intertwined\u{0020}with\u{0020}Shingyou\u{0020}House\u{0020}has\u{0020}already\u{0020}been\u{0020}predestined.\u{0020}But\u{0020}what\u{0020}of\u{0020}the\u{0020}other\u{0020}drivers\u{0020}and\u{0020}the\u{0020}world's\u{0020}future?\u{0020}Where\u{0020}will\u{0020}you\u{0020}lead\u{0020}them,\u{0020}as\u{0020}Danube's\u{0020}Navigator?\u{0020}I\u{0020}shall\u{0020}be\u{0020}waiting\u{0020}for\u{0020}the\u{0020}answer.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100201] = {id = 11100201, name = "Kokorokami", head = "11002", type = 5, title = "I\u{0020}Want\u{0020}to\u{0020}Become\u{0020}Human", txt = "Recently,\u{0020}the\u{0020}number\u{0020}of\u{0020}worshippers\u{0020}visiting\u{0020}the\u{0020}Shingyou\u{0020}has\u{0020}been\u{0020}few\u{0020}and\u{0020}far\u{0020}between.\u{0020}Even\u{0020}today's\u{0020}\"Day\u{0020}of\u{0020}Divine\u{0020}Birth\"\u{0020}festival\u{0020}drew\u{0020}only\u{0020}a\u{0020}handful\u{0020}of\u{0020}believers.\nIn\u{0020}order\u{0020}to\u{0020}uncover\u{0020}the\u{0020}reason,\u{0020}this\u{0020}old\u{0020}one\u{0020}disguised\u{0020}herself\u{0020}and\u{0020}investigated\u{0020}in\u{0020}many\u{0020}places.\u{0020}Though\u{0020}I\u{0020}did\u{0020}not\u{0020}find\u{0020}a\u{0020}direct\u{0020}cause,\u{0020}I\u{0020}discovered\u{0020}that\u{0020}people\u{0020}often\u{0020}speak\u{0020}of\u{0020}sin\u{0020}and\u{0020}the\u{0020}conflict\u{0020}with\u{0020}the\u{0020}drivers,\u{0020}and\u{0020}I\u{0020}also\u{0020}heard\u{0020}Navigator's\u{0020}name\u{0020}mentioned\u{0020}many\u{0020}times.\u{0020}\"Humanity's\u{0020}Star\u{0020}of\u{0020}Hope\"\u{0020}-\u{0020}such\u{0020}is\u{0020}the\u{0020}affectionate\u{0020}title\u{0020}people\u{0020}have\u{0020}given\u{0020}Navigator.\nOnly\u{0020}then\u{0020}did\u{0020}this\u{0020}old\u{0020}one\u{0020}finally\u{0020}understand.\nIt\u{0020}is\u{0020}truly\u{0020}embarrassing\u{0020}to\u{0020}admit,\u{0020}but\u{0020}Navigator,\u{0020}with\u{0020}nothing\u{0020}more\u{0020}than\u{0020}a\u{0020}human\u{0020}body,\u{0020}has\u{0020}kindled\u{0020}a\u{0020}spark\u{0020}of\u{0020}hope\u{0020}for\u{0020}the\u{0020}world.\u{0020}Compared\u{0020}to\u{0020}that,\u{0020}this\u{0020}old\u{0020}one\u{0020}bears\u{0020}only\u{0020}the\u{0020}hollow\u{0020}name\u{0020}of\u{0020}a\u{0020}\"god.\"\u{0020}It\u{0020}seems\u{0020}that\u{0020}the\u{0020}power\u{0020}of\u{0020}faith\u{0020}may\u{0020}protect\u{0020}hope's\u{0020}embers\u{0020}in\u{0020}the\u{0020}darkness,\u{0020}yet\u{0020}it\u{0020}cannot\u{0020}fan\u{0020}them\u{0020}into\u{0020}a\u{0020}blazing\u{0020}fire.\u{0020}Since\u{0020}ancient\u{0020}times,\u{0020}those\u{0020}who\u{0020}achieved\u{0020}the\u{0020}extraordinary\u{0020}were\u{0020}never\u{0020}vague\u{0020}and\u{0020}distant\u{0020}\"deities,\"\u{0020}but\u{0020}living,\u{0020}breathing\u{0020}people.\nThis\u{0020}old\u{0020}one...\u{0020}wishes\u{0020}to\u{0020}speak\u{0020}with\u{0020}Navigator\u{0020}through\u{0020}the\u{0020}night,\u{0020}about\u{0020}gods,\u{0020}and\u{0020}about\u{0020}humans...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111003] = {id = 111003, name = "Suzuki\u{0020}Seifung", head = "11003", type = 5, title = "一起來做超大壽喜燒吧", txt = "navigator，你應該知道了吧？\n沒錯，今天就是咱的生日！\n在咱的老家，村子裡的人過生日了都會邀請大家來吃飯、\n就算當了駕駛員，咱也不能忘了老家的習俗！\n咱已經想好了，咱要做一頓超大的壽喜燒，把所有駕駛員都叫來一起吃！\n怎麼樣，這個想法很好吧？既然如此，navigator就趕緊過來幫咱一起做吧。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100301] = {id = 11100301, name = "Suzuki\u{0020}Seifung", head = "11003", type = 5, title = "\"Let's\u{0020}Make\u{0020}a\u{0020}Giant\u{0020}Sukiyaki\u{0020}Together!\"", txt = "Navigator,\u{0020}you\u{0020}must\u{0020}have\u{0020}guessed\u{0020}by\u{0020}now,\u{0020}right?\nThat's\u{0020}right,\u{0020}today's\u{0020}my\u{0020}birthday!\u{0020}\nBack\u{0020}in\u{0020}my\u{0020}hometown,\u{0020}it's\u{0020}tradition\u{0020}for\u{0020}people\u{0020}to\u{0020}invite\u{0020}everyone\u{0020}over\u{0020}to\u{0020}celebrate\u{0020}with\u{0020}a\u{0020}big\u{0020}meal\u{0020}on\u{0020}their\u{0020}birthday.\nEven\u{0020}though\u{0020}I'm\u{0020}a\u{0020}driver\u{0020}now,\u{0020}I\u{0020}still\u{0020}hold\u{0020}onto\u{0020}those\u{0020}old\u{0020}customs!\nI've\u{0020}already\u{0020}got\u{0020}it\u{0020}all\u{0020}planned\u{0020}–\u{0020}I'm\u{0020}going\u{0020}to\u{0020}make\u{0020}a\u{0020}huge\u{0020}sukiyaki\u{0020}and\u{0020}invite\u{0020}all\u{0020}the\u{0020}drivers\u{0020}to\u{0020}join\u{0020}me!\nHow\u{0020}does\u{0020}that\u{0020}sound?\u{0020}A\u{0020}great\u{0020}idea,\u{0020}right?\u{0020}So,\u{0020}come\u{0020}on\u{0020}over\u{0020}and\u{0020}help\u{0020}me\u{0020}get\u{0020}it\u{0020}ready,\u{0020}Navigator!\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100302] = {id = 11100302, name = "Suzuki\u{0020}Seifung", head = "11003", type = 5, title = "Taking\u{0020}a\u{0020}Few\u{0020}Days\u{0020}Off", txt = "Navigator,\u{0020}my\u{0020}birthday's\u{0020}coming\u{0020}up.\u{0020}\nI've\u{0020}already\u{0020}taken\u{0020}a\u{0020}few\u{0020}days\u{0020}off\u{0020}and\u{0020}I'm\u{0020}planning\u{0020}to\u{0020}go\u{0020}back\u{0020}home\u{0020}to\u{0020}see\u{0020}my\u{0020}father\u{0020}and\u{0020}my\u{0020}little\u{0020}sister.\u{0020}\nThey\u{0020}sent\u{0020}me\u{0020}a\u{0020}lot\u{0020}of\u{0020}photos\u{0020}and\u{0020}letters\u{0020}this\u{0020}year.\u{0020}They\u{0020}look\u{0020}so\u{0020}happy\u{0020}in\u{0020}the\u{0020}pictures.\u{0020}\nMm…\u{0020}now\u{0020}that\u{0020}I\u{0020}think\u{0020}about\u{0020}it,\u{0020}it's\u{0020}been\u{0020}a\u{0020}long\u{0020}time\u{0020}since\u{0020}I\u{0020}last\u{0020}went\u{0020}home.\u{0020}But\u{0020}I'm\u{0020}glad\u{0020}I\u{0020}became\u{0020}a\u{0020}Driver,\u{0020}haha...\u{0020}even\u{0020}though\u{0020}I\u{0020}joined\u{0020}back\u{0020}then\u{0020}only\u{0020}because\u{0020}I\u{0020}had\u{0020}no\u{0020}choice.\u{0020}\nI\u{0020}got\u{0020}to\u{0020}know\u{0020}everyone\u{0020}in\u{0020}Fuurinkazan...\u{0020}I\u{0020}earned\u{0020}money...\u{0020}and\u{0020}I\u{0020}met\u{0020}you,\u{0020}Navigator.\u{0020}\nSo,\u{0020}do\u{0020}you\u{0020}have\u{0020}time\u{0020}this\u{0020}year\u{0020}to\u{0020}go\u{0020}home\u{0020}with\u{0020}me?\u{0020}I\u{0020}think\u{0020}it's\u{0020}about\u{0020}time\u{0020}I\u{0020}introduced\u{0020}you\u{0020}to\u{0020}them.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111004] = {id = 111004, name = "Kuriyama", head = "11004", type = 5, title = "Thank\u{0020}You", txt = "I\u{0020}really\u{0020}wanted\u{0020}to\u{0020}thank\u{0020}Navigator\u{0020}for\u{0020}today.\u{0020}Thanks\u{0020}to\u{0020}you,\u{0020}no\u{0020}one\u{0020}continued\u{0020}to\u{0020}stare\u{0020}at\u{0020}me\u{0020}with\u{0020}a\u{0020}strange\u{0020}look…at\u{0020}this\u{0020}strange\u{0020}body\u{0020}of\u{0020}mine.\nRemember\u{0020}how\u{0020}you\u{0020}praised\u{0020}my\u{0020}bargaining\u{0020}skills\u{0020}earlier?\u{0020}If\u{0020}it's\u{0020}okay,\u{0020}please\u{0020}take\u{0020}me\u{0020}with\u{0020}you\u{0020}the\u{0020}next\u{0020}time\u{0020}you\u{0020}go\u{0020}shopping.\u{0020}Oh,\u{0020}is\u{0020}that\u{0020}a\u{0020}little\u{0020}too\u{0020}complacent?\u{0020}I’m\u{0020}sorry…\nNavigator,\u{0020}please\u{0020}allow\u{0020}me\u{0020}to\u{0020}say\u{0020}thank\u{0020}you\u{0020}one\u{0020}more\u{0020}time\nThank\u{0020}you\u{0020}for\u{0020}taking\u{0020}me\u{0020}out,\u{0020}for\u{0020}vouching\u{0020}for\u{0020}me\u{0020}in\u{0020}front\u{0020}of\u{0020}outsiders,\u{0020}for\u{0020}never\u{0020}being\u{0020}afraid\u{0020}of\u{0020}me…\u{0020}and\u{0020}for\u{0020}spending\u{0020}a\u{0020}wonderful\u{0020}birthday\u{0020}with\u{0020}me.\nI\u{0020}will\u{0020}always\u{0020}remember\u{0020}this.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100401] = {id = 11100401, name = "Kuriyama", head = "11004", type = 5, title = "Letter\u{0020}of\u{0020}Gratitude", txt = "I\u{0020}really\u{0020}can't\u{0020}thank\u{0020}you\u{0020}enough\u{0020}for\u{0020}today,\u{0020}Navigator.\u{0020}Thanks\u{0020}to\u{0020}your\u{0020}efforts,\u{0020}everyone\u{0020}finally\u{0020}stopped...\u{0020}staring\u{0020}at\u{0020}this\u{0020}strange\u{0020}body\u{0020}of\u{0020}mine.\nYou\u{0020}were\u{0020}surprised\u{0020}about\u{0020}my\u{0020}bargaining\u{0020}skills,\u{0020}right?\u{0020}Hope\u{0020}my\u{0020}memory\u{0020}serves\u{0020}me\u{0020}fine.\u{0020}Maybe\u{0020}I\u{0020}could\u{0020}join\u{0020}you\u{0020}on\u{0020}the\u{0020}next\u{0020}supply\u{0020}run\u{0020}if\u{0020}you\u{0020}like.\nAh,\u{0020}please\u{0020}forgive\u{0020}me\u{0020}if\u{0020}I\u{0020}seem\u{0020}presumptuous.\nFinally,\u{0020}please\u{0020}let\u{0020}me\u{0020}say\u{0020}it\u{0020}one\u{0020}more\u{0020}time:\u{0020}Thank\u{0020}you.\nThank\u{0020}you\u{0020}for\u{0020}taking\u{0020}someone\u{0020}like\u{0020}me\u{0020}outside.\u{0020}Thank\u{0020}you\u{0020}for\u{0020}standing\u{0020}up\u{0020}for\u{0020}me\u{0020}in\u{0020}front\u{0020}of\u{0020}others.\u{0020}Thank\u{0020}you\u{0020}for\u{0020}never\u{0020}looking\u{0020}at\u{0020}me\u{0020}with\u{0020}fear...And\u{0020}thank\u{0020}you\u{0020}for\u{0020}giving\u{0020}me\u{0020}the\u{0020}most\u{0020}perfect\u{0020}birthday\u{0020}I\u{0020}could've\u{0020}asked\u{0020}for.\u{0020}I'll\u{0020}cherish\u{0020}this\u{0020}memory\u{0020}forever.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100402] = {id = 11100402, name = "Kuriyama", head = "11004", type = 5, title = "I\u{0020}Want\u{0020}to\u{0020}Be\u{0020}Fashionable", txt = "Navigator,\u{0020}I\u{0020}heard\u{0020}that\u{0020}a\u{0020}new\u{0020}clothing\u{0020}store\u{0020}recently\u{0020}opened,\u{0020}with\u{0020}many\u{0020}stylish\u{0020}new\u{0020}outfits\u{0020}designed\u{0020}especially\u{0020}for\u{0020}people\u{0020}with\u{0020}special\u{0020}needs.\u{0020}I\u{0020}would\u{0020}like\u{0020}to\u{0020}try\u{0020}them\u{0020}on\u{0020}and\u{0020}see\u{0020}whether\u{0020}even\u{0020}someone\u{0020}like\u{0020}me\u{0020}can\u{0020}find\u{0020}a\u{0020}way\u{0020}to\u{0020}become\u{0020}fashionable.\nBut\u{0020}I\u{0020}have\u{0020}not\u{0020}been\u{0020}able\u{0020}to\u{0020}make\u{0020}up\u{0020}my\u{0020}mind.\u{0020}On\u{0020}one\u{0020}hand,\u{0020}I\u{0020}feel\u{0020}that\u{0020}perhaps\u{0020}I\u{0020}do\u{0020}not\u{0020}need\u{0020}to\u{0020}imitate\u{0020}others\u{0020}and\u{0020}pursue\u{0020}something\u{0020}flashy.\u{0020}On\u{0020}the\u{0020}other\u{0020}hand,\u{0020}I\u{0020}am\u{0020}not\u{0020}very\u{0020}confident\u{0020}in\u{0020}my\u{0020}own\u{0020}fashion\u{0020}sense,\u{0020}and\u{0020}I\u{0020}do\u{0020}not\u{0020}know\u{0020}whether\u{0020}Navigator\u{0020}would\u{0020}like\u{0020}me\u{0020}after\u{0020}I\u{0020}change\u{0020}into\u{0020}new\u{0020}clothes...\u{0020}So,\u{0020}could\u{0020}you\u{0020}please\u{0020}give\u{0020}me\u{0020}some\u{0020}advice,\u{0020}or\u{0020}accompany\u{0020}me\u{0020}to\u{0020}browse\u{0020}the\u{0020}store\u{0020}on\u{0020}my\u{0020}birthday\u{0020}and\u{0020}help\u{0020}me\u{0020}pick\u{0020}out\u{0020}some\u{0020}clothes\u{0020}that\u{0020}suit\u{0020}me?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111006] = {id = 111006, name = "Jenny Ross", head = "11006", type = 5, title = "A\u{0020}Fine\u{0020}Day\u{0020}for\u{0020}Adventures", txt = "My\u{0020}birthday's\u{0020}finally\u{0020}here!\nNow,\u{0020}what\u{0020}kinda\u{0020}gift\u{0020}should\u{0020}I\u{0020}ask\u{0020}for?\u{0020}Cake\u{0020}gets\u{0020}eaten,\u{0020}objects\u{0020}break.\u{0020}Nah,\u{0020}what\u{0020}I\u{0020}really\u{0020}want\u{0020}is\u{0020}a\u{0020}big,\u{0020}juicy\u{0020}scoop\u{0020}that'll\u{0020}stand\u{0020}the\u{0020}test\u{0020}of\u{0020}time!\u{0020}A\u{0020}once-a-year\u{0020}opportunity\u{0020}like\u{0020}this\u{0020}calls\u{0020}for\u{0020}you,\u{0020}Navigator,\u{0020}to\u{0020}join\u{0020}me\u{0020}in\u{0020}scouring\u{0020}every\u{0020}nook\u{0020}and\u{0020}cranny\u{0020}of\u{0020}Danube,\u{0020}diggin'\u{0020}up\u{0020}all\u{0020}the\u{0020}secrets\u{0020}lurkin'\u{0020}in\u{0020}the\u{0020}shadows!\nHmph!\u{0020}Or\u{0020}hey,\u{0020}if\u{0020}you're\u{0020}already\u{0020}carryin'\u{0020}some\u{0020}deep,\u{0020}dark,\u{0020}earth-shatterin'\u{0020}secret\u{0020}of\u{0020}your\u{0020}own,\u{0020}today's\u{0020}the\u{0020}perfect\u{0020}day\u{0020}to\u{0020}spill\u{0020}it\u{0020}as\u{0020}my\u{0020}present!\u{0020}No\u{0020}matter\u{0020}how\u{0020}twisted,\u{0020}wicked,\u{0020}evil,\u{0020}I\u{0020}and\u{0020}my\u{0020}camera\u{0020}are\u{0020}more\u{0020}than\u{0020}ready\u{0020}for\u{0020}it!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100601] = {id = 11100601, name = "Jenny Ross", head = "11006", type = 5, title = "Interview\u{0020}Appointment", txt = "It's\u{0020}finally\u{0020}my\u{0020}birthday\u{0020}again!\u{0020}Navigator,\u{0020}are\u{0020}you\u{0020}ready\u{0020}for\u{0020}your\u{0020}interview?\nDon't\u{0020}be\u{0020}surprised.\u{0020}The\u{0020}birthday\u{0020}present\u{0020}I\u{0020}want\u{0020}most\u{0020}is\u{0020}a\u{0020}one-on-one\u{0020}interview\u{0020}with\u{0020}you.\nYour\u{0020}height,\u{0020}your\u{0020}weight,\u{0020}your\u{0020}hobbies;\u{0020}the\u{0020}clothes\u{0020}you\u{0020}like\u{0020}to\u{0020}wear,\u{0020}the\u{0020}food\u{0020}you\u{0020}love,\u{0020}the\u{0020}shops\u{0020}you\u{0020}frequent,\u{0020}and\u{0020}the\u{0020}street\u{0020}you\u{0020}like\u{0020}to\u{0020}stroll\u{0020}along\u{0020}beneath\u{0020}the\u{0020}evening\u{0020}glow...\u{0020}Every\u{0020}question\u{0020}listed\u{0020}here\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}most\u{0020}popular\u{0020}entries\u{0020}from\u{0020}the\u{0020}\"1,001\u{0020}Things\u{0020}I\u{0020}Want\u{0020}to\u{0020}Know\u{0020}About\u{0020}the\u{0020}Navigator\"\u{0020}that\u{0020}I've\u{0020}painstakingly\u{0020}compiled.\nBut\u{0020}don't\u{0020}worry.\u{0020}Since\u{0020}this\u{0020}is\u{0020}my\u{0020}birthday\u{0020}present,\u{0020}the\u{0020}contents\u{0020}of\u{0020}this\u{0020}interview\u{0020}will\u{0020}only\u{0020}ever\u{0020}run\u{0020}as\u{0020}the\u{0020}top\u{0020}story\u{0020}in\u{0020}my\u{0020}heart.\u{0020}It's\u{0020}a\u{0020}secret\u{0020}for\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}to\u{0020}protect\u{0020}together.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111007] = {id = 111007, name = "Lydia", head = "11007", type = 5, title = "Today\u{0020}is\u{0020}my\u{0020}birthday.", txt = "The\u{0020}bitter\u{0020}cold\u{0020}and\u{0020}the\u{0020}bright\u{0020}sun—what\u{0020}a\u{0020}wonderful\u{0020}day!\nAre\u{0020}you\u{0020}still\u{0020}dozing\u{0020}off,\u{0020}my\u{0020}dear\u{0020}friend—\nIt's\u{0020}time,\u{0020}wake\u{0020}up...\nDo\u{0020}you\u{0020}like\u{0020}this\u{0020}nursery\u{0020}rhyme?\u{0020}Every\u{0020}year\u{0020}around\u{0020}this\u{0020}time,\u{0020}I\u{0020}think\u{0020}back\u{0020}to\u{0020}when\u{0020}my\u{0020}mother\u{0020}would\u{0020}sing\u{0020}nursery\u{0020}rhymes\u{0020}to\u{0020}wake\u{0020}me\u{0020}up\u{0020}as\u{0020}a\u{0020}child.\u{0020}It\u{0020}was\u{0020}always\u{0020}a\u{0020}sign\u{0020}that\u{0020}my\u{0020}birthday\u{0020}had\u{0020}arrived\u{0020}once\u{0020}again.\nBirthdays\u{0020}are\u{0020}such\u{0020}beautiful\u{0020}days,\u{0020}marking\u{0020}the\u{0020}very\u{0020}first\u{0020}moment\u{0020}we\u{0020}connect\u{0020}with\u{0020}the\u{0020}world.\nI've\u{0020}always\u{0020}believed\u{0020}that\u{0020}a\u{0020}baby's\u{0020}cry\u{0020}isn't\u{0020}just\u{0020}an\u{0020}expression\u{0020}of\u{0020}fear—it's\u{0020}also\u{0020}a\u{0020}proud\u{0020}declaration\u{0020}of\u{0020}its\u{0020}arrival.\u{0020}And\u{0020}those\u{0020}born\u{0020}in\u{0020}winter\u{0020}are\u{0020}the\u{0020}luckiest\u{0020}of\u{0020}all.\u{0020}They\u{0020}don't\u{0020}have\u{0020}to\u{0020}fear\u{0020}the\u{0020}cold;\u{0020}they\u{0020}only\u{0020}need\u{0020}to\u{0020}look\u{0020}forward\u{0020}to\u{0020}the\u{0020}spring.\nI'm\u{0020}one\u{0020}of\u{0020}those\u{0020}lucky\u{0020}ones,\u{0020}born\u{0020}in\u{0020}winter.\u{0020}If\u{0020}I\u{0020}can\u{0020}endure\u{0020}the\u{0020}harsh\u{0020}chill\u{0020}of\u{0020}winter,\u{0020}then\u{0020}every\u{0020}day\u{0020}after\u{0020}will\u{0020}be\u{0020}as\u{0020}warm\u{0020}and\u{0020}hopeful\u{0020}as\u{0020}spring.\n\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100701] = {id = 11100701, name = "Lydia", head = "11007", type = 5, title = "A\u{0020}New\u{0020}Day\u{0020}Has\u{0020}Already\u{0020}Begun", txt = "To\u{0020}me,\u{0020}the\u{0020}moment\u{0020}the\u{0020}clock's\u{0020}hour\u{0020}hand\u{0020}passes\u{0020}twelve,\u{0020}a\u{0020}new\u{0020}day\u{0020}has\u{0020}already\u{0020}begun.\nThere's\u{0020}a\u{0020}saying\u{0020}in\u{0020}Kyushu:\u{0020}\"A\u{0020}year's\u{0020}plan\u{0020}begins\u{0020}in\u{0020}spring,\u{0020}a\u{0020}day's\u{0020}plan\u{0020}at\u{0020}dawn.\"\u{0020}It's\u{0020}not\u{0020}spring,\u{0020}and\u{0020}it's\u{0020}not\u{0020}morning.\u{0020}But\u{0020}it\u{0020}is\u{0020}the\u{0020}beginning\u{0020}of\u{0020}a\u{0020}new\u{0020}day.\nAnd\u{0020}I\u{0020}want\u{0020}to\u{0020}spend\u{0020}the\u{0020}beginning\u{0020}of\u{0020}my\u{0020}birthday\u{0020}with\u{0020}the\u{0020}person\u{0020}she\u{0020}cares\u{0020}about.\nSo,\u{0020}when\u{0020}you\u{0020}receive\u{0020}this\u{0020}email,\u{0020}please\u{0020}open\u{0020}your\u{0020}door.\nIf\u{0020}everything\u{0020}goes\u{0020}right...\u{0020}you'll\u{0020}find\u{0020}a\u{0020}white-haired\u{0020}woman\u{0020}waiting\u{0020}outside.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111008] = {id = 111008, name = "Ashlica", head = "11008", type = 5, title = "Invitation\u{0020}to\u{0020}a\u{0020}Party\u{0020}in\u{0020}Hell", txt = "Every\u{0020}year\u{0020}at\u{0020}this\u{0020}time,\u{0020}a\u{0020}voice\u{0020}rings\u{0020}in\u{0020}my\u{0020}ears\u{0020}as\u{0020}if\u{0020}it\u{0020}were\u{0020}the\u{0020}screams\u{0020}of\u{0020}hell.\u{0020}Those\u{0020}screams\u{0020}tear\u{0020}through\u{0020}my\u{0020}flesh,\u{0020}shake\u{0020}the\u{0020}very\u{0020}depths\u{0020}of\u{0020}my\u{0020}soul,\u{0020}and\u{0020}give\u{0020}me\u{0020}endless\u{0020}inspiration\u{0020}for\u{0020}my\u{0020}music\u{0020}creation.\nWhile\u{0020}feeling\u{0020}so\u{0020}inspired,\u{0020}I\u{0020}created\u{0020}three\u{0020}new\u{0020}songs.\u{0020}Each\u{0020}time\u{0020}a\u{0020}new\u{0020}piece\u{0020}of\u{0020}music\u{0020}is\u{0020}created,\u{0020}I\u{0020}eagerly\u{0020}want\u{0020}to\u{0020}share\u{0020}it\u{0020}with\u{0020}others.\u{0020}But\u{0020}here\u{0020}in\u{0020}the\u{0020}Ark,\u{0020}when\u{0020}people\u{0020}hear\u{0020}my\u{0020}songs,\u{0020}they\u{0020}all\u{0020}run\u{0020}away,\u{0020}even\u{0020}the\u{0020}Drivers.\u{0020}Hahaha,\u{0020}they\u{0020}are\u{0020}all\u{0020}cowards\u{0020}with\u{0020}no\u{0020}guts.\nAfter\u{0020}thinking\u{0020}about\u{0020}it,\u{0020}Navigator\u{0020}is\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}clicks\u{0020}with\u{0020}me,\u{0020}so\u{0020}I\u{0020}wrote\u{0020}one\u{0020}of\u{0020}my\u{0020}new\u{0020}songs\u{0020}for\u{0020}Navigator.\nSo\u{0020}with\u{0020}that\u{0020}in\u{0020}mind,\u{0020}would\u{0020}Navigator\u{0020}have\u{0020}the\u{0020}guts\u{0020}to\u{0020}join\u{0020}me\u{0020}in\u{0020}my\u{0020}quest\u{0020}for\u{0020}immortality?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100801] = {id = 11100801, name = "Ashlica", head = "11008", type = 5, title = "An\u{0020}Invitation\u{0020}to\u{0020}the\u{0020}Infernal\u{0020}Party", txt = "Around\u{0020}this\u{0020}time\u{0020}each\u{0020}year,\u{0020}I\u{0020}hear\u{0020}it—a\u{0020}howl,\u{0020}raw\u{0020}and\u{0020}otherworldly,\u{0020}as\u{0020}if\u{0020}from\u{0020}the\u{0020}depths\u{0020}of\u{0020}hell\u{0020}itself.\u{0020}It\u{0020}rips\u{0020}through\u{0020}my\u{0020}body,\u{0020}shatters\u{0020}my\u{0020}soul,\u{0020}and\u{0020}fills\u{0020}my\u{0020}mind\u{0020}with\u{0020}boundless\u{0020}inspiration\u{0020}for\u{0020}my\u{0020}music.\u{0020}\nThis\u{0020}time,\u{0020}that\u{0020}inspiration\u{0020}gave\u{0020}birth\u{0020}to\u{0020}three\u{0020}new\u{0020}tracks.\u{0020}Every\u{0020}time\u{0020}I\u{0020}complete\u{0020}a\u{0020}piece,\u{0020}I'm\u{0020}eager\u{0020}to\u{0020}share\u{0020}it,\u{0020}but…\u{0020}no\u{0020}one\u{0020}on\u{0020}the\u{0020}Ark\u{0020}has\u{0020}the\u{0020}spine\u{0020}to\u{0020}stick\u{0020}around\u{0020}and\u{0020}listen.\u{0020}Even\u{0020}the\u{0020}drivers\u{0020}run\u{0020}at\u{0020}the\u{0020}first\u{0020}note.\u{0020}Hah!\u{0020}What\u{0020}a\u{0020}sorry\u{0020}lot\u{0020}of\u{0020}cowards.\u{0020}\nBut\u{0020}you,\u{0020}Navigator—you're\u{0020}different.\u{0020}You've\u{0020}got\u{0020}the\u{0020}nerve,\u{0020}the\u{0020}rhythm,\u{0020}the\u{0020}vibe.\u{0020}One\u{0020}of\u{0020}these\u{0020}tracks?\u{0020}It's\u{0020}written\u{0020}just\u{0020}for\u{0020}you.\u{0020}So,\u{0020}how\u{0020}about\u{0020}it?\u{0020}Do\u{0020}you\u{0020}have\u{0020}the\u{0020}guts\u{0020}to\u{0020}join\u{0020}me\u{0020}and\u{0020}dive\u{0020}into\u{0020}this\u{0020}infernal\u{0020}melody?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100802] = {id = 11100802, name = "Ashlica", head = "11008", type = 5, title = "Hope\u{0020}Abyss", txt = "Navigator,\u{0020}I\u{0020}recently\u{0020}heard\u{0020}a\u{0020}saying:\u{0020}\"Every\u{0020}birthday\u{0020}means\u{0020}you're\u{0020}one\u{0020}step\u{0020}closer\u{0020}to\u{0020}death.\"\nHonestly…\u{0020}it's\u{0020}laughable.\u{0020}Does\u{0020}not\u{0020}celebrating\u{0020}birthdays\u{0020}make\u{0020}people\u{0020}immortal?\u{0020}Does\u{0020}the\u{0020}certainty\u{0020}of\u{0020}death\u{0020}mean\u{0020}we\u{0020}should\u{0020}stop\u{0020}living\u{0020}with\u{0020}all\u{0020}our\u{0020}strength.\u{0020}To\u{0020}me,\u{0020}that\u{0020}kind\u{0020}of\u{0020}thinking\u{0020}is\u{0020}something\u{0020}only\u{0020}true\u{0020}cowards\u{0020}cling\u{0020}to.\u{0020}The\u{0020}strong\u{0020}are\u{0020}those\u{0020}who\u{0020}live\u{0020}brilliant\u{0020}lives\u{0020}in\u{0020}spite\u{0020}of\u{0020}the\u{0020}fear\u{0020}of\u{0020}death.\nI've\u{0020}had\u{0020}a\u{0020}sudden\u{0020}inspiration.\u{0020}I'm\u{0020}going\u{0020}to\u{0020}write\u{0020}a\u{0020}song\u{0020}about\u{0020}birthdays,\u{0020}death,\u{0020}and\u{0020}growth.\u{0020}I\u{0020}will\u{0020}become\u{0020}the\u{0020}executioner\u{0020}of\u{0020}\"hope\"\u{0020}-\u{0020}with\u{0020}my\u{0020}bass,\u{0020}with\u{0020}my\u{0020}music,\u{0020}I'll\u{0020}kill\u{0020}the\u{0020}fear\u{0020}festering\u{0020}in\u{0020}the\u{0020}hearts\u{0020}of\u{0020}cowards.\u{0020}I'll\u{0020}drag\u{0020}them\u{0020}into\u{0020}an\u{0020}abyss\u{0020}deeper\u{0020}than\u{0020}death\u{0020}itself\u{0020}-\u{0020}an\u{0020}abyss\u{0020}called\u{0020}hope,\u{0020}where\u{0020}they\u{0020}will\u{0020}never\u{0020}escape.\nThat\u{0020}is\u{0020}my\u{0020}birthday\u{0020}wish\u{0020}this\u{0020}year.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111009] = {id = 111009, name = "Bolina", head = "11009", type = 5, title = "Birthday\u{0020}Gift", txt = "Content:\u{0020}[Audio\u{0020}transcript]\nNavigator,\u{0020}happy\u{0020}birthday\u{0020}to\u{0020}you!\u{0020}Oh,\u{0020}wait...\u{0020}No,\u{0020}happy\u{0020}birthday\u{0020}to\u{0020}me!\u{0020}Yes,\u{0020}today\u{0020}is\u{0020}Bolina's\u{0020}birthday!\u{0020}Iliya\u{0020}just\u{0020}told\u{0020}me!\nBut...\u{0020}what\u{0020}is\u{0020}a\u{0020}birthday?\u{0020}Bolina\u{0020}doesn't\u{0020}know.\u{0020}But\u{0020}a\u{0020}birthday\u{0020}means\u{0020}cake!\u{0020}And\u{0020}a\u{0020}big\u{0020}one!\u{0020}Bolina\u{0020}has\u{0020}never\u{0020}had\u{0020}a\u{0020}cake\u{0020}this\u{0020}big\u{0020}before,\u{0020}so\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}it\u{0020}with\u{0020}you.\nOh,\u{0020}and\u{0020}everyone\u{0020}gave\u{0020}me\u{0020}presents!\u{0020}Korowin\u{0020}gave\u{0020}me\u{0020}a\u{0020}novel.\u{0020}Hmm…\u{0020}Bolina\u{0020}can't\u{0020}read\u{0020}it.\u{0020}Crim\u{0020}gave\u{0020}me…\u{0020}wine?\u{0020}But\u{0020}Iliya\u{0020}won't\u{0020}allow\u{0020}it.\u{0020}It's\u{0020}fine.\u{0020}Bolina\u{0020}doesn't\u{0020}like\u{0020}alcohol\u{0020}anyway.\u{0020}Bolina\u{0020}prefers\u{0020}juice!\u{0020}And\u{0020}Iliya…?\u{0020}Ah,\u{0020}right!\u{0020}She\u{0020}was\u{0020}the\u{0020}one\u{0020}who\u{0020}gave\u{0020}me\u{0020}this\u{0020}big\u{0020}cake!\nSOOOOO—Navigator,\u{0020}when\u{0020}are\u{0020}you\u{0020}coming\u{0020}over?\u{0020}Bolina\u{0020}will\u{0020}be\u{0020}home,\u{0020}waiting\u{0020}for\u{0020}you!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11100901] = {id = 11100901, name = "Bolina", head = "11009", type = 5, title = "Bolina\u{0020}Bolina\u{0020}Bolina", txt = "Bolina\u{0020}Bolina\u{0020}Bolina.\nBolina\u{0020}is\u{0020}Bolina's\u{0020}name!\u{0020}Bolina\u{0020}likes\u{0020}her\u{0020}own\u{0020}name,\u{0020}and\u{0020}Bolina\u{0020}can\u{0020}write\u{0020}now!\nBolina\u{0020}can\u{0020}write\u{0020}more\u{0020}than\u{0020}just\u{0020}her\u{0020}own\u{0020}name\u{0020}-\u{0020}Bolina\u{0020}can\u{0020}write\u{0020}everyone's\u{0020}names.\nCrim\nKorowin\nIliya\u{0020}-\u{0020}Iliya\u{0020}taught\u{0020}Bolina\u{0020}how\u{0020}to\u{0020}write!\nAnd\u{0020}Navigator\u{0020}too!\u{0020}But\u{0020}is\u{0020}Navigator's\u{0020}name\u{0020}not\u{0020}actually\u{0020}Navigator?\nOh,\u{0020}and\u{0020}also...\u{0020}happy\u{0020}birthday!\nHappy\u{0020}birthday\u{0020}to\u{0020}Bolina,\u{0020}and\u{0020}Bolina\u{0020}hopes\u{0020}Navigator\u{0020}will\u{0020}be\u{0020}happy\u{0020}too!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111010] = {id = 111010, name = "Rou", head = "11010", type = 5, title = "一起去拔胡蘿蔔嗎？", txt = "\u{0020}那個那個那個那個那個那個......\nnavigator......那個......聽說瑪雅這邊的農業園裡的胡蘿蔔成熟了，他們正在舉辦收穫季的活動。只要是在當天生日的人，就可以免費領取一筐胡蘿蔔......\n但是我不知道埃塔人能不能參加這個活動......\n這幾天正好也是換毛的季節，渠都在忙著幫大家換毛的事，銀如往常一樣一直在訓練所，我一個人去的話又有點害怕......\n所以，navigator能陪著我嗎？唔~到時候拿到的胡蘿蔔可以分navigator一半。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101001] = {id = 11101001, name = "Rou", head = "11010", type = 5, title = "Want\u{0020}to\u{0020}Go\u{0020}Pull\u{0020}Some\u{0020}Carrots?", txt = "U-um…\nNavigator,\u{0020}I\u{0020}heard\u{0020}that\u{0020}the\u{0020}agricultural\u{0020}garden\u{0020}in\u{0020}Maya\u{0020}is\u{0020}having\u{0020}a\u{0020}harvest\u{0020}festival,\u{0020}and\u{0020}the\u{0020}carrots\u{0020}are\u{0020}ready\u{0020}to\u{0020}be\u{0020}picked.\u{0020}They're\u{0020}offering\u{0020}a\u{0020}free\u{0020}basket\u{0020}of\u{0020}carrots\u{0020}to\u{0020}anyone\u{0020}celebrating\u{0020}their\u{0020}birthday\u{0020}that\u{0020}day…\nBut,\u{0020}uh,\u{0020}I'm\u{0020}not\u{0020}sure\u{0020}if\u{0020}the\u{0020}Eta\u{0020}people\u{0020}can\u{0020}join\u{0020}in…\nAnd,\u{0020}well,\u{0020}it's\u{0020}shedding\u{0020}season,\u{0020}so\u{0020}Mizo's\u{0020}busy\u{0020}helping\u{0020}everyone\u{0020}with\u{0020}their\u{0020}coats.\u{0020}Shirogane\u{0020}is\u{0020}at\u{0020}the\u{0020}training\u{0020}facility\u{0020}as\u{0020}usual,\u{0020}so\u{0020}I'd\u{0020}be\u{0020}all\u{0020}alone…\u{0020}I'm\u{0020}kind\u{0020}of\u{0020}nervous\u{0020}about\u{0020}going\u{0020}by\u{0020}myself…\nSo,\u{0020}um,\u{0020}would\u{0020}you\u{0020}mind\u{0020}coming\u{0020}with\u{0020}me?\u{0020}Hehe,\u{0020}I'll\u{0020}share\u{0020}half\u{0020}of\u{0020}the\u{0020}carrots\u{0020}with\u{0020}you\u{0020}if\u{0020}you\u{0020}do.\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101002] = {id = 11101002, name = "Rou", head = "11010", type = 5, title = "Have\u{0020}a\u{0020}Sweet\u{0020}Dream\u{0020}/\u{0020}I\u{0020}Want\u{0020}to\u{0020}Sleep\u{0020}With\u{0020}You", txt = "Navigator,\u{0020}time\u{0020}on\u{0020}Earth\u{0020}passes\u{0020}so\u{0020}quickly...\u{0020}in\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye,\u{0020}it's\u{0020}my\u{0020}birthday\u{0020}again.\u{0020}\nThis\u{0020}past\u{0020}year\u{0020}feels\u{0020}like\u{0020}it\u{0020}was\u{0020}only\u{0020}a\u{0020}single\u{0020}day\u{0020}to\u{0020}me.\u{0020}In\u{0020}the\u{0020}morning,\u{0020}I\u{0020}wake\u{0020}up\u{0020}on\u{0020}a\u{0020}bed\u{0020}layered\u{0020}with\u{0020}cotton\u{0020}and\u{0020}straw.\u{0020}After\u{0020}a\u{0020}quick\u{0020}wash,\u{0020}I\u{0020}head\u{0020}out,\u{0020}greet\u{0020}Captain\u{0020}Shirogane\u{0020}and\u{0020}Mizo\u{0020}senpai,\u{0020}report\u{0020}in.\u{0020}Then\u{0020}we\u{0020}prepare\u{0020}and\u{0020}go\u{0020}on\u{0020}patrol\u{0020}together,\u{0020}returning\u{0020}at\u{0020}sunset\u{0020}and\u{0020}dusk,\u{0020}and\u{0020}finally\u{0020}each\u{0020}go\u{0020}back\u{0020}to\u{0020}our\u{0020}own\u{0020}place\u{0020}to\u{0020}rest.\u{0020}\nDay\u{0020}after\u{0020}day.\u{0020}\nI\u{0020}like\u{0020}laying\u{0020}straw\u{0020}on\u{0020}my\u{0020}bed.\u{0020}Dried\u{0020}straw\u{0020}is\u{0020}fluffy\u{0020}and\u{0020}warm,\u{0020}and\u{0020}the\u{0020}lingering\u{0020}fragrance\u{0020}of\u{0020}rice\u{0020}grains\u{0020}is\u{0020}especially\u{0020}soothing.\u{0020}It\u{0020}makes\u{0020}it\u{0020}feel\u{0020}more\u{0020}like\u{0020}home.\u{0020}\nWhat\u{0020}do\u{0020}you\u{0020}like\u{0020}to\u{0020}sleep\u{0020}on,\u{0020}Navigator?\u{0020}If\u{0020}you've\u{0020}been\u{0020}troubled\u{0020}by\u{0020}insomnia\u{0020}lately,\u{0020}then\u{0020}maybe...\u{0020}maybe...\u{0020}um...\u{0020}you\u{0020}could\u{0020}come\u{0020}to\u{0020}Rou's\u{0020}place.\u{0020}With\u{0020}the\u{0020}scent\u{0020}of\u{0020}straw,\u{0020}and\u{0020}with\u{0020}Rou\u{0020}by\u{0020}your\u{0020}side,\u{0020}you\u{0020}can\u{0020}have\u{0020}a\u{0020}good\u{0020}dream.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111011] = {id = 111011, name = "Gourai", head = "11011", type = 5, title = "非navigator者若窺此信格殺勿論", txt = "不知navigator是否還記得今日是我生日一事？如若忘記倒也無妨，實不相瞞，我此番是有事求於navigator。\n事情說起來也簡單，近來總部突然傳聞有人正在計劃對您進行某種不可告人的行為，牽扯到心經屋的某位駕駛員，忍心社正在調查此事。我想近距離接觸那位駕駛員，但又不想暴露忍心社……或者說我的身份。\n假如navigator能提供一下幫助，找個藉口與那位同僚見面，屆時我偽裝身份跟隨，即可與其近距離接觸。這便是我的計劃。\n至於這個偽裝的身份……青梅、戀人又或者是妻子……navigator更喜歡哪一個呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101101] = {id = 11101101, name = "Gourai", head = "11011", type = 5, title = "密信navigator閱後請速速焚毀不留痕跡", txt = "不知navigator是否還記得今日是我生日一事？如若忘記倒也無妨，實不相瞞，我此番是有事求於navigator。\n事情說起來也簡單，近來總部突然傳聞有人正在計劃對您進行某種不可告人的行為，牽扯到心經屋的某位駕駛員，忍心社正在調查此事。我想近距離接觸那位駕駛員，但又不想暴露忍心社……或者說我的身份。\n假如navigator能提供一下幫助，找個藉口與那位同僚見面，屆時我偽裝身份跟隨，即可與其近距離接觸。這便是我的計劃。\n至於這個偽裝的身份……青梅、戀人又或者是妻子……navigator更喜歡哪一個呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101102] = {id = 11101102, name = "Gourai", head = "11011", type = 5, title = "Unauthorized\u{0020}Readers\u{0020}Will\u{0020}Be\u{0020}Eliminated\u{0020}Without\u{0020}Mercy", txt = "Forgive\u{0020}my\u{0020}abruptness\u{0020}in\u{0020}penning\u{0020}this\u{0020}confidential\u{0020}missive;\u{0020}circumstances\u{0020}leave\u{0020}me\u{0020}no\u{0020}choice.\u{0020}Time\u{0020}is\u{0020}of\u{0020}the\u{0020}essence,\u{0020}so\u{0020}I\u{0020}shall\u{0020}be\u{0020}direct:\u{0020}For\u{0020}this\u{0020}day\u{0020}alone,\u{0020}I\u{0020}humbly\u{0020}request\u{0020}you\u{0020}lend\u{0020}me\u{0020}your\u{0020}idle\u{0020}hours\u{0020}to\u{0020}aid\u{0020}me\u{0020}in\u{0020}fulfilling\u{0020}my\u{0020}duties\u{0020}unimpeded.\nYou\u{0020}may\u{0020}have\u{0020}guessed\u{0020}it:\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday.\u{0020}That\u{0020}said,\u{0020}I\u{0020}have\u{0020}never\u{0020}been\u{0020}one\u{0020}to\u{0020}celebrate,\u{0020}much\u{0020}less\u{0020}now\u{0020}when\u{0020}pressing\u{0020}missions\u{0020}brook\u{0020}no\u{0020}distraction.\u{0020}However,\u{0020}Meika\u{0020}and\u{0020}the\u{0020}other\u{0020}girls\u{0020}have\u{0020}been\u{0020}relentlessly\u{0020}interfering\u{0020}with\u{0020}my\u{0020}work\u{0020}with\u{0020}their\u{0020}ninja\u{0020}arts,\u{0020}insisting\u{0020}I\u{0020}\"take\u{0020}the\u{0020}day\u{0020}off.\u{0020}Even\u{0020}for\u{0020}once.\"\nNinja\u{0020}Group's\u{0020}duty\u{0020}to\u{0020}uphold\u{0020}the\u{0020}system's\u{0020}integrity\u{0020}is\u{0020}absolute;\u{0020}how\u{0020}could\u{0020}I\u{0020}possibly\u{0020}abandon\u{0020}my\u{0020}post?\u{0020}Thus,\u{0020}I\u{0020}have\u{0020}a\u{0020}plan:\u{0020}Should\u{0020}you\u{0020}accompany\u{0020}me\u{0020}under\u{0020}the\u{0020}guise\u{0020}of\u{0020}a\u{0020}rendezvous,\u{0020}their\u{0020}surveillance\u{0020}will\u{0020}cease\u{0020}upon\u{0020}sight\u{0020}of\u{0020}us.\nRest\u{0020}assured,\u{0020}this\u{0020}debt\u{0020}shall\u{0020}be\u{0020}repaid.\u{0020}Once\u{0020}the\u{0020}deal\u{0020}is\u{0020}settled,\u{0020}whatever\u{0020}you\u{0020}ask\u{0020}of\u{0020}me,\u{0020}consider\u{0020}it\u{0020}done.\u{0020}You\u{0020}have\u{0020}my\u{0020}word.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101103] = {id = 11101103, name = "Gourai", head = "11011", type = 5, title = "Confidential\u{0020}Letter\u{0020}to\u{0020}Navigator\u{0020}-\u{0020}Please\u{0020}Burn\u{0020}Immediately\u{0020}After\u{0020}Reading\u{0020}Without\u{0020}Leaving\u{0020}a\u{0020}Trace", txt = "I\u{0020}wonder\u{0020}whether\u{0020}you\u{0020}still\u{0020}remember\u{0020}that\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday?\u{0020}If\u{0020}you\u{0020}have\u{0020}forgotten,\u{0020}that\u{0020}is\u{0020}no\u{0020}matter.\u{0020}To\u{0020}be\u{0020}honest,\u{0020}I\u{0020}am\u{0020}writing\u{0020}because\u{0020}I\u{0020}have\u{0020}a\u{0020}favor\u{0020}to\u{0020}ask\u{0020}of\u{0020}you.\nThe\u{0020}matter\u{0020}itself\u{0020}is\u{0020}rather\u{0020}simple.\u{0020}Recently,\u{0020}rumors\u{0020}have\u{0020}suddenly\u{0020}begun\u{0020}circulating\u{0020}at\u{0020}headquarters\u{0020}that\u{0020}someone\u{0020}is\u{0020}planning\u{0020}some\u{0020}unspeakable\u{0020}act\u{0020}against\u{0020}you.\u{0020}It\u{0020}seems\u{0020}to\u{0020}involve\u{0020}a\u{0020}certain\u{0020}driver\u{0020}from\u{0020}Shingyou,\u{0020}and\u{0020}Ninja\u{0020}Group\u{0020}is\u{0020}currently\u{0020}investigating\u{0020}the\u{0020}matter.\u{0020}I\u{0020}wish\u{0020}to\u{0020}get\u{0020}close\u{0020}to\u{0020}that\u{0020}driver,\u{0020}but\u{0020}I\u{0020}do\u{0020}not\u{0020}want\u{0020}to\u{0020}expose\u{0020}Ninja\u{0020}Group...\u{0020}or\u{0020}rather,\u{0020}my\u{0020}own\u{0020}identity.\nIf\u{0020}you\u{0020}would\u{0020}be\u{0020}willing\u{0020}to\u{0020}lend\u{0020}me\u{0020}a\u{0020}hand,\u{0020}perhaps\u{0020}you\u{0020}could\u{0020}find\u{0020}an\u{0020}excuse\u{0020}to\u{0020}meet\u{0020}with\u{0020}that\u{0020}colleague.\u{0020}At\u{0020}that\u{0020}time,\u{0020}I\u{0020}could\u{0020}accompany\u{0020}you\u{0020}in\u{0020}disguise\u{0020}and\u{0020}get\u{0020}close\u{0020}to\u{0020}them.\u{0020}That\u{0020}is\u{0020}my\u{0020}plan.\nAs\u{0020}for\u{0020}what\u{0020}identity\u{0020}I\u{0020}should\u{0020}assume\u{0020}in\u{0020}this\u{0020}disguise...\u{0020}a\u{0020}childhood\u{0020}friend,\u{0020}a\u{0020}lover,\u{0020}or\u{0020}perhaps\u{0020}a\u{0020}wife...\u{0020}which\u{0020}one\u{0020}do\u{0020}you\u{0020}prefer,\u{0020}Navigator?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111014] = {id = 111014, name = "Skadi", head = "11014", type = 5, title = "The\u{0020}Queen\u{0020}of\u{0020}Dun\u{0020}Scaith's\u{0020}Grand\u{0020}Banquet!", txt = "Rejoice!\u{0020}Today\u{0020}marks\u{0020}my\u{0020}glorious\u{0020}birth\u{0020}and\u{0020}the\u{0020}sacred\u{0020}festival\u{0020}of\u{0020}the\u{0020}Dun\u{0020}Scaith!\u{0020}And\u{0020}you,\u{0020}favored\u{0020}one,\u{0020}are\u{0020}hereby\u{0020}granted\u{0020}passage\u{0020}to\u{0020}our\u{0020}lands.\u{0020}To\u{0020}feast\u{0020}with\u{0020}my\u{0020}subjects\u{0020}at\u{0020}the\u{0020}Queen's\u{0020}annual\u{0020}revel!\nShould\u{0020}you\u{0020}dare\u{0020}tread\u{0020}the\u{0020}line\u{0020}between\u{0020}night\u{0020}and\u{0020}day\u{0020}alone,\u{0020}your\u{0020}soul\u{0020}may\u{0020}fray\u{0020}betwixt\u{0020}time.\u{0020}But\u{0020}fear\u{0020}not!\u{0020}This\u{0020}token\u{0020}bears\u{0020}my\u{0020}blessing,\u{0020}shielding\u{0020}you\u{0020}from...\n\n\nNavigator!\u{0020}Can\u{0020}you\u{0020}please\u{0020}deal\u{0020}with\u{0020}Lilith?\u{0020}She's\u{0020}ruining\u{0020}my\u{0020}invitation\u{0020}cards\u{0020}again!\u{0020}\"The\u{0020}sentence\u{0020}is\u{0020}grammatically\u{0020}wrong.\"\u{0020}\"Your\u{0020}word\u{0020}choice\u{0020}is\u{0020}weird.”\nUgh!\u{0020}What\u{0020}does\u{0020}she\u{0020}know?\u{0020}This\u{0020}is\u{0020}perfect!!!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101401] = {id = 11101401, name = "Skadi", head = "11014", type = 5, title = "I\u{0020}Shall\u{0020}Shine\u{0020}Brilliantly", txt = "Emergency\u{0020}Notice\u{0020}from\u{0020}Dunescaith\nLong\u{0020}time\u{0020}no\u{0020}see,\u{0020}Navigator.\u{0020}I\u{0020}have\u{0020}ended\u{0020}the\u{0020}battle\u{0020}in\u{0020}the\u{0020}Realm\u{0020}of\u{0020}the\u{0020}Sixth\u{0020}Heaven\u{0020}and\u{0020}returned\u{0020}victorious.\nThrough\u{0020}our\u{0020}intervention\u{0020}from\u{0020}Dunescaith,\u{0020}this\u{0020}Realm\u{0020}of\u{0020}the\u{0020}Sixth\u{0020}Heaven\u{0020}has\u{0020}become\u{0020}peaceful.\u{0020}We\u{0020}of\u{0020}Moon\u{0020}Corona\u{0020}successfully\u{0020}purified\u{0020}the\u{0020}sacred\u{0020}body\u{0020}of\u{0020}the\u{0020}eternal\u{0020}kitty\u{0020}that\u{0020}endlessly\u{0020}shed\u{0020}its\u{0020}husks.\nThis\u{0020}cannot\u{0020}help\u{0020}but\u{0020}remind\u{0020}me\u{0020}of\u{0020}the\u{0020}days\u{0020}when\u{0020}I\u{0020}fought\u{0020}by\u{0020}your\u{0020}side.\nI\u{0020}look\u{0020}forward\u{0020}to\u{0020}meeting\u{0020}you\u{0020}once\u{0020}again.\u{0020}On\u{0020}the\u{0020}divine\u{0020}birthday\u{0020}of\u{0020}the\u{0020}Queen\u{0020}of\u{0020}Dunescaith,\u{0020}please\u{0020}be\u{0020}sure\u{0020}to\u{0020}honor\u{0020}me\u{0020}with\u{0020}your\u{0020}presence.\n\n\nAttachment\nAh--ha--ha!\u{0020}How\u{0020}was\u{0020}that,\u{0020}Navigator?\u{0020}Were\u{0020}you\u{0020}shaken\u{0020}to\u{0020}your\u{0020}core\u{0020}by\u{0020}my\u{0020}dignified\u{0020}and\u{0020}formal\u{0020}writing?\u{0020}It\u{0020}surprised\u{0020}you,\u{0020}right?\u{0020}But\u{0020}this\u{0020}is\u{0020}not\u{0020}even\u{0020}my\u{0020}limit.\u{0020}At\u{0020}the\u{0020}birthday\u{0020}party,\u{0020}I\u{0020}will\u{0020}shine\u{0020}even\u{0020}more!\u{0020}Even\u{0020}more\u{0020}brilliantly!\u{0020}I\u{0020}am\u{0020}already\u{0020}prepared,\u{0020}so\u{0020}you\u{0020}have\u{0020}to\u{0020}come!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111015] = {id = 111015, name = "Suzu", head = "11015", type = 5, title = "A\u{0020}Birthday\u{0020}Greeting\u{0020}from\u{0020}a\u{0020}Genius", txt = "Hello,\u{0020}Navigator!\nHow's\u{0020}everything\u{0020}going?\u{0020}Guess\u{0020}what?\u{0020}Today's\u{0020}my\u{0020}birthday!\u{0020}It's\u{0020}one\u{0020}of\u{0020}those\u{0020}rare\u{0020}birthdays\u{0020}that\u{0020}only\u{0020}comes\u{0020}around\u{0020}a\u{0020}hundred\u{0020}times\u{0020}in\u{0020}a\u{0020}hundred\u{0020}years.\nOh,\u{0020}speaking\u{0020}of\u{0020}birthdays,\u{0020}have\u{0020}you\u{0020}heard\u{0020}about\u{0020}this\u{0020}new\u{0020}trend?\u{0020}Apparently,\u{0020}drivers\u{0020}are\u{0020}supposed\u{0020}to\u{0020}send\u{0020}letters\u{0020}and\u{0020}gifts\u{0020}to\u{0020}their\u{0020}Navigators\u{0020}on\u{0020}their\u{0020}birthdays.\nStrange,\u{0020}isn't\u{0020}it?\nWhy\u{0020}should\u{0020}we\u{0020}be\u{0020}giving\u{0020}out\u{0020}gifts\u{0020}on\u{0020}our\u{0020}special\u{0020}day?\nThere's\u{0020}definitely\u{0020}some\u{0020}kind\u{0020}of\u{0020}mystery\u{0020}behind\u{0020}this,\u{0020}and\u{0020}as\u{0020}the\u{0020}genius\u{0020}that\u{0020}I\u{0020}am,\u{0020}I'm\u{0020}determined\u{0020}to\u{0020}get\u{0020}to\u{0020}the\u{0020}bottom\u{0020}of\u{0020}it!\nSo,\u{0020}as\u{0020}part\u{0020}of\u{0020}my\u{0020}brilliant\u{0020}investigation,\u{0020}I'm\u{0020}sending\u{0020}you\u{0020}these\u{0020}gifts\u{0020}today.\nLet's\u{0020}see\u{0020}if\u{0020}anything\u{0020}amazing\u{0020}happens\u{0020}because\u{0020}of\u{0020}it!\n", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101501] = {id = 11101501, name = "Suzu", head = "11015", type = 5, title = "A\u{0020}Birthday\u{0020}Greeting\u{0020}from\u{0020}a\u{0020}Genius", txt = "Hello,\u{0020}Navigator!\nHow's\u{0020}everything\u{0020}going?\u{0020}Guess\u{0020}what?\u{0020}Today's\u{0020}my\u{0020}birthday!\u{0020}It's\u{0020}one\u{0020}of\u{0020}those\u{0020}rare\u{0020}birthdays\u{0020}that\u{0020}only\u{0020}comes\u{0020}around\u{0020}a\u{0020}hundred\u{0020}times\u{0020}in\u{0020}a\u{0020}hundred\u{0020}years.\nOh,\u{0020}speaking\u{0020}of\u{0020}birthdays,\u{0020}have\u{0020}you\u{0020}heard\u{0020}about\u{0020}this\u{0020}new\u{0020}trend?\u{0020}Apparently,\u{0020}drivers\u{0020}are\u{0020}supposed\u{0020}to\u{0020}send\u{0020}letters\u{0020}and\u{0020}gifts\u{0020}to\u{0020}their\u{0020}Navigators\u{0020}on\u{0020}their\u{0020}birthdays.\nStrange,\u{0020}isn't\u{0020}it?\nWhy\u{0020}should\u{0020}we\u{0020}be\u{0020}giving\u{0020}out\u{0020}gifts\u{0020}on\u{0020}our\u{0020}special\u{0020}day?\nThere's\u{0020}definitely\u{0020}some\u{0020}kind\u{0020}of\u{0020}mystery\u{0020}behind\u{0020}this,\u{0020}and\u{0020}as\u{0020}the\u{0020}genius\u{0020}that\u{0020}I\u{0020}am,\u{0020}I'm\u{0020}determined\u{0020}to\u{0020}get\u{0020}to\u{0020}the\u{0020}bottom\u{0020}of\u{0020}it!\nSo,\u{0020}as\u{0020}part\u{0020}of\u{0020}my\u{0020}brilliant\u{0020}investigation,\u{0020}I'm\u{0020}sending\u{0020}you\u{0020}these\u{0020}gifts\u{0020}today.\nLet's\u{0020}see\u{0020}if\u{0020}anything\u{0020}amazing\u{0020}happens\u{0020}because\u{0020}of\u{0020}it!\n", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101502] = {id = 11101502, name = "Suzu", head = "11015", type = 5, title = "The\u{0020}Most\u{0020}Special\u{0020}Day", txt = "Today\u{0020}is\u{0020}the\u{0020}birthday\u{0020}of\u{0020}the\u{0020}great\u{0020}genius,\u{0020}Suzu.\nToday\u{0020}is\u{0020}the\u{0020}deathday\u{0020}of\u{0020}my\u{0020}mother.\nToday\u{0020}is\u{0020}the\u{0020}day\u{0020}I\u{0020}met\u{0020}my\u{0020}second\u{0020}mother.\nFor\u{0020}me,\u{0020}today\u{0020}is\u{0020}an\u{0020}incredibly\u{0020}special\u{0020}day,\u{0020}a\u{0020}day\u{0020}when\u{0020}I\u{0020}can\u{0020}laugh,\u{0020}cry,\u{0020}and\u{0020}freely\u{0020}do\u{0020}whatever\u{0020}I\u{0020}wish.\nI\u{0020}will\u{0020}cherish\u{0020}this\u{0020}special\u{0020}day\u{0020}and\u{0020}live\u{0020}it\u{0020}with\u{0020}a\u{0020}hundredfold\u{0020}of\u{0020}heartfelt\u{0020}feelings.\nNavigator,\u{0020}could\u{0020}you\u{0020}come\u{0020}back\u{0020}to\u{0020}my\u{0020}hometown\u{0020}with\u{0020}me?\u{0020}I'd\u{0020}like\u{0020}to\u{0020}tell\u{0020}my\u{0020}first\u{0020}mother\u{0020}all\u{0020}about\u{0020}you.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111016] = {id = 111016, name = "Kurobane", head = "11016", type = 5, title = "Seeking\u{0020}Your\u{0020}Guidance", txt = "I\u{0020}just\u{0020}received\u{0020}messages\u{0020}from\u{0020}members\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group,\u{0020}and\u{0020}that's\u{0020}how\u{0020}I\u{0020}remembered:\u{0020}it's\u{0020}my\u{0020}birthday\u{0020}today.\u{0020}In\u{0020}their\u{0020}letters,\u{0020}the\u{0020}other\u{0020}Meika\u{0020}mentioned\u{0020}that\u{0020}a\u{0020}birthday\u{0020}is\u{0020}an\u{0020}important\u{0020}occasion\u{0020}worth\u{0020}celebrating,\u{0020}and\u{0020}should\u{0020}be\u{0020}spent\u{0020}with\u{0020}someone\u{0020}I\u{0020}trust\u{0020}and\u{0020}hold\u{0020}dear.\u{0020}But...\u{0020}if\u{0020}that\u{0020}is\u{0020}the\u{0020}case,\u{0020}then\u{0020}I\u{0020}have\u{0020}essentially\u{0020}been\u{0020}celebrating\u{0020}my\u{0020}birthday\u{0020}every\u{0020}day\u{0020}since\u{0020}I\u{0020}became\u{0020}your\u{0020}guard.\nDuring\u{0020}the\u{0020}years\u{0020}when\u{0020}I\u{0020}was\u{0020}young\u{0020}and\u{0020}being\u{0020}trained\u{0020}by\u{0020}my\u{0020}clan\u{0020}as\u{0020}the\u{0020}next\u{0020}Kurobane,\u{0020}I\u{0020}never\u{0020}received\u{0020}any\u{0020}special\u{0020}recognition\u{0020}from\u{0020}my\u{0020}elders\u{0020}for\u{0020}anything\u{0020}trivial,\u{0020}including\u{0020}birthdays.\u{0020}Naturally,\u{0020}even\u{0020}now,\u{0020}I\u{0020}don't\u{0020}know\u{0020}how\u{0020}one\u{0020}should\u{0020}celebrate.\nBut\u{0020}since\u{0020}staying\u{0020}by\u{0020}your\u{0020}side\u{0020}is\u{0020}the\u{0020}right\u{0020}thing\u{0020}to\u{0020}do,\u{0020}perhaps\u{0020}no\u{0020}additional\u{0020}actions\u{0020}are\u{0020}necessary.\u{0020}Today\u{0020}can\u{0020}simply\u{0020}be\u{0020}like\u{0020}any\u{0020}other\u{0020}day.\nOf\u{0020}course...\u{0020}please\u{0020}enlighten\u{0020}me,\u{0020}if\u{0020}you,\u{0020}Navigator,\u{0020}have\u{0020}more\u{0020}fitting\u{0020}ways\u{0020}to\u{0020}mark\u{0020}the\u{0020}occasion.\u{0020}I\u{0020}am\u{0020}ready\u{0020}to\u{0020}listen\u{0020}and\u{0020}follow\u{0020}your\u{0020}guidance.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101601] = {id = 11101601, name = "Kurobane", head = "11016", type = 5, title = "The\u{0020}Path\u{0020}of\u{0020}Protection\u{0020}Lies\u{0020}Within", txt = "The\u{0020}Kurobane\u{0020}clan\u{0020}is\u{0020}a\u{0020}lineage\u{0020}of\u{0020}guardians—ninjas\u{0020}who\u{0020}walk\u{0020}the\u{0020}world\u{0020}guided\u{0020}by\u{0020}the\u{0020}conviction\u{0020}to\u{0020}protect,\u{0020}until\u{0020}the\u{0020}day\u{0020}we\u{0020}find\u{0020}the\u{0020}one\u{0020}worthy\u{0020}of\u{0020}our\u{0020}loyalty.\u{0020}\n\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}every\u{0020}successor\u{0020}who\u{0020}bears\u{0020}the\u{0020}name\u{0020}\"Kurobane\"\u{0020}only\u{0020}comes\u{0020}to\u{0020}understand\u{0020}emotion\u{0020}after\u{0020}discovering\u{0020}the\u{0020}one\u{0020}thing\u{0020}they\u{0020}truly\u{0020}wish\u{0020}to\u{0020}protect.\u{0020}\n\u{0020}Perhaps\u{0020}my\u{0020}family\u{0020}is\u{0020}an\u{0020}exception\u{0020}among\u{0020}exceptions.\u{0020}I\u{0020}could\u{0020}feel\u{0020}it\u{0020}clearly—they\u{0020}raised\u{0020}me\u{0020}as\u{0020}a\u{0020}person,\u{0020}not\u{0020}as\u{0020}a\u{0020}tool.\u{0020}And\u{0020}I\u{0020}answered\u{0020}that\u{0020}trust\u{0020}by\u{0020}prevailing\u{0020}in\u{0020}the\u{0020}trials\u{0020}and\u{0020}earning\u{0020}the\u{0020}name\u{0020}\"Kurobane\".\u{0020}\n\u{0020}Even\u{0020}so…\u{0020}I\u{0020}have\u{0020}never\u{0020}celebrated\u{0020}a\u{0020}birthday\u{0020}with\u{0020}them.\u{0020}\n\u{0020}So,\u{0020}I\u{0020}would\u{0020}like\u{0020}to\u{0020}take\u{0020}this\u{0020}opportunity\u{0020}to\u{0020}return\u{0020}home\u{0020}and\u{0020}see\u{0020}my\u{0020}family.\u{0020}\n\u{0020}And\u{0020}I\u{0020}wish\u{0020}to\u{0020}introduce\u{0020}them\u{0020}properly—to\u{0020}you,\u{0020}my\u{0020}Lord,\u{0020}the\u{0020}one\u{0020}I\u{0020}now\u{0020}serve.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111017] = {id = 111017, name = "Flora", head = "11017", type = 5, title = "April\u{0020}Drizzle\u{0020}Brings\u{0020}May\u{0020}Blossoms", txt = "The\u{0020}weather\u{0020}has\u{0020}changed\u{0020}recently.\u{0020}The\u{0020}frequent\u{0020}spring\u{0020}rain\u{0020}has\u{0020}left\u{0020}the\u{0020}air\u{0020}thick\u{0020}with\u{0020}moisture.\u{0020}I\u{0020}wonder\u{0020}if\u{0020}you\u{0020}have\u{0020}been\u{0020}keeping\u{0020}well,\u{0020}Navigator.\nAll\u{0020}across\u{0020}the\u{0020}city,\u{0020}leaves\u{0020}are\u{0020}weighed\u{0020}down\u{0020}by\u{0020}glistening\u{0020}droplets,\u{0020}bending\u{0020}lower\u{0020}with\u{0020}each\u{0020}passing\u{0020}day,\u{0020}like\u{0020}bowstrings\u{0020}drawn\u{0020}taut.\u{0020}You\u{0020}know,\u{0020}there's\u{0020}an\u{0020}old\u{0020}saying\u{0020}from\u{0020}the\u{0020}Danube:\u{0020}April\u{0020}Drizzle\u{0020}brings\u{0020}May\u{0020}blossoms.\u{0020}Once\u{0020}the\u{0020}rains\u{0020}have\u{0020}passed,\u{0020}one\u{0020}will\u{0020}surely\u{0020}be\u{0020}greeted\u{0020}with\u{0020}an\u{0020}even\u{0020}more\u{0020}pleasant\u{0020}fragrance.\nMy\u{0020}birthday\u{0020}always\u{0020}arrives\u{0020}alongside\u{0020}this\u{0020}season,\u{0020}though\u{0020}I'm\u{0020}grateful\u{0020}for\u{0020}the\u{0020}Ark\u{0020}as\u{0020}my\u{0020}shelter\u{0020}from\u{0020}unpredictable\u{0020}rain.\u{0020}If\u{0020}you're\u{0020}free,\u{0020}Navigator,\u{0020}I'd\u{0020}be\u{0020}delighted\u{0020}if\u{0020}you\u{0020}join\u{0020}me\u{0020}for\u{0020}a\u{0020}stroll\u{0020}through\u{0020}the\u{0020}misty\u{0020}Danube.\u{0020}And\u{0020}when\u{0020}we\u{0020}grow\u{0020}tired,\u{0020}we\u{0020}can\u{0020}sit\u{0020}by\u{0020}the\u{0020}window,\u{0020}listening\u{0020}to\u{0020}the\u{0020}patter\u{0020}of\u{0020}raindrops\u{0020}while\u{0020}sipping\u{0020}on\u{0020}a\u{0020}fine\u{0020}cup\u{0020}of\u{0020}rose\u{0020}tea.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101701] = {id = 11101701, name = "Flora", head = "11017", type = 5, title = "Would\u{0020}You\u{0020}Like\u{0020}to\u{0020}Have\u{0020}Tea\u{0020}Together?", txt = "Forgive\u{0020}me\u{0020}for\u{0020}troubling\u{0020}you\u{0020}amid\u{0020}your\u{0020}busy\u{0020}schedule.\u{0020}I\u{0020}wonder\u{0020}how\u{0020}you\u{0020}have\u{0020}been\u{0020}lately,\u{0020}Navigator.\nThe\u{0020}rain\u{0020}of\u{0020}these\u{0020}past\u{0020}few\u{0020}days\u{0020}seems\u{0020}to\u{0020}be\u{0020}reminding\u{0020}me\u{0020}that\u{0020}my\u{0020}birthday\u{0020}has\u{0020}come\u{0020}around\u{0020}once\u{0020}again.\u{0020}For\u{0020}some\u{0020}reason,\u{0020}this\u{0020}year,\u{0020}on\u{0020}my\u{0020}birthday\u{0020}of\u{0020}all\u{0020}days,\u{0020}I\u{0020}especially\u{0020}wanted\u{0020}to\u{0020}see\u{0020}you.\nRecently,\u{0020}I\u{0020}received\u{0020}a\u{0020}shipment\u{0020}from\u{0020}Kyushu,\u{0020}and\u{0020}while\u{0020}going\u{0020}through\u{0020}it,\u{0020}I\u{0020}found\u{0020}a\u{0020}packet\u{0020}of\u{0020}tea.\u{0020}It\u{0020}seems\u{0020}to\u{0020}be\u{0020}one\u{0020}of\u{0020}Kyushu's\u{0020}specialties.\u{0020}The\u{0020}leaves\u{0020}are\u{0020}tender\u{0020}green\u{0020}with\u{0020}a\u{0020}hidden\u{0020}luster,\u{0020}and\u{0020}the\u{0020}fragrance\u{0020}is\u{0020}wonderfully\u{0020}rich,\u{0020}quite\u{0020}different\u{0020}from\u{0020}the\u{0020}tea\u{0020}of\u{0020}Danube.\u{0020}I\u{0020}imagine\u{0020}that\u{0020}perhaps,\u{0020}on\u{0020}this\u{0020}Ark\u{0020}in\u{0020}Danube,\u{0020}only\u{0020}you\u{0020}truly\u{0020}understand\u{0020}Kyushu's\u{0020}tea\u{0020}culture\u{0020}well\u{0020}enough\u{0020}not\u{0020}to\u{0020}waste\u{0020}such\u{0020}a\u{0020}rare\u{0020}treasure.\nIf\u{0020}you\u{0020}have\u{0020}no\u{0020}other\u{0020}plans\u{0020}today,\u{0020}would\u{0020}you\u{0020}be\u{0020}willing\u{0020}to\u{0020}come\u{0020}to\u{0020}my\u{0020}residence\u{0020}so\u{0020}we\u{0020}may\u{0020}enjoy\u{0020}some\u{0020}tea\u{0020}together?\u{0020}I\u{0020}would\u{0020}also\u{0020}like\u{0020}to\u{0020}hear\u{0020}you\u{0020}speak\u{0020}of\u{0020}the\u{0020}people\u{0020}and\u{0020}happenings\u{0020}beyond\u{0020}this\u{0020}Ark.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111018] = {id = 111018, name = "Shirogane", head = "11018", type = 5, title = "The\u{0020}Moon\u{0020}and\u{0020}Apple\u{0020}Pie", txt = "Birthdays\u{0020}are\u{0020}actually\u{0020}a\u{0020}pretty\u{0020}big\u{0020}deal\u{0020}for\u{0020}us\u{0020}Eta\u{0020}people.\u{0020}Given\u{0020}the\u{0020}length\u{0020}of\u{0020}time\u{0020}on\u{0020}our\u{0020}planet,\u{0020}the\u{0020}gap\u{0020}between\u{0020}two\u{0020}birthdays\u{0020}is\u{0020}roughly\u{0020}equivalent\u{0020}to\u{0020}several\u{0020}Earth\u{0020}years.\u{0020}But\u{0020}since\u{0020}we're\u{0020}currently\u{0020}living\u{0020}on\u{0020}Earth,\u{0020}I\u{0020}guess\u{0020}it's\u{0020}only\u{0020}right\u{0020}to\u{0020}adopt\u{0020}the\u{0020}local\u{0020}custom\u{0020}and\u{0020}celebrate\u{0020}once\u{0020}a\u{0020}year\u{0020}like\u{0020}everyone\u{0020}else.\nThat\u{0020}means\u{0020}the\u{0020}way\u{0020}we\u{0020}celebrate\u{0020}needs\u{0020}to\u{0020}change\u{0020}as\u{0020}well.\u{0020}We\u{0020}can't\u{0020}have\u{0020}those\u{0020}multi-day\u{0020}feasts\u{0020}like\u{0020}we\u{0020}did\u{0020}back\u{0020}on\u{0020}Eta.\u{0020}Mizo\u{0020}told\u{0020}me\u{0020}that\u{0020}Earthlings\u{0020}like\u{0020}to\u{0020}enjoy\u{0020}a\u{0020}good\u{0020}meal\u{0020}with\u{0020}close\u{0020}friends\u{0020}and\u{0020}chat\u{0020}about\u{0020}the\u{0020}future\u{0020}on\u{0020}their\u{0020}birthdays.\nOh,\u{0020}and\u{0020}the\u{0020}news\u{0020}this\u{0020}morning\u{0020}mentioned\u{0020}that\u{0020}tonight\u{0020}there\u{0020}will\u{0020}be\u{0020}a\u{0020}once-in-a-lifetime\u{0020}supermoon.\u{0020}I've\u{0020}already\u{0020}baked\u{0020}an\u{0020}apple\u{0020}pie,\u{0020}and\u{0020}I\u{0020}was\u{0020}wondering\u{0020}if\u{0020}you'd\u{0020}be\u{0020}free\u{0020}this\u{0020}evening.\u{0020}Maybe\u{0020}we\u{0020}can\u{0020}talk\u{0020}about\u{0020}how\u{0020}we're\u{0020}going\u{0020}to\u{0020}tackle\u{0020}the\u{0020}sins\u{0020}on\u{0020}the\u{0020}moon\u{0020}together?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101801] = {id = 11101801, name = "Shirogane", head = "11018", type = 5, title = "The\u{0020}Moon\u{0020}and\u{0020}Apple\u{0020}Pie", txt = "Birthdays\u{0020}are\u{0020}actually\u{0020}a\u{0020}pretty\u{0020}big\u{0020}deal\u{0020}for\u{0020}us\u{0020}Eta\u{0020}people.\u{0020}Given\u{0020}the\u{0020}length\u{0020}of\u{0020}time\u{0020}on\u{0020}our\u{0020}planet,\u{0020}the\u{0020}gap\u{0020}between\u{0020}two\u{0020}birthdays\u{0020}is\u{0020}roughly\u{0020}equivalent\u{0020}to\u{0020}several\u{0020}Earth\u{0020}years.\u{0020}But\u{0020}since\u{0020}we're\u{0020}currently\u{0020}living\u{0020}on\u{0020}Earth,\u{0020}I\u{0020}guess\u{0020}it's\u{0020}only\u{0020}right\u{0020}to\u{0020}adopt\u{0020}the\u{0020}local\u{0020}custom\u{0020}and\u{0020}celebrate\u{0020}once\u{0020}a\u{0020}year\u{0020}like\u{0020}everyone\u{0020}else.\nThat\u{0020}means\u{0020}the\u{0020}way\u{0020}we\u{0020}celebrate\u{0020}needs\u{0020}to\u{0020}change\u{0020}as\u{0020}well.\u{0020}We\u{0020}can't\u{0020}have\u{0020}those\u{0020}multi-day\u{0020}feasts\u{0020}like\u{0020}we\u{0020}did\u{0020}back\u{0020}on\u{0020}Eta.\u{0020}Mizo\u{0020}told\u{0020}me\u{0020}that\u{0020}Earthlings\u{0020}like\u{0020}to\u{0020}enjoy\u{0020}a\u{0020}good\u{0020}meal\u{0020}with\u{0020}close\u{0020}friends\u{0020}and\u{0020}chat\u{0020}about\u{0020}the\u{0020}future\u{0020}on\u{0020}their\u{0020}birthdays.\nOh,\u{0020}and\u{0020}the\u{0020}news\u{0020}this\u{0020}morning\u{0020}mentioned\u{0020}that\u{0020}tonight\u{0020}there\u{0020}will\u{0020}be\u{0020}a\u{0020}once-in-a-lifetime\u{0020}supermoon.\u{0020}I've\u{0020}already\u{0020}baked\u{0020}an\u{0020}apple\u{0020}pie,\u{0020}and\u{0020}I\u{0020}was\u{0020}wondering\u{0020}if\u{0020}you'd\u{0020}be\u{0020}free\u{0020}this\u{0020}evening.\u{0020}Maybe\u{0020}we\u{0020}can\u{0020}talk\u{0020}about\u{0020}how\u{0020}we're\u{0020}going\u{0020}to\u{0020}tackle\u{0020}the\u{0020}sins\u{0020}on\u{0020}the\u{0020}moon\u{0020}together?", goods = "1_100000_1