[11101802] = {id = 11101802, name = "Shirogane", head = "11018", type = 5, title = "A\u{0020}New\u{0020}Countdown", txt = "It's\u{0020}time\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday\u{0020}again.\u{0020}Lately,\u{0020}I've\u{0020}been\u{0020}regretting\u{0020}synchronizing\u{0020}my\u{0020}birthday\u{0020}with\u{0020}Earth's\u{0020}orbital\u{0020}cycle,\u{0020}the\u{0020}interval\u{0020}is\u{0020}a\u{0020}bit\u{0020}too\u{0020}short,\u{0020}especially\u{0020}for\u{0020}me.\u{0020}\nI'm\u{0020}starting\u{0020}to\u{0020}feel\u{0020}like\u{0020}birthdays\u{0020}are\u{0020}becoming\u{0020}a\u{0020}burden.\u{0020}Like\u{0020}the\u{0020}countdown\u{0020}on\u{0020}an\u{0020}explosive,\u{0020}measured\u{0020}in\u{0020}days,\u{0020}urging\u{0020}me\u{0020}to\u{0020}learn,\u{0020}train,\u{0020}and\u{0020}grow\u{0020}stronger\u{0020}within\u{0020}a\u{0020}new\u{0020}set\u{0020}of\u{0020}365\u{0020}days.\u{0020}Then,\u{0020}when\u{0020}the\u{0020}countdown\u{0020}hits\u{0020}zero,\u{0020}I\u{0020}look\u{0020}back\u{0020}at\u{0020}myself\u{0020}and\u{0020}make\u{0020}the\u{0020}decision\u{0020}--\u{0020}whether\u{0020}to\u{0020}cut\u{0020}the\u{0020}red\u{0020}wire\u{0020}or\u{0020}the\u{0020}blue\u{0020}one.\u{0020}\nOf\u{0020}course,\u{0020}no\u{0020}matter\u{0020}what\u{0020}choice\u{0020}I\u{0020}make,\u{0020}the\u{0020}countdown\u{0020}won't\u{0020}stop.\u{0020}It\u{0020}will\u{0020}reset\u{0020}to\u{0020}365,\u{0020}sometimes\u{0020}366,\u{0020}and\u{0020}then\u{0020}it\u{0020}will\u{0020}be\u{0020}waiting\u{0020}for\u{0020}me\u{0020}again\u{0020}on\u{0020}the\u{0020}next\u{0020}birthday.\u{0020}And\u{0020}most\u{0020}importantly...\u{0020}my\u{0020}age\u{0020}also...\u{0020}\nStill,\u{0020}there\u{0020}are\u{0020}plenty\u{0020}of\u{0020}things\u{0020}worth\u{0020}looking\u{0020}forward\u{0020}to\u{0020}on\u{0020}a\u{0020}birthday.\u{0020}Apple\u{0020}pie,\u{0020}for\u{0020}instance.\u{0020}And\u{0020}the\u{0020}chance\u{0020}to\u{0020}write\u{0020}you\u{0020}a\u{0020}letter,\u{0020}Navigator.\u{0020}\nIf\u{0020}possible,\u{0020}I'd\u{0020}like\u{0020}to\u{0020}see\u{0020}you\u{0020}in\u{0020}person\u{0020}and...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111019] = {id = 111019, name = "Tenten", head = "11019", type = 5, title = "肉醬蛋糕研製大成功！", txt = "navigator！navigator！navigator！我成功了！\n我做了一個超級大蛋糕！雖然很早之前我做過蛋糕，但是這次的做法不一樣。這次的蛋糕原料只有肉！\n用九州牛肉作為蛋糕坯，塗上肉醬做成的奶油,最後把雞肉裱花裝飾在蛋糕上，全部放進烤箱烘烤。雖然出來的成品樣子不太符合“美食”的定義，但是聞起來和吃起來的味道超級棒！\n如果要說有什麼缺點的話，那就是一不小心做得太大了，根本吃不完。所以navigator如果還沒吃飯的話，我這裏給navigator留了位子，隨時恭候navigator光臨。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101901] = {id = 11101901, name = "Tenten", head = "11019", type = 5, title = "Meatcake\u{0020}Masterpiece\u{0020}Complete!", txt = "NAVIGATOR!\u{0020}NAVIGATOR!\u{0020}NAVIGATOR!\u{0020}I\u{0020}did\u{0020}it!\nI\u{0020}made\u{0020}a\u{0020}mega\u{0020}-\u{0020}delicious\u{0020}cake!\u{0020}I\u{0020}know\u{0020}I’ve\u{0020}baked\u{0020}cakes\u{0020}before,\u{0020}but\u{0020}this\u{0020}one’s\u{0020}totally\u{0020}different,\u{0020}because\u{0020}this\u{0020}time,\u{0020}it's\u{0020}made\u{0020}entirely\u{0020}out\u{0020}of\u{0020}meat!\nI\u{0020}used\u{0020}Kyushu\u{0020}beef\u{0020}for\u{0020}the\u{0020}base,\u{0020}slathered\u{0020}on\u{0020}a\u{0020}meat\u{0020}-\u{0020}sauce\u{0020}\"frosting,\"\u{0020}then\u{0020}piped\u{0020}chicken\u{0020}into\u{0020}flower\u{0020}-\u{0020}shaped\u{0020}decorations.\u{0020}Tossed\u{0020}the\u{0020}whole\u{0020}thing\u{0020}into\u{0020}the\u{0020}oven\u{0020}and\u{0020}finally,\u{0020}a\u{0020}DING!\u{0020}It\u{0020}might\u{0020}not\u{0020}feast\u{0020}your\u{0020}eyes,\u{0020}but\u{0020}the\u{0020}smell\u{0020}and\u{0020}the\u{0020}taste\u{0020}are\u{0020}out\u{0020}of\u{0020}this\u{0020}world!\nIf\u{0020}I\u{0020}had\u{0020}to\u{0020}nitpick,\u{0020}well...\u{0020}I\u{0020}may\u{0020}have\u{0020}gotten\u{0020}a\u{0020}bit\u{0020}carried\u{0020}away\u{0020}with\u{0020}the\u{0020}size.\u{0020}There’s\u{0020}no\u{0020}way\u{0020}Anan,\u{0020}Karen,\u{0020}and\u{0020}I\u{0020}can\u{0020}finish\u{0020}it\u{0020}ourselves.\u{0020}So,\u{0020}come\u{0020}anytime\u{0020}on\u{0020}an\u{0020}empty\u{0020}stomach,\u{0020}Navigator.\u{0020}I’ve\u{0020}saved\u{0020}you\u{0020}a\u{0020}seat.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11101902] = {id = 11101902, name = "Tenten", head = "11019", type = 5, title = "A\u{0020}Long-Awaited\u{0020}Birthday", txt = "Navigator,\u{0020}do\u{0020}you\u{0020}know\u{0020}about\u{0020}the\u{0020}legendary\u{0020}cooking\u{0020}utensils?\u{0020}They\u{0020}are\u{0020}magical\u{0020}utensils\u{0020}said\u{0020}to\u{0020}make\u{0020}any\u{0020}ingredients\u{0020}delicious.\nI\u{0020}will\u{0020}tell\u{0020}you\u{0020}a\u{0020}secret,\u{0020}Navigator--\u{0020}I\u{0020}have\u{0020}already\u{0020}found\u{0020}the\u{0020}legendary\u{0020}cooking\u{0020}utensils.\u{0020}To\u{0020}be\u{0020}more\u{0020}precise,\u{0020}I\u{0020}found\u{0020}a\u{0020}clue\u{0020}to\u{0020}the\u{0020}legendary\u{0020}cooking\u{0020}utensils.\nNo\u{0020}chef\u{0020}can\u{0020}resist\u{0020}the\u{0020}temptation\u{0020}of\u{0020}the\u{0020}legendary\u{0020}cooking\u{0020}utensils,\u{0020}and\u{0020}I\u{0020}have\u{0020}already\u{0020}decided\u{0020}to\u{0020}set\u{0020}out\u{0020}alone\u{0020}on\u{0020}a\u{0020}journey\u{0020}to\u{0020}find\u{0020}them.\u{0020}It\u{0020}will\u{0020}not\u{0020}take\u{0020}long.\u{0020}Three\u{0020}days\u{0020}at\u{0020}most.\nBut\u{0020}before\u{0020}I\u{0020}set\u{0020}out\u{0020}on\u{0020}my\u{0020}journey\u{0020}to\u{0020}find\u{0020}the\u{0020}legendary\u{0020}cooking\u{0020}utensils,\u{0020}there\u{0020}is\u{0020}something\u{0020}I\u{0020}must\u{0020}ask\u{0020}you\u{0020}for.\u{0020}To\u{0020}keep\u{0020}Anan\u{0020}and\u{0020}the\u{0020}class\u{0020}president\u{0020}from\u{0020}worrying,\u{0020}I\u{0020}did\u{0020}not\u{0020}tell\u{0020}them\u{0020}the\u{0020}truth\u{0020}and\u{0020}instead\u{0020}lied\u{0020}that\u{0020}I\u{0020}was\u{0020}going\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday\u{0020}at\u{0020}your\u{0020}place,\u{0020}Navigator.\u{0020}If\u{0020}they\u{0020}ask\u{0020}about\u{0020}it,\u{0020}please\u{0020}be\u{0020}sure\u{0020}to\u{0020}cover\u{0020}for\u{0020}me.\u{0020}Please,\u{0020}please.\nI\u{0020}will\u{0020}thank\u{0020}you\u{0020}later\u{0020}with\u{0020}dishes\u{0020}made\u{0020}using\u{0020}the\u{0020}legendary\u{0020}cooking\u{0020}utensils,\u{0020}and\u{0020}I\u{0020}will\u{0020}make\u{0020}up\u{0020}the\u{0020}birthday\u{0020}party\u{0020}I\u{0020}owe\u{0020}you\u{0020}too.\u{0020}I\u{0020}am\u{0020}counting\u{0020}on\u{0020}you!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111020] = {id = 111020, name = "Caroline", head = "11020", type = 5, title = "提醒？求助！", txt = "我知道，navigator您也忘了，所以我又又又發來了消息！\n首先，今天是我的生日。\n其次，我特地買了個足夠大家分著吃的五層大蛋糕回來。\n最後，從十天前起，我每天都給你們發消息，讓你們千萬、一定、絕對不要忘了今早在休息室集合，一起吃蛋糕。\n但……但是到現在都沒有一個人來！為什麼啊？！\n剛才試著給隊長她們發消息，到現在都還是未讀狀態……navigator，我只能指望你了。快幫幫我。這冰淇淩蛋糕化得滿桌都是，還有不少流到了地上，我、我現在該怎麼辦啊？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102001] = {id = 11102001, name = "Caroline", head = "11020", type = 5, title = "It’s\u{0020}Actually\u{0020}a\u{0020}Mayday\u{0020}Call!", txt = "I\u{0020}know\u{0020}you\u{0020}forgot\u{0020}too,\u{0020}so\u{0020}here\u{0020}I\u{0020}am.\u{0020}Messaging\u{0020}you\u{0020}AGAIN!\nFirst:\u{0020}It's\u{0020}my\u{0020}birthday\u{0020}today.\nSecond:\u{0020}I\u{0020}went\u{0020}out\u{0020}of\u{0020}my\u{0020}way\u{0020}to\u{0020}get\u{0020}this\u{0020}five-tier\u{0020}cake\u{0020}big\u{0020}enough\u{0020}for\u{0020}everyone.\nThird:\u{0020}For\u{0020}the\u{0020}past\u{0020}TEN\u{0020}DAYS,\u{0020}I've\u{0020}been\u{0020}spamming\u{0020}everyone\u{0020}to\u{0020}absolutely,\u{0020}NO\u{0020}MATTER\u{0020}WHAT,\u{0020}remember\u{0020}to\u{0020}meet\u{0020}in\u{0020}the\u{0020}lounge\u{0020}this\u{0020}morning\u{0020}for\u{0020}cake.\nBut...\u{0020}but\u{0020}nobody\u{0020}showed\u{0020}up!\u{0020}Why?!\nI\u{0020}just\u{0020}texted\u{0020}the\u{0020}Captain\u{0020}and\u{0020}Zepar...\u{0020}still\u{0020}on\u{0020}\"unread\"...\u{0020}Navigator,\u{0020}you're\u{0020}my\u{0020}last\u{0020}hope.\u{0020}Help\u{0020}me\u{0020}out\u{0020}here.\u{0020}The\u{0020}ice\u{0020}cream\u{0020}cake\u{0020}is\u{0020}melting\u{0020}all\u{0020}over\u{0020}the\u{0020}table\u{0020}and\u{0020}it's\u{0020}literally\u{0020}dripping\u{0020}onto\u{0020}the\u{0020}floor!\u{0020}What...\u{0020}what\u{0020}am\u{0020}I\u{0020}supposed\u{0020}to\u{0020}do?!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102002] = {id = 11102002, name = "Caroline", head = "11020", type = 5, title = "An\u{0020}Unordinary\u{0020}Birthday", txt = "Since\u{0020}the\u{0020}captain\u{0020}and\u{0020}the\u{0020}others\u{0020}always\u{0020}forget\u{0020}my\u{0020}birthday,\u{0020}and\u{0020}do\u{0020}not\u{0020}even\u{0020}reply\u{0020}to\u{0020}my\u{0020}messages,\u{0020}I\u{0020}have\u{0020}decided\u{0020}that\u{0020}this\u{0020}year,\u{0020}it\u{0020}will\u{0020}just\u{0020}be\u{0020}you\u{0020}and\u{0020}me\u{0020}celebrating\u{0020}together!\nAs\u{0020}for\u{0020}how\u{0020}we\u{0020}should\u{0020}celebrate,\u{0020}of\u{0020}course\u{0020}we\u{0020}should\u{0020}go\u{0020}through\u{0020}the\u{0020}full\u{0020}course:\u{0020}amusement\u{0020}park,\u{0020}aquarium,\u{0020}movie\u{0020}theater,\u{0020}right?\u{0020}No,\u{0020}that\u{0020}still\u{0020}feels\u{0020}too\u{0020}ordinary...\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}it\u{0020}is\u{0020}a\u{0020}place\u{0020}open\u{0020}to\u{0020}the\u{0020}public,\u{0020}anywhere\u{0020}will\u{0020}seem\u{0020}ordinary,\u{0020}without\u{0020}exception.\u{0020}Unless\u{0020}we\u{0020}can\u{0020}find\u{0020}a\u{0020}place\u{0020}that\u{0020}is\u{0020}not\u{0020}open\u{0020}to\u{0020}the\u{0020}public.\u{0020}Right,\u{0020}for\u{0020}example,\u{0020}your\u{0020}home,\u{0020}Navigator!\nThen,\u{0020}when\u{0020}the\u{0020}time\u{0020}comes,\u{0020}let\u{0020}us\u{0020}spend\u{0020}the\u{0020}whole\u{0020}day\u{0020}having\u{0020}fun\u{0020}outside\u{0020}first,\u{0020}and\u{0020}after\u{0020}we\u{0020}are\u{0020}tired\u{0020}out,\u{0020}we\u{0020}can\u{0020}make\u{0020}the\u{0020}final\u{0020}stop\u{0020}on\u{0020}our\u{0020}itinerary\u{0020}your\u{0020}place,\u{0020}Navigator.\u{0020}Mm-hmm,\u{0020}it\u{0020}is\u{0020}decided!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111023] = {id = 111023, name = "Xiaomeng", head = "11023", type = 5, title = "Please\u{0020}Give\u{0020}Me\u{0020}a\u{0020}Birthday\u{0020}Mission", txt = "Chenglian\u{0020}said\u{0020}that\u{0020}in\u{0020}Danube,\u{0020}there's\u{0020}a\u{0020}tradition.\u{0020}On\u{0020}your\u{0020}birthday,\u{0020}you're\u{0020}supposed\u{0020}to\u{0020}make\u{0020}a\u{0020}request\u{0020}to\u{0020}those\u{0020}celebrating\u{0020}with\u{0020}you.\u{0020}Xiaomeng\u{0020}followed\u{0020}the\u{0020}tradition.\u{0020}But\u{0020}her\u{0020}request\u{0020}got\u{0020}rejected.\nAll\u{0020}I\u{0020}asked\u{0020}was\u{0020}to\u{0020}spend\u{0020}the\u{0020}whole\u{0020}day\u{0020}doing\u{0020}whatever\u{0020}people\u{0020}told\u{0020}me\u{0020}to\u{0020}do.\u{0020}That's\u{0020}not\u{0020}so\u{0020}hard,\u{0020}is\u{0020}it?\u{0020}So\u{0020}why\u{0020}did\u{0020}no\u{0020}one\u{0020}say\u{0020}yes?\u{0020}Even\u{0020}Gia\u{0020}turned\u{0020}me\u{0020}down...\u{0020}She's\u{0020}never\u{0020}said\u{0020}no\u{0020}to\u{0020}anyone's\u{0020}birthday\u{0020}request\u{0020}before.\u{0020}Maybe\u{0020}she\u{0020}doesn't\u{0020}like\u{0020}me\u{0020}anymore...\nBut\u{0020}I\u{0020}know\u{0020}you\u{0020}don't\u{0020}feel\u{0020}that\u{0020}way\u{0020}about\u{0020}me.\nSo\u{0020}you'll\u{0020}say\u{0020}yes\u{0020}to\u{0020}my\u{0020}request.\u{0020}Right?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102301] = {id = 11102301, name = "Xiaomeng", head = "11023", type = 5, title = "Once-a-Year\u{0020}Thinking\u{0020}Time!", txt = "Because\u{0020}Xiaomeng\u{0020}\"doesn't\u{0020}want\u{0020}to\u{0020}think\u{0020}and\u{0020}only\u{0020}wants\u{0020}to\u{0020}be\u{0020}told\u{0020}what\u{0020}to\u{0020}do,\"\u{0020}everyone\u{0020}usually\u{0020}racks\u{0020}their\u{0020}brains\u{0020}for\u{0020}all\u{0020}sorts\u{0020}of\u{0020}ways\u{0020}to\u{0020}grant\u{0020}my\u{0020}wish\u{0020}and\u{0020}make\u{0020}me\u{0020}happy.\nSo\u{0020}Xiaomeng\u{0020}has\u{0020}been\u{0020}thinking\u{0020}that,\u{0020}once\u{0020}in\u{0020}a\u{0020}while,\u{0020}I\u{0020}should\u{0020}think\u{0020}carefully\u{0020}for\u{0020}myself\u{0020}about\u{0020}what\u{0020}to\u{0020}do\u{0020}next,\u{0020}and\u{0020}about\u{0020}what\u{0020}I\u{0020}ought\u{0020}to\u{0020}do\u{0020}for\u{0020}everyone\u{0020}to\u{0020}make\u{0020}them\u{0020}happy.\nBut\u{0020}Xiaomeng\u{0020}isn't\u{0020}good\u{0020}at\u{0020}this\u{0020}sort\u{0020}of\u{0020}thing,\u{0020}so\u{0020}I\u{0020}would\u{0020}like\u{0020}to\u{0020}ask\u{0020}you\u{0020}to\u{0020}think\u{0020}about\u{0020}it\u{0020}together\u{0020}with\u{0020}me.\nXiaomeng\u{0020}is\u{0020}a\u{0020}dummy\u{0020}who\u{0020}only\u{0020}uses\u{0020}my\u{0020}brain\u{0020}once\u{0020}a\u{0020}year,\u{0020}while\u{0020}you\u{0020}are\u{0020}a\u{0020}clever\u{0020}person\u{0020}who\u{0020}thinks\u{0020}every\u{0020}day.\u{0020}Together,\u{0020}we\u{0020}are\u{0020}sure\u{0020}to\u{0020}come\u{0020}up\u{0020}with\u{0020}a\u{0020}way\u{0020}to\u{0020}make\u{0020}everyone\u{0020}happy.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111024] = {id = 111024, name = "Yanyanlo", head = "11024", type = 5, title = "A\u{0020}Little\u{0020}Reminder", txt = "Just\u{0020}in\u{0020}case\u{0020}you\u{0020}forgot.\u{0020}Today's\u{0020}my\u{0020}birthday.\nNot\u{0020}that\u{0020}I\u{0020}need\u{0020}gifts\u{0020}or\u{0020}anything.\nBut\u{0020}if\u{0020}you\u{0020}insist\u{0020}on\u{0020}celebrating...\u{0020}well,\u{0020}I\u{0020}wouldn't\u{0020}say\u{0020}no\u{0020}to\u{0020}a\u{0020}diving\u{0020}trip.\u{0020}There\u{0020}are\u{0020}three\u{0020}hotspots\u{0020}right\u{0020}now:\u{0020}the\u{0020}continental\u{0020}shelf\u{0020}near\u{0020}Danubian\u{0020}Sea,\u{0020}that\u{0020}abandoned\u{0020}offshore\u{0020}oil\u{0020}rig,\u{0020}and\u{0020}the\u{0020}submarine\u{0020}wreck\u{0020}under\u{0020}the\u{0020}Arctic\u{0020}Ocean.\nI'd\u{0020}pick\u{0020}the\u{0020}wreck.\u{0020}Barely\u{0020}anyone's\u{0020}been\u{0020}there.\u{0020}No\u{0020}guides,\u{0020}no\u{0020}handholding\u{0020}and\u{0020}that\u{0020}is\u{0020}what\u{0020}makes\u{0020}a\u{0020}good\u{0020}adventure.\nHowever,\u{0020}the\u{0020}only\u{0020}thing\u{0020}is\u{0020}the\u{0020}water's\u{0020}freezing\u{0020}there.\u{0020}Guess\u{0020}you'll\u{0020}just\u{0020}have\u{0020}to\u{0020}keep\u{0020}me\u{0020}warm.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102401] = {id = 11102401, name = "Yanyanlo", head = "11024", type = 5, title = "On\u{0020}a\u{0020}Sense\u{0020}of\u{0020}Ceremony", txt = "Do\u{0020}you\u{0020}care\u{0020}about\u{0020}having\u{0020}a\u{0020}sense\u{0020}of\u{0020}ceremony\u{0020}for\u{0020}birthdays,\u{0020}Navigator?\nThis\u{0020}morning,\u{0020}I\u{0020}was\u{0020}sorting\u{0020}out\u{0020}which\u{0020}places\u{0020}I\u{0020}should\u{0020}go\u{0020}diving\u{0020}for\u{0020}this\u{0020}birthday.\u{0020}Then\u{0020}Momo\u{0020}suddenly\u{0020}said,\u{0020}\"If\u{0020}you\u{0020}dive\u{0020}on\u{0020}normal\u{0020}days\u{0020}and\u{0020}also\u{0020}just\u{0020}pick\u{0020}places\u{0020}to\u{0020}dive\u{0020}on\u{0020}your\u{0020}birthday,\u{0020}then\u{0020}how\u{0020}is\u{0020}your\u{0020}birthday\u{0020}any\u{0020}different\u{0020}from\u{0020}any\u{0020}other\u{0020}day?\"\u{0020}That\u{0020}made\u{0020}me\u{0020}start\u{0020}caring\u{0020}about\u{0020}it\u{0020}a\u{0020}little.\nI\u{0020}really\u{0020}do\u{0020}like\u{0020}diving,\u{0020}but\u{0020}if\u{0020}someone\u{0020}is\u{0020}always\u{0020}traveling,\u{0020}they\u{0020}might\u{0020}gradually\u{0020}start\u{0020}to\u{0020}feel\u{0020}that\u{0020}traveling\u{0020}is\u{0020}nothing\u{0020}special,\u{0020}right?\u{0020}I\u{0020}think\u{0020}Mom\u{0020}and\u{0020}Dad\u{0020}said\u{0020}something\u{0020}similar\u{0020}to\u{0020}me\u{0020}before,\u{0020}about\u{0020}treasuring\u{0020}the\u{0020}things\u{0020}I\u{0020}like\u{0020}more.\n--So\u{0020}I\u{0020}have\u{0020}decided\u{0020}to\u{0020}give\u{0020}my\u{0020}birthday\u{0020}a\u{0020}greater\u{0020}sense\u{0020}of\u{0020}ceremony.\u{0020}For\u{0020}the\u{0020}details,\u{0020}you\u{0020}can\u{0020}check\u{0020}the\u{0020}message\u{0020}that\u{0020}popped\u{0020}up\u{0020}on\u{0020}your\u{0020}terminal.\nThey\u{0020}never\u{0020}approved\u{0020}my\u{0020}special\u{0020}request\u{0020}to\u{0020}go\u{0020}giant-form\u{0020}diving\u{0020}on\u{0020}holidays\u{0020}before,\u{0020}but\u{0020}Navigator,\u{0020}who\u{0020}understands\u{0020}the\u{0020}life\u{0020}reflections\u{0020}behind\u{0020}this,\u{0020}will\u{0020}definitely\u{0020}approve\u{0020}of\u{0020}me,\u{0020}right?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111028] = {id = 111028, name = "Geiro", head = "11028", type = 5, title = "Do\u{0020}What\u{0020}You're\u{0020}Supposed\u{0020}To", txt = "As\u{0020}the\u{0020}Navigator,\u{0020}your\u{0020}time,\u{0020}energy,\u{0020}and\u{0020}life\u{0020}itself\u{0020}should\u{0020}be\u{0020}spent\u{0020}on\u{0020}things\u{0020}that\u{0020}matter\u{0020}could\u{0020}be\u{0020}put\u{0020}to\u{0020}better\u{0020}use\u{0020}than\u{0020}throwing\u{0020}birthday\u{0020}parties\u{0020}for\u{0020}Drivers\u{0020}from\u{0020}another\u{0020}branch?\u{0020}Surely,\u{0020}you\u{0020}understand\u{0020}the\u{0020}difference\u{0020}between\u{0020}maintaining\u{0020}a\u{0020}social\u{0020}circle\u{0020}and\u{0020}devising\u{0020}actual\u{0020}countermeasures\u{0020}against\u{0020}the\u{0020}Sin.\u{0020}Or\u{0020}do\u{0020}you\u{0020}think\u{0020}I\u{0020}won't\u{0020}follow\u{0020}your\u{0020}orders\u{0020}in\u{0020}battle\u{0020}unless\u{0020}you\u{0020}bribe\u{0020}me\u{0020}with\u{0020}gifts?\nHmph.\u{0020}So\u{0020}that's\u{0020}how\u{0020}little\u{0020}you\u{0020}think\u{0020}of\u{0020}me.\nLet\u{0020}me\u{0020}make\u{0020}this\u{0020}clear\u{0020}ONE\u{0020}MORE\u{0020}TIME:\u{0020}I\u{0020}am\u{0020}Katya's\u{0020}top\u{0020}Driver.\u{0020}If\u{0020}your\u{0020}leadership\u{0020}works,\u{0020}I\u{0020}will\u{0020}follow\u{0020}you\u{0020}unconditionally.\u{0020}These\u{0020}little\u{0020}tactics\u{0020}of\u{0020}yours...\u{0020}fine,\u{0020}I'll\u{0020}accept\u{0020}this\u{0020}year's\u{0020}gift.\u{0020}But\u{0020}just\u{0020}this\u{0020}once.\nNavigator,\u{0020}don't\u{0020}make\u{0020}me\u{0020}regret\u{0020}putting\u{0020}my\u{0020}trust\u{0020}in\u{0020}you.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102801] = {id = 11102801, name = "Geiro", head = "11028", type = 5, title = "The\u{0020}Birthday\u{0020}Gift\u{0020}I\u{0020}Want", txt = "Recently,\u{0020}while\u{0020}tidying\u{0020}up\u{0020}my\u{0020}room,\u{0020}I\u{0020}accidentally\u{0020}broke\u{0020}some\u{0020}furniture...\u{0020}It\u{0020}was\u{0020}not\u{0020}my\u{0020}fault.\u{0020}They\u{0020}were\u{0020}too\u{0020}fragile.\nAlthough\u{0020}I\u{0020}rarely\u{0020}stay\u{0020}at\u{0020}home,\u{0020}I\u{0020}will\u{0020}still\u{0020}run\u{0020}into\u{0020}trouble\u{0020}without\u{0020}that\u{0020}furniture.\nFor\u{0020}example,\u{0020}the\u{0020}wardrobe...\u{0020}Right\u{0020}now\u{0020}I\u{0020}can\u{0020}only\u{0020}put\u{0020}my\u{0020}clothes\u{0020}on\u{0020}the\u{0020}bed,\u{0020}which\u{0020}makes\u{0020}sleeping\u{0020}very\u{0020}uncomfortable.\nIn\u{0020}short,\u{0020}I\u{0020}need\u{0020}a\u{0020}new\u{0020}set\u{0020}of\u{0020}furniture\u{0020}now.\u{0020}Come\u{0020}help\u{0020}me\u{0020}pick\u{0020}it\u{0020}out.\nConsider\u{0020}it\u{0020}choosing\u{0020}a\u{0020}birthday\u{0020}gift\u{0020}for\u{0020}me!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111029] = {id = 111029, name = "Senhaku", head = "11029", type = 5, title = "My\u{0020}Apologies\u{0020}for\u{0020}the\u{0020}Sudden\u{0020}Letter", txt = "Dear\u{0020}Navigator,\nI\u{0020}hope\u{0020}you'll\u{0020}forgive\u{0020}me\u{0020}for\u{0020}writing\u{0020}out\u{0020}of\u{0020}the\u{0020}blue.\u{0020}I\u{0020}have\u{0020}a\u{0020}small\u{0020}favor\u{0020}to\u{0020}ask.\nToday's\u{0020}my\u{0020}birthday,\u{0020}and\u{0020}I'd\u{0020}hoped\u{0020}to\u{0020}use\u{0020}the\u{0020}occasion\u{0020}to\u{0020}bond\u{0020}a\u{0020}little\u{0020}more\u{0020}with\u{0020}Tenten\u{0020}and\u{0020}Anan.\u{0020}As\u{0020}you\u{0020}know,\u{0020}they\u{0020}only\u{0020}joined\u{0020}the\u{0020}squad\u{0020}thanks\u{0020}to\u{0020}Karen's\u{0020}invitation,\u{0020}and\u{0020}with\u{0020}how\u{0020}tied\u{0020}up\u{0020}I've\u{0020}been\u{0020}with\u{0020}academy\u{0020}affairs,\u{0020}I\u{0020}haven't\u{0020}really\u{0020}had\u{0020}the\u{0020}chance\u{0020}to\u{0020}get\u{0020}to\u{0020}know\u{0020}them\u{0020}properly.\u{0020}But,\u{0020}for\u{0020}reasons\u{0020}I\u{0020}can't\u{0020}quite\u{0020}figure\u{0020}out,\u{0020}they\u{0020}turned\u{0020}down\u{0020}all\u{0020}my\u{0020}invitations\u{0020}today,\u{0020}each\u{0020}with\u{0020}a\u{0020}different\u{0020}excuse.\nI\u{0020}asked\u{0020}Karen\u{0020}about\u{0020}it,\u{0020}and\u{0020}all\u{0020}she\u{0020}said\u{0020}was:\u{0020}\"I\u{0020}promised\u{0020}them\u{0020}I'd\u{0020}keep\u{0020}it\u{0020}a\u{0020}secret...\u{0020}Don't\u{0020}worry,\u{0020}though.\u{0020}It's\u{0020}a\u{0020}surprise.\"\nWhich,\u{0020}of\u{0020}course,\u{0020}only\u{0020}left\u{0020}me\u{0020}more\u{0020}confused.\nSince\u{0020}Tenten,\u{0020}Anan,\u{0020}and\u{0020}Karen\u{0020}all\u{0020}trust\u{0020}you\u{0020}deeply,\u{0020}I\u{0020}wondered\u{0020}if\u{0020}maybe\u{0020}they've\u{0020}mentioned\u{0020}something\u{0020}to\u{0020}you\u{0020}about\u{0020}me\u{0020}lately.\u{0020}So,\u{0020}as\u{0020}a\u{0020}last\u{0020}resort,\u{0020}I\u{0020}thought\u{0020}I'd\u{0020}write\u{0020}and\u{0020}ask\u{0020}if\u{0020}you\u{0020}happen\u{0020}to\u{0020}know\u{0020}anything,\u{0020}I'd\u{0020}really\u{0020}appreciate\u{0020}your\u{0020}insight.\nI'll\u{0020}be\u{0020}looking\u{0020}forward\u{0020}to\u{0020}your\u{0020}reply.\\u{0020}n\nWarm\u{0020}regards,\nSenhaku", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11102901] = {id = 11102901, name = "Senhaku", head = "11029", type = 5, title = "A\u{0020}Year\u{0020}On,\u{0020}I\u{0020}Must\u{0020}Trouble\u{0020}You\u{0020}Again", txt = "Mr.\u{0020}Navigator,\u{0020}I\u{0020}have\u{0020}a\u{0020}request\u{0020}to\u{0020}make...\nYes,\u{0020}I\u{0020}opened\u{0020}in\u{0020}the\u{0020}same\u{0020}way\u{0020}at\u{0020}this\u{0020}time\u{0020}last\u{0020}year.\u{0020}This\u{0020}is\u{0020}neither\u{0020}symmetry\u{0020}for\u{0020}symmetry's\u{0020}sake\u{0020}nor\u{0020}the\u{0020}result\u{0020}of\u{0020}running\u{0020}out\u{0020}of\u{0020}words\u{0020}after\u{0020}racking\u{0020}my\u{0020}brains.\u{0020}It\u{0020}is\u{0020}simply\u{0020}what\u{0020}I\u{0020}truly\u{0020}mean.\nRecently,\u{0020}I\u{0020}have\u{0020}begun\u{0020}reconsidering\u{0020}whether\u{0020}my\u{0020}approach\u{0020}to\u{0020}management\u{0020}is\u{0020}suited\u{0020}to\u{0020}the\u{0020}present\u{0020}day--\nThe\u{0020}phrase\u{0020}\"the\u{0020}present\u{0020}day\"\u{0020}may\u{0020}sound\u{0020}grandiose,\u{0020}but\u{0020}in\u{0020}any\u{0020}case,\u{0020}I\u{0020}want\u{0020}to\u{0020}determine\u{0020}whether\u{0020}the\u{0020}experience\u{0020}I\u{0020}accumulated\u{0020}as\u{0020}a\u{0020}student,\u{0020}and\u{0020}the\u{0020}rules\u{0020}I\u{0020}used\u{0020}to\u{0020}regulate\u{0020}people's\u{0020}conduct,\u{0020}can\u{0020}still\u{0020}be\u{0020}applied\u{0020}in\u{0020}the\u{0020}same\u{0020}way\u{0020}to\u{0020}active\u{0020}Drivers\u{0020}now\u{0020}that\u{0020}I\u{0020}have\u{0020}left\u{0020}school.\nIt\u{0020}may\u{0020}be\u{0020}premature,\u{0020}or\u{0020}even\u{0020}presumptuous,\u{0020}for\u{0020}a\u{0020}mere\u{0020}student\u{0020}to\u{0020}ponder\u{0020}such\u{0020}matters,\u{0020}but\u{0020}I\u{0020}do\u{0020}not\u{0020}believe\u{0020}there\u{0020}is\u{0020}any\u{0020}harm\u{0020}in\u{0020}beginning\u{0020}to\u{0020}think\u{0020}about\u{0020}them\u{0020}now.\nAnd\u{0020}so,\u{0020}on\u{0020}the\u{0020}occasion\u{0020}of\u{0020}my\u{0020}birthday,\u{0020}I\u{0020}would\u{0020}like\u{0020}to\u{0020}make\u{0020}a\u{0020}request\u{0020}of\u{0020}you,\u{0020}Mr.\u{0020}Navigator--please\u{0020}teach\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111030] = {id = 111030, name = "Chenglian", head = "11030", type = 5, title = "Mail\u{0020}from\u{0020}Your\u{0020}Historican", txt = "Nov\u{0020}2,\u{0020}Sunny\nIt's\u{0020}that\u{0020}time\u{0020}of\u{0020}year\u{0020}again.\nI\u{0020}flipped\u{0020}through\u{0020}my\u{0020}birthday\u{0020}journals\u{0020}from\u{0020}previous\u{0020}years,\u{0020}and\u{0020}it\u{0020}felt\u{0020}like\u{0020}I\u{0020}was\u{0020}reading\u{0020}my\u{0020}own\u{0020}history.\u{0020}Some\u{0020}of\u{0020}those\u{0020}old\u{0020}memories\u{0020}are\u{0020}a\u{0020}bit\u{0020}awkward.\nBut\u{0020}as\u{0020}a\u{0020}Historican,\u{0020}I\u{0020}have\u{0020}to\u{0020}record\u{0020}things\u{0020}truthfully,\u{0020}even\u{0020}about\u{0020}myself.\u{0020}And\u{0020}my\u{0020}most\u{0020}honest\u{0020}thought\u{0020}right\u{0020}now\u{0020}is...\u{0020}I\u{0020}wish\u{0020}Navigator\u{0020}could\u{0020}be\u{0020}here\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday\u{0020}with\u{0020}me!\nBut\u{0020}I\u{0020}can\u{0020}only\u{0020}write\u{0020}this\u{0020}down\u{0020}in\u{0020}my\u{0020}journal.\u{0020}If\u{0020}I\u{0020}say\u{0020}it\u{0020}out\u{0020}loud,\u{0020}my\u{0020}cool,\u{0020}collected\u{0020}image\u{0020}would\u{0020}go\u{0020}up\u{0020}in\u{0020}smoke!\u{0020}Ugh,\u{0020}a\u{0020}mere\u{0020}thought\u{0020}makes\u{0020}me\u{0020}want\u{0020}to\u{0020}hide.\nFrom\u{0020}today\u{0020}on,\u{0020}I'm\u{0020}going\u{0020}to\u{0020}switch\u{0020}to\u{0020}e-diary.\u{0020}My\u{0020}paper\u{0020}one\u{0020}was\u{0020}clearly\u{0020}not\u{0020}safe\u{0020}at\u{0020}all;\u{0020}it's\u{0020}easily\u{0020}found\u{0020}by\u{0020}the\u{0020}others.\u{0020}But\u{0020}I\u{0020}haven't\u{0020}quite\u{0020}figured\u{0020}out\u{0020}how\u{0020}to\u{0020}use\u{0020}this\u{0020}e-book\u{0020}yet,\u{0020}like\u{0020}how\u{0020}to\u{0020}save\u{0020}the\u{0020}entries\u{0020}after\u{0020}I\u{0020}write\u{0020}them.\nSave\u{0020}and\u{0020}Share?\u{0020}I\u{0020}think\u{0020}it\u{0020}should\u{0020}be\u{0020}the\u{0020}one.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111031] = {id = 111031, name = "Lailaps", head = "11031", type = 5, title = "久違的生日", txt = "黎貝卡今天突然找上我，說要給我慶祝生日。\n不是她提醒，我都忘了今天是什麼日子。\n在登上方舟之前，店長每年會為我們訂蛋糕，和我們一起慶祝生日。都是靠她，我們才能想起自己的生日。\n現在說以前也沒什麼意義了，畢竟店長已經……\n不對不對，今天不是說這種事的日子。\n我裝飾了下房間，還試著做了一個蛋糕，可能外觀不太討喜，但味道應該是沒問題的……吧。\n你應該明白我說這些的意思吧？明白了的話，就快點過來吧，我和黎貝卡在等你呢。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103101] = {id = 11103101, name = "Lailaps", head = "11031", type = 5, title = "A\u{0020}Birthday\u{0020}I\u{0020}Almost\u{0020}Forgot", txt = "Rebecca\u{0020}came\u{0020}to\u{0020}me\u{0020}today\u{0020}and\u{0020}said\u{0020}she’s\u{0020}throwing\u{0020}me\u{0020}a\u{0020}birthday\u{0020}party.\nIf\u{0020}she\u{0020}hadn’t\u{0020}brought\u{0020}it\u{0020}up,\u{0020}I\u{0020}probably\u{0020}would’ve\u{0020}just\u{0020}treated\u{0020}today\u{0020}like\u{0020}any\u{0020}other\u{0020}ordinary\u{0020}day.\nBack\u{0020}before\u{0020}we\u{0020}boarded\u{0020}the\u{0020}Ark,\u{0020}the\u{0020}shopkeeper\u{0020}used\u{0020}to\u{0020}order\u{0020}us\u{0020}a\u{0020}birthday\u{0020}cake\u{0020}every\u{0020}year\u{0020}and\u{0020}celebrate\u{0020}with\u{0020}us.\u{0020}She\u{0020}was\u{0020}the\u{0020}reason\u{0020}we\u{0020}even\u{0020}remembered\u{0020}them\u{0020}at\u{0020}all.\nNot\u{0020}that\u{0020}it\u{0020}matters\u{0020}now,\u{0020}not\u{0020}after\u{0020}what\u{0020}happened\u{0020}to\u{0020}her...\u{0020}No,\u{0020}not\u{0020}today\u{0020}of\u{0020}all\u{0020}days.\nI\u{0020}tried\u{0020}dressing\u{0020}up\u{0020}the\u{0020}place\u{0020}a\u{0020}bit.\u{0020}Even\u{0020}baked\u{0020}a\u{0020}cake\u{0020}myself.\u{0020}It\u{0020}might\u{0020}not\u{0020}be\u{0020}much\u{0020}to\u{0020}look\u{0020}at,\u{0020}but\u{0020}I\u{0020}think\u{0020}it\u{0020}tastes\u{0020}fine...\u{0020}probably.\n\u{0020}You\u{0020}get\u{0020}what\u{0020}I'm\u{0020}saying,\u{0020}right?\u{0020}Well,\u{0020}if\u{0020}you\u{0020}do,\u{0020}then\u{0020}hurry\u{0020}up\u{0020}and\u{0020}get\u{0020}over\u{0020}here.\u{0020}Rebecca\u{0020}and\u{0020}I\u{0020}are\u{0020}waiting.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103102] = {id = 11103102, name = "Lailaps", head = "11031", type = 5, title = "A\u{0020}Good\u{0020}Change", txt = "Did\u{0020}you\u{0020}see\u{0020}the\u{0020}photo\u{0020}I\u{0020}just\u{0020}sent\u{0020}you?\u{0020}It\u{0020}is\u{0020}the\u{0020}birthday\u{0020}cake\u{0020}Rebecca\u{0020}made\u{0020}for\u{0020}me.\nIt\u{0020}looks\u{0020}beautiful,\u{0020}right?\u{0020}She\u{0020}made\u{0020}it\u{0020}together\u{0020}with\u{0020}friends\u{0020}from\u{0020}other\u{0020}squads.\nAbout\u{0020}half\u{0020}a\u{0020}year\u{0020}ago,\u{0020}she\u{0020}was\u{0020}still\u{0020}someone\u{0020}who\u{0020}preferred\u{0020}to\u{0020}stand\u{0020}at\u{0020}a\u{0020}distance\u{0020}and\u{0020}observe\u{0020}others.\u{0020}It\u{0020}was\u{0020}only\u{0020}recently\u{0020}that\u{0020}she\u{0020}told\u{0020}me\u{0020}she\u{0020}had\u{0020}tried\u{0020}making\u{0020}a\u{0020}few\u{0020}friends.\u{0020}As\u{0020}for\u{0020}how\u{0020}that\u{0020}turned\u{0020}out,\u{0020}I\u{0020}just\u{0020}sent\u{0020}you\u{0020}the\u{0020}result.\nHow\u{0020}should\u{0020}I\u{0020}put\u{0020}it...\u{0020}Mm,\u{0020}it\u{0020}is\u{0020}nice.\nBack\u{0020}when\u{0020}we\u{0020}were\u{0020}in\u{0020}Logan\u{0020}City,\u{0020}we\u{0020}really\u{0020}did\u{0020}not\u{0020}make\u{0020}many\u{0020}friends\u{0020}our\u{0020}age.\u{0020}But\u{0020}now,\u{0020}when\u{0020}I\u{0020}hear\u{0020}her\u{0020}excitedly\u{0020}sharing\u{0020}stories\u{0020}about\u{0020}what\u{0020}happened\u{0020}with\u{0020}her\u{0020}friends\u{0020}over\u{0020}meals,\u{0020}I\u{0020}think\u{0020}life\u{0020}here\u{0020}has\u{0020}indeed\u{0020}filled\u{0020}in\u{0020}another\u{0020}missing\u{0020}piece\u{0020}of\u{0020}her\u{0020}life.\n--And\u{0020}perhaps,\u{0020}some\u{0020}missing\u{0020}pieces\u{0020}of\u{0020}mine\u{0020}as\u{0020}well.\nThank\u{0020}you,\u{0020}Navigator.\nNo\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}it\u{0020}takes,\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}you\u{0020}that.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111032] = {id = 111032, name = "Chiaki", head = "11032", type = 5, title = "The\u{0020}Birthday\u{0020}Cake\u{0020}is\u{0020}Mine\u{0020}and\u{0020}Mine\u{0020}ONLY!", txt = "Finally\u{0020}Hmph,\u{0020}I've\u{0020}been\u{0020}looking\u{0020}forward\u{0020}to\u{0020}this\u{0020}day\u{0020}for\u{0020}so\u{0020}long!\nIf\u{0020}you\u{0020}ask\u{0020}me\u{0020}why...\u{0020}you're\u{0020}DONE\u{0020}FOR.\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}hear\u{0020}another\u{0020}stupid\u{0020}question.\nA\u{0020}birthday,\u{0020}you\u{0020}see,\u{0020}is\u{0020}a\u{0020}day\u{0020}when\u{0020}even\u{0020}the\u{0020}most\u{0020}wanted\u{0020}criminal\u{0020}in\u{0020}AEGIS\u{0020}can,\u{0020}without\u{0020}hesitation\u{0020}or\u{0020}guilt,\u{0020}have\u{0020}a\u{0020}cake.\nWhat?\u{0020}You\u{0020}don't\u{0020}actually\u{0020}expect\u{0020}me\u{0020}to\u{0020}share\u{0020}my\u{0020}cake\u{0020}with\u{0020}you,\u{0020}do\u{0020}you?\u{0020}Anyone\u{0020}foolish\u{0020}enough\u{0020}to\u{0020}try\u{0020}and\u{0020}take\u{0020}it\u{0020}from\u{0020}me...\u{0020}well,\u{0020}let's\u{0020}just\u{0020}say\u{0020}they\u{0020}won't\u{0020}live\u{0020}to\u{0020}regret\u{0020}it.\u{0020}\nBut...\u{0020}if\u{0020}you\u{0020}say\u{0020}the\u{0020}magic\u{0020}words\u{0020}Chiaki-sama,\u{0020}then\u{0020}maybe,\u{0020}I'll\u{0020}be\u{0020}willing\u{0020}to\u{0020}part\u{0020}with\u{0020}a\u{0020}slice.\u{0020}Now,\u{0020}now,\u{0020}just\u{0020}say\u{0020}it,\u{0020}and\u{0020}you'll\u{0020}have\u{0020}your\u{0020}share.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103201] = {id = 11103201, name = "Chiaki", head = "11032", type = 5, title = "Stingy\u{0020}Stephanie's\u{0020}Scheme", txt = "Hey,\u{0020}do\u{0020}you\u{0020}know\u{0020}what\u{0020}that\u{0020}Stephanie\u{0020}girl\u{0020}is\u{0020}plotting?\nOh,\u{0020}right,\u{0020}I\u{0020}forgot\u{0020}-\u{0020}you\u{0020}don't\u{0020}know\u{0020}what\u{0020}happened\u{0020}yet...\nThat\u{0020}Stephanie\u{0020}actually\u{0020}acted\u{0020}completely\u{0020}out\u{0020}of\u{0020}character\u{0020}and\u{0020}said\u{0020}with\u{0020}a\u{0020}sickening\u{0020}smile\u{0020}that\u{0020}nearly\u{0020}made\u{0020}me\u{0020}throw\u{0020}up,\u{0020}\"It's\u{0020}your\u{0020}birthday\u{0020}today,\u{0020}so\u{0020}you\u{0020}can\u{0020}do\u{0020}whatever\u{0020}you\u{0020}want\u{0020}-\u{0020}of\u{0020}course,\u{0020}nothing\u{0020}beyond\u{0020}what\u{0020}the\u{0020}law\u{0020}allows.\"\nWhy\u{0020}would\u{0020}she\u{0020}suddenly\u{0020}be\u{0020}so\u{0020}generous?\u{0020}She\u{0020}must\u{0020}be\u{0020}hiding\u{0020}some\u{0020}kind\u{0020}of\u{0020}scheme\u{0020}I\u{0020}don't\u{0020}know\u{0020}about...\nAnyway,\u{0020}get\u{0020}over\u{0020}here\u{0020}and\u{0020}help\u{0020}me\u{0020}already\u{0020}-\u{0020}I\u{0020}can't\u{0020}deal\u{0020}with\u{0020}her\u{0020}on\u{0020}my\u{0020}own!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111033] = {id = 111033, name = "Starry", head = "11033", type = 5, title = "Want\u{0020}to\u{0020}come\u{0020}to\u{0020}my\u{0020}7-day\u{0020}tour?", txt = "Birthday\u{0020}-\u{0020}Yes,\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday,\u{0020}I\u{0020}almost\u{0020}forgot.\u{0020}If\u{0020}it\u{0020}wasn't\u{0020}for\u{0020}the\u{0020}reminder\u{0020}on\u{0020}my\u{0020}digital\u{0020}calendar,\u{0020}I\u{0020}would\u{0020}have\u{0020}treated\u{0020}it\u{0020}as\u{0020}an\u{0020}ordinary\u{0020}day.\nSince\u{0020}it's\u{0020}my\u{0020}birthday…\u{0020}it's\u{0020}okay\u{0020}for\u{0020}me\u{0020}to\u{0020}be\u{0020}a\u{0020}little\u{0020}bit\u{0020}selfish,\u{0020}isn't\u{0020}it?\u{0020}If\u{0020}Stephanie\u{0020}holds\u{0020}me\u{0020}accountable,\u{0020}then\u{0020}Mr.\u{0020}Hentai\u{0020}will\u{0020}have\u{0020}some\u{0020}explanation\u{0020}to\u{0020}do~\nYou're\u{0020}wondering\u{0020}what\u{0020}I'm\u{0020}going\u{0020}to\u{0020}do?\u{0020}Well,\u{0020}I've\u{0020}won\u{0020}the\u{0020}grand\u{0020}prize\u{0020}of\u{0020}a\u{0020}seven-day\u{0020}trip\u{0020}for\u{0020}two\u{0020}to\u{0020}the\u{0020}Sahara.\u{0020}So\u{0020}what\u{0020}now,\u{0020}are\u{0020}you\u{0020}going\u{0020}to\u{0020}offer\u{0020}me\u{0020}seven\u{0020}measly\u{0020}days\u{0020}of\u{0020}your\u{0020}life?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103301] = {id = 11103301, name = "Starry", head = "11033", type = 5, title = "Care\u{0020}to\u{0020}Join\u{0020}Me\u{0020}for\u{0020}a\u{0020}Seven-Day\u{0020}Getaway?", txt = "Oh,\u{0020}it's\u{0020}my\u{0020}birthday…\u{0020}That's\u{0020}right,\u{0020}today's\u{0020}the\u{0020}day!\u{0020}Honestly,\u{0020}I\u{0020}almost\u{0020}forgot.\u{0020}If\u{0020}not\u{0020}for\u{0020}the\u{0020}reminder\u{0020}on\u{0020}my\u{0020}digital\u{0020}calendar,\u{0020}I\u{0020}probably\u{0020}would've\u{0020}let\u{0020}it\u{0020}pass\u{0020}like\u{0020}any\u{0020}ordinary\u{0020}day.\u{0020}\nBut\u{0020}since\u{0020}it's\u{0020}my\u{0020}special\u{0020}day,\u{0020}I\u{0020}think\u{0020}I'm\u{0020}entitled\u{0020}to\u{0020}a\u{0020}little\u{0020}indulgence,\u{0020}don't\u{0020}you?\u{0020}And\u{0020}if\u{0020}Stephanie\u{0020}decides\u{0020}to\u{0020}make\u{0020}a\u{0020}fuss\u{0020}about\u{0020}it,\u{0020}I'll\u{0020}leave\u{0020}the\u{0020}explaining\u{0020}to\u{0020}you,\u{0020}Mr.\u{0020}Navigator~\nWondering\u{0020}what\u{0020}I\u{0020}have\u{0020}in\u{0020}mind?\u{0020}Well,\u{0020}here's\u{0020}the\u{0020}surprise—I\u{0020}won\u{0020}a\u{0020}grand\u{0020}prize:\u{0020}a\u{0020}seven-day,\u{0020}two-person\u{0020}trip\u{0020}to\u{0020}the\u{0020}Sahara!\u{0020}So,\u{0020}what\u{0020}do\u{0020}you\u{0020}think?\u{0020}Would\u{0020}you\u{0020}let\u{0020}me\u{0020}borrow\u{0020}just\u{0020}seven\u{0020}little\u{0020}days\u{0020}of\u{0020}your\u{0020}life\u{0020}for\u{0020}an\u{0020}unforgettable\u{0020}adventure?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103302] = {id = 11103302, name = "Starry", head = "11033", type = 5, title = "Giving\u{0020}My\u{0020}Birthday\u{0020}a\u{0020}Surprise", txt = "Come\u{0020}to\u{0020}think\u{0020}of\u{0020}it,\u{0020}I\u{0020}realized\u{0020}my\u{0020}birthday\u{0020}was\u{0020}coming\u{0020}up\u{0020}about\u{0020}half\u{0020}a\u{0020}month\u{0020}ago.\u{0020}After\u{0020}all,\u{0020}every\u{0020}year\u{0020}when\u{0020}the\u{0020}calendar\u{0020}flips\u{0020}on\u{0020}January\u{0020}1st,\u{0020}I\u{0020}can't\u{0020}help\u{0020}noticing\u{0020}the\u{0020}date,\u{0020}and\u{0020}then\u{0020}it\u{0020}hits\u{0020}me\u{0020}that\u{0020}my\u{0020}birthday\u{0020}is\u{0020}less\u{0020}than\u{0020}two\u{0020}weeks\u{0020}away.\u{0020}\nSo\u{0020}these\u{0020}past\u{0020}couple\u{0020}of\u{0020}weeks,\u{0020}I've\u{0020}found\u{0020}myself\u{0020}constantly\u{0020}wondering\u{0020}what\u{0020}kind\u{0020}of\u{0020}birthday\u{0020}I'd\u{0020}have\u{0020}this\u{0020}year.\u{0020}I\u{0020}mean…\u{0020}this\u{0020}time\u{0020}last\u{0020}year,\u{0020}I\u{0020}spent\u{0020}an\u{0020}unforgettable\u{0020}birthday\u{0020}with\u{0020}you,\u{0020}Mister\u{0020}Pervert~\u{0020}\nAs\u{0020}for\u{0020}this\u{0020}year…\u{0020}How\u{0020}about\u{0020}inviting\u{0020}Chiaki,\u{0020}Levi\u{0020}to\u{0020}play\u{0020}baseball\u{0020}together?\u{0020}I've\u{0020}been\u{0020}wanting\u{0020}to\u{0020}host\u{0020}a\u{0020}Starry-themed\u{0020}baseball\u{0020}game\u{0020}for\u{0020}ages.\u{0020}\nIf\u{0020}you\u{0020}turn\u{0020}down\u{0020}this\u{0020}idea,\u{0020}I'll\u{0020}be\u{0020}really\u{0020}sad,\u{0020}you\u{0020}know~\u{0020}\nOh,\u{0020}and\u{0020}one\u{0020}more\u{0020}thing.\u{0020}I'll\u{0020}leave\u{0020}it\u{0020}to\u{0020}you,\u{0020}Mister\u{0020}Pervert,\u{0020}to\u{0020}explain\u{0020}everything\u{0020}to\u{0020}Stephanie\u{0020}for\u{0020}me~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111034] = {id = 111034, name = "Rodnia", head = "11034", type = 5, title = "My\u{0020}Sister\u{0020}Likes\u{0020}You\u{0020}Too", txt = "I\u{0020}paid\u{0020}my\u{0020}sister\u{0020}a\u{0020}visit\u{0020}today,\u{0020}just\u{0020}as\u{0020}I\u{0020}do\u{0020}every\u{0020}year\u{0020}on\u{0020}my\u{0020}birthday.\nI\u{0020}told\u{0020}her\u{0020}everything\u{0020}that's\u{0020}happened\u{0020}in\u{0020}the\u{0020}past\u{0020}year.\u{0020}About\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin,\u{0020}the\u{0020}reorganization\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad...\u{0020}When\u{0020}I\u{0020}got\u{0020}to\u{0020}talking\u{0020}about\u{0020}you,\u{0020}the\u{0020}wind\u{0020}chimes\u{0020}just\u{0020}wouldn't\u{0020}stop\u{0020}ringing,\u{0020}like\u{0020}she\u{0020}was\u{0020}nudging\u{0020}me\u{0020}to\u{0020}share\u{0020}more.\nAh,\u{0020}right.\u{0020}You\u{0020}haven't\u{0020}been\u{0020}there,\u{0020}so\u{0020}you\u{0020}don't\u{0020}know.\u{0020}There's\u{0020}a\u{0020}little\u{0020}tree\u{0020}next\u{0020}to\u{0020}my\u{0020}sister's\u{0020}gravestone.\u{0020}It\u{0020}hasn't\u{0020}grown\u{0020}at\u{0020}all\u{0020}over\u{0020}the\u{0020}years,\u{0020}as\u{0020}if\u{0020}time\u{0020}has\u{0020}stood\u{0020}still\u{0020}for\u{0020}everyone\u{0020}resting\u{0020}here.\u{0020}I\u{0020}hung\u{0020}the\u{0020}wind\u{0020}chimes\u{0020}on\u{0020}the\u{0020}branch,\u{0020}and\u{0020}every\u{0020}time\u{0020}the\u{0020}wind\u{0020}blows,\u{0020}they\u{0020}play\u{0020}their\u{0020}little\u{0020}tune,\u{0020}“ding-ling-ling.”\u{0020}It's\u{0020}really\u{0020}lovely.\u{0020}Even\u{0020}when\u{0020}I'm\u{0020}not\u{0020}there\u{0020}to\u{0020}keep\u{0020}her\u{0020}company,\u{0020}my\u{0020}sister\u{0020}won't\u{0020}feel\u{0020}alone.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111035] = {id = 111035, name = "Zepar", head = "11035", type = 5, title = "人家的生日到啦", txt = "哼哼，navigator，猜猜看今天是什麼日子？\n哼哼，你一定知道今天是人家的生日吧？\n你肯定不會想成是另外一個人的生日吧？。\nnavigator記著人家一個人的生日就足夠了！\n咳咳，總之，今天是人家的……不知道第幾個生日，但是今天你一定要陪人家玩噢！\n今天的navigator，只屬於人家一個人！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103501] = {id = 11103501, name = "Zepar", head = "11035", type = 5, title = "Guess\u{0020}What?\u{0020}It's\u{0020}My\u{0020}Birthday!", txt = "Hehe,\u{0020}Navigator,\u{0020}guess\u{0020}what\u{0020}day\u{0020}it\u{0020}is?\nHehe,\u{0020}you\u{0020}do\u{0020}know\u{0020}it's\u{0020}my\u{0020}birthday,\u{0020}right?\u{0020}\nYou\u{0020}didn't\u{0020}think\u{0020}it\u{0020}was\u{0020}someone\u{0020}else's,\u{0020}did\u{0020}you?\nOne\u{0020}resurrection\u{0020}is\u{0020}enough\u{0020}for\u{0020}anyone!\nAhem,\u{0020}anyway,\u{0020}today’s\u{0020}my…\u{0020}well,\u{0020}I'm\u{0020}not\u{0020}sure\u{0020}how\u{0020}many\u{0020}birthdays\u{0020}I've\u{0020}had,\u{0020}but\u{0020}you\u{0020}definitely\u{0020}have\u{0020}to\u{0020}spend\u{0020}the\u{0020}day\u{0020}with\u{0020}me!\nToday,\u{0020}Navigator,\u{0020}is\u{0020}all\u{0020}about\u{0020}me!\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103502] = {id = 11103502, name = "Zepar", head = "11035", type = 5, title = "It's\u{0020}My\u{0020}Birthday\u{0020}Again", txt = "It\u{0020}feels\u{0020}like\u{0020}something\u{0020}should\u{0020}be\u{0020}happening,\u{0020}but\u{0020}why\u{0020}is\u{0020}everything\u{0020}around\u{0020}me\u{0020}still\u{0020}the\u{0020}same\u{0020}as\u{0020}always...\u{0020}when\u{0020}it's\u{0020}already\u{0020}my\u{0020}birthday\u{0020}today!\u{0020}\nWhat\u{0020}a\u{0020}brand-new\u{0020}experience,\u{0020}I'm\u{0020}angry\u{0020}now.\u{0020}\nIf\u{0020}you\u{0020}won't\u{0020}come\u{0020}over,\u{0020}then\u{0020}right\u{0020}now,\u{0020}I'll\u{0020}come\u{0020}to\u{0020}you.\u{0020}\nI've\u{0020}already\u{0020}thought\u{0020}of\u{0020}the\u{0020}punishment\u{0020}too.\u{0020}In\u{0020}all\u{0020}these\u{0020}years\u{0020}I've\u{0020}lived,\u{0020}Navigator,\u{0020}you're\u{0020}the\u{0020}boldest\u{0020}one\u{0020}I've\u{0020}ever\u{0020}met!\u{0020}\nDon't\u{0020}you\u{0020}dare\u{0020}say\u{0020}you\u{0020}don't\u{0020}have\u{0020}time\u{0020}for\u{0020}me,\u{0020}or\u{0020}that\u{0020}you\u{0020}forgot\u{0020}or\u{0020}anything\u{0020}like\u{0020}that.\u{0020}Today's\u{0020}Navigator~\u{0020}belongs\u{0020}to\u{0020}me\u{0020}and\u{0020}me\u{0020}alone!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111036] = {id = 111036, name = "Precio", head = "11036", type = 5, title = "生日的意義", txt = "雖然我言必談及數據，但我並非對每個數字都抱有興趣，例如出生日期，除了提醒我在生物學意義上離死又近了一步，就沒什麼值得一提的了。\n人類慶祝生日的目的是什麼？起初也許是迷信，而在如今這個時代，則是像其他節日那樣找個藉口放鬆。\n但與公共節日的區別在於，生日更加私人化，它的日期因人而異，它的性質其實與我每次攻克一個困難課題、完成一項突破性研究後，所進行的慶祝行為相似——即是說，生日正是為慶祝自己又在生存這一課題上取得了階段性成果。\n……如此鋪墊，可能我也只是想說服自己放鬆下。所以navigator，今天陪我一起盡個興吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103601] = {id = 11103601, name = "Precio", head = "11036", type = 5, title = "The\u{0020}Meaning\u{0020}of\u{0020}Birthdays", txt = "While\u{0020}I\u{0020}often\u{0020}discuss\u{0020}data,\u{0020}not\u{0020}every\u{0020}number\u{0020}catches\u{0020}my\u{0020}interest—take\u{0020}my\u{0020}birthdate,\u{0020}for\u{0020}example.\u{0020}The\u{0020}only\u{0020}thing\u{0020}it\u{0020}really\u{0020}reminds\u{0020}me\u{0020}of\u{0020}is\u{0020}that,\u{0020}biologically\u{0020}speaking,\u{0020}I'm\u{0020}just\u{0020}one\u{0020}step\u{0020}closer\u{0020}to\u{0020}death.\u{0020}Not\u{0020}exactly\u{0020}something\u{0020}worth\u{0020}celebrating.\nBut\u{0020}what's\u{0020}the\u{0020}point\u{0020}of\u{0020}humans\u{0020}celebrating\u{0020}birthdays?\u{0020}At\u{0020}first,\u{0020}it\u{0020}might\u{0020}have\u{0020}been\u{0020}for\u{0020}superstitious\u{0020}reasons.\u{0020}In\u{0020}today's\u{0020}world,\u{0020}it's\u{0020}just\u{0020}another\u{0020}excuse\u{0020}to\u{0020}take\u{0020}a\u{0020}break,\u{0020}much\u{0020}like\u{0020}any\u{0020}other\u{0020}holiday.\nThe\u{0020}difference,\u{0020}however,\u{0020}is\u{0020}that\u{0020}birthdays\u{0020}are\u{0020}more\u{0020}personal.\u{0020}They\u{0020}vary\u{0020}from\u{0020}person\u{0020}to\u{0020}person,\u{0020}and\u{0020}the\u{0020}celebration\u{0020}is\u{0020}really\u{0020}quite\u{0020}similar\u{0020}to\u{0020}how\u{0020}I\u{0020}celebrate\u{0020}any\u{0020}achievement—whether\u{0020}it's\u{0020}conquering\u{0020}a\u{0020}tough\u{0020}problem\u{0020}or\u{0020}completing\u{0020}a\u{0020}groundbreaking\u{0020}study.\u{0020}A\u{0020}birthday\u{0020}marks\u{0020}another\u{0020}milestone\u{0020}in\u{0020}the\u{0020}ongoing\u{0020}challenge\u{0020}of\u{0020}simply\u{0020}staying\u{0020}alive.\n…Perhaps\u{0020}I'm\u{0020}just\u{0020}trying\u{0020}to\u{0020}convince\u{0020}myself\u{0020}to\u{0020}relax\u{0020}for\u{0020}once.\u{0020}So,\u{0020}Navigator,\u{0020}care\u{0020}to\u{0020}join\u{0020}me\u{0020}in\u{0020}marking\u{0020}the\u{0020}occasion?\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103602] = {id = 11103602, name = "Precio", head = "11036", type = 5, title = "This\u{0020}Year's\u{0020}Birthday\u{0020}Report", txt = "Dear\u{0020}Navigator,\u{0020}by\u{0020}the\u{0020}time\u{0020}you\u{0020}read\u{0020}this\u{0020}letter,\u{0020}I\u{0020}should\u{0020}be\u{0020}in\u{0020}my\u{0020}laboratory,\u{0020}dissecting\u{0020}the\u{0020}newly\u{0020}obtained\u{0020}Sin\u{0020}samples,\u{0020}to\u{0020}pass\u{0020}the\u{0020}time\u{0020}while\u{0020}I\u{0020}wait\u{0020}for\u{0020}you\u{0020}to\u{0020}arrive.\u{0020}\nNot\u{0020}long\u{0020}ago,\u{0020}an\u{0020}alarm\u{0020}set\u{0020}by\u{0020}last\u{0020}year's\u{0020}me\u{0020}interrupted\u{0020}my\u{0020}experiment.\u{0020}\nSo\u{0020}today\u{0020}is\u{0020}actually\u{0020}my\u{0020}birthday...\u{0020}I\u{0020}truly\u{0020}had\u{0020}forgotten\u{0020}it.\u{0020}After\u{0020}all,\u{0020}in\u{0020}my\u{0020}past\u{0020}life,\u{0020}it\u{0020}was\u{0020}always\u{0020}a\u{0020}lower\u{0020}priority\u{0020}than\u{0020}my\u{0020}interests.\u{0020}\nHowever,\u{0020}last\u{0020}year's\u{0020}birthday\u{0020}changed\u{0020}how\u{0020}I\u{0020}see\u{0020}that\u{0020}number,\u{0020}the\u{0020}one\u{0020}used\u{0020}to\u{0020}mark\u{0020}the\u{0020}moment\u{0020}a\u{0020}person\u{0020}officially\u{0020}becomes\u{0020}\"human\".\u{0020}\nSo...\u{0020}would\u{0020}you\u{0020}be\u{0020}willing\u{0020}to\u{0020}spend\u{0020}this\u{0020}birthday\u{0020}with\u{0020}me\u{0020}again\u{0020}this\u{0020}year?\u{0020}I'll\u{0020}be\u{0020}waiting\u{0020}for\u{0020}your\u{0020}reply.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111037] = {id = 111037, name = "Celesia", head = "11037", type = 5, title = "Only\u{0020}for\u{0020}today.", txt = "I've\u{0020}thought\u{0020}about\u{0020}this\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}unsure\u{0020}if\u{0020}what\u{0020}I'm\u{0020}doing\u{0020}is\u{0020}truly\u{0020}appropriate.\u{0020}But\u{0020}in\u{0020}the\u{0020}end,\u{0020}I've\u{0020}decided\u{0020}that\u{0020}no\u{0020}matter\u{0020}what,\u{0020}I\u{0020}must\u{0020}send\u{0020}you\u{0020}this\u{0020}invitation\u{0020}today…\nAlthough,\u{0020}I\u{0020}don't\u{0020}personally\u{0020}believe\u{0020}in\u{0020}indulging\u{0020}oneself\u{0020}to\u{0020}celebrate\u{0020}something,\u{0020}especially\u{0020}when\u{0020}it's\u{0020}a\u{0020}day\u{0020}that\u{0020}isn't\u{0020}truly\u{0020}mine\u{0020}to\u{0020}celebrate.\nMy\u{0020}personal\u{0020}records\u{0020}mark\u{0020}today\u{0020}as\u{0020}my\u{0020}birthday,\u{0020}but\u{0020}it's\u{0020}merely\u{0020}the\u{0020}day\u{0020}the\u{0020}church\u{0020}found\u{0020}me\u{0020}in\u{0020}the\u{0020}snow.\u{0020}When\u{0020}was\u{0020}I\u{0020}really\u{0020}born?\u{0020}That\u{0020}answer\u{0020}has\u{0020}long\u{0020}been\u{0020}buried\u{0020}beneath\u{0020}the\u{0020}snowdrifts.\u{0020}To\u{0020}be\u{0020}honest,\u{0020}I\u{0020}don't\u{0020}feel\u{0020}much\u{0020}need\u{0020}to\u{0020}know.\u{0020}The\u{0020}church\u{0020}gave\u{0020}me\u{0020}a\u{0020}new\u{0020}birthday,\u{0020}and\u{0020}through\u{0020}this,\u{0020}I've\u{0020}come\u{0020}to\u{0020}realize\u{0020}that\u{0020}birthdays\u{0020}are\u{0020}not\u{0020}for\u{0020}oneself,\u{0020}but\u{0020}for\u{0020}others.\nSo,\u{0020}whether\u{0020}or\u{0020}not\u{0020}today\u{0020}matters\u{0020}to\u{0020}me,\u{0020}perhaps\u{0020}you've\u{0020}remembered\u{0020}it\u{0020}all\u{0020}along.\u{0020}To\u{0020}show\u{0020}my\u{0020}respect\u{0020}for\u{0020}you\u{0020}in\u{0020}return,\u{0020}I'll\u{0020}wait\u{0020}for\u{0020}you\u{0020}in\u{0020}the\u{0020}church,\u{0020}just\u{0020}for\u{0020}today,\u{0020}no\u{0020}matter\u{0020}how\u{0020}late\u{0020}it\u{0020}gets...\n\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103701] = {id = 11103701, name = "Celesia", head = "11037", type = 5, title = "Clean\u{0020}Body", txt = "Cleansing\u{0020}the\u{0020}body\u{0020}is\u{0020}not\u{0020}merely\u{0020}to\u{0020}wash\u{0020}away\u{0020}dirt.\u{0020}It\u{0020}is\u{0020}to\u{0020}rinse\u{0020}off\u{0020}the\u{0020}shadows\u{0020}and\u{0020}bitterness\u{0020}that\u{0020}cling\u{0020}to\u{0020}the\u{0020}heart,\u{0020}to\u{0020}return\u{0020}oneself\u{0020}to\u{0020}a\u{0020}state\u{0020}as\u{0020}pure\u{0020}as\u{0020}one's\u{0020}first\u{0020}breath\u{0020}in\u{0020}this\u{0020}world.\nToday\u{0020}is\u{0020}my\u{0020}birthday,\u{0020}and\u{0020}the\u{0020}day\u{0020}of\u{0020}our\u{0020}annual\u{0020}private\u{0020}meeting.\nTo\u{0020}welcome\u{0020}it,\u{0020}I\u{0020}will\u{0020}bathe\u{0020}in\u{0020}holy\u{0020}waters,\u{0020}purify\u{0020}my\u{0020}heart,\u{0020}and\u{0020}meet\u{0020}you\u{0020}with\u{0020}a\u{0020}self-untouched\u{0020}by\u{0020}the\u{0020}filth\u{0020}of\u{0020}this\u{0020}world.\u{0020}Navigator,\u{0020}do\u{0020}not\u{0020}break\u{0020}this\u{0020}appointment.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111038] = {id = 111038, name = "Kafka", head = "11038", type = 5, title = "Life\u{0020}Advice,\u{0020}Please!", txt = "Hey,\u{0020}Navigator.\u{0020}Bet\u{0020}you've\u{0020}got\u{0020}nothing\u{0020}better\u{0020}to\u{0020}do\u{0020}today.\u{0020}Well,\u{0020}neither\u{0020}do\u{0020}I.\u{0020}Just\u{0020}beat\u{0020}all\u{0020}the\u{0020}high\u{0020}scores\u{0020}at\u{0020}the\u{0020}arcade\u{0020}again.\u{0020}Know\u{0020}what\u{0020}it's\u{0020}like\u{0020}to\u{0020}be\u{0020}beyond\u{0020}reach?\u{0020}Oh,\u{0020}and\u{0020}I\u{0020}held\u{0020}the\u{0020}older\u{0020}records,\u{0020}too.\u{0020}Haha.\nBut,\u{0020}it's\u{0020}like\u{0020}my\u{0020}life's\u{0020}already\u{0020}over!\u{0020}Can't\u{0020}see\u{0020}where\u{0020}I'm\u{0020}even\u{0020}headed...\nIs\u{0020}this\u{0020}what\u{0020}they\u{0020}call\u{0020}youthful\u{0020}angst?\u{0020}Pisses\u{0020}me\u{0020}off.\u{0020}And\u{0020}today's\u{0020}my\u{0020}birthday,\u{0020}which\u{0020}means\u{0020}another\u{0020}year\u{0020}totally\u{0020}wasted.\nNavigator,\u{0020}give\u{0020}me\u{0020}some\u{0020}advice\u{0020}speaking\u{0020}as\u{0020}an\u{0020}adult.\u{0020}Study\u{0020}harder,\u{0020}stay\u{0020}the\u{0020}same,\u{0020}whatever.\u{0020}Make\u{0020}it\u{0020}good.\nI\u{0020}appreciate\u{0020}it.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11103801] = {id = 11103801, name = "Kafka", head = "11038", type = 5, title = "Still\u{0020}a\u{0020}Life\u{0020}Consultation", txt = "...Do\u{0020}you\u{0020}have\u{0020}time?\u{0020}There\u{0020}is\u{0020}something\u{0020}I\u{0020}want\u{0020}to\u{0020}talk\u{0020}to\u{0020}you\u{0020}about.\nI\u{0020}just\u{0020}got\u{0020}a\u{0020}call\u{0020}from\u{0020}that\u{0020}damn\u{0020}old\u{0020}man.\u{0020}I\u{0020}was\u{0020}ready\u{0020}to\u{0020}hang\u{0020}up\u{0020}right\u{0020}after\u{0020}hearing\u{0020}the\u{0020}first\u{0020}sentence,\u{0020}but\u{0020}after\u{0020}the\u{0020}call\u{0020}connected,\u{0020}it\u{0020}was\u{0020}Mom's\u{0020}voice\u{0020}that\u{0020}came\u{0020}through.\nI\u{0020}will\u{0020}skip\u{0020}the\u{0020}details\u{0020}for\u{0020}now.\u{0020}Basically,\u{0020}it\u{0020}was\u{0020}all\u{0020}about\u{0020}how\u{0020}my\u{0020}health\u{0020}was,\u{0020}whether\u{0020}my\u{0020}wounds\u{0020}hurt,\u{0020}whether\u{0020}the\u{0020}severed\u{0020}hand\u{0020}would\u{0020}really\u{0020}recover\u{0020}after\u{0020}I\u{0020}changed\u{0020}back,\u{0020}things\u{0020}like\u{0020}that.\u{0020}They\u{0020}even\u{0020}said\u{0020}they\u{0020}were\u{0020}proud\u{0020}of\u{0020}me\u{0020}and\u{0020}would\u{0020}make\u{0020}up\u{0020}my\u{0020}birthday\u{0020}for\u{0020}me\u{0020}in\u{0020}a\u{0020}couple\u{0020}days\u{0020}if\u{0020}I\u{0020}had\u{0020}time\u{0020}to\u{0020}go\u{0020}back.\nI\u{0020}guess\u{0020}they\u{0020}saw\u{0020}the\u{0020}news\u{0020}about\u{0020}the\u{0020}squad\u{0020}being\u{0020}commended\u{0020}a\u{0020}few\u{0020}days\u{0020}ago.\u{0020}Ha...\nI\u{0020}worked\u{0020}so\u{0020}hard\u{0020}because\u{0020}I\u{0020}was\u{0020}annoyed\u{0020}with\u{0020}my\u{0020}family,\u{0020}but\u{0020}now\u{0020}it\u{0020}ended\u{0020}up\u{0020}like\u{0020}this.\u{0020}I\u{0020}really\u{0020}do\u{0020}not\u{0020}want\u{0020}to\u{0020}do\u{0020}this\u{0020}anymore,\u{0020}so\u{0020}I\u{0020}am\u{0020}coming\u{0020}to\u{0020}resign.\nJust\u{0020}kidding.\u{0020}But\u{0020}I\u{0020}really\u{0020}do\u{0020}want\u{0020}to\u{0020}talk\u{0020}to\u{0020}someone.\nLet\u{0020}us\u{0020}meet\u{0020}at\u{0020}the\u{0020}same\u{0020}arcade\u{0020}as\u{0020}before.\u{0020}If\u{0020}that\u{0020}works\u{0020}for\u{0020}you,\u{0020}I\u{0020}will\u{0020}head\u{0020}over\u{0020}now.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111041] = {id = 111041, name = "Vega", head = "11041", type = 5, title = "生日特權", txt = "最近聽說了一件有趣的事。\n似乎在多瑙支部，只要駕駛員過生日，就可以行使一種特殊的權利……\n那個權利就是可以無條件讓navigator陪自己一天。（可要是倆人同一天生日怎麼辦？）\n沒想到這麼多年沒什麼意義的生日，在今年有不一樣的收穫了。\nnavigator，我想請你——還有你的妹妹和我一起玩一天，我想“好好”地和你們相處，你應該不會拒絕吧？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104101] = {id = 11104101, name = "Vega", head = "11041", type = 5, title = "Birthday\u{0020}Privilege", txt = "I\u{0020}heard\u{0020}something\u{0020}interesting\u{0020}the\u{0020}other\u{0020}day.\n\"Apparently,\"\u{0020}at\u{0020}the\u{0020}Danube\u{0020}branch,\u{0020}every\u{0020}Driver\u{0020}has\u{0020}a\u{0020}special\u{0020}gift\u{0020}for\u{0020}their\u{0020}birthday...\nA\u{0020}privilege\u{0020}to\u{0020}have\u{0020}Navigator\u{0020}spend\u{0020}the\u{0020}entire\u{0020}day\u{0020}with\u{0020}them\u{0020}unconditionally.\u{0020}(Though\u{0020}I\u{0020}do\u{0020}wonder\u{0020}what\u{0020}happens\u{0020}if\u{0020}two\u{0020}Drivers\u{0020}share\u{0020}the\u{0020}same\u{0020}birthday...)\nI\u{0020}never\u{0020}used\u{0020}to\u{0020}care\u{0020}much\u{0020}about\u{0020}birthdays,\u{0020}but\u{0020}this\u{0020}year,\u{0020}it\u{0020}feels\u{0020}a\u{0020}little\u{0020}different.\nNavigator,\u{0020}I\u{0020}want\u{0020}to\u{0020}ask\u{0020}you,\u{0020}along\u{0020}with\u{0020}your\u{0020}sister,\u{0020}to\u{0020}spend\u{0020}the\u{0020}day\u{0020}with\u{0020}me.\u{0020}I\u{0020}want\u{0020}to\u{0020}really\u{0020}get\u{0020}to\u{0020}know\u{0020}you\u{0020}both.\u{0020}You’re\u{0020}not\u{0020}planning\u{0020}to\u{0020}turn\u{0020}me\u{0020}down,\u{0020}are\u{0020}you?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104102] = {id = 11104102, name = "Vega", head = "11041", type = 5, title = "Urgently\u{0020}Need\u{0020}Help", txt = "Do\u{0020}you\u{0020}know\u{0020}what\u{0020}the\u{0020}most\u{0020}terrifying\u{0020}job\u{0020}at\u{0020}the\u{0020}police\u{0020}station\u{0020}is,\u{0020}Navigator?\nIt\u{0020}is\u{0020}seasonal\u{0020}paperwork.\nLists\u{0020}of\u{0020}newly\u{0020}excavated\u{0020}cultural\u{0020}relics,\u{0020}their\u{0020}ownership\u{0020}and\u{0020}value,\u{0020}security\u{0020}protocols\u{0020}for\u{0020}related\u{0020}facilities...\u{0020}including\u{0020}the\u{0020}pile\u{0020}of\u{0020}scrap\u{0020}paper\u{0020}that\u{0020}was\u{0020}tossed\u{0020}aside\u{0020}before\u{0020}because\u{0020}of\u{0020}the\u{0020}Sin\u{0020}invasion.\u{0020}At\u{0020}this\u{0020}time\u{0020}of\u{0020}year,\u{0020}they\u{0020}all\u{0020}come\u{0020}rushing\u{0020}out\u{0020}at\u{0020}once,\u{0020}you\u{0020}know?\nThanks\u{0020}to\u{0020}that,\u{0020}I\u{0020}have\u{0020}only\u{0020}slept\u{0020}three\u{0020}hours\u{0020}this\u{0020}past\u{0020}week,\u{0020}you\u{0020}know?\nI\u{0020}spent\u{0020}my\u{0020}birthday\u{0020}buried\u{0020}under\u{0020}files\u{0020}that\u{0020}filled\u{0020}my\u{0020}desk,\u{0020}you\u{0020}know?\nI\u{0020}have\u{0020}not\u{0020}even\u{0020}gone\u{0020}to\u{0020}the\u{0020}front\u{0020}lines,\u{0020}but\u{0020}I\u{0020}am\u{0020}already\u{0020}about\u{0020}to\u{0020}die,\u{0020}you\u{0020}know?\n...That\u{0020}is\u{0020}enough\u{0020}complaining.\u{0020}I\u{0020}must\u{0020}have\u{0020}had\u{0020}too\u{0020}much\u{0020}coffee.\nHelp\u{0020}me\u{0020}out,\u{0020}Navigator.\nOnce\u{0020}this\u{0020}pile\u{0020}of\u{0020}work\u{0020}is\u{0020}finished,\u{0020}I\u{0020}want\u{0020}to\u{0020}use\u{0020}my\u{0020}vacation\u{0020}to\u{0020}make\u{0020}a\u{0020}trip\u{0020}to\u{0020}Danube.\u{0020}Just\u{0020}a\u{0020}few\u{0020}hours\u{0020}would\u{0020}be\u{0020}enough.\u{0020}Could\u{0020}you\u{0020}and\u{0020}Gia\u{0020}find\u{0020}some\u{0020}time\u{0020}to\u{0020}accompany\u{0020}me\u{0020}again?\nThink\u{0020}of\u{0020}it\u{0020}as\u{0020}granting\u{0020}me\u{0020}one\u{0020}late\u{0020}birthday\u{0020}wish.\u{0020}Is\u{0020}that\u{0020}okay?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111042] = {id = 111042, name = "Kyla", head = "11042", type = 5, title = "What's\u{0020}Today\u{0020}Again?", txt = "This\u{0020}morning,\u{0020}Rosalind\u{0020}said,\u{0020}Don't\u{0020}tell\u{0020}me\u{0020}you\u{0020}forgot\u{0020}what\u{0020}day\u{0020}it\u{0020}is.\nSo\u{0020}I\u{0020}said,\u{0020}\"Is\u{0020}it\u{0020}the\u{0020}anniversary\u{0020}of\u{0020}me\u{0020}joining\u{0020}the\u{0020}Frontier?\"\nAnd\u{0020}then\u{0020}she\u{0020}totally\u{0020}blew\u{0020}up\u{0020}at\u{0020}me.\nAfter\u{0020}that,\u{0020}she\u{0020}still\u{0020}wouldn't\u{0020}tell\u{0020}me\u{0020}what\u{0020}today\u{0020}was\u{0020}supposed\u{0020}to\u{0020}be...\u{0020}What\u{0020}a\u{0020}grumpy\u{0020}little\u{0020}girl.\nAnyway,\u{0020}Navigator,\u{0020}the\u{0020}weather's\u{0020}so\u{0020}nice\u{0020}today!\u{0020}Perfect\u{0020}for\u{0020}a\u{0020}walk.\nLet's\u{0020}go\u{0020}explore\u{0020}every\u{0020}single\u{0020}corner\u{0020}of\u{0020}this\u{0020}city\u{0020}together!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104201] = {id = 11104201, name = "Kyla", head = "11042", type = 5, title = "I\u{0020}Will\u{0020}Not\u{0020}Get\u{0020}It\u{0020}Wrong\u{0020}This\u{0020}Year!", txt = "All\u{0020}right,\u{0020}I\u{0020}have\u{0020}fully\u{0020}learned\u{0020}from\u{0020}last\u{0020}year's\u{0020}lesson!\nJust\u{0020}to\u{0020}be\u{0020}safe,\u{0020}I\u{0020}checked\u{0020}the\u{0020}calendar\u{0020}this\u{0020}morning,\u{0020}and\u{0020}sure\u{0020}enough,\u{0020}today's\u{0020}date\u{0020}had\u{0020}a\u{0020}huge\u{0020}\"BIRTHDAY!!!!\"\u{0020}written\u{0020}on\u{0020}it.\u{0020}Making\u{0020}a\u{0020}reminder\u{0020}in\u{0020}advance\u{0020}really\u{0020}was\u{0020}the\u{0020}right\u{0020}call!\nAfter\u{0020}that,\u{0020}I\u{0020}checked\u{0020}the\u{0020}dormitory\u{0020}and\u{0020}found\u{0020}that\u{0020}not\u{0020}only\u{0020}were\u{0020}the\u{0020}gifts\u{0020}ready,\u{0020}but\u{0020}the\u{0020}party\u{0020}decorations\u{0020}and\u{0020}cake\u{0020}were\u{0020}ready\u{0020}too.\u{0020}It\u{0020}was\u{0020}even\u{0020}hazelnut\u{0020}cookie\u{0020}flavor,\u{0020}the\u{0020}one\u{0020}Rosa\u{0020}had\u{0020}always\u{0020}wanted\u{0020}to\u{0020}try\u{0020}but\u{0020}could\u{0020}never\u{0020}bring\u{0020}herself\u{0020}to\u{0020}buy.\u{0020}The\u{0020}me\u{0020}from\u{0020}a\u{0020}few\u{0020}days\u{0020}ago\u{0020}was\u{0020}simply\u{0020}a\u{0020}genius!\nIn\u{0020}short,\u{0020}everything\u{0020}is\u{0020}ready\u{0020}now!\u{0020}Navigator,\u{0020}if\u{0020}you\u{0020}have\u{0020}time,\u{0020}come\u{0020}help\u{0020}me\u{0020}set\u{0020}up\u{0020}the\u{0020}venue.\u{0020}I\u{0020}absolutely,\u{0020}absolutely\u{0020}want\u{0020}to\u{0020}prepare\u{0020}a\u{0020}birthday\u{0020}surprise\u{0020}for\u{0020}Rosa\u{0020}that\u{0020}will\u{0020}leave\u{0020}her\u{0020}speechless!\n\n[Reply\u{0020}below]\nI\u{0020}received\u{0020}your\u{0020}reply,\u{0020}but--\u{0020}Navigator,\u{0020}what\u{0020}do\u{0020}you\u{0020}mean\u{0020}by\u{0020}\"Rosalind's\u{0020}birthday\u{0020}is\u{0020}April\u{0020}16.\u{0020}Stop\u{0020}before\u{0020}she\u{0020}gets\u{0020}angry.\"?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111043] = {id = 111043, name = "Mira", head = "11043", type = 5, title = "不要給別人看到這封信哦", txt = "生日的祝福，以及神明的祝福，兩者間究竟哪個更加優先，彼此又是否存在重疊？曾經的我，其實會一本正經地思考這樣無聊的問題，到後來我才明白自己實在是不解人意，根本搞錯了重點，甚至以為人們在意的真的是祝福本身。\n畢竟是紀念自己降生的日子，開開心心的就好了嘛，今天到了我的生日，我也想卸去那些麻煩的職責，單純度過一天。\n我想穿上平時不會在信眾前穿的私服，以不會被認出來的尋常少女模樣，和navigator你一起隨便找些地方閒逛。這樣子是不是還有點瞞著神明幽會的背德感呢？光是想想就很有意思。那麼，碰面地點就由你決定吧，盡快回復我哦。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11104302] = {id = 11104302, name = "Mira", head = "11043", type = 5, title = "God\u{0020}Has\u{0020}Forgotten\u{0020}Me", txt = "May\u{0020}the\u{0020}light\u{0020}of\u{0020}God\u{0020}shine\u{0020}upon\u{0020}you,\u{0020}perhaps\u{0020}it\u{0020}was\u{0020}a\u{0020}subtle\u{0020}arrangement\u{0020}of\u{0020}God\u{0020}that\u{0020}you\u{0020}received\u{0020}this\u{0020}mail\u{0020}at\u{0020}this\u{0020}time.\u{0020}\nJust\u{0020}kidding.\u{0020}A\u{0020}\"nun\"\u{0020}isn't\u{0020}exactly\u{0020}the\u{0020}kind\u{0020}of\u{0020}\"profession\"\u{0020}that\u{0020}can\u{0020}bring\u{0020}about\u{0020}such\u{0020}holy\u{0020}miracles.\u{0020}If\u{0020}the\u{0020}people\u{0020}who\u{0020}guide\u{0020}the\u{0020}faithful...\u{0020}if\u{0020}we,\u{0020}dressed\u{0020}in\u{0020}our\u{0020}habits,\u{0020}are\u{0020}watched\u{0020}by\u{0020}God,\u{0020}then\u{0020}at\u{0020}least\u{0020}in\u{0020}private,\u{0020}we're\u{0020}just\u{0020}ordinary\u{0020}girls.\u{0020}And\u{0020}only\u{0020}at\u{0020}moments\u{0020}like\u{0020}this,\u{0020}we\u{0020}are\u{0020}forgotten\u{0020}by\u{0020}God.\u{0020}\nSo\u{0020}yesterday,\u{0020}I\u{0020}made\u{0020}a\u{0020}wish\u{0020}to\u{0020}God:\u{0020}that\u{0020}you\u{0020}would\u{0020}have\u{0020}time\u{0020}today\u{0020}to\u{0020}come\u{0020}and\u{0020}celebrate\u{0020}my\u{0020}birthday.\u{0020}\nAnd\u{0020}so,\u{0020}on\u{0020}that\u{0020}night\u{0020}when\u{0020}God\u{0020}is\u{0020}absent,\u{0020}please,\u{0020}be\u{0020}with\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111045] = {id = 111045, name = "Verir", head = "11045", type = 5, title = "Scheduled\u{0020}to\u{0020}Send\u{0020}on\u{0020}December\u{0020}9", txt = "[Transcribed\u{0020}from\u{0020}audio]\nThe\u{0020}time\u{0020}was\u{0020}set\u{0020}correctly,\u{0020}right?\nHuh?\u{0020}It\u{0020}has\u{0020}already\u{0020}started\u{0020}recording?\u{0020}Why\u{0020}didn't\u{0020}you\u{0020}tell\u{0020}me?\u{0020}And\u{0020}where’s\u{0020}the\u{0020}note\u{0020}D34\u{0020}helped\u{0020}with?\u{0020}Don't\u{0020}hand\u{0020}it\u{0020}over,\u{0020}S52.\u{0020}I\u{0020}don't\u{0020}want\u{0020}yours.\u{0020}Who\u{0020}would\u{0020}even\u{0020}say\u{0020}the\u{0020}things\u{0020}you\u{0020}wrote\u{0020}out\u{0020}loud?\nFine,\u{0020}I'll\u{0020}just\u{0020}improvise.\nHey,\u{0020}Navigator,\u{0020}can\u{0020}you\u{0020}hear\u{0020}me?\u{0020}I\u{0020}need\u{0020}a\u{0020}favor.\u{0020}On\u{0020}December\u{0020}9,\u{0020}the\u{0020}day\u{0020}you\u{0020}get\u{0020}this\u{0020}recording,\u{0020}can\u{0020}you\u{0020}put\u{0020}in\u{0020}a\u{0020}request\u{0020}to\u{0020}send\u{0020}me\u{0020}on\u{0020}a\u{0020}mission?\u{0020}Any\u{0020}mission\u{0020}will\u{0020}do,\u{0020}so\u{0020}long\u{0020}as\u{0020}it\u{0020}lets\u{0020}me\u{0020}gigantify.\u{0020}And\u{0020}make\u{0020}sure\u{0020}you\u{0020}ask\u{0020}firmly.\nThe\u{0020}lab\u{0020}people\u{0020}are\u{0020}still\u{0020}insisting\u{0020}that\u{0020}I\u{0020}should\u{0020}rest\u{0020}on\u{0020}my\u{0020}birthday.\u{0020}What\u{0020}a\u{0020}joke.\u{0020}Without\u{0020}a\u{0020}Transformation\u{0020}Core\u{0020}I\u{0020}can't\u{0020}even\u{0020}\"stay\u{0020}awake.\"\nAt\u{0020}the\u{0020}very\u{0020}least,\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}miss\u{0020}my\u{0020}birthday\u{0020}this\u{0020}year...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[111049] = {id = 111049, name = "Althea", head = "11049", type = 5, title = "A\u{0020}Birthday\u{0020}in\u{0020}Your\u{0020}Teens\u{0020}Doesn't\u{0020}Carry\u{0020}Any\u{0020}Deeper\u{0020}Meaning", txt = "Today\u{0020}is\u{0020}my\u{0020}birthday!\u{0020}Althea\u{0020}Weiss's\u{0020}birthday!\u{0020}Even\u{0020}though\u{0020}hearing\u{0020}that\u{0020}might\u{0020}make\u{0020}you\u{0020}think,\u{0020}\"Which\u{0020}Althea?\"\u{0020}or\u{0020}something\u{0020}like\u{0020}that,\u{0020}just\u{0020}treat\u{0020}it\u{0020}as\u{0020}my\u{0020}birthday,\u{0020}okay?\nI\u{0020}once\u{0020}watched\u{0020}an\u{0020}anime\u{0020}titled\u{0020}\"A\u{0020}Birthday\u{0020}in\u{0020}Your\u{0020}Twenties\u{0020}Doesn't\u{0020}Carry\u{0020}Any\u{0020}Deeper\u{0020}Meaning\",\u{0020}but\u{0020}what\u{0020}about\u{0020}the\u{0020}other\u{0020}way\u{0020}around?\u{0020}Does\u{0020}that\u{0020}mean\u{0020}a\u{0020}birthday\u{0020}in\u{0020}your\u{0020}teens\u{0020}does\u{0020}carry\u{0020}some\u{0020}deeper\u{0020}meaning?\u{0020}Or\u{0020}that\u{0020}birthdays\u{0020}only\u{0020}start\u{0020}carrying\u{0020}deeper\u{0020}meaning\u{0020}after\u{0020}you\u{0020}turn\u{0020}thirty?\nOnly\u{0020}recently\u{0020}did\u{0020}I\u{0020}finally\u{0020}figure\u{0020}it\u{0020}out:\u{0020}what\u{0020}it\u{0020}really\u{0020}means\u{0020}is\u{0020}that\u{0020}birthdays\u{0020}were\u{0020}never\u{0020}supposed\u{0020}to\u{0020}have\u{0020}any\u{0020}deeper\u{0020}meaning\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\nSpending\u{0020}the\u{0020}day\u{0020}in\u{0020}whatever\u{0020}way\u{0020}you\u{0020}like\u{0020}is\u{0020}the\u{0020}ultimate,\u{0020}best,\u{0020}one\u{0020}and\u{0020}only\u{0020}correct\u{0020}answer\u{0020}to\u{0020}the\u{0020}question\u{0020}of\u{0020}what\u{0020}a\u{0020}birthday\u{0020}is\u{0020}supposed\u{0020}to\u{0020}mean!\nMr.\u{0020}Lizard,\u{0020}come\u{0020}watch\u{0020}a\u{0020}movie\u{0020}with\u{0020}me!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "