[111059] = {id = 111059, name = "Mikael", head = "11059", type = 5, title = "A\u{0020}Birthday\u{0020}Party\u{0020}for\u{0020}the\u{0020}Strong", txt = "Today's\u{0020}training\u{0020}plan\u{0020}has\u{0020}been\u{0020}canceled,\u{0020}because\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday.\nTaking\u{0020}one\u{0020}day\u{0020}off\u{0020}once\u{0020}in\u{0020}a\u{0020}while\u{0020}will\u{0020}not\u{0020}affect\u{0020}my\u{0020}combat\u{0020}strength.\u{0020}Consider\u{0020}it\u{0020}a\u{0020}chance\u{0020}for\u{0020}the\u{0020}other\u{0020}drivers\u{0020}to\u{0020}catch\u{0020}up\u{0020}to\u{0020}me.\nSpeaking\u{0020}of\u{0020}celebrating\u{0020}birthdays,\u{0020}most\u{0020}people\u{0020}would\u{0020}make\u{0020}a\u{0020}birthday\u{0020}cake\u{0020}and\u{0020}invite\u{0020}their\u{0020}friends\u{0020}to\u{0020}hold\u{0020}a\u{0020}lively\u{0020}party,\u{0020}right?\u{0020}But\u{0020}those\u{0020}are\u{0020}ways\u{0020}for\u{0020}the\u{0020}weak\u{0020}to\u{0020}celebrate.\u{0020}A\u{0020}strong\u{0020}one\u{0020}like\u{0020}me\u{0020}has\u{0020}no\u{0020}need\u{0020}for\u{0020}others\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday...\nBut\u{0020}you\u{0020}are\u{0020}different,\u{0020}Navigator.\u{0020}In\u{0020}my\u{0020}heart...\u{0020}you\u{0020}are\u{0020}the\u{0020}only\u{0020}strong\u{0020}one\u{0020}I\u{0020}acknowledge.\nThat\u{0020}is\u{0020}why\u{0020}I\u{0020}am\u{0020}inviting\u{0020}you\u{0020}to\u{0020}my\u{0020}birthday\u{0020}party.\u{0020}That\u{0020}is\u{0020}right,\u{0020}just\u{0020}you\u{0020}and\u{0020}me.\u{0020}A\u{0020}party\u{0020}for\u{0020}the\u{0020}strong\u{0020}and\u{0020}the\u{0020}victorious.\nI\u{0020}will\u{0020}prepare\u{0020}the\u{0020}birthday\u{0020}cake\u{0020}and\u{0020}everything\u{0020}else,\u{0020}and\u{0020}wait\u{0020}for\u{0020}you\u{0020}to\u{0020}arrive.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
