[112002] = {id = 112002, name = "Shiranui", head = "12002", type = 5, title = "Where\u{0020}Is\u{0020}My\u{0020}Cutest\u{0020}Navigator?", txt = "Hey\u{0020}there.\u{0020}My\u{0020}adorable\u{0020}Navigator,\u{0020}you\u{0020}haven't\u{0020}forgotten\u{0020}what\u{0020}day\u{0020}it\u{0020}is\u{0020}today,\u{0020}have\u{0020}you?\u{0020}It'd\u{0020}be\u{0020}pretty\u{0020}cold\u{0020}if\u{0020}you\u{0020}didn't\u{0020}even\u{0020}say\u{0020}\"Happy\u{0020}Birthday\"\u{0020}to\u{0020}me.\u{0020}That's\u{0020}not\u{0020}something\u{0020}a\u{0020}good\u{0020}kid\u{0020}would\u{0020}do.\nAlright,\u{0020}alright,\u{0020}no\u{0020}more\u{0020}jokes.\nBeen\u{0020}busy\u{0020}lately?\u{0020}Haven't\u{0020}heard\u{0020}from\u{0020}you\u{0020}in\u{0020}days.\u{0020}The\u{0020}rest\u{0020}of\u{0020}the\u{0020}Fuurinkazan\u{0020}have\u{0020}been\u{0020}missing\u{0020}you.\nThey've\u{0020}all\u{0020}been\u{0020}keeping\u{0020}me\u{0020}company\u{0020}today,\u{0020}including\u{0020}Kinosuke,\u{0020}who\u{0020}usually\u{0020}hates\u{0020}group\u{0020}activities.\u{0020}Hehe,\u{0020}being\u{0020}surrounded\u{0020}by\u{0020}all\u{0020}these\u{0020}sweet\u{0020}girls...\u{0020}I\u{0020}wish\u{0020}every\u{0020}day\u{0020}could\u{0020}be\u{0020}my\u{0020}birthday.\nSo,\u{0020}whenever\u{0020}you\u{0020}have\u{0020}some\u{0020}free\u{0020}time,\u{0020}come\u{0020}join\u{0020}us\u{0020}for\u{0020}a\u{0020}meal.\u{0020}It'll\u{0020}make\u{0020}them\u{0020}happy\u{0020}too.\u{0020}Consider\u{0020}it\u{0020}my\u{0020}birthday\u{0020}present,\u{0020}okay?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
