[11200701] = {id = 11200701, name = "Huameng", head = "12007", type = 5, title = "Let's\u{0020}Head\u{0020}to\u{0020}the\u{0020}Mountains!", txt = "Navigator,\u{0020}today's\u{0020}my\u{0020}birthday!\nIn\u{0020}Aegis,\u{0020}everyone\u{0020}seems\u{0020}to\u{0020}have\u{0020}their\u{0020}own\u{0020}special\u{0020}way\u{0020}of\u{0020}celebrating,\u{0020}and\u{0020}I\u{0020}can't\u{0020}be\u{0020}the\u{0020}odd\u{0020}one\u{0020}out,\u{0020}right?\u{0020}So,\u{0020}I've\u{0020}decided\u{0020}to\u{0020}come\u{0020}up\u{0020}with\u{0020}a\u{0020}celebration\u{0020}that's\u{0020}uniquely\u{0020}mine!\nHere's\u{0020}the\u{0020}plan—let's\u{0020}venture\u{0020}to\u{0020}my\u{0020}homeland.\u{0020}Deep\u{0020}within\u{0020}the\u{0020}vast\u{0020}mountain\u{0020}range,\u{0020}where\u{0020}danger\u{0020}and\u{0020}opportunity\u{0020}walk\u{0020}hand\u{0020}in\u{0020}hand,\u{0020}we'll\u{0020}spend\u{0020}the\u{0020}most\u{0020}important\u{0020}day\u{0020}of\u{0020}the\u{0020}year\u{0020}together.\u{0020}Doesn't\u{0020}that\u{0020}sound\u{0020}thrilling?\nSo,\u{0020}what\u{0020}do\u{0020}you\u{0020}say,\u{0020}Navigator?\u{0020}Grab\u{0020}your\u{0020}gear\u{0020}and\u{0020}let's\u{0020}set\u{0020}off\u{0020}on\u{0020}this\u{0020}grand\u{0020}adventure!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200702] = {id = 11200702, name = "Huameng", head = "12007", type = 5, title = "I\u{0020}Want\u{0020}Meat", txt = "Today,\u{0020}this\u{0020}humble\u{0020}one\u{0020}came\u{0020}to\u{0020}Danube\u{0020}for\u{0020}only\u{0020}two\u{0020}things…\u{0020}Training,\u{0020}and\u{0020}after\u{0020}training…\u{0020}eating\u{0020}meat.\u{0020}Big\u{0020}bites.\u{0020}Unrestrained.\u{0020}Meat!\nWalking\u{0020}all\u{0020}the\u{0020}way\u{0020}from\u{0020}Kyushu\u{0020}to\u{0020}Danube,\u{0020}I\u{0020}tempered\u{0020}my\u{0020}martial\u{0020}arts\u{0020}through\u{0020}unexpected\u{0020}battles\u{0020}against\u{0020}Sins\u{0020}along\u{0020}the\u{0020}road.\u{0020}On\u{0020}that\u{0020}foundation,\u{0020}I\u{0020}endured\u{0020}the\u{0020}desire\u{0020}to\u{0020}feast,\u{0020}treating\u{0020}hunger\u{0020}itself\u{0020}as\u{0020}a\u{0020}form\u{0020}of\u{0020}spiritual\u{0020}discipline…\u{0020}But\u{0020}still,\u{0020}meat…\u{0020}This\u{0020}humble\u{0020}one\u{0020}believes\u{0020}that\u{0020}without\u{0020}meat,\u{0020}the\u{0020}state\u{0020}of\u{0020}mind\u{0020}required\u{0020}for\u{0020}martial\u{0020}cultivation\u{0020}will\u{0020}always\u{0020}remain\u{0020}incomplete!\u{0020}\nAt\u{0020}last,\u{0020}just\u{0020}before\u{0020}my\u{0020}birthday\u{0020}arrived,\u{0020}I\u{0020}managed\u{0020}to\u{0020}reach\u{0020}Danube.\u{0020}With\u{0020}that,\u{0020}my\u{0020}training\u{0020}is\u{0020}complete,\u{0020}and\u{0020}now,\u{0020}it\u{0020}is\u{0020}time\u{0020}to\u{0020}lift\u{0020}the\u{0020}restraints\u{0020}I\u{0020}placed\u{0020}upon\u{0020}myself.\u{0020}\nAt\u{0020}this\u{0020}moment,\u{0020}all\u{0020}I\u{0020}want\u{0020}is\u{0020}meat.\u{0020}Everything\u{0020}else\u{0020}can\u{0020}wait.\u{0020}First,\u{0020}I\u{0020}must\u{0020}overcome\u{0020}the\u{0020}inner\u{0020}demon\u{0020}that\u{0020}blocks\u{0020}my\u{0020}path\u{0020}of\u{0020}martial\u{0020}mastery.\u{0020}\nSo,\u{0020}Navigator,\u{0020}are\u{0020}there\u{0020}any\u{0020}recommended\u{0020}all-you-can-eat\u{0020}places\u{0020}in\u{0020}Danube?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112008] = {id = 112008, name = "Baili\u{0020}Momo", head = "12008", type = 5, title = "Birthday\u{0020}Bash!", txt = "*Yawn*\u{0020}So\u{0020}sleepy!\u{0020}Early\u{0020}this\u{0020}morning,\u{0020}Momo\u{0020}woke\u{0020}up\u{0020}before\u{0020}dawn.\u{0020}Even\u{0020}though\u{0020}I'm\u{0020}really\u{0020}looking\u{0020}forward\u{0020}to\u{0020}my\u{0020}birthday,\u{0020}the\u{0020}main\u{0020}reason\u{0020}for\u{0020}being\u{0020}woken\u{0020}up\u{0020}was\u{0020}the\u{0020}noise...\u{0020}Xixi,\u{0020}Yuanyuan,\u{0020}Lingling\u{0020}and\u{0020}everyone\u{0020}arguing\u{0020}early\u{0020}in\u{0020}the\u{0020}morning\u{0020}as\u{0020}if\u{0020}they\u{0020}were\u{0020}more\u{0020}excited\u{0020}than\u{0020}I\u{0020}was\u{0020}about\u{0020}how\u{0020}the\u{0020}day\u{0020}was\u{0020}going\u{0020}to\u{0020}go.\nSister\u{0020}Xixi\u{0020}wanted\u{0020}to\u{0020}spend\u{0020}the\u{0020}whole\u{0020}day\u{0020}on\u{0020}the\u{0020}roller\u{0020}coasters\u{0020}until\u{0020}she\u{0020}threw\u{0020}up;\u{0020}Sister\u{0020}Yuanyuan\u{0020}thought\u{0020}it\u{0020}would\u{0020}be\u{0020}better\u{0020}to\u{0020}find\u{0020}a\u{0020}library\u{0020}to\u{0020}immerse\u{0020}herself\u{0020}in;\u{0020}Sister\u{0020}Lingling\u{0020}seemed\u{0020}to\u{0020}be\u{0020}more\u{0020}interested\u{0020}in\u{0020}the\u{0020}aquarium.\u{0020}But\u{0020}Momo\u{0020}doesn't\u{0020}know\u{0020}how\u{0020}to\u{0020}divide\u{0020}herself,\u{0020}so\u{0020}how\u{0020}can\u{0020}she\u{0020}satisfy\u{0020}her\u{0020}sisters\u{0020}at\u{0020}the\u{0020}same\u{0020}time?\u{0020}For\u{0020}Momo\u{0020}herself...\u{0020}It\u{0020}doesn't\u{0020}matter\u{0020}where\u{0020}we\u{0020}go,\u{0020}as\u{0020}long\u{0020}as\u{0020}we\u{0020}have\u{0020}fun\u{0020}with\u{0020}the\u{0020}people\u{0020}we\u{0020}like.\nWonder\u{0020}if\u{0020}someone\u{0020}as\u{0020}smart\u{0020}as\u{0020}Navigator\u{0020}could\u{0020}come\u{0020}up\u{0020}with\u{0020}a\u{0020}perfect\u{0020}solution?\nIt\u{0020}occurred\u{0020}to\u{0020}us\u{0020}that\u{0020}\"Navigator\"\u{0020}and\u{0020}\"tour\u{0020}guide\"\u{0020}are\u{0020}somewhat\u{0020}similar\u{0020}in\u{0020}meaning.\u{0020}Can\u{0020}you\u{0020}take\u{0020}us\u{0020}out\u{0020}today?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200801] = {id = 11200801, name = "Baili\u{0020}Momo", head = "12008", type = 5, title = "The\u{0020}Birthday\u{0020}Dilemma!", txt = "Ugh,\u{0020}I'm\u{0020}so\u{0020}sleepy!\u{0020}I\u{0020}woke\u{0020}up\u{0020}before\u{0020}dawn\u{0020}today—not\u{0020}just\u{0020}because\u{0020}I'm\u{0020}excited\u{0020}about\u{0020}my\u{0020}birthday,\u{0020}but\u{0020}mostly\u{0020}because\u{0020}of\u{0020}the\u{0020}noise.\u{0020}Sis\u{0020}Qianqian,\u{0020}Sis\u{0020}Yuanyuan,\u{0020}and\u{0020}Sis\u{0020}Lingling\u{0020}couldn't\u{0020}wait\u{0020}to\u{0020}argue\u{0020}about\u{0020}how\u{0020}to\u{0020}spend\u{0020}the\u{0020}day.\nSis\u{0020}Qianqian\u{0020}wants\u{0020}to\u{0020}ride\u{0020}the\u{0020}roller\u{0020}coaster\u{0020}and\u{0020}won't\u{0020}stop\u{0020}until\u{0020}she\u{0020}does!\u{0020}Sis\u{0020}Yuanyuan\u{0020}insists\u{0020}on\u{0020}spending\u{0020}the\u{0020}day\u{0020}in\u{0020}a\u{0020}library,\u{0020}and\u{0020}Sis\u{0020}Lingling\u{0020}is\u{0020}all\u{0020}about\u{0020}the\u{0020}aquarium.\u{0020}But\u{0020}how\u{0020}am\u{0020}I\u{0020}supposed\u{0020}to\u{0020}be\u{0020}in\u{0020}three\u{0020}places\u{0020}at\u{0020}once?\u{0020}As\u{0020}for\u{0020}me…\u{0020}I\u{0020}don't\u{0020}mind\u{0020}where\u{0020}we\u{0020}go.\u{0020}As\u{0020}long\u{0020}as\u{0020}I'm\u{0020}with\u{0020}people\u{0020}I\u{0020}care\u{0020}about,\u{0020}I'm\u{0020}happy\u{0020}wherever\u{0020}we\u{0020}are.\nWhat\u{0020}do\u{0020}you\u{0020}think,\u{0020}Navigator?\u{0020}You're\u{0020}so\u{0020}clever—can\u{0020}you\u{0020}figure\u{0020}out\u{0020}a\u{0020}way\u{0020}to\u{0020}make\u{0020}everyone\u{0020}happy?\u{0020}After\u{0020}all,\u{0020}\"Navigator\"\u{0020}is\u{0020}kind\u{0020}of\u{0020}like\u{0020}a\u{0020}\"tour\u{0020}guide,\"\u{0020}right?\u{0020}Maybe\u{0020}you\u{0020}could\u{0020}take\u{0020}us\u{0020}on\u{0020}a\u{0020}perfect\u{0020}adventure\u{0020}today!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200802] = {id = 11200802, name = "Baili\u{0020}Momo", head = "12008", type = 5, title = "Birthday\u{0020}Operation!!", txt = "Good\u{0020}morning,\u{0020}Navigator!\u{0020}It's\u{0020}Momo's\u{0020}birthday\u{0020}again!\u{0020}But\u{0020}something\u{0020}strange\u{0020}happened\u{0020}today.\u{0020}Qianqian-nesan,\u{0020}Yuanyuan-nesan,\u{0020}and\u{0020}Lingling-nesan\u{0020}didn't\u{0020}argue\u{0020}at\u{0020}all.\u{0020}The\u{0020}sisters\u{0020}said\u{0020}that,\u{0020}thanks\u{0020}to\u{0020}last\u{0020}year's\u{0020}experience,\u{0020}they've\u{0020}decided\u{0020}to\u{0020}leave\u{0020}this\u{0020}year's\u{0020}birthday\u{0020}plans\u{0020}entirely\u{0020}up\u{0020}to\u{0020}you.\u{0020}After\u{0020}all,\u{0020}Navigator,\u{0020}you've\u{0020}seen\u{0020}the\u{0020}world\u{0020}-\u{0020}you're\u{0020}sure\u{0020}to\u{0020}come\u{0020}up\u{0020}with\u{0020}something\u{0020}that\u{0020}makes\u{0020}everyone\u{0020}happy!\u{0020}\nThat\u{0020}said,\u{0020}they\u{0020}asked\u{0020}me\u{0020}to\u{0020}pass\u{0020}along\u{0020}a\u{0020}few\u{0020}places\u{0020}they\u{0020}don't\u{0020}want\u{0020}to\u{0020}go.\u{0020}Qianqian-nesan\u{0020}says\u{0020}a\u{0020}birthday\u{0020}has\u{0020}to\u{0020}be\u{0020}lively,\u{0020}so\u{0020}she\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}go\u{0020}anywhere\u{0020}quiet\u{0020}like\u{0020}museums\u{0020}or\u{0020}libraries.\u{0020}Yuanyuan-nesan\u{0020}really\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}sweat,\u{0020}so\u{0020}please\u{0020}avoid\u{0020}activities\u{0020}like\u{0020}shopping\u{0020}trips\u{0020}or\u{0020}amusement\u{0020}parks.\u{0020}As\u{0020}for\u{0020}Lingling-nesan,\u{0020}she\u{0020}thinks\u{0020}I've\u{0020}gained\u{0020}a\u{0020}bit\u{0020}of\u{0020}weight\u{0020}lately,\u{0020}so\u{0020}she\u{0020}doesn't\u{0020}want\u{0020}me\u{0020}going\u{0020}to\u{0020}restaurants\u{0020}and\u{0020}eating\u{0020}too\u{0020}much…\u{0020}As\u{0020}for\u{0020}me…\u{0020}I\u{0020}think\u{0020}as\u{0020}long\u{0020}as\u{0020}I\u{0020}get\u{0020}to\u{0020}spend\u{0020}the\u{0020}day\u{0020}happily\u{0020}with\u{0020}the\u{0020}people\u{0020}I\u{0020}like,\u{0020}that's\u{0020}more\u{0020}than\u{0020}enough.\u{0020}\nSo,\u{0020}Navigator,\u{0020}have\u{0020}you\u{0020}thought\u{0020}about\u{0020}where\u{0020}we\u{0020}should\u{0020}go\u{0020}today?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112009] = {id = 112009, name = "Maria", head = "12009", type = 5, title = "孤獨的夜", txt = "近來可好，小弟弟。\n算起來我們已經有半年多沒有見面了吧，有沒有想我呀？\n\u{0020}寫這份信倒也不是有什麼大事，只是今天好像是我的生日。\n\u{0020}所謂生日，應該是值得慶祝的日子吧。可莉迪婭她們不知道去執行什麼任務了，雪鴞現在就留了我一人在，都沒人可以陪我開生日會了。\n這幾天卡佳的雪也是越下越大。在這樣寒冷寂寞的夜晚，不知哪位紳士可以給我一個溫暖的擁抱呢？小弟弟？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200901] = {id = 11200901, name = "Maria", head = "12009", type = 5, title = "A\u{0020}Lonely\u{0020}Night", txt = "How\u{0020}have\u{0020}you\u{0020}been,\u{0020}little\u{0020}guy?\nIt's\u{0020}been\u{0020}more\u{0020}than\u{0020}half\u{0020}a\u{0020}year\u{0020}since\u{0020}we\u{0020}last\u{0020}saw\u{0020}each\u{0020}other…\u{0020}Have\u{0020}you\u{0020}missed\u{0020}me?\nI'm\u{0020}not\u{0020}writing\u{0020}for\u{0020}any\u{0020}particular\u{0020}reason,\u{0020}just\u{0020}that\u{0020}today\u{0020}happens\u{0020}to\u{0020}be\u{0020}my\u{0020}birthday.\nBirthdays\u{0020}are\u{0020}supposed\u{0020}to\u{0020}be\u{0020}special,\u{0020}right?\u{0020}But\u{0020}Lydia\u{0020}and\u{0020}the\u{0020}others\u{0020}are\u{0020}off\u{0020}on\u{0020}some\u{0020}mission,\u{0020}and\u{0020}Snow\u{0020}Owl\u{0020}has\u{0020}left\u{0020}me\u{0020}here\u{0020}all\u{0020}alone.\u{0020}Looks\u{0020}like\u{0020}it'll\u{0020}be\u{0020}just\u{0020}me,\u{0020}spending\u{0020}the\u{0020}day\u{0020}without\u{0020}anyone\u{0020}to\u{0020}celebrate\u{0020}with.\nThe\u{0020}snow\u{0020}has\u{0020}been\u{0020}falling\u{0020}heavier\u{0020}here\u{0020}in\u{0020}Katya\u{0020}these\u{0020}past\u{0020}few\u{0020}days.\u{0020}On\u{0020}a\u{0020}cold,\u{0020}lonely\u{0020}night\u{0020}like\u{0020}this,\u{0020}I\u{0020}wonder…\u{0020}which\u{0020}gentleman\u{0020}might\u{0020}offer\u{0020}me\u{0020}a\u{0020}warm\u{0020}embrace?\u{0020}Little\u{0020}guy,\u{0020}perhaps?\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11200902] = {id = 11200902, name = "Maria", head = "12009", type = 5, title = "Give\u{0020}Me\u{0020}a\u{0020}Hug", txt = "Surprised?\u{0020}It's\u{0020}been\u{0020}a\u{0020}long\u{0020}time\u{0020}since\u{0020}I\u{0020}last\u{0020}wrote\u{0020}to\u{0020}you,\u{0020}little\u{0020}brother.\u{0020}The\u{0020}last\u{0020}time\u{0020}was\u{0020}a\u{0020}year\u{0020}ago...\u{0020}no\u{0020}more,\u{0020}no\u{0020}less.\u{0020}Exactly\u{0020}one\u{0020}year.\u{0020}You\u{0020}know\u{0020}what\u{0020}that\u{0020}means,\u{0020}don't\u{0020}you?\u{0020}\nThat's\u{0020}right,\u{0020}it's\u{0020}your\u{0020}big\u{0020}sister's\u{0020}birthday.\u{0020}And\u{0020}birthdays\u{0020}call\u{0020}for\u{0020}birthday\u{0020}gifts.\u{0020}As\u{0020}for\u{0020}what\u{0020}I\u{0020}want..\u{0020}\nI\u{0020}really,\u{0020}really,\u{0020}really\u{0020}want\u{0020}a\u{0020}big\u{0020}hug\u{0020}from\u{0020}you,\u{0020}little\u{0020}brother.\u{0020}\nBut\u{0020}I\u{0020}guess\u{0020}it's\u{0020}not\u{0020}possible\u{0020}right\u{0020}now.\u{0020}Your\u{0020}work\u{0020}as\u{0020}the\u{0020}Navigator\u{0020}must\u{0020}be\u{0020}incredibly\u{0020}busy,\u{0020}from\u{0020}morning\u{0020}till\u{0020}night.\u{0020}Dealing\u{0020}with\u{0020}Sin,\u{0020}managing\u{0020}the\u{0020}Drivers...\u{0020}it\u{0020}can't\u{0020}be\u{0020}easy.\u{0020}Causing\u{0020}you\u{0020}trouble\u{0020}at\u{0020}a\u{0020}time\u{0020}like\u{0020}this\u{0020}isn't\u{0020}what\u{0020}a\u{0020}proper\u{0020}big\u{0020}sister\u{0020}should\u{0020}do.\u{0020}But\u{0020}that\u{0020}doesn't\u{0020}mean\u{0020}I'm\u{0020}giving\u{0020}up.\u{0020}\nJust\u{0020}remember:\u{0020}you\u{0020}owe\u{0020}me\u{0020}a\u{0020}hug.\u{0020}Next\u{0020}time\u{0020}we\u{0020}meet,\u{0020}I'll\u{0020}be\u{0020}coming\u{0020}to\u{0020}collect.\u{0020}\nSo\u{0020}be\u{0020}ready,\u{0020}little\u{0020}brother...\u{0020}\u{0020}for\u{0020}a\u{0020}deadly\u{0020}hug\u{0020}from\u{0020}your\u{0020}older,\u{0020}slightly\u{0020}resentful\u{0020}big\u{0020}sister.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112010] = {id = 112010, name = "Meika", head = "12010", type = 5, title = "The\u{0020}Title...\u{0020}Whatever!", txt = "Ugh,\u{0020}what\u{0020}a\u{0020}hassle,\u{0020}it's\u{0020}that\u{0020}time\u{0020}again.\u{0020}My\u{0020}birthday.\u{0020}And\u{0020}of\u{0020}course,\u{0020}\"the\u{0020}other\u{0020}me\"\u{0020}is\u{0020}all\u{0020}set\u{0020}on\u{0020}celebrating.\u{0020}She\u{0020}doesn't\u{0020}seem\u{0020}to\u{0020}care\u{0020}about\u{0020}any\u{0020}other\u{0020}holidays,\u{0020}but\u{0020}this\u{0020}one?\u{0020}She's\u{0020}all\u{0020}in.\nOh!\u{0020}I\u{0020}get\u{0020}it.\u{0020}She's\u{0020}doing\u{0020}all\u{0020}this\u{0020}especially\u{0020}for\u{0020}me?\u{0020}Then,\u{0020}why\u{0020}not\u{0020}even\u{0020}say\u{0020}it\u{0020}straight?\u{0020}Hah,\u{0020}honestly,\u{0020}it's\u{0020}a\u{0020}little\u{0020}embarrassing\u{0020}but\u{0020}kind\u{0020}of\u{0020}funny\u{0020}at\u{0020}the\u{0020}same\u{0020}time.\nOh,\u{0020}and\u{0020}she\u{0020}mentioned\u{0020}she's\u{0020}preparing\u{0020}two\u{0020}cakes.\u{0020}I\u{0020}mean,\u{0020}one\u{0020}will\u{0020}do,\u{0020}right?\u{0020}We\u{0020}can\u{0020}use\u{0020}the\u{0020}other\u{0020}for\u{0020}a\u{0020}cake\u{0020}fight!\u{0020}Heh,\u{0020}you\u{0020}up\u{0020}for\u{0020}the\u{0020}challenge\u{0020}with\u{0020}the\u{0020}one\u{0020}with\u{0020}the\u{0020}undefeated\u{0020}record?\u{0020}Bring\u{0020}it\u{0020}on.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112011] = {id = 112011, name = "Samghrma", head = "12011", type = 5, title = "The\u{0020}Unknown\u{0020}Book", txt = "My\u{0020}\"birthday\"\u{0020}is\u{0020}not\u{0020}quite\u{0020}what\u{0020}people\u{0020}usually\u{0020}understand\u{0020}it\u{0020}to\u{0020}be.\u{0020}In\u{0020}fact,\u{0020}it\u{0020}refers\u{0020}to\u{0020}\"the\u{0020}day\u{0020}of\u{0020}survival\".\nI\u{0020}was\u{0020}fortunate\u{0020}enough\u{0020}to\u{0020}survive\u{0020}that\u{0020}disaster\u{0020}and\u{0020}grow\u{0020}into\u{0020}who\u{0020}I\u{0020}am\u{0020}today,\u{0020}and\u{0020}because\u{0020}of\u{0020}that,\u{0020}my\u{0020}birthday\u{0020}has\u{0020}taken\u{0020}on\u{0020}a\u{0020}unique\u{0020}meaning.\u{0020}It\u{0020}signifies\u{0020}the\u{0020}unpredictability\u{0020}of\u{0020}fate,\u{0020}while\u{0020}also\u{0020}symbolizing\u{0020}a\u{0020}certain\u{0020}kind\u{0020}of\u{0020}hope.\nToday,\u{0020}I\u{0020}want\u{0020}to\u{0020}try\u{0020}experiencing\u{0020}something\u{0020}new.\u{0020}I\u{0020}plan\u{0020}to\u{0020}search\u{0020}for\u{0020}a\u{0020}book\u{0020}in\u{0020}the\u{0020}library\u{0020}based\u{0020}on\u{0020}its\u{0020}call\u{0020}number:\u{0020}one\u{0020}whose\u{0020}publication\u{0020}date\u{0020}and\u{0020}additional\u{0020}number,\u{0020}when\u{0020}combined,\u{0020}produce\u{0020}a\u{0020}classification\u{0020}number\u{0020}that\u{0020}happens\u{0020}to\u{0020}match\u{0020}my\u{0020}birth\u{0020}date\u{0020}exactly.\u{0020}Although\u{0020}I\u{0020}have\u{0020}no\u{0020}way\u{0020}of\u{0020}knowing\u{0020}what\u{0020}kind\u{0020}of\u{0020}book\u{0020}it\u{0020}might\u{0020}be,\u{0020}or\u{0020}even\u{0020}whether\u{0020}such\u{0020}a\u{0020}coincidence\u{0020}truly\u{0020}exists,\u{0020}I\u{0020}still\u{0020}want\u{0020}to\u{0020}try\u{0020}finding\u{0020}it\u{0020}and\u{0020}then\u{0020}read\u{0020}it\u{0020}through\u{0020}to\u{0020}the\u{0020}end.\nIf\u{0020}this\u{0020}interests\u{0020}you\u{0020}as\u{0020}well,\u{0020}then\u{0020}come\u{0020}and\u{0020}read\u{0020}that\u{0020}fated\u{0020}book\u{0020}together\u{0020}with\u{0020}me.\u{0020}I\u{0020}will\u{0020}be\u{0020}waiting\u{0020}for\u{0020}you\u{0020}at\u{0020}the\u{0020}library\u{0020}we\u{0020}often\u{0020}visit.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112012] = {id = 112012, name = "Julia", head = "12012", type = 5, title = "Good\u{0020}News...\u{0020}or\u{0020}Bad?", txt = "Well\u{0020}well,\u{0020}it's\u{0020}been\u{0020}a\u{0020}while.\u{0020}How\u{0020}have\u{0020}you\u{0020}been,\u{0020}***?\nAh!\u{0020}Looks\u{0020}like\u{0020}AEGIS\u{0020}updated\u{0020}its\u{0020}word\u{0020}filters\u{0020}again.\u{0020}I\u{0020}can't\u{0020}type\u{0020}that\u{0020}name\u{0020}in\u{0020}emails\u{0020}anymore.\u{0020}But\u{0020}never\u{0020}mind.\u{0020}I'm\u{0020}sure\u{0020}you\u{0020}know\u{0020}exactly\u{0020}what\u{0020}nickname\u{0020}I\u{0020}always\u{0020}use\u{0020}for\u{0020}you.\u{0020}It's\u{0020}the\u{0020}thought\u{0020}that\u{0020}counts,\u{0020}isn't\u{0020}it?\nNow\u{0020}then,\u{0020}on\u{0020}to\u{0020}more\u{0020}important\u{0020}things.\u{0020}My\u{0020}most\u{0020}noble\u{0020}birthday\u{0020}has\u{0020}arrived,\u{0020}and\u{0020}at\u{0020}last,\u{0020}all\u{0020}the\u{0020}marvelous\u{0020}props\u{0020}my\u{0020}dear\u{0020}attendants\u{0020}have\u{0020}prepared\u{0020}will\u{0020}finally\u{0020}see\u{0020}some\u{0020}use.\u{0020}I\u{0020}do\u{0020}wonder...\u{0020}hasn't\u{0020}your\u{0020}day-to-day\u{0020}training\u{0020}in\u{0020}AEGIS\u{0020}grown\u{0020}a\u{0020}little\u{0020}dull?\u{0020}Well\u{0020}then,\u{0020}tremble\u{0020}with\u{0020}excitement.\u{0020}Scream,\u{0020}if\u{0020}you\u{0020}must.\nTonight,\u{0020}I'll\u{0020}give\u{0020}you\u{0020}something\u{0020}far\u{0020}more\u{0020}intense—an\u{0020}experience\u{0020}that\u{0020}will\u{0020}leave\u{0020}you\u{0020}breathless\u{0020}and\u{0020}shaken.\u{0020}Time\u{0020}waits\u{0020}for\u{0020}no\u{0020}one.\u{0020}You'd\u{0020}better\u{0020}get\u{0020}ready.\u{0020}Oh,\u{0020}and\u{0020}don't\u{0020}worry\u{0020}about\u{0020}medical\u{0020}supplies.\u{0020}I've\u{0020}already\u{0020}packed\u{0020}enough.\u{0020}No\u{0020}need\u{0020}to\u{0020}bring\u{0020}your\u{0020}own!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201201] = {id = 11201201, name = "Julia", head = "12012", type = 5, title = "Are\u{0020}You\u{0020}Brave\u{0020}Enough\u{0020}to\u{0020}Keep\u{0020}Our\u{0020}Date?", txt = "How\u{0020}many\u{0020}times\u{0020}do\u{0020}I\u{0020}have\u{0020}to\u{0020}catch\u{0020}Jenny\u{0020}Ross\u{0020}before\u{0020}that\u{0020}woman\u{0020}gives\u{0020}up\u{0020}on\u{0020}her\u{0020}investigation?\u{0020}Even\u{0020}I\u{0020}cannot\u{0020}help\u{0020}admiring\u{0020}her\u{0020}nerve.\nThis\u{0020}time,\u{0020}though,\u{0020}she\u{0020}said\u{0020}it\u{0020}was\u{0020}the\u{0020}Navigator\u{0020}-\u{0020}that\u{0020}you\u{0020}were\u{0020}the\u{0020}one\u{0020}who\u{0020}sent\u{0020}her\u{0020}to\u{0020}investigate,\u{0020}idiot,\u{0020}because\u{0020}you\u{0020}wanted\u{0020}to\u{0020}prepare\u{0020}some\u{0020}kind\u{0020}of\u{0020}birthday\u{0020}gift...\nWhat,\u{0020}even\u{0020}my\u{0020}idiot\u{0020}is\u{0020}curious\u{0020}about\u{0020}my\u{0020}background\u{0020}now?\nHehe.\u{0020}If\u{0020}you\u{0020}are\u{0020}willing\u{0020}to\u{0020}kneel\u{0020}down\u{0020}and\u{0020}lick\u{0020}my\u{0020}toes,\u{0020}I\u{0020}would\u{0020}not\u{0020}mind\u{0020}telling\u{0020}my\u{0020}idiot\u{0020}a\u{0020}few\u{0020}secrets\u{0020}that\u{0020}have\u{0020}never\u{0020}been\u{0020}made\u{0020}public.\nI\u{0020}will\u{0020}be\u{0020}waiting\u{0020}in\u{0020}my\u{0020}room\u{0020}tonight.\u{0020}Do\u{0020}not\u{0020}be\u{0020}a\u{0020}cowardly\u{0020}little\u{0020}pig,\u{0020}Navi--gator.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112013] = {id = 112013, name = "Karen", head = "12013", type = 5, title = "來自學生的問候以及......", txt = "老師，許久不見，甚是想念。\n今天是我的生日，原本想和同學一同出門到街上的餐館慶祝，但是撒哈拉正值雨季，路面都是積水，出門用餐多少有些不便。不得已只能留在宿舍用昨天晚飯留下的小蛋糕稍作慶祝。\n百無聊賴之下，忽想起老師。聽聞老師在薩爾一戰中擊敗了准罪級原罪取得大捷，正巧這學期有門原罪學的課程。不知老師最近是否有空，我想就有關准罪級的事向您討教些許。\n擇日不如撞日，不如我現在就去購買到多瑙的機票，老師意下如何呢？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201301] = {id = 11201301, name = "Karen", head = "12013", type = 5, title = "A\u{0020}Greeting\u{0020}from\u{0020}Your\u{0020}Student\u{0020}and...", txt = "Professor,\u{0020}it's\u{0020}been\u{0020}far\u{0020}too\u{0020}long\u{0020}—\u{0020}I\u{0020}hope\u{0020}you're\u{0020}doing\u{0020}well.\nToday\u{0020}happens\u{0020}to\u{0020}be\u{0020}my\u{0020}birthday.\u{0020}I\u{0020}had\u{0020}intended\u{0020}to\u{0020}celebrate\u{0020}it\u{0020}with\u{0020}some\u{0020}classmates\u{0020}at\u{0020}a\u{0020}restaurant,\u{0020}but\u{0020}with\u{0020}the\u{0020}rainy\u{0020}season\u{0020}in\u{0020}full\u{0020}swing\u{0020}here\u{0020}in\u{0020}the\u{0020}Sahara,\u{0020}the\u{0020}streets\u{0020}are\u{0020}flooded,\u{0020}making\u{0020}it\u{0020}a\u{0020}bit\u{0020}too\u{0020}inconvenient\u{0020}to\u{0020}go\u{0020}out.\u{0020}So,\u{0020}I\u{0020}ended\u{0020}up\u{0020}staying\u{0020}in\u{0020}the\u{0020}dorm,\u{0020}celebrating\u{0020}with\u{0020}a\u{0020}small\u{0020}piece\u{0020}of\u{0020}cake\u{0020}leftover\u{0020}from\u{0020}last\u{0020}night's\u{0020}dinner.\nWith\u{0020}nothing\u{0020}much\u{0020}to\u{0020}do,\u{0020}I\u{0020}found\u{0020}myself\u{0020}thinking\u{0020}of\u{0020}you.\u{0020}I\u{0020}heard\u{0020}about\u{0020}your\u{0020}impressive\u{0020}victory\u{0020}in\u{0020}the\u{0020}Battle\u{0020}of\u{0020}Saar,\u{0020}where\u{0020}you\u{0020}defeated\u{0020}a\u{0020}Major\u{0020}Sin\u{0020}—\u{0020}truly\u{0020}a\u{0020}remarkable\u{0020}feat!\u{0020}Coincidentally,\u{0020}I'm\u{0020}taking\u{0020}a\u{0020}course\u{0020}on\u{0020}Sins\u{0020}this\u{0020}semester,\u{0020}and\u{0020}I\u{0020}was\u{0020}hoping\u{0020}you\u{0020}might\u{0020}have\u{0020}some\u{0020}time\u{0020}to\u{0020}share\u{0020}your\u{0020}insights\u{0020}on\u{0020}the\u{0020}subject,\u{0020}especially\u{0020}when\u{0020}it\u{0020}comes\u{0020}to\u{0020}Major\u{0020}Sins.\nWhy\u{0020}wait\u{0020}for\u{0020}a\u{0020}better\u{0020}time?\u{0020}How\u{0020}about\u{0020}I\u{0020}go\u{0020}ahead\u{0020}and\u{0020}book\u{0020}a\u{0020}flight\u{0020}to\u{0020}Danube\u{0020}now?\u{0020}What\u{0020}do\u{0020}you\u{0020}think,\u{0020}Professor?\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201302] = {id = 11201302, name = "Karen", head = "12013", type = 5, title = "May\u{0020}Heroes\u{0020}Be\u{0020}Immortal", txt = "Sensei,\u{0020}please\u{0020}forgive\u{0020}the\u{0020}interruption.\u{0020}\nToday\u{0020}is\u{0020}my\u{0020}birthday,\u{0020}and\u{0020}for\u{0020}some\u{0020}reason,\u{0020}you\u{0020}were\u{0020}the\u{0020}first\u{0020}person\u{0020}I\u{0020}thought\u{0020}of.\u{0020}Perhaps\u{0020}it's\u{0020}because\u{0020}I've\u{0020}been\u{0020}studying\u{0020}materials\u{0020}about\u{0020}battles\u{0020}against\u{0020}Sin\u{0020}lately,\u{0020}and\u{0020}in\u{0020}them\u{0020}I\u{0020}kept\u{0020}seeing\u{0020}your\u{0020}figure,\u{0020}over\u{0020}and\u{0020}over,\u{0020}filling\u{0020}page\u{0020}after\u{0020}page.\u{0020}You've\u{0020}taken\u{0020}part\u{0020}in\u{0020}battles\u{0020}big\u{0020}and\u{0020}small,\u{0020}saving\u{0020}countless\u{0020}people\u{0020}from\u{0020}beneath\u{0020}Sin's\u{0020}feet.\u{0020}To\u{0020}me,\u{0020}you\u{0020}are\u{0020}the\u{0020}\"hero\"\u{0020}I've\u{0020}always\u{0020}looked\u{0020}up\u{0020}to.\u{0020}Always.\u{0020}\nIf\u{0020}I\u{0020}could\u{0020}share\u{0020}the\u{0020}joy\u{0020}of\u{0020}my\u{0020}birthday\u{0020}with\u{0020}a\u{0020}hero\u{0020}like\u{0020}you,\u{0020}then\u{0020}I\u{0020}could\u{0020}even\u{0020}say\u{0020}I'd\u{0020}have\u{0020}no\u{0020}regrets\u{0020}if\u{0020}I\u{0020}died.\u{0020}No...\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}die...\u{0020}and\u{0020}please,\u{0020}Sensei,\u{0020}don't\u{0020}die\u{0020}so\u{0020}easily\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}either...\u{0020}\nYes.\u{0020}That\u{0020}is\u{0020}my\u{0020}birthday\u{0020}wish:\u{0020}May\u{0020}all\u{0020}heroes\u{0020}who\u{0020}fight\u{0020}for\u{0020}humanity\u{0020}overcome\u{0020}every\u{0020}hardship\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}and\u{0020}survive\u{0020}frightened,\u{0020}perhaps,\u{0020}but\u{0020}unharmed.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112014] = {id = 112014, name = "Cephalis", head = "12014", type = 5, title = "Can\u{0020}you\u{0020}see\u{0020}the\u{0020}stars?", txt = "The\u{0020}star\u{0020}at\u{0020}06h45m08.9173s\u{0020}RA\u{0020}and\u{0020}-16d42m58.017s\u{0020}Dec\u{0020}begin\u{0020}to\u{0020}shine\u{0020}again.\nAccording\u{0020}to\u{0020}the\u{0020}people\u{0020}here,\u{0020}this\u{0020}means\u{0020}that\u{0020}my\u{0020}birthday\u{0020}is\u{0020}coming.\u{0020}I\u{0020}still\u{0020}remember\u{0020}when\u{0020}I\u{0020}first\u{0020}looked\u{0020}up\u{0020}at\u{0020}the\u{0020}shining\u{0020}star\u{0020}after\u{0020}being\u{0020}born\u{0020}on\u{0020}Earth.\u{0020}It\u{0020}was\u{0020}the\u{0020}brightest\u{0020}and\u{0020}most\u{0020}beautiful\u{0020}star\u{0020}I\u{0020}had\u{0020}ever\u{0020}seen.\u{0020}If\u{0020}there\u{0020}were\u{0020}no\u{0020}Sin,\u{0020}I'd\u{0020}travel\u{0020}there\u{0020}in\u{0020}a\u{0020}spaceship,\u{0020}but\u{0020}sadly,\u{0020}I\u{0020}can't.\nIn\u{0020}reality,\u{0020}the\u{0020}shining\u{0020}of\u{0020}the\u{0020}stars\u{0020}is\u{0020}not\u{0020}always\u{0020}a\u{0020}good\u{0020}thing,\u{0020}often\u{0020}meaning\u{0020}the\u{0020}death\u{0020}of\u{0020}a\u{0020}star.\u{0020}But\u{0020}then,\u{0020}it\u{0020}can\u{0020}also\u{0020}be\u{0020}the\u{0020}birth\u{0020}of\u{0020}a\u{0020}new\u{0020}one.\u{0020}Death\u{0020}and\u{0020}new\u{0020}life\u{0020}are\u{0020}always\u{0020}present\u{0020}at\u{0020}the\u{0020}same\u{0020}time\u{0020}in\u{0020}the\u{0020}universe,\u{0020}so\u{0020}is\u{0020}it\u{0020}possible\u{0020}that\u{0020}a\u{0020}new\u{0020}star\u{0020}was\u{0020}born\u{0020}at\u{0020}the\u{0020}same\u{0020}time\u{0020}as\u{0020}Midyr's\u{0020}destruction?\u{0020}I\u{0020}hear\u{0020}that\u{0020}it's\u{0020}tradition\u{0020}to\u{0020}make\u{0020}a\u{0020}wish\u{0020}on\u{0020}an\u{0020}Earth\u{0020}birthday.\u{0020}Then\u{0020}my\u{0020}birthday\u{0020}wish\u{0020}will\u{0020}be\u{0020}to\u{0020}find\u{0020}the\u{0020}star\u{0020}that\u{0020}was\u{0020}reborn\u{0020}in\u{0020}the\u{0020}midst\u{0020}of\u{0020}destruction\u{0020}someday.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201401] = {id = 11201401, name = "Cephalis", head = "12014", type = 5, title = "Do\u{0020}You\u{0020}See\u{0020}That\u{0020}Dazzling\u{0020}Star?", txt = "Coordinates:\u{0020}right\u{0020}ascension\u{0020}06h\u{0020}45m\u{0020}08.9173s,\u{0020}declination\u{0020}-16.716116.\u{0020}That\u{0020}star\u{0020}has\u{0020}started\u{0020}to\u{0020}shine\u{0020}again.\nAccording\u{0020}to\u{0020}them,\u{0020}that\u{0020}marks\u{0020}the\u{0020}arrival\u{0020}of\u{0020}my\u{0020}birthday.\nI\u{0020}still\u{0020}remember\u{0020}the\u{0020}first\u{0020}star\u{0020}I\u{0020}saw\u{0020}after\u{0020}being\u{0020}reborn\u{0020}on\u{0020}Earth.\u{0020}It\u{0020}was\u{0020}the\u{0020}brightest,\u{0020}most\u{0020}beautiful\u{0020}light\u{0020}I’d\u{0020}ever\u{0020}seen.\u{0020}If\u{0020}not\u{0020}for\u{0020}the\u{0020}Sin,\u{0020}I\u{0020}might\u{0020}have\u{0020}boarded\u{0020}a\u{0020}ship\u{0020}and\u{0020}traveled\u{0020}there\u{0020}myself.\u{0020}But\u{0020}alas,\u{0020}that\u{0020}wouldn't\u{0020}happen.\u{0020}At\u{0020}least\u{0020}for\u{0020}now.\nStill,\u{0020}such\u{0020}a\u{0020}dazzling\u{0020}light\u{0020}isn’t\u{0020}always\u{0020}a\u{0020}good\u{0020}omen.\u{0020}It\u{0020}often\u{0020}signals\u{0020}a\u{0020}star's\u{0020}demise...\u{0020}or\u{0020}the\u{0020}birth\u{0020}of\u{0020}a\u{0020}new\u{0020}one.\u{0020}Death\u{0020}and\u{0020}birth\u{0020}walk\u{0020}hand\u{0020}in\u{0020}hand\u{0020}in\u{0020}the\u{0020}cosmos.\u{0020}So\u{0020}perhaps,\u{0020}as\u{0020}Midiel\u{0020}fell\u{0020}apart,\u{0020}there\u{0020}was\u{0020}another\u{0020}newborn\u{0020}world.\nI’ve\u{0020}heard\u{0020}Earthlings\u{0020}make\u{0020}wishes\u{0020}on\u{0020}their\u{0020}birthdays.\u{0020}If\u{0020}I\u{0020}could\u{0020}have\u{0020}one\u{0020}wish,\u{0020}it\u{0020}would\u{0020}be\u{0020}to\u{0020}find\u{0020}that\u{0020}one\u{0020}star\u{0020}reborn\u{0020}from\u{0020}ruin\u{0020}in\u{0020}my\u{0020}life.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201402] = {id = 11201402, name = "Cephalis", head = "12014", type = 5, title = "A\u{0020}Wonderful\u{0020}Dream", txt = "Last\u{0020}night,\u{0020}I\u{0020}had\u{0020}a\u{0020}wonderful\u{0020}dream.\nIn\u{0020}the\u{0020}dream,\u{0020}I\u{0020}woke\u{0020}up\u{0020}in\u{0020}the\u{0020}sky,\u{0020}but\u{0020}I\u{0020}did\u{0020}not\u{0020}feel\u{0020}like\u{0020}I\u{0020}was\u{0020}falling.\u{0020}Instead,\u{0020}I\u{0020}was\u{0020}floating\u{0020}in\u{0020}the\u{0020}air\u{0020}as\u{0020}if\u{0020}I\u{0020}were\u{0020}in\u{0020}water.\u{0020}Before\u{0020}my\u{0020}eyes\u{0020}was\u{0020}a\u{0020}mysterious\u{0020}planet.\u{0020}It\u{0020}was\u{0020}definitely\u{0020}not\u{0020}Midyr,\u{0020}and\u{0020}certainly\u{0020}not\u{0020}Earth.\nOn\u{0020}that\u{0020}planet,\u{0020}I\u{0020}saw\u{0020}many\u{0020}incredible\u{0020}things.\u{0020}I\u{0020}saw\u{0020}wind\u{0020}running\u{0020}through\u{0020}water,\u{0020}purple\u{0020}flowers\u{0020}blooming\u{0020}into\u{0020}flocks\u{0020}of\u{0020}birds\u{0020}that\u{0020}preyed\u{0020}upon\u{0020}the\u{0020}clouds,\u{0020}distant\u{0020}mountains\u{0020}slowly\u{0020}wriggling\u{0020}toward\u{0020}the\u{0020}east,\u{0020}and\u{0020}volcanoes\u{0020}erupting\u{0020}with\u{0020}six\u{0020}waterfalls\u{0020}that\u{0020}converged\u{0020}in\u{0020}low\u{0020}orbit\u{0020}before\u{0020}flying\u{0020}into\u{0020}the\u{0020}depths\u{0020}of\u{0020}space...\nStrangely,\u{0020}even\u{0020}though\u{0020}everything\u{0020}before\u{0020}my\u{0020}eyes\u{0020}made\u{0020}no\u{0020}logical\u{0020}sense,\u{0020}I\u{0020}could\u{0020}still\u{0020}feel\u{0020}joy\u{0020}from\u{0020}it.\u{0020}It\u{0020}seemed\u{0020}as\u{0020}if\u{0020}they\u{0020}were\u{0020}blessing\u{0020}me,\u{0020}celebrating\u{0020}the\u{0020}arrival\u{0020}of\u{0020}some\u{0020}important\u{0020}day.\nHowever,\u{0020}even\u{0020}now,\u{0020}I\u{0020}still\u{0020}cannot\u{0020}think\u{0020}of\u{0020}any\u{0020}holiday\u{0020}worthy\u{0020}of\u{0020}such\u{0020}a\u{0020}celebration.\u{0020}Navigator,\u{0020}would\u{0020}you\u{0020}happen\u{0020}to\u{0020}know?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112015] = {id = 112015, name = "Vesper", head = "12015", type = 5, title = "Beneath\u{0020}the\u{0020}Pleasant\u{0020}Autumn\u{0020}Scenery", txt = "September\u{0020}in\u{0020}Danube\u{0020}is\u{0020}here\u{0020}again.\u{0020}The\u{0020}autumn\u{0020}breeze\u{0020}carries\u{0020}a\u{0020}gentle\u{0020}chill,\u{0020}painting\u{0020}the\u{0020}deciduous\u{0020}trees\u{0020}in\u{0020}dazzling\u{0020}hues.\nSuch\u{0020}scenery\u{0020}always\u{0020}delights\u{0020}me.\u{0020}Not\u{0020}just\u{0020}because\u{0020}of\u{0020}the\u{0020}legends\u{0020}of\u{0020}the\u{0020}Autumn\u{0020}Goddess\u{0020}I\u{0020}read\u{0020}as\u{0020}a\u{0020}child,\u{0020}but\u{0020}because\u{0020}this\u{0020}harmony\u{0020}of\u{0020}colors;\u{0020}each\u{0020}shade\u{0020}is\u{0020}indispensable,\u{0020}woven\u{0020}together\u{0020}to\u{0020}create\u{0020}a\u{0020}wonder.\nAnd\u{0020}so,\u{0020}I\u{0020}earnestly\u{0020}hope\u{0020}that\u{0020}tonight's\u{0020}birthday\u{0020}banquet\u{0020}will\u{0020}be\u{0020}one\u{0020}where\u{0020}nobles\u{0020}old\u{0020}and\u{0020}new,\u{0020}commoners\u{0020}and\u{0020}elites\u{0020}alike,\u{0020}might\u{0020}set\u{0020}aside\u{0020}their\u{0020}prejudices,\u{0020}sharing\u{0020}bountiful\u{0020}fine\u{0020}wine\u{0020}and\u{0020}delicacies\u{0020}in\u{0020}season\u{0020}together...\u{0020}Perhaps\u{0020}that's\u{0020}too\u{0020}idealistic.\u{0020}And\u{0020}that's\u{0020}why\u{0020}I\u{0020}need\u{0020}to\u{0020}take\u{0020}every\u{0020}opportunity\u{0020}to\u{0020}step\u{0020}forward\u{0020}and\u{0020}eventually,\u{0020}every\u{0020}distant\u{0020}goal,\u{0020}I\u{0020}believe,\u{0020}will\u{0020}be\u{0020}achieved.\nI\u{0020}trust\u{0020}you,\u{0020}Navigator,\u{0020}will\u{0020}lose\u{0020}yourself\u{0020}in\u{0020}such\u{0020}a\u{0020}reverie\u{0020}as\u{0020}well?\u{0020}I\u{0020}shall\u{0020}await\u{0020}your\u{0020}arrival\u{0020}with\u{0020}grace\u{0020}as\u{0020}always.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201501] = {id = 11201501, name = "Vesper", head = "12015", type = 5, title = "Please\u{0020}Hear\u{0020}Me", txt = "I\u{0020}always\u{0020}keep\u{0020}my\u{0020}gaze\u{0020}fixed\u{0020}on\u{0020}the\u{0020}future,\u{0020}planning\u{0020}and\u{0020}constantly\u{0020}adjusting\u{0020}every\u{0020}step\u{0020}I\u{0020}take\u{0020}toward\u{0020}it.\u{0020}Yet\u{0020}in\u{0020}my\u{0020}current\u{0020}plans,\u{0020}there\u{0020}is\u{0020}still\u{0020}no\u{0020}place\u{0020}for\u{0020}you.\nLet\u{0020}the\u{0020}hazy\u{0020}lights\u{0020}of\u{0020}the\u{0020}evening\u{0020}party\u{0020}remain\u{0020}in\u{0020}the\u{0020}distance.\u{0020}For\u{0020}this\u{0020}moment\u{0020}alone,\u{0020}I\u{0020}wish\u{0020}to\u{0020}invite\u{0020}you\u{0020}into\u{0020}my\u{0020}garden.\nPerhaps\u{0020}one\u{0020}day\u{0020}we\u{0020}will\u{0020}stand\u{0020}on\u{0020}opposite\u{0020}sides.\u{0020}But\u{0020}before\u{0020}our\u{0020}relationship\u{0020}turns\u{0020}openly\u{0020}hostile\u{0020}and\u{0020}we\u{0020}stand\u{0020}with\u{0020}swords\u{0020}drawn--I\u{0020}would\u{0020}rather\u{0020}reveal\u{0020}these\u{0020}feelings\u{0020}first.\n\u{0020}It\u{0020}is\u{0020}enough\u{0020}that\u{0020}my\u{0020}thoughts,\u{0020}wishes,\u{0020}and\u{0020}feelings\u{0020}existed\u{0020}in\u{0020}this\u{0020}moment.\u{0020}Please\u{0020}hear\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112016] = {id = 112016, name = "Salati", head = "12016", type = 5, title = "可以陪我去聽音樂會嗎？", txt = "今天晚上有空嗎？我手上有兩張音樂會的門票，想請navigator一同去欣賞。\n時間是晚上六點，地點是在多瑙方舟附近的大歌劇院，離你那裡應該很近。\n這場音樂會我期待已久，因為這是該樂團今年的第一場演奏，也是他們新編曲的首次展示。還有那位被譽為“九州最年輕音樂家”的大師作為嘉賓出演。\n這實在太令人激動了，聽說許多音樂界的大亨都為了這音樂會的門票搶破了頭。要不是因為我生日，我也不可能能拿到這兩張門票。\n所以一定要珍惜這個機會哦，navigator。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201601] = {id = 11201601, name = "Salati", head = "12016", type = 5, title = "Will\u{0020}You\u{0020}Join\u{0020}Me\u{0020}for\u{0020}the\u{0020}Concert?", txt = "Got\u{0020}plans\u{0020}for\u{0020}tonight?\u{0020}I've\u{0020}got\u{0020}two\u{0020}tickets\u{0020}to\u{0020}a\u{0020}concert\u{0020}and\u{0020}would\u{0020}love\u{0020}for\u{0020}you\u{0020}to\u{0020}join\u{0020}me.\nIt's\u{0020}at\u{0020}the\u{0020}Grand\u{0020}Opera\u{0020}House\u{0020}near\u{0020}the\u{0020}Danube\u{0020}Ark,\u{0020}starting\u{0020}at\u{0020}6\u{0020}PM\u{0020}—\u{0020}should\u{0020}be\u{0020}close\u{0020}to\u{0020}you.\nI've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}this\u{0020}concert\u{0020}for\u{0020}ages!\u{0020}It's\u{0020}the\u{0020}orchestra's\u{0020}first\u{0020}performance\u{0020}of\u{0020}the\u{0020}year\u{0020}and\u{0020}will\u{0020}feature\u{0020}their\u{0020}new\u{0020}arrangements.\u{0020}Plus,\u{0020}the\u{0020}guest\u{0020}performer\u{0020}is\u{0020}the\u{0020}\"youngest\u{0020}musical\u{0020}prodigy\u{0020}in\u{0020}Kyushu.\"\nI'm\u{0020}beyond\u{0020}excited!\u{0020}Word\u{0020}has\u{0020}it\u{0020}that\u{0020}the\u{0020}tickets\u{0020}were\u{0020}so\u{0020}sought-after,\u{0020}music\u{0020}moguls\u{0020}were\u{0020}fighting\u{0020}for\u{0020}them.\u{0020}Honestly,\u{0020}if\u{0020}it\u{0020}wasn't\u{0020}for\u{0020}my\u{0020}birthday,\u{0020}I\u{0020}never\u{0020}would've\u{0020}been\u{0020}able\u{0020}to\u{0020}get\u{0020}my\u{0020}hands\u{0020}on\u{0020}these\u{0020}two.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201602] = {id = 11201602, name = "Salati", head = "12016", type = 5, title = "Birthday\u{0020}Song", txt = "Navigator,\u{0020}are\u{0020}you\u{0020}home\u{0020}today?\u{0020}There's\u{0020}a\u{0020}song\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}listen\u{0020}to.\u{0020}\nIt's\u{0020}a\u{0020}new\u{0020}song\u{0020}I\u{0020}wrote\u{0020}recently,\u{0020}something\u{0020}I\u{0020}happened\u{0020}to\u{0020}receive\u{0020}when\u{0020}a\u{0020}shooting\u{0020}star\u{0020}streaked\u{0020}across\u{0020}a\u{0020}dark\u{0020}night.\u{0020}\nAs\u{0020}it\u{0020}cut\u{0020}through\u{0020}the\u{0020}night\u{0020}sky,\u{0020}its\u{0020}brilliant\u{0020}tail\u{0020}flame\u{0020}tore\u{0020}open\u{0020}the\u{0020}silence,\u{0020}lighting\u{0020}up\u{0020}the\u{0020}heavens,\u{0020}and\u{0020}lighting\u{0020}up\u{0020}my\u{0020}eyes\u{0020}as\u{0020}well.\u{0020}Brief,\u{0020}yet\u{0020}dazzling,\u{0020}it\u{0020}felt\u{0020}as\u{0020}though\u{0020}I\u{0020}heard\u{0020}the\u{0020}strings\u{0020}of\u{0020}the\u{0020}universe\u{0020}being\u{0020}softly\u{0020}plucked,\u{0020}and\u{0020}the\u{0020}most\u{0020}radiant\u{0020}note\u{0020}of\u{0020}all\u{0020}was\u{0020}shining\u{0020}right\u{0020}before\u{0020}me.\u{0020}\nLife\u{0020}dances\u{0020}with\u{0020}music,\u{0020}and\u{0020}it\u{0020}can't\u{0020}help\u{0020}but\u{0020}make\u{0020}one\u{0020}think\u{0020}of\u{0020}the\u{0020}connection\u{0020}between\u{0020}the\u{0020}birth\u{0020}of\u{0020}life\u{0020}and\u{0020}the\u{0020}birth\u{0020}of\u{0020}the\u{0020}universe.\u{0020}Life\u{0020}is\u{0020}a\u{0020}miracle\u{0020}as\u{0020}great\u{0020}as\u{0020}the\u{0020}universe\u{0020}itself.\u{0020}I\u{0020}wrote\u{0020}down\u{0020}the\u{0020}melody\u{0020}and\u{0020}the\u{0020}emotion\u{0020}of\u{0020}that\u{0020}moment,\u{0020}a\u{0020}song\u{0020}about\u{0020}the\u{0020}birth\u{0020}of\u{0020}life.\u{0020}\nAnd\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday.\u{0020}I\u{0020}can't\u{0020}think\u{0020}of\u{0020}a\u{0020}more\u{0020}fitting\u{0020}day\u{0020}than\u{0020}this\u{0020}to\u{0020}listen\u{0020}to\u{0020}it.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112018] = {id = 112018, name = "Shisha", head = "12018", type = 5, title = "The\u{0020}Promised\u{0020}Day", txt = "The\u{0020}weather\u{0020}is\u{0020}nice\u{0020}today.\u{0020}Would\u{0020}you\u{0020}like\u{0020}to\u{0020}go\u{0020}for\u{0020}a\u{0020}walk\u{0020}together?\u{0020}I\u{0020}recently\u{0020}found\u{0020}a\u{0020}new\u{0020}cafe,\u{0020}but\u{0020}the\u{0020}best\u{0020}thing\u{0020}they\u{0020}serve\u{0020}is\u{0020}not\u{0020}the\u{0020}coffee\u{0020}-\u{0020}it\u{0020}is\u{0020}the\u{0020}fried\u{0020}pork\u{0020}cutlet.\u{0020}Strange\u{0020}for\u{0020}a\u{0020}cafe\u{0020}to\u{0020}serve\u{0020}pork\u{0020}cutlets,\u{0020}isn't\u{0020}it?\u{0020}They\u{0020}really\u{0020}are\u{0020}delicious,\u{0020}though.\nAfter\u{0020}we\u{0020}finish\u{0020}our\u{0020}coffee\u{0020}and\u{0020}pork\u{0020}cutlets,\u{0020}we\u{0020}can\u{0020}take\u{0020}a\u{0020}walk\u{0020}through\u{0020}the\u{0020}nearby\u{0020}park\u{0020}and\u{0020}enjoy\u{0020}the\u{0020}sun.\u{0020}But\u{0020}it\u{0020}is\u{0020}so\u{0020}hot\u{0020}that\u{0020}we\u{0020}probably\u{0020}should\u{0020}not\u{0020}stay\u{0020}outside\u{0020}for\u{0020}too\u{0020}long,\u{0020}or\u{0020}we\u{0020}might\u{0020}get\u{0020}heatstroke.\nI\u{0020}heard\u{0020}there\u{0020}will\u{0020}be\u{0020}a\u{0020}fireworks\u{0020}display\u{0020}tonight,\u{0020}near\u{0020}a\u{0020}cable-stayed\u{0020}bridge\u{0020}I\u{0020}have\u{0020}always\u{0020}wanted\u{0020}to\u{0020}visit.\nWe\u{0020}can\u{0020}enjoy\u{0020}the\u{0020}fireworks\u{0020}and\u{0020}study\u{0020}the\u{0020}bridge's\u{0020}structure\u{0020}at\u{0020}the\u{0020}same\u{0020}time.\u{0020}It\u{0020}is\u{0020}rare\u{0020}to\u{0020}find\u{0020}an\u{0020}opportunity\u{0020}that\u{0020}offers\u{0020}the\u{0020}best\u{0020}of\u{0020}both\u{0020}worlds,\u{0020}so\u{0020}we\u{0020}should\u{0020}make\u{0020}the\u{0020}most\u{0020}of\u{0020}it.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11201901] = {id = 11201901, name = "Caitlin", head = "12019", type = 5, title = "Hunting", txt = "Got\u{0020}some\u{0020}free\u{0020}time?\u{0020}Come\u{0020}take\u{0020}a\u{0020}walk\u{0020}in\u{0020}the\u{0020}suburbs\u{0020}with\u{0020}me,\u{0020}consider\u{0020}it\u{0020}my\u{0020}birthday\u{0020}treat.\u{0020}\nI\u{0020}heard\u{0020}there's\u{0020}a\u{0020}forest\u{0020}on\u{0020}the\u{0020}outskirts\u{0020}where\u{0020}wild\u{0020}boars\u{0020}have\u{0020}been\u{0020}running\u{0020}rampant\u{0020}lately,\u{0020}attacking\u{0020}quite\u{0020}a\u{0020}few\u{0020}campers.\u{0020}Perfect\u{0020}for\u{0020}target\u{0020}practice\u{0020}to\u{0020}sharpen\u{0020}our\u{0020}shooting\u{0020}skills.\u{0020}\nRemember\u{0020}to\u{0020}bring\u{0020}your\u{0020}gun.\u{0020}If\u{0020}you\u{0020}don't\u{0020}have\u{0020}one,\u{0020}I\u{0020}can\u{0020}lend\u{0020}you\u{0020}a\u{0020}few.\u{0020}Do\u{0020}you\u{0020}prefer\u{0020}automatic\u{0020}rifles\u{0020}or\u{0020}sniper\u{0020}rifles?\u{0020}I've\u{0020}got\u{0020}handguns\u{0020}too,\u{0020}but\u{0020}they're\u{0020}custom\u{0020}models—powerful,\u{0020}though\u{0020}they\u{0020}might\u{0020}be\u{0020}a\u{0020}bit\u{0020}tricky\u{0020}for\u{0020}you\u{0020}to\u{0020}handle.\u{0020}Wild\u{0020}boars\u{0020}are\u{0020}tough-skinned\u{0020}and\u{0020}thick-bodied;\u{0020}only\u{0020}an\u{0020}enhanced\u{0020}handgun\u{0020}can\u{0020}take\u{0020}them\u{0020}down\u{0020}with\u{0020}one\u{0020}shot.\u{0020}If\u{0020}you're\u{0020}confident\u{0020}in\u{0020}your\u{0020}aim,\u{0020}you\u{0020}could\u{0020}try\u{0020}targeting\u{0020}a\u{0020}vital\u{0020}spot\u{0020}for\u{0020}a\u{0020}clean\u{0020}headshot.\u{0020}\nWith\u{0020}Navigator's\u{0020}assistance,\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}might\u{0020}just\u{0020}solve\u{0020}the\u{0020}local\u{0020}ecological\u{0020}problem\u{0020}today.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112020] = {id = 112020, name = "Flovira", head = "12020", type = 5, title = "Birthday!\u{0020}Birthday\u{0020}on\u{0020}Earth!", txt = "Finally,\u{0020}it's\u{0020}my\u{0020}birthday!\u{0020}Woohoo!\nAmusement\u{0020}park,\u{0020}movie\u{0020}theater,\u{0020}ski\u{0020}resort,\u{0020}cruise\u{0020}ship,\u{0020}glider...\u{0020}There\u{0020}are\u{0020}just\u{0020}too\u{0020}many\u{0020}places\u{0020}I\u{0020}wanna\u{0020}go!\u{0020}Hmm,\u{0020}how\u{0020}about\u{0020}you,\u{0020}Navigator,\u{0020}decide\u{0020}for\u{0020}me?\nThis\u{0020}is\u{0020}the\u{0020}perfect\u{0020}chance\u{0020}to\u{0020}introduce\u{0020}Earth's\u{0020}wonders\u{0020}to\u{0020}a\u{0020}non-Earthling,\u{0020}you\u{0020}know?\u{0020}Most\u{0020}don't\u{0020}even\u{0020}get\u{0020}to\u{0020}meet\u{0020}one.\u{0020}You'd\u{0020}better\u{0020}make\u{0020}the\u{0020}most\u{0020}of\u{0020}it.\nOh,\u{0020}don't\u{0020}worry!\u{0020}I've\u{0020}already\u{0020}arranged\u{0020}everything.\u{0020}Today,\u{0020}my\u{0020}data\u{0020}will\u{0020}be\u{0020}loaded\u{0020}into\u{0020}a\u{0020}portable\u{0020}terminal,\u{0020}and\u{0020}all\u{0020}you\u{0020}have\u{0020}to\u{0020}do\u{0020}is\u{0020}carry\u{0020}it,\u{0020}which\u{0020}means\u{0020}carry\u{0020}me,\u{0020}around\u{0020}to\u{0020}live\u{0020}a\u{0020}day\u{0020}of\u{0020}celebration\u{0020}as\u{0020}an\u{0020}Earthling.\u{0020}Easy-peasy,\u{0020}right?\nSo,\u{0020}meet\u{0020}me\u{0020}in\u{0020}the\u{0020}lounge\u{0020}at\u{0020}noon\u{0020}sharp.\u{0020}\nDon't\u{0020}you\u{0020}dare\u{0020}stand\u{0020}me\u{0020}up!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202001] = {id = 11202001, name = "Flovira", head = "12020", type = 5, title = "Project:\u{0020}Make\u{0020}Earth\u{0020}Celebrate\u{0020}My\u{0020}Birthday", txt = "I\u{0020}want\u{0020}to\u{0020}take\u{0020}a\u{0020}high-speed\u{0020}journey\u{0020}in\u{0020}the\u{0020}form\u{0020}of\u{0020}data,\u{0020}constantly\u{0020}traveling\u{0020}across\u{0020}Earth\u{0020}and\u{0020}leaving\u{0020}my\u{0020}\"traces\"\u{0020}everywhere.\nThrough\u{0020}those\u{0020}\"traces,\"\u{0020}I\u{0020}can\u{0020}take\u{0020}control\u{0020}of\u{0020}every\u{0020}device\u{0020}in\u{0020}the\u{0020}world\u{0020}on\u{0020}my\u{0020}birthday\u{0020}and\u{0020}make\u{0020}them\u{0020}play\u{0020}the\u{0020}\"Happy\u{0020}Birthday\"\u{0020}song!\nWhat\u{0020}do\u{0020}you\u{0020}think\u{0020}of\u{0020}the\u{0020}idea,\u{0020}Navigator?\nMm...\u{0020}But\u{0020}that\u{0020}might\u{0020}cause\u{0020}trouble\u{0020}for\u{0020}everyone,\u{0020}and\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}come\u{0020}with\u{0020}me\u{0020}on\u{0020}this\u{0020}journey...\nI've\u{0020}got\u{0020}it!\u{0020}Let's\u{0020}travel\u{0020}around\u{0020}the\u{0020}Danube\u{0020}Ark\u{0020}instead!\u{0020}You\u{0020}can\u{0020}take\u{0020}me\u{0020}through\u{0020}all\u{0020}those\u{0020}familiar\u{0020}places.\u{0020}Mm~\u{0020}That's\u{0020}part\u{0020}of\u{0020}the\u{0020}fun\u{0020}of\u{0020}traveling\u{0020}too!\u{0020}And\u{0020}of\u{0020}course,\u{0020}there\u{0020}still\u{0020}has\u{0020}to\u{0020}be\u{0020}a\u{0020}\"Happy\u{0020}Birthday\"\u{0020}song\u{0020}on\u{0020}the\u{0020}big\u{0020}day~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112021] = {id = 112021, name = "Shaoyin", head = "12021", type = 5, title = "請柬", txt = "拜啟者：\n小滿已至，適逢本人生辰，原以為能平淡度之，與往年無二，然未料友人駁論，只得設宴以慶之。\n故此，恭候蒞臨。\n\n宴席詳情將以附件文本形式發送，望navigator及時查收。\n\n\n備註：我就知道她會寫成這樣！還好在發送前成功攔截下來了……navigator，韶音她其實超級無敵期待您來參加她的生日派對。除了您，她可沒有專門寫信邀請過其他人。所以您可一定要準時到場哦~\u{0020}u{3000}\u{0020}by好心的澄練隊長", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202101] = {id = 11202101, name = "Shaoyin", head = "12021", type = 5, title = "Invitation", txt = "To\u{0020}whom\u{0020}it\u{0020}may\u{0020}concern:\nTo\u{0020}the\u{0020}esteemed\u{0020}Navigator,\nCaptain\u{0020}Chenglian\u{0020}once\u{0020}warned\u{0020}this\u{0020}young\u{0020}lady\u{0020}that\u{0020}the\u{0020}\"style\"\u{0020}of\u{0020}my\u{0020}previous\u{0020}letters\u{0020}might\u{0020}have\u{0020}been\u{0020}too\u{0020}obscure\u{0020}and\u{0020}difficult\u{0020}to\u{0020}understand\u{0020}for\u{0020}those\u{0020}outside\u{0020}the\u{0020}[Academy].\nSo\u{0020}I\u{0020}have\u{0020}reflected\u{0020}on\u{0020}that\u{0020}matter,\u{0020}and\u{0020}this\u{0020}time\u{0020}I\u{0020}have\u{0020}tried\u{0020}to\u{0020}express\u{0020}my\u{0020}\"feelings\"\u{0020}directly\u{0020}on\u{0020}the\u{0020}page.\u{0020}(I\u{0020}am\u{0020}not\u{0020}sure\u{0020}whether\u{0020}\"feelings\"\u{0020}is\u{0020}the\u{0020}correct\u{0020}word.\u{0020}If\u{0020}my\u{0020}wording\u{0020}is\u{0020}mistaken,\u{0020}I\u{0020}ask\u{0020}for\u{0020}your\u{0020}kind\u{0020}understanding.)\nOn\u{0020}the\u{0020}day\u{0020}of\u{0020}my\u{0020}birthday,\u{0020}I\u{0020}hope\u{0020}you\u{0020}will\u{0020}attend\u{0020}the\u{0020}banquet\u{0020}that\u{0020}my\u{0020}friends\u{0020}and\u{0020}I\u{0020}are\u{0020}hosting\u{0020}together.\u{0020}I...\u{0020}am\u{0020}looking\u{0020}forward\u{0020}to\u{0020}your\u{0020}arrival,\u{0020}Navigator.\u{0020}If\u{0020}you\u{0020}come,\u{0020}I\u{0020}will\u{0020}surely\u{0020}be\u{0020}very\u{0020}happy...\u{0020}Yes,\u{0020}that\u{0020}is\u{0020}all.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112022] = {id = 112022, name = "Lepani", head = "12022", type = 5, title = "I'm\u{0020}finally\u{0020}cured\u{0020}of\u{0020}getting\u{0020}lost!", txt = "I\u{0020}couldn't\u{0020}wait\u{0020}to\u{0020}share\u{0020}some\u{0020}great\u{0020}news\u{0020}with\u{0020}you—I've\u{0020}finally\u{0020}stopped\u{0020}getting\u{0020}lost!\u{0020}It's\u{0020}all\u{0020}thanks\u{0020}to\u{0020}my\u{0020}birthday\u{0020}wish.\nOf\u{0020}course,\u{0020}the\u{0020}only\u{0020}way\u{0020}to\u{0020}know\u{0020}if\u{0020}it\u{0020}really\u{0020}worked\u{0020}is\u{0020}to\u{0020}try\u{0020}it\u{0020}out\u{0020}for\u{0020}real.\u{0020}By\u{0020}the\u{0020}time\u{0020}you're\u{0020}reading\u{0020}this,\u{0020}I'm\u{0020}already\u{0020}on\u{0020}my\u{0020}way\u{0020}to\u{0020}see\u{0020}you—just\u{0020}me\u{0020}this\u{0020}time,\u{0020}no\u{0020}Caroline\u{0020}to\u{0020}guide\u{0020}me!\nBelieve\u{0020}it\u{0020}or\u{0020}not,\u{0020}I've\u{0020}genuinely\u{0020}overcome\u{0020}my\u{0020}terrible\u{0020}sense\u{0020}of\u{0020}direction.\u{0020}Last\u{0020}month,\u{0020}I\u{0020}graduated\u{0020}from\u{0020}an\u{0020}online\u{0020}program\u{0020}called\u{0020}the\u{0020}\"Mutual\u{0020}Aid\u{0020}Association\u{0020}for\u{0020}the\u{0020}Chronically\u{0020}Lost.\"\nThey\u{0020}taught\u{0020}me\u{0020}all\u{0020}kinds\u{0020}of\u{0020}practical\u{0020}things,\u{0020}like\u{0020}how\u{0020}to\u{0020}properly\u{0020}use\u{0020}the\u{0020}sun\u{0020}for\u{0020}navigation,\u{0020}why\u{0020}compasses\u{0020}don't\u{0020}actually\u{0020}point\u{0020}south,\u{0020}and\u{0020}simple\u{0020}tricks\u{0020}for\u{0020}remembering\u{0020}directions.\nThis\u{0020}time,\u{0020}I'm\u{0020}absolutely\u{0020}confident\u{0020}I\u{0020}won't\u{0020}get\u{0020}lost!\n…Although,\u{0020}there\u{0020}is\u{0020}one\u{0020}strange\u{0020}thing.\u{0020}Is\u{0020}it\u{0020}normal\u{0020}for\u{0020}the\u{0020}North\u{0020}Star\u{0020}to\u{0020}be\u{0020}in\u{0020}the\u{0020}east?\u{0020}\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202201] = {id = 11202201, name = "Lepani", head = "12022", type = 5, title = "Making\u{0020}My\u{0020}Birthday\u{0020}Wish\u{0020}Come\u{0020}True", txt = "It's\u{0020}a\u{0020}universal\u{0020}tradition\u{0020}to\u{0020}make\u{0020}a\u{0020}wish\u{0020}on\u{0020}your\u{0020}birthday.\nSo\u{0020}today,\u{0020}I\u{0020}made\u{0020}mine.\u{0020}I\u{0020}wish\u{0020}for\u{0020}every\u{0020}last\u{0020}Sin\u{0020}in\u{0020}this\u{0020}world\u{0020}to\u{0020}vanish\u{0020}without\u{0020}a\u{0020}trace.\nThe\u{0020}wish\u{0020}has\u{0020}been\u{0020}made.\u{0020}And\u{0020}now...\u{0020}it's\u{0020}time\u{0020}to\u{0020}make\u{0020}it\u{0020}happen.\nNavigator,\u{0020}in\u{0020}exactly\u{0020}one\u{0020}minute,\u{0020}you'll\u{0020}receive\u{0020}a\u{0020}request\u{0020}to\u{0020}join\u{0020}a\u{0020}mission\u{0020}to\u{0020}exterminate\u{0020}Sins.\nTo\u{0020}fulfill\u{0020}my\u{0020}birthday\u{0020}wish,\u{0020}I'll\u{0020}need\u{0020}you\u{0020}beside\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[112023] = {id = 112023, name = "Stella", head = "12023", type = 5, title = "生日的光景", txt = "navigator……你有想過嗎？\n宇宙每一天的景象都是不一樣的，那麼自己出生那天的宇宙是一副怎樣的光景呢？\n我們已經很難親眼再見到那天的景象了，但我想……我們還可以去看當下的光景。\nnavigator……今晚，我想和你在天文台，一起見證自己生日時的宇宙景象。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202301] = {id = 11202301, name = "Stella", head = "12023", type = 5, title = "The\u{0020}View\u{0020}of\u{0020}My\u{0020}Birthday", txt = "Navigator...\u{0020}have\u{0020}you\u{0020}ever\u{0020}thought\u{0020}about\u{0020}this?\nEach\u{0020}day,\u{0020}the\u{0020}universe\u{0020}unfolds\u{0020}in\u{0020}a\u{0020}unique\u{0020}way.\u{0020}What\u{0020}do\u{0020}you\u{0020}think\u{0020}the\u{0020}universe\u{0020}looked\u{0020}like\u{0020}on\u{0020}the\u{0020}day\u{0020}I\u{0020}was\u{0020}born?\nIt's\u{0020}impossible\u{0020}to\u{0020}witness\u{0020}that\u{0020}exact\u{0020}moment\u{0020}again,\u{0020}but…\u{0020}I\u{0020}believe\u{0020}we\u{0020}can\u{0020}still\u{0020}experience\u{0020}the\u{0020}present\u{0020}view.\nNavigator…\u{0020}tonight,\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}with\u{0020}you\u{0020}at\u{0020}the\u{0020}observatory,\u{0020}and\u{0020}together,\u{0020}let's\u{0020}gaze\u{0020}upon\u{0020}the\u{0020}universe\u{0020}as\u{0020}it\u{0020}was\u{0020}on\u{0020}the\u{0020}day\u{0020}I\u{0020}was\u{0020}born.\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11202302] = {id = 11202302, name = "Stella", head = "12023", type = 5, title = "A\u{0020}Moment\u{0020}in\u{0020}the\u{0020}Universe", txt = "A\u{0020}single\u{0020}moment\u{0020}somewhere\u{0020}in\u{0020}the\u{0020}universe,\u{0020}a\u{0020}single\u{0020}moment\u{0020}somewhere\u{0020}in\u{0020}the\u{0020}starry\u{0020}sky...\u{0020}can\u{0020}be\u{0020}an\u{0020}eternity\u{0020}we\u{0020}could\u{0020}never\u{0020}glimpse\u{0020}even\u{0020}in\u{0020}a\u{0020}lifetime.\u{0020}\nIf\u{0020}you're\u{0020}willing,\u{0020}maybe\u{0020}we\u{0020}can\u{0020}walk\u{0020}out\u{0020}together\u{0020}beneath\u{0020}the\u{0020}open\u{0020}sky,\u{0020}look\u{0020}at\u{0020}those\u{0020}twinkling\u{0020}stars,\u{0020}and\u{0020}listen\u{0020}to\u{0020}the\u{0020}silence\u{0020}of\u{0020}a\u{0020}lonely\u{0020}world.\u{0020}\nNavigator...\u{0020}you're\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}has\u{0020}spent\u{0020}a\u{0020}birthday\u{0020}with\u{0020}me\u{0020}under\u{0020}this\u{0020}sky,\u{0020}and\u{0020}the\u{0020}stars\u{0020}have\u{0020}been\u{0020}quietly\u{0020}watching\u{0020}over\u{0020}us.\u{0020}\nI\u{0020}think\u{0020}that\u{0020}from\u{0020}now\u{0020}on,\u{0020}whenever\u{0020}I\u{0020}look\u{0020}up\u{0020}at\u{0020}the\u{0020}night\u{0020}sky,\u{0020}I'll\u{0020}imagine\u{0020}whether\u{0020}you\u{0020}might\u{0020}be\u{0020}lifting\u{0020}your\u{0020}head\u{0020}under\u{0020}the\u{0020}same\u{0020}sky\u{0020}too...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113000] = {id = 113000, name = "Odora", head = "13000", type = 5, title = "睡覺覺", txt = "又到了我的生日…\n和以前一樣，我打算喝點牛奶就睡覺，除了想要長高，我沒有別的願望了…\n呼…似乎在出生以前，每個人就是一直在睡覺吧？所以今天睡很久很久也沒問題…沒有人會說什麼，因為是在慶祝嘛…\n這麼好的事，navigator也要一起來嗎？我在夢中等你…", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300001] = {id = 11300001, name = "Odora", head = "13000", type = 5, title = "繼續睡覺覺", txt = "醒了，發現又到生日這天了。\n去年的今天我好像是在睡夢中度過的吧，那今年就延續去年的傳統，繼續睡覺吧。\n生日願望……也和去年一樣是長高吧，雖然並不是很靈驗。一年的時間我的個子連一釐米都沒有增加。難道是沒有吹蠟燭的原因嗎？\n蛋糕、蠟燭，無論哪個都好麻煩。\n算了還是睡覺吧，在夢裏舉辦生日派對的話就，什麼都可以不用準備了……", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300002] = {id = 11300002, name = "Odora", head = "13000", type = 5, title = "Nighty-Night", txt = "My\u{0020}birthday's\u{0020}here\u{0020}again...\nLike\u{0020}always,\u{0020}I'll\u{0020}drink\u{0020}some\u{0020}milk\u{0020}and\u{0020}go\u{0020}to\u{0020}bed.\u{0020}I\u{0020}don't\u{0020}really\u{0020}have\u{0020}any\u{0020}wishes,\u{0020}except\u{0020}getting\u{0020}taller...\nSnooze...\u{0020}Didn't\u{0020}everyone\u{0020}sleep\u{0020}forever\u{0020}before\u{0020}they\u{0020}were\u{0020}born?\u{0020}So\u{0020}sleeping\u{0020}all\u{0020}day\u{0020}today's\u{0020}fine...\u{0020}No\u{0020}one\u{0020}will\u{0020}say\u{0020}anything.\u{0020}It's\u{0020}my\u{0020}way\u{0020}of\u{0020}celebration,\u{0020}after\u{0020}all...\nWant\u{0020}to\u{0020}join\u{0020}me,\u{0020}Navigator?\u{0020}The\u{0020}all-day-snooze\u{0020}pass\u{0020}is\u{0020}strictly\u{0020}annual,\u{0020}you\u{0020}know...\u{0020}I'll\u{0020}be\u{0020}waiting\u{0020}for\u{0020}you\u{0020}in\u{0020}my\u{0020}dream...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300003] = {id = 11300003, name = "Odora", head = "13000", type = 5, title = "Keep\u{0020}Sleeping", txt = "I\u{0020}woke\u{0020}up\u{0020}and\u{0020}realized\u{0020}it\u{0020}is\u{0020}my\u{0020}birthday\u{0020}again.\nI\u{0020}think\u{0020}I\u{0020}spent\u{0020}this\u{0020}day\u{0020}last\u{0020}year\u{0020}asleep,\u{0020}so\u{0020}this\u{0020}year\u{0020}I\u{0020}might\u{0020}as\u{0020}well\u{0020}continue\u{0020}last\u{0020}year's\u{0020}tradition\u{0020}and\u{0020}keep\u{0020}sleeping.\nAs\u{0020}for\u{0020}my\u{0020}birthday\u{0020}wish...\u{0020}just\u{0020}like\u{0020}last\u{0020}year,\u{0020}it\u{0020}is\u{0020}to\u{0020}grow\u{0020}taller,\u{0020}though\u{0020}it\u{0020}does\u{0020}not\u{0020}seem\u{0020}to\u{0020}be\u{0020}very\u{0020}effective.\u{0020}After\u{0020}a\u{0020}whole\u{0020}year,\u{0020}I\u{0020}have\u{0020}not\u{0020}grown\u{0020}even\u{0020}a\u{0020}single\u{0020}centimeter.\u{0020}Could\u{0020}it\u{0020}be\u{0020}because\u{0020}I\u{0020}did\u{0020}not\u{0020}blow\u{0020}out\u{0020}the\u{0020}candles?\nCake,\u{0020}candles,\u{0020}either\u{0020}one\u{0020}sounds\u{0020}like\u{0020}too\u{0020}much\u{0020}trouble.\nForget\u{0020}it,\u{0020}I\u{0020}should\u{0020}just\u{0020}go\u{0020}back\u{0020}to\u{0020}sleep.\u{0020}If\u{0020}I\u{0020}hold\u{0020}my\u{0020}birthday\u{0020}party\u{0020}in\u{0020}a\u{0020}dream,\u{0020}then\u{0020}I\u{0020}would\u{0020}not\u{0020}have\u{0020}to\u{0020}prepare\u{0020}anything\u{0020}at\u{0020}all...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113001] = {id = 113001, name = "Franca", head = "13001", type = 5, title = "About\u{0020}today…", txt = "Could\u{0020}Navigator\u{0020}come\u{0020}to\u{0020}my\u{0020}room\u{0020}after\u{0020}work\u{0020}for\u{0020}a\u{0020}little\u{0020}birthday\u{0020}party\u{0020}today?\u{0020}Julius\u{0020}and\u{0020}Charlissa\u{0020}will\u{0020}be\u{0020}there\u{0020}and\u{0020}I\u{0020}even\u{0020}made\u{0020}a\u{0020}big\u{0020}cake.\nWell…\u{0020}Actually,\u{0020}I\u{0020}was\u{0020}not\u{0020}sure\u{0020}on\u{0020}whether\u{0020}to\u{0020}write\u{0020}a\u{0020}letter,\u{0020}as\u{0020}it\u{0020}felt\u{0020}too\u{0020}formal\u{0020}and\u{0020}distant.\u{0020}I\u{0020}wanted\u{0020}to\u{0020}invite\u{0020}you\u{0020}in\u{0020}the\u{0020}command\u{0020}room\u{0020}as\u{0020}I\u{0020}normally\u{0020}would,\u{0020}but\u{0020}I\u{0020}felt\u{0020}a\u{0020}little\u{0020}embarassed…\u{0020}I\u{0020}was\u{0020}afraid\u{0020}that\u{0020}it\u{0020}might\u{0020}disturb\u{0020}your\u{0020}work,\u{0020}so\u{0020}I\u{0020}chose\u{0020}to\u{0020}send\u{0020}a\u{0020}message\u{0020}in\u{0020}the\u{0020}end.\nThen…\u{0020}There's\u{0020}still\u{0020}a\u{0020}lot\u{0020}more\u{0020}to\u{0020}say\u{0020}that\u{0020}can't\u{0020}fit\u{0020}in\u{0020}a\u{0020}message,\u{0020}words\u{0020}that\u{0020}are\u{0020}difficult\u{0020}to\u{0020}put\u{0020}together,\u{0020}words\u{0020}that\u{0020}even\u{0020}I'm\u{0020}not\u{0020}sure\u{0020}about…\u{0020}I'll\u{0020}tell\u{0020}you\u{0020}after\u{0020}the\u{0020}party\u{0020}tonight,\u{0020}okay?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300101] = {id = 11300101, name = "Franca", head = "13001", type = 5, title = "麻將大賽", txt = "明明只要在今天訓練時跟你說就可以了，為什麼還要特地發郵件……寫郵件的時候又不知不覺這麼想了。\nnavigator，今天是我的生日，但我決定今年要嘗試一次不一樣的慶生方式……\n您應該知道“麻將”吧？我在自己的房間裡準備了RX八口機，還叫上了查麗莎學姐和朱利烏斯學姐。\n對！我要要一整晚的麻將來度過生日……您要是不了解規則的話，我可以教您。您一定很快就能學會的！\n請您一定要來啊T_T！", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300102] = {id = 11300102, name = "Franca", head = "13001", type = 5, title = "About\u{0020}Today...", txt = "Navigator,\u{0020}would\u{0020}you\u{0020}be\u{0020}able\u{0020}to\u{0020}come\u{0020}join\u{0020}a\u{0020}small\u{0020}birthday\u{0020}party\u{0020}in\u{0020}my\u{0020}room\u{0020}after\u{0020}work\u{0020}today?\u{0020}Julius-senpai\u{0020}and\u{0020}Charlissa-senpai\u{0020}will\u{0020}be\u{0020}there\u{0020}too,\u{0020}and\u{0020}I've\u{0020}baked\u{0020}a\u{0020}really\u{0020}big\u{0020}cake.\n", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300103] = {id = 11300103, name = "Franca", head = "13001", type = 5, title = "Mahjong\u{0020}Tournament", txt = "Even\u{0020}though\u{0020}I\u{0020}could\u{0020}have\u{0020}just\u{0020}told\u{0020}you\u{0020}during\u{0020}training\u{0020}today,\u{0020}why\u{0020}did\u{0020}I\u{0020}have\u{0020}to\u{0020}go\u{0020}out\u{0020}of\u{0020}my\u{0020}way\u{0020}to\u{0020}send\u{0020}an\u{0020}email\u{0020}instead...?\u{0020}I\u{0020}ended\u{0020}up\u{0020}thinking\u{0020}that\u{0020}again\u{0020}without\u{0020}even\u{0020}realizing\u{0020}it\u{0020}while\u{0020}writing\u{0020}this.\nNavigator,\u{0020}today\u{0020}is\u{0020}my\u{0020}birthday,\u{0020}but\u{0020}this\u{0020}year\u{0020}I\u{0020}decided\u{0020}to\u{0020}try\u{0020}celebrating\u{0020}it\u{0020}in\u{0020}a\u{0020}different\u{0020}way...\nYou\u{0020}do\u{0020}know\u{0020}what\u{0020}\"mahjong\"\u{0020}is,\u{0020}right?\u{0020}I\u{0020}have\u{0020}prepared\u{0020}an\u{0020}RX\u{0020}automatic\u{0020}mahjong\u{0020}table\u{0020}in\u{0020}my\u{0020}room,\u{0020}and\u{0020}I\u{0020}also\u{0020}invited\u{0020}Charlissa\u{0020}senpai\u{0020}and\u{0020}Julius\u{0020}senpai.\nThat's\u{0020}right!\u{0020}I\u{0020}am\u{0020}going\u{0020}to\u{0020}spend\u{0020}my\u{0020}birthday\u{0020}playing\u{0020}mahjong\u{0020}all\u{0020}night\u{0020}long...\u{0020}If\u{0020}you\u{0020}do\u{0020}not\u{0020}know\u{0020}the\u{0020}rules,\u{0020}I\u{0020}can\u{0020}teach\u{0020}you.\u{0020}I\u{0020}am\u{0020}sure\u{0020}you\u{0020}will\u{0020}learn\u{0020}very\u{0020}quickly!\nYou\u{0020}absolutely\u{0020}have\u{0020}to\u{0020}come,\u{0020}okay?\u{0020}T_T!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113002] = {id = 113002, name = "Tina", head = "13002", type = 5, title = "An\u{0020}Unsolicited\u{0020}Request", txt = "Greetings,\u{0020}Navigator,\u{0020}from\u{0020}Tina\u{0020}Eisen,\u{0020}the\u{0020}most\u{0020}loyal\u{0020}matron\u{0020}of\u{0020}House\u{0020}Cretia.\nForgive\u{0020}me\u{0020}for\u{0020}taking\u{0020}the\u{0020}liberty\u{0020}of\u{0020}writing\u{0020}this\u{0020}letter,\u{0020}as\u{0020}my\u{0020}patience\u{0020}has\u{0020}been\u{0020}worn\u{0020}thin\u{0020}by\u{0020}the\u{0020}zeal\u{0020}of\u{0020}two\u{0020}family's\u{0020}daughters\u{0020}before\u{0020}putting\u{0020}pen\u{0020}to\u{0020}paper.\u{0020}Notwithstanding\u{0020}Miss\u{0020}Gin,\u{0020}who\u{0020}has\u{0020}always\u{0020}acted\u{0020}in\u{0020}her\u{0020}own\u{0020}way,\u{0020}but\u{0020}even\u{0020}Miss\u{0020}Alice,\u{0020}who\u{0020}has\u{0020}been\u{0020}so\u{0020}reserved\u{0020}and\u{0020}dignified,\u{0020}seems\u{0020}to\u{0020}have\u{0020}had\u{0020}a\u{0020}sudden\u{0020}impulse\u{0020}to\u{0020}hold\u{0020}a\u{0020}banquet\u{0020}for\u{0020}a\u{0020}trifling\u{0020}matter\u{0020}of\u{0020}no\u{0020}importance.\nTo\u{0020}be\u{0020}perfectly\u{0020}frank,\u{0020}it\u{0020}was\u{0020}my\u{0020}birthday\u{0020}today,\u{0020}which\u{0020}gave\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}an\u{0020}opportunity\u{0020}to\u{0020}disobey\u{0020}instructions.\u{0020}Ignoring\u{0020}all\u{0020}advice,\u{0020}they\u{0020}insisted\u{0020}that\u{0020}the\u{0020}cooks\u{0020}prepare\u{0020}an\u{0020}endless\u{0020}array\u{0020}of\u{0020}dishes\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday,\u{0020}not\u{0020}realizing\u{0020}that\u{0020}I\u{0020}only\u{0020}wanted\u{0020}them\u{0020}to\u{0020}be\u{0020}more\u{0020}understanding.\nKnowing\u{0020}that\u{0020}Navigator\u{0020}is\u{0020}a\u{0020}good\u{0020}disciplinarian\u{0020}with\u{0020}his\u{0020}Drivers,\u{0020}I\u{0020}have\u{0020}invited\u{0020}you\u{0020}to\u{0020}a\u{0020}dinner\u{0020}party\u{0020}to\u{0020}discuss\u{0020}the\u{0020}young\u{0020}ladies'\u{0020}future\u{0020}with\u{0020}me.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
