[113005] = {id = 113005, name = "Genia", head = "13005", type = 5, title = "免費體檢", txt = "navigator今年做過體檢了嗎？平時有那麼多需要操勞的事情，絕不能忽視自身的身體健康，每年都必須進行一次身體檢查。\n不過正常的體檢幾乎做不到全面徹底的清查，特別是那些症狀輕微的慢性問題……正好今天是我生日，我可以申請為期一天的生日假期。我就親自去你那兒一趟，給navigator您進行全方位深入的免費體檢，從細胞層面解決您身體的健康問題。\n另外在我來之前，navigator請保持空腹，以免攝入影響體檢結果的食物。", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
