[113007] = {id = 113007, name = "Type\u{0020}T", head = "13007", type = 5, title = "Case\u{0020}File\u{0020}No.\u{0020}0518", txt = "Case\u{0020}File\u{0020}No.\u{0020}0518.\u{0020}System\u{0020}loading...\nPersonality\u{0020}logic\u{0020}check\u{0020}-\u{0020}Passed.\nPersonality\u{0020}stability\u{0020}check\u{0020}-\u{0020}Passed.\nGenerating\u{0020}thought\u{0020}content...\n\n\"The\u{0020}day\u{0020}a\u{0020}human\u{0020}is\u{0020}born\u{0020}is\u{0020}called\u{0020}a\u{0020}birthday.\u{0020}On\u{0020}the\u{0020}same\u{0020}month\u{0020}and\u{0020}date\u{0020}in\u{0020}each\u{0020}following\u{0020}calendar\u{0020}year,\u{0020}humans\u{0020}hold\u{0020}a\u{0020}ritual\u{0020}to\u{0020}celebrate\u{0020}that\u{0020}birthday.\nMay\u{0020}18,\u{0020}the\u{0020}manufacture\u{0020}date\u{0020}of\u{0020}Type\u{0020}T.\u{0020}Should\u{0020}I\u{0020}also\u{0020}carry\u{0020}out\u{0020}a\u{0020}celebration\u{0020}ritual?\nError.\u{0020}Type\u{0020}T\u{0020}units\u{0020}cannot\u{0020}consume\u{0020}human\u{0020}food.\nCorrection.\u{0020}Celebrating\u{0020}a\u{0020}birthday\u{0020}is\u{0020}not\u{0020}limited\u{0020}to\u{0020}eating.\u{0020}More\u{0020}importantly,\u{0020}it\u{0020}is\u{0020}about\u{0020}sharing\u{0020}the\u{0020}happiness\u{0020}of\u{0020}a\u{0020}birthday\u{0020}with\u{0020}the\u{0020}human\u{0020}one\u{0020}is\u{0020}thinking\u{0020}of.\nThe\u{0020}human\u{0020}I\u{0020}am\u{0020}thinking\u{0020}of...\"\n\nGenerating\u{0020}new\u{0020}mission...\nMission\u{0020}objective:\u{0020}Share\u{0020}the\u{0020}happiness\u{0020}of\u{0020}a\u{0020}birthday.\nFirst\u{0020}action\u{0020}step\u{0020}-\u{0020}Find\u{0020}the\u{0020}Navigator.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
