[113009] = {id = 113009, name = "Aevati", head = "13009", type = 5, title = "A\u{0020}Day\u{0020}Worth\u{0020}Remembering", txt = "Greetings,\u{0020}esteemed\u{0020}Navigator.\nToday\u{0020}marks\u{0020}exactly\u{0020}one\u{0020}full\u{0020}orbit\u{0020}of\u{0020}Earth\u{0020}since\u{0020}I\u{0020}received\u{0020}my\u{0020}new\u{0020}body.\u{0020}By\u{0020}this\u{0020}planet's\u{0020}customs,\u{0020}that\u{0020}makes\u{0020}it\u{0020}my\u{0020}birthday.\nWe\u{0020}Midyrians\u{0020}leave\u{0020}our\u{0020}homeworld\u{0020}the\u{0020}moment\u{0020}we\u{0020}are\u{0020}born,\u{0020}embarking\u{0020}on\u{0020}an\u{0020}endless\u{0020}journey\u{0020}through\u{0020}the\u{0020}stars.\u{0020}With\u{0020}a\u{0020}vast\u{0020}cosmos\u{0020}as\u{0020}our\u{0020}domain,\u{0020}we\u{0020}never\u{0020}found\u{0020}the\u{0020}need\u{0020}to\u{0020}track\u{0020}a\u{0020}homeworld's\u{0020}orbit,\u{0020}hence\u{0020}no\u{0020}tradition\u{0020}of\u{0020}celebrating\u{0020}our\u{0020}own\u{0020}births.\nBut\u{0020}in\u{0020}the\u{0020}life\u{0020}I've\u{0020}begun\u{0020}here\u{0020}on\u{0020}Earth,\u{0020}after\u{0020}the\u{0020}fall\u{0020}of\u{0020}the\u{0020}Midyr,\u{0020}I\u{0020}have\u{0020}found\u{0020}the\u{0020}beauty\u{0020}of\u{0020}it.\u{0020}Perhaps,\u{0020}in\u{0020}an\u{0020}ever-changing\u{0020}universe,\u{0020}we\u{0020}do\u{0020}need\u{0020}something\u{0020}constant—an\u{0020}anchor\u{0020}to\u{0020}hold\u{0020}onto.\nAnd\u{0020}so,\u{0020}I've\u{0020}made\u{0020}a\u{0020}decision:\u{0020}If\u{0020}I\u{0020}ever\u{0020}get\u{0020}the\u{0020}chance\u{0020}to\u{0020}rebuild\u{0020}Midyr,\u{0020}I\u{0020}shall\u{0020}introduce\u{0020}this\u{0020}tradition\u{0020}to\u{0020}our\u{0020}civilization.\u{0020}But\u{0020}until\u{0020}that\u{0020}day\u{0020}comes...\u{0020}Navigator,\u{0020}would\u{0020}you\u{0020}honor\u{0020}me\u{0020}by\u{0020}spending\u{0020}this\u{0020}day\u{0020}with\u{0020}me?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11300901] = {id = 11300901, name = "Aevati", head = "13009", type = 5, title = "Carving\u{0020}a\u{0020}Mark\u{0020}Upon\u{0020}Time", txt = "Greetings,\u{0020}esteemed\u{0020}Navigator.\nTo\u{0020}be\u{0020}frank,\u{0020}while\u{0020}we\u{0020}have\u{0020}been\u{0020}caught\u{0020}up\u{0020}in\u{0020}the\u{0020}endless\u{0020}busyness\u{0020}of\u{0020}daily\u{0020}life,\u{0020}the\u{0020}planet\u{0020}Earth\u{0020}has\u{0020}once\u{0020}again\u{0020}completed\u{0020}another\u{0020}orbit.\u{0020}In\u{0020}other\u{0020}words,\u{0020}my\u{0020}birthday\u{0020}has\u{0020}arrived\u{0020}once\u{0020}more.\nBorn\u{0020}on\u{0020}Midir,\u{0020}a\u{0020}world\u{0020}whose\u{0020}customs\u{0020}are\u{0020}utterly\u{0020}different\u{0020}from\u{0020}those\u{0020}of\u{0020}Earth,\u{0020}each\u{0020}passing\u{0020}year\u{0020}here\u{0020}allows\u{0020}me\u{0020}to\u{0020}feel\u{0020}more\u{0020}deeply\u{0020}the\u{0020}meaning\u{0020}and\u{0020}weight\u{0020}of\u{0020}the\u{0020}birthday\u{0020}tradition,\u{0020}for\u{0020}it\u{0020}is\u{0020}the\u{0020}weight\u{0020}of\u{0020}time\u{0020}itself,\u{0020}a\u{0020}gravity\u{0020}that\u{0020}not\u{0020}even\u{0020}the\u{0020}mightiest\u{0020}stars\u{0020}can\u{0020}escape.\nThe\u{0020}people\u{0020}of\u{0020}Midir\u{0020}do\u{0020}not\u{0020}fear\u{0020}death,\u{0020}but\u{0020}we\u{0020}do\u{0020}fear\u{0020}time.\u{0020}Therefore,\u{0020}on\u{0020}the\u{0020}day\u{0020}of\u{0020}our\u{0020}birth,\u{0020}I\u{0020}choose\u{0020}to\u{0020}leave\u{0020}a\u{0020}small\u{0020}mark\u{0020}upon\u{0020}endless\u{0020}time,\u{0020}a\u{0020}sign\u{0020}of\u{0020}our\u{0020}modest\u{0020}victory\u{0020}over\u{0020}the\u{0020}world.\u{0020}Would\u{0020}Navigator\u{0020}be\u{0020}willing\u{0020}to\u{0020}accompany\u{0020}me\u{0020}in\u{0020}this\u{0020}wonderful\u{0020}ritual?\u{0020}I\u{0020}shall\u{0020}be\u{0020}waiting\u{0020}quietly\u{0020}in\u{0020}my\u{0020}room\u{0020}for\u{0020}your\u{0020}arrival.", goods = "1_100000_100,1_110121_1