[113014] = {id = 113014, name = "Momoka", head = "13014", type = 5, title = "The\u{0020}Shape\u{0020}of\u{0020}Snow", txt = "Navigator,\u{0020}have\u{0020}you\u{0020}ever\u{0020}wondered\u{0020}how\u{0020}many\u{0020}shapes\u{0020}a\u{0020}snowflake\u{0020}can\u{0020}take?\u{0020}\nWhile\u{0020}walking\u{0020}in\u{0020}the\u{0020}snow\u{0020}today,\u{0020}a\u{0020}tiny\u{0020}flurry\u{0020}landed\u{0020}right\u{0020}on\u{0020}the\u{0020}tip\u{0020}of\u{0020}my\u{0020}nose.\u{0020}The\u{0020}chilly\u{0020}air,\u{0020}along\u{0020}with\u{0020}my\u{0020}naturally\u{0020}lower\u{0020}body\u{0020}temperature,\u{0020}kept\u{0020}it\u{0020}from\u{0020}melting\u{0020}right\u{0020}away,\u{0020}giving\u{0020}me\u{0020}a\u{0020}chance\u{0020}to\u{0020}admire\u{0020}its\u{0020}delicate\u{0020}form.\u{0020}\nIt\u{0020}was\u{0020}a\u{0020}cluster\u{0020}of\u{0020}hexagonal\u{0020}shapes—a\u{0020}gathering\u{0020}of\u{0020}individual\u{0020}snowflakes.\u{0020}Each\u{0020}flake\u{0020}held\u{0020}its\u{0020}signature\u{0020}six-sided\u{0020}symmetry\u{0020}but\u{0020}extended\u{0020}in\u{0020}unique\u{0020}ways,\u{0020}weaving\u{0020}together\u{0020}through\u{0020}tiny\u{0020}gaps.\u{0020}Light\u{0020}danced\u{0020}across\u{0020}those\u{0020}spaces,\u{0020}creating\u{0020}shimmering\u{0020}colors\u{0020}that\u{0020}left\u{0020}me\u{0020}in\u{0020}awe.\nEvery\u{0020}snowflake\u{0020}is\u{0020}alike,\u{0020}yet\u{0020}entirely\u{0020}unique.\u{0020}It\u{0020}made\u{0020}me\u{0020}think\u{0020}of\u{0020}you,\u{0020}Navigator.\u{0020}Like\u{0020}two\u{0020}snowflakes,\u{0020}we're\u{0020}similar\u{0020}in\u{0020}some\u{0020}ways\u{0020}and\u{0020}so\u{0020}different\u{0020}in\u{0020}others.\u{0020}But\u{0020}maybe,\u{0020}when\u{0020}we\u{0020}come\u{0020}together,\u{0020}we\u{0020}can\u{0020}create\u{0020}something\u{0020}truly\u{0020}brilliant.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301401] = {id = 11301401, name = "Momoka", head = "13014", type = 5, title = "Frozen\u{0020}Cream\u{0020}Is\u{0020}Harder\u{0020}Than\u{0020}Stone", txt = "Late\u{0020}last\u{0020}night,\u{0020}a\u{0020}heavy\u{0020}snowfall\u{0020}arrived\u{0020}unannounced\u{0020}once\u{0020}again.\u{0020}When\u{0020}I\u{0020}was\u{0020}finally\u{0020}awakened\u{0020}by\u{0020}the\u{0020}piercing\u{0020}light\u{0020}of\u{0020}morning,\u{0020}I\u{0020}discovered\u{0020}that\u{0020}the\u{0020}window\u{0020}had\u{0020}been\u{0020}sealed\u{0020}shut\u{0020}by\u{0020}snow\u{0020}and\u{0020}ice,\u{0020}utterly\u{0020}immovable,\u{0020}solid\u{0020}beyond\u{0020}expectation.\u{0020}\nSomething\u{0020}else\u{0020}had\u{0020}become\u{0020}just\u{0020}as\u{0020}solid:\u{0020}a\u{0020}large\u{0020}bowl\u{0020}of\u{0020}cream\u{0020}I\u{0020}prepared\u{0020}yesterday.\u{0020}I\u{0020}had\u{0020}originally\u{0020}planned\u{0020}to\u{0020}use\u{0020}it\u{0020}to\u{0020}make\u{0020}cream\u{0020}ice\u{0020}cream,\u{0020}but\u{0020}the\u{0020}snowstorm\u{0020}kindly\u{0020}saved\u{0020}me\u{0020}the\u{0020}trouble\u{0020}of\u{0020}freezing\u{0020}it.\u{0020}I\u{0020}can't\u{0020}help\u{0020}but\u{0020}wonder\u{0020}how\u{0020}it\u{0020}will\u{0020}taste\u{0020}now.\u{0020}At\u{0020}the\u{0020}moment,\u{0020}it's\u{0020}harder\u{0020}than\u{0020}stone,\u{0020}so\u{0020}firm\u{0020}that\u{0020}even\u{0020}a\u{0020}knife\u{0020}and\u{0020}fork\u{0020}can\u{0020}barely\u{0020}make\u{0020}a\u{0020}dent,\u{0020}making\u{0020}it\u{0020}impossible\u{0020}to\u{0020}taste.\u{0020}\nSo\u{0020}I've\u{0020}carefully\u{0020}packed\u{0020}it\u{0020}up\u{0020}and\u{0020}sent\u{0020}it\u{0020}to\u{0020}you,\u{0020}Navigator,\u{0020}asking\u{0020}you\u{0020}to\u{0020}taste\u{0020}it\u{0020}in\u{0020}my\u{0020}place.\u{0020}I\u{0020}hope\u{0020}that\u{0020}after\u{0020}its\u{0020}journey\u{0020}across\u{0020}mountains\u{0020}and\u{0020}rivers,\u{0020}this\u{0020}cream\u{0020}ice\u{0020}cream\u{0020}might\u{0020}shed\u{0020}its\u{0020}stubborn\u{0020}hardness\u{0020}and\u{0020}arrive\u{0020}before\u{0020}you\u{0020}with\u{0020}a\u{0020}softer,\u{0020}gentler\u{0020}texture.\u{0020}When\u{0020}that\u{0020}happens,\u{0020}I'd\u{0020}love\u{0020}to\u{0020}know\u{0020}how\u{0020}it\u{0020}feels\u{0020}to\u{0020}you\u{0020}-\u{0020}what\u{0020}kind\u{0020}of\u{0020}impression\u{0020}it\u{0020}leaves\u{0020}behind.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113015] = {id = 113015, name = "Lina", head = "13015", type = 5, title = "It'd\u{0020}be\u{0020}nice\u{0020}if\u{0020}we\u{0020}could\u{0020}take\u{0020}down\u{0020}some\u{0020}criminals\u{0020}along\u{0020}the\u{0020}way.", txt = "Long\u{0020}time\u{0020}no\u{0020}see~\u{0020}Boy~\nI'll\u{0020}keep\u{0020}it\u{0020}short.\u{0020}Today's\u{0020}my\u{0020}birthday,\u{0020}and\u{0020}I\u{0020}want\u{0020}to\u{0020}steal\u{0020}your\u{0020}time\u{0020}for\u{0020}some\u{0020}fun\u{0020}together.\u{0020}\"Maybe,\u{0020}just\u{0020}for\u{0020}today,\u{0020}I\u{0020}don't\u{0020}have\u{0020}to\u{0020}be\u{0020}a\u{0020}hero~\"\u{0020}It\u{0020}might\u{0020}sound\u{0020}a\u{0020}bit\u{0020}unambitious,\u{0020}laid-back,\u{0020}and\u{0020}unheroic,\u{0020}but\u{0020}hey,\u{0020}that's\u{0020}how\u{0020}I\u{0020}feel~\nIf\u{0020}you\u{0020}get\u{0020}what\u{0020}I\u{0020}mean,\u{0020}hurry\u{0020}up\u{0020}and\u{0020}get\u{0020}ready.\u{0020}I'm\u{0020}bringing\u{0020}my\u{0020}motorcycle\u{0020}over—you'll\u{0020}ride\u{0020}behind\u{0020}me,\u{0020}and\u{0020}we'll\u{0020}head\u{0020}into\u{0020}the\u{0020}city\u{0020}for\u{0020}some\u{0020}fun~\nOh,\u{0020}and\u{0020}don't\u{0020}forget\u{0020}your\u{0020}gear\u{0020}and\u{0020}weapons.\u{0020}Just\u{0020}in\u{0020}case—we\u{0020}might\u{0020}run\u{0020}into\u{0020}some\u{0020}trouble\u{0020}while\u{0020}going\u{0020}undercover.\u{0020}If\u{0020}we\u{0020}see\u{0020}anything\u{0020}unjust,\u{0020}we\u{0020}should\u{0020}step\u{0020}in.\u{0020}Not\u{0020}that\u{0020}I\u{0020}think\u{0020}anything\u{0020}like\u{0020}that\u{0020}would\u{0020}happen\u{0020}downtown\u{0020}in\u{0020}Danube,\u{0020}but\u{0020}it's\u{0020}always\u{0020}better\u{0020}to\u{0020}be\u{0020}prepared~\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301501] = {id = 11301501, name = "Lina", head = "13015", type = 5, title = "Superhero\u{0020}Association\u{0020}Founding\u{0020}Day", txt = "Hello,\u{0020}boy.\nIt's\u{0020}the\u{0020}anniversary\u{0020}of\u{0020}the\u{0020}Superhero\u{0020}Association's\u{0020}founding.\u{0020}So\u{0020}far\u{0020}it\u{0020}only\u{0020}has\u{0020}you\u{0020}and\u{0020}me,\u{0020}but\u{0020}that\u{0020}doesn't\u{0020}stop\u{0020}me\u{0020}from\u{0020}being\u{0020}excited\u{0020}to\u{0020}celebrate.\nYou're\u{0020}probably\u{0020}wondering\u{0020}why\u{0020}my\u{0020}birthday\u{0020}is\u{0020}the\u{0020}Association's\u{0020}anniversary,\u{0020}right?\nHaha,\u{0020}that\u{0020}story\u{0020}would\u{0020}take\u{0020}more\u{0020}than\u{0020}one\u{0020}email.\u{0020}Let's\u{0020}ride\u{0020}our\u{0020}bikes\u{0020}and\u{0020}I'll\u{0020}tell\u{0020}you\u{0020}all\u{0020}about\u{0020}it.\nMake\u{0020}sure\u{0020}your\u{0020}mask\u{0020}is\u{0020}ready,\u{0020}Number\u{0020}Two.\nListen\u{0020}carefully\u{0020}to\u{0020}the\u{0020}sounds\u{0020}around\u{0020}you.\u{0020}If\u{0020}you\u{0020}hear\u{0020}an\u{0020}engine\u{0020}roar,\u{0020}that's\u{0020}me\u{0020}calling\u{0020}you.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113017] = {id = 113017, name = "Tsukumo\u{0020}Tamaki", head = "13017", type = 5, title = "Let's\u{0020}Celebrate\u{0020}My\u{0020}Birthday\u{0020}Again\u{0020}in\u{0020}Secret!", txt = "Darling!\u{0020}Guess\u{0020}what\u{0020}day\u{0020}it\u{0020}is\u{0020}today~\nMm,\u{0020}but\u{0020}by\u{0020}the\u{0020}time\u{0020}you\u{0020}see\u{0020}this\u{0020}email,\u{0020}the\u{0020}answer\u{0020}has\u{0020}probably\u{0020}already\u{0020}been\u{0020}spoiled--today\u{0020}is\u{0020}my\u{0020}birthday.\u{0020}I've\u{0020}been\u{0020}looking\u{0020}forward\u{0020}to\u{0020}today\u{0020}for\u{0020}ages,\u{0020}and\u{0020}of\u{0020}course\u{0020}I've\u{0020}made\u{0020}plenty\u{0020}of\u{0020}preparations!\nI\u{0020}had\u{0020}all\u{0020}sorts\u{0020}of\u{0020}plans...\u{0020}I\u{0020}originally\u{0020}planned\u{0020}to\u{0020}spend\u{0020}a\u{0020}romantic,\u{0020}special\u{0020}day\u{0020}with\u{0020}my\u{0020}darling\u{0020}today,\u{0020}just\u{0020}the\u{0020}two\u{0020}of\u{0020}us...\u{0020}Mm,\u{0020}but\u{0020}even\u{0020}though\u{0020}I\u{0020}didn't\u{0020}tell\u{0020}anyone,\u{0020}I\u{0020}still\u{0020}received\u{0020}gifts\u{0020}from\u{0020}everyone,\u{0020}so\u{0020}I'll\u{0020}have\u{0020}to\u{0020}put\u{0020}Plan\u{0020}B\u{0020}into\u{0020}action.\nI'm\u{0020}going\u{0020}to\u{0020}invite\u{0020}everyone\u{0020}to\u{0020}my\u{0020}birthday\u{0020}party\u{0020}this\u{0020}afternoon.\u{0020}I've\u{0020}already\u{0020}taken\u{0020}a\u{0020}look\u{0020}at\u{0020}the\u{0020}\"future,\"\u{0020}and\u{0020}there\u{0020}won't\u{0020}be\u{0020}any\u{0020}Sin\u{0020}attacks\u{0020}then.\nAnd\u{0020}then,\u{0020}and\u{0020}then,\u{0020}we'll\u{0020}save\u{0020}our\u{0020}date\u{0020}for\u{0020}the\u{0020}evening,\u{0020}so\u{0020}let\u{0020}me\u{0020}sneak\u{0020}in\u{0020}one\u{0020}more\u{0020}birthday\u{0020}celebration\u{0020}with\u{0020}you!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301701] = {id = 11301701, name = "Tsukumo\u{0020}Tamaki", head = "13017", type = 5, title = "Darling!\u{0020}Darling!\u{0020}Darling!", txt = "Darling,\u{0020}do\u{0020}you\u{0020}remember\u{0020}what\u{0020}day\u{0020}it\u{0020}is\u{0020}today?\nHere's\u{0020}a\u{0020}hint...\u{0020}It\u{0020}has\u{0020}something\u{0020}to\u{0020}do\u{0020}with\u{0020}me.\u{0020}It\u{0020}isn't\u{0020}our\u{0020}wedding\u{0020}anniversary,\u{0020}or\u{0020}the\u{0020}anniversary\u{0020}of\u{0020}when\u{0020}we\u{0020}started\u{0020}dating...\u{0020}and\u{0020}it\u{0020}certainly\u{0020}isn't\u{0020}the\u{0020}anniversary\u{0020}of\u{0020}the\u{0020}day\u{0020}we\u{0020}first\u{0020}met...\u{0020}I\u{0020}know\u{0020}my\u{0020}darling\u{0020}will\u{0020}remember!\nThen...\u{0020}shall\u{0020}we\u{0020}meet\u{0020}at\u{0020}the\u{0020}place\u{0020}where\u{0020}we\u{0020}first\u{0020}met?\nOnly\u{0020}by\u{0020}hiding\u{0020}there\u{0020}today\u{0020}can\u{0020}we\u{0020}make\u{0020}sure\u{0020}no\u{0020}one\u{0020}comes\u{0020}to\u{0020}disturb\u{0020}us,\u{0020}and\u{0020}that\u{0020}we\u{0020}don't\u{0020}cause\u{0020}trouble\u{0020}for\u{0020}anyone\u{0020}else\u{0020}either...\nLet's\u{0020}quietly\u{0020}enjoy\u{0020}some\u{0020}time\u{0020}alone,\u{0020}just\u{0020}the\u{0020}two\u{0020}of\u{0020}us~\u{0020}(P.S.\u{0020}I've\u{0020}already\u{0020}checked.\u{0020}There\u{0020}won't\u{0020}be\u{0020}any\u{0020}Sin\u{0020}attacks\u{0020}today,\u{0020}so\u{0020}we\u{0020}can\u{0020}stay\u{0020}as\u{0020}long\u{0020}as\u{0020}we\u{0020}like!)", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113019] = {id = 113019, name = "Zhaowu", head = "13019", type = 5, title = "您會答應嗎？", txt = "過去在“學宮”的時候，生日當天我都會找一個安靜的地方，將所有的事情都暫時放下，享受讀書的樂趣。\n離開“學宮”之後，我偶爾也會懷念那時候的日子。\n但人……總不能一直停留在過去吧？戴罪之人……更應該追求進步，不是嗎？\n而且，生日要是也一整天待在家裡，澄練隊長也會有意見的\n……所以，小女子有一個異想天開的想法……\n就是，今年的生日，我想待在navigator身邊……您會答應嗎？", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301901] = {id = 11301901, name = "Zhaowu", head = "13019", type = 5, title = "Would\u{0020}You\u{0020}Agree?", txt = "Back\u{0020}when\u{0020}I\u{0020}was\u{0020}at\u{0020}the\u{0020}\"Academy,\"\u{0020}I\u{0020}would\u{0020}always\u{0020}seek\u{0020}a\u{0020}quiet\u{0020}place\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}setting\u{0020}everything\u{0020}else\u{0020}aside\u{0020}to\u{0020}enjoy\u{0020}the\u{0020}pleasure\u{0020}of\u{0020}reading.\nEven\u{0020}after\u{0020}leaving\u{0020}the\u{0020}Academy,\u{0020}I\u{0020}still\u{0020}find\u{0020}myself\u{0020}reminiscing\u{0020}about\u{0020}those\u{0020}peaceful\u{0020}days.\nBut,\u{0020}well...\u{0020}we\u{0020}can't\u{0020}linger\u{0020}in\u{0020}the\u{0020}past\u{0020}forever,\u{0020}can\u{0020}we?\u{0020}Those\u{0020}of\u{0020}us\u{0020}who\u{0020}carry\u{0020}burdens...\u{0020}should\u{0020}always\u{0020}strive\u{0020}to\u{0020}move\u{0020}forward,\u{0020}don't\u{0020}you\u{0020}think?\nBesides,\u{0020}if\u{0020}I\u{0020}were\u{0020}to\u{0020}spend\u{0020}the\u{0020}whole\u{0020}day\u{0020}alone\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}Captain\u{0020}Chenglian\u{0020}would\u{0020}certainly\u{0020}have\u{0020}something\u{0020}to\u{0020}say\u{0020}about\u{0020}it.\n...So,\u{0020}I've\u{0020}come\u{0020}up\u{0020}with\u{0020}a\u{0020}rather\u{0020}bold\u{0020}idea...\nThis\u{0020}year,\u{0020}I'd\u{0020}like\u{0020}to\u{0020}spend\u{0020}my\u{0020}birthday\u{0020}by\u{0020}your\u{0020}side,\u{0020}Navigator...\u{0020}Would\u{0020}you\u{0020}be\u{0020}willing\u{0020}to\u{0020}grant\u{0020}me\u{0020}that?\u{0020}", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301902] = {id = 11301902, name = "Zhaowu", head = "13019", type = 5, title = "It's\u{0020}Nice\u{0020}to\u{0020}Fantasize\u{0020}About\u{0020}Celebrating\u{0020}a\u{0020}Birthday", txt = "I\u{0020}know\u{0020}the\u{0020}Navigator\u{0020}must\u{0020}be\u{0020}very\u{0020}busy,\u{0020}and\u{0020}I'm\u{0020}aware\u{0020}that\u{0020}this\u{0020}email\u{0020}will\u{0020}surely\u{0020}disturb\u{0020}you...\u{0020}If\u{0020}it\u{0020}truly\u{0020}does,\u{0020}please\u{0020}pretend\u{0020}you\u{0020}never\u{0020}read\u{0020}this\u{0020}letter.\u{0020}\nIt\u{0020}might\u{0020}be\u{0020}better\u{0020}to\u{0020}go\u{0020}wash\u{0020}your\u{0020}eyes\u{0020}as\u{0020}well,\u{0020}ah...\u{0020}and\u{0020}you\u{0020}must\u{0020}have\u{0020}touched\u{0020}the\u{0020}letter\u{0020}paper\u{0020}when\u{0020}you\u{0020}took\u{0020}the\u{0020}envelope.\u{0020}Even\u{0020}though\u{0020}I\u{0020}disinfected\u{0020}my\u{0020}entire\u{0020}body\u{0020}while\u{0020}writing\u{0020}this\u{0020}and\u{0020}wore\u{0020}a\u{0020}hazmat\u{0020}suit\u{0020}to\u{0020}pen\u{0020}this\u{0020}letter...\u{0020}\nI\u{0020}thought\u{0020}if\u{0020}you\u{0020}touched\u{0020}a\u{0020}letter\u{0020}from\u{0020}a\u{0020}sinner\u{0020}like\u{0020}me,\u{0020}you'd\u{0020}surely\u{0020}be\u{0020}unable\u{0020}to\u{0020}bear\u{0020}it...\u{0020}No,\u{0020}I'd\u{0020}be\u{0020}the\u{0020}one\u{0020}unable\u{0020}to\u{0020}bear\u{0020}it,\u{0020}to\u{0020}have\u{0020}defiled\u{0020}you...\u{0020}a\u{0020}capital\u{0020}offense...\u{0020}\nBut...\u{0020}but...\u{0020}even\u{0020}now,\u{0020}I\u{0020}still\u{0020}fantasize\u{0020}that\u{0020}you\u{0020}might\u{0020}appear\u{0020}to\u{0020}celebrate\u{0020}my\u{0020}birthday\u{0020}with\u{0020}me...\u{0020}I\u{0020}shouldn't\u{0020}even\u{0020}be\u{0020}having\u{0020}these\u{0020}thoughts...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113020] = {id = 113020, name = "Maybelle", head = "13020", type = 5, title = "Let's\u{0020}make\u{0020}a\u{0020}promise.", txt = "I\u{0020}just\u{0020}noticed\u{0020}the\u{0020}birthday\u{0020}gift\u{0020}from\u{0020}Navigator\u{0020}at\u{0020}the\u{0020}office,\u{0020}I\u{0020}really\u{0020}like\u{0020}it,\u{0020}thank\u{0020}you\u{0020}very\u{0020}much.\u{0020}But\u{0020}if\u{0020}you\u{0020}could\u{0020}deliver\u{0020}it\u{0020}to\u{0020}me\u{0020}in\u{0020}person,\u{0020}where\u{0020}we\u{0020}could\u{0020}meet\u{0020}face-to-face,\u{0020}I\u{0020}would\u{0020}be\u{0020}even\u{0020}happier.\nLet's\u{0020}make\u{0020}a\u{0020}deal:\u{0020}I'll\u{0020}prepare\u{0020}the\u{0020}coffee\u{0020}and\u{0020}snacks\u{0020}next\u{0020}year,\u{0020}and\u{0020}Navigator\u{0020}will\u{0020}simply\u{0020}meet\u{0020}me\u{0020}in\u{0020}person.\u{0020}After\u{0020}all,\u{0020}compared\u{0020}to\u{0020}gifts,\u{0020}I'd\u{0020}rather\u{0020}hear\u{0020}you\u{0020}say\u{0020}\"Happy\u{0020}Birthday\"\u{0020}-\u{0020}in\u{0020}person,\u{0020}of\u{0020}course,\u{0020}not\u{0020}just\u{0020}a\u{0020}phone\u{0020}call\u{0020}like\u{0020}this\u{0020}year.\nBy\u{0020}the\u{0020}way,\u{0020}this\u{0020}nightgown\u{0020}you\u{0020}gave\u{0020}me,\u{0020}the\u{0020}texture\u{0020}and\u{0020}craftsmanship\u{0020}is\u{0020}very\u{0020}impressive,\u{0020}after\u{0020}putting\u{0020}it\u{0020}on,\u{0020}it's\u{0020}very…\u{0020}Whoa,\u{0020}nearly\u{0020}fell\u{0020}asleep\u{0020}again.\u{0020}I\u{0020}would\u{0020}like\u{0020}to\u{0020}ask,\u{0020}where\u{0020}did\u{0020}Navigator\u{0020}buy\u{0020}it?\u{0020}Can\u{0020}you\u{0020}share\u{0020}the\u{0020}store\u{0020}name,\u{0020}address,\u{0020}and\u{0020}also\u{0020}contact\u{0020}information?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302001] = {id = 11302001, name = "Maybelle", head = "13020", type = 5, title = "Let’s\u{0020}Make\u{0020}a\u{0020}Deal", txt = "Just\u{0020}saw\u{0020}the\u{0020}birthday\u{0020}gift\u{0020}you\u{0020}left\u{0020}in\u{0020}my\u{0020}office.\u{0020}I\u{0020}love\u{0020}it,\u{0020}thank\u{0020}you.\u{0020}Though\u{0020}I'd\u{0020}have\u{0020}been\u{0020}much\u{0020}happier\u{0020}receiving\u{0020}it\u{0020}directly\u{0020}from\u{0020}your\u{0020}hands.\nHere's\u{0020}my\u{0020}proposal:\u{0020}Next\u{0020}year,\u{0020}I'll\u{0020}handle\u{0020}the\u{0020}coffee\u{0020}and\u{0020}desserts.\u{0020}All\u{0020}you\u{0020}need\u{0020}to\u{0020}do\u{0020}is\u{0020}show\u{0020}up.\u{0020}Because\u{0020}honestly?\u{0020}More\u{0020}than\u{0020}any\u{0020}present,\u{0020}I\u{0020}just\u{0020}want\u{0020}to\u{0020}hear\u{0020}you\u{0020}say\u{0020}\"Happy\u{0020}Birthday\"\u{0020}to\u{0020}my\u{0020}face.\u{0020}No\u{0020}more\u{0020}phone\u{0020}call\u{0020}greetings\u{0020}like\u{0020}this\u{0020}year.\u{0020}That's\u{0020}not\u{0020}gonna\u{0020}happen.\nOh,\u{0020}about\u{0020}this\u{0020}nightgown\u{0020}you\u{0020}chose,\u{0020}the\u{0020}fabric\u{0020}and\u{0020}craftsmanship\u{0020}are\u{0020}exquisite.\u{0020}It's\u{0020}so\u{0020}comfortable\u{0020}I\u{0020}almost...\u{0020}*yawn*...\u{0020}fell\u{0020}asleep\u{0020}again.\u{0020}Where\u{0020}did\u{0020}you\u{0020}get\u{0020}this,\u{0020}anyway?\u{0020}I\u{0020}need\u{0020}the\u{0020}shop\u{0020}name,\u{0020}address,\u{0020}and\u{0020}contact\u{0020}details.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302002] = {id = 11302002, name = "Maybelle", head = "13020", type = 5, title = "When\u{0020}Will\u{0020}You\u{0020}Come\u{0020}for\u{0020}Our\u{0020}Appointment?", txt = "I\u{0020}am\u{0020}preparing\u{0020}fine\u{0020}Sahara\u{0020}coffee\u{0020}and\u{0020}Danube-style\u{0020}desserts.\u{0020}I\u{0020}wonder\u{0020}when\u{0020}Navigator\u{0020}will\u{0020}arrive?\nI\u{0020}do\u{0020}not\u{0020}mean\u{0020}to\u{0020}rush\u{0020}you.\u{0020}It\u{0020}is\u{0020}just\u{0020}that\u{0020}I\u{0020}can\u{0020}easily\u{0020}fall\u{0020}asleep\u{0020}by\u{0020}accident\u{0020}and\u{0020}miss\u{0020}the\u{0020}chance\u{0020}to\u{0020}welcome\u{0020}you,\u{0020}so\u{0020}if\u{0020}that\u{0020}happens,\u{0020}please\u{0020}forgive\u{0020}me.\nThe\u{0020}spare\u{0020}key\u{0020}is\u{0020}still\u{0020}hidden\u{0020}in\u{0020}the\u{0020}usual\u{0020}place.\u{0020}If\u{0020}you\u{0020}knock\u{0020}and\u{0020}there\u{0020}is\u{0020}no\u{0020}answer\u{0020}when\u{0020}you\u{0020}arrive,\u{0020}just\u{0020}come\u{0020}in\u{0020}directly.\u{0020}Then\u{0020}Navigator\u{0020}might\u{0020}find\u{0020}me\u{0020}collapsed\u{0020}on\u{0020}the\u{0020}floor\u{0020}in\u{0020}disheveled\u{0020}clothes?\nThat\u{0020}is\u{0020}how\u{0020}suddenly\u{0020}hypersomnia\u{0020}can\u{0020}strike,\u{0020}so\u{0020}there\u{0020}is\u{0020}nothing\u{0020}I\u{0020}can\u{0020}do\u{0020}about\u{0020}it.\u{0020}I\u{0020}will\u{0020}just\u{0020}have\u{0020}to\u{0020}ask\u{0020}Navigator\u{0020}to\u{0020}help\u{0020}carry\u{0020}me\u{0020}to\u{0020}bed\u{0020}when\u{0020}the\u{0020}time\u{0020}comes.\u{0020}I\u{0020}do\u{0020}not\u{0020}want\u{0020}to\u{0020}spend\u{0020}my\u{0020}birthday\u{0020}sleeping\u{0020}on\u{0020}the\u{0020}floor.\u{0020}Leaning\u{0020}against\u{0020}you\u{0020}would\u{0020}be\u{0020}much\u{0020}more\u{0020}comfortable~", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113013] = {id = 113013, name = "Fleur", head = "13013", type = 5, title = "Love\u{0020}Moon\u{0020}Corona\u{0020}So\u{0020}Much,\u{0020}Meow", txt = "It's\u{0020}Fleur's\u{0020}birthday\u{0020}today,\u{0020}meow!\u{0020}Gia\u{0020}woke\u{0020}Fleur\u{0020}up\u{0020}this\u{0020}morning.\u{0020}She\u{0020}smells\u{0020}so\u{0020}nice,\u{0020}just\u{0020}like\u{0020}Navigator,\u{0020}meow...\nThen\u{0020}Skadi\u{0020}brought\u{0020}this\u{0020}HUUUGE\u{0020}painting\u{0020}of\u{0020}everyone\u{0020}in\u{0020}Moon\u{0020}Corona,\u{0020}with\u{0020}Navigator\u{0020}and\u{0020}Gia\u{0020}too!\u{0020}And\u{0020}the\u{0020}little\u{0020}birthday\u{0020}message\u{0020}in\u{0020}the\u{0020}corner...\u{0020}Fleur\u{0020}knew\u{0020}it\u{0020}was\u{0020}Navigator's\u{0020}writing\u{0020}right\u{0020}away,\u{0020}meow!\u{0020}Hehe\nLilith\u{0020}helped\u{0020}hang\u{0020}it\u{0020}up\u{0020}at\u{0020}the\u{0020}foot\u{0020}of\u{0020}Fleur's\u{0020}bed,\u{0020}so\u{0020}now\u{0020}Fleur\u{0020}wakes\u{0020}up\u{0020}to\u{0020}everyone\u{0020}every\u{0020}morning,\u{0020}meow!\nOh!\u{0020}And\u{0020}while\u{0020}waiting\u{0020}for\u{0020}Navigator\u{0020}in\u{0020}the\u{0020}lounge,\u{0020}Captain\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}did\u{0020}sooo\u{0020}many\u{0020}magic\u{0020}tricks\u{0020}for\u{0020}Fleur,\u{0020}meow!\u{0020}They\u{0020}were\u{0020}amazing!\u{0020}Poor\u{0020}Navigator\u{0020}missed\u{0020}out,\u{0020}meow!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11301301] = {id = 11301301, name = "Fleur", head = "13013", type = 5, title = "Meow", txt = "Navigator,\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}go\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}kittens\u{0020}with\u{0020}Fleur,\u{0020}meow?\nIt\u{0020}is\u{0020}right\u{0020}by\u{0020}the\u{0020}coast\u{0020}of\u{0020}Danube,\u{0020}a\u{0020}place\u{0020}Fleur\u{0020}often\u{0020}goes,\u{0020}meow.\nBecause\u{0020}today\u{0020}is\u{0020}Fleur's\u{0020}birthday,\u{0020}I\u{0020}want\u{0020}to\u{0020}spend\u{0020}noon\u{0020}together\u{0020}with\u{0020}the\u{0020}kitties\u{0020}who\u{0020}have\u{0020}always\u{0020}kept\u{0020}me\u{0020}company,\u{0020}meow.\nThen\u{0020}at\u{0020}night,\u{0020}everyone\u{0020}from\u{0020}Moon\u{0020}Corona\u{0020}helped\u{0020}prepare\u{0020}a\u{0020}birthday\u{0020}party,\u{0020}so\u{0020}now\u{0020}Fleur\u{0020}has\u{0020}to\u{0020}find\u{0020}everyone\u{0020}and\u{0020}bring\u{0020}them\u{0020}over\u{0020}to\u{0020}eat\u{0020}cake\u{0020}together,\u{0020}meow.\nThe\u{0020}cake\u{0020}is\u{0020}delicious,\u{0020}so\u{0020}I\u{0020}hope\u{0020}everyone\u{0020}can\u{0020}have\u{0020}some,\u{0020}meow.\nIf\u{0020}we\u{0020}play\u{0020}too\u{0020}late,\u{0020}Captain\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}said\u{0020}Navigator\u{0020}can\u{0020}stay\u{0020}the\u{0020}night\u{0020}and\u{0020}go\u{0020}back\u{0020}the\u{0020}next\u{0020}day,\u{0020}meow.\nFleur\u{0020}hopes\u{0020}Navigator\u{0020}will\u{0020}stay,\u{0020}meow.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113018] = {id = 113018, name = "Mittoshiva", head = "13018", type = 5, title = "Please\u{0020}Stay\u{0020}Silent", txt = "This\u{0020}morning,\u{0020}I\u{0020}received\u{0020}a\u{0020}mysterious\u{0020}message\u{0020}saying:\u{0020}\"Birthday\u{0020}Special!\u{0020}Amusement\u{0020}park\u{0020}two-person\u{0020}tickets\u{0020}half\u{0020}price!\"\nQuite\u{0020}suspicious,\u{0020}right?\u{0020}I've\u{0020}never\u{0020}told\u{0020}anyone\u{0020}my\u{0020}birthday!\u{0020}Except,\u{0020}of\u{0020}course,\u{0020}when\u{0020}I\u{0020}signed\u{0020}up\u{0020}as\u{0020}a\u{0020}mall\u{0020}member...\nBesides\u{0020}that,\u{0020}there\u{0020}were\u{0020}messages\u{0020}like\u{0020}\"Cinema\u{0020}Birthday\u{0020}Discount,\"\u{0020}\"Free\u{0020}Dessert\u{0020}on\u{0020}Birthday,\"\u{0020}and\u{0020}so\u{0020}on.\u{0020}My\u{0020}instincts\u{0020}tell\u{0020}me\u{0020}that\u{0020}this\u{0020}is\u{0020}likely\u{0020}telecom\u{0020}fraud.\u{0020}This\u{0020}is\u{0020}common\u{0020}in\u{0020}space\u{0020}travel.\u{0020}Sending\u{0020}out\u{0020}fake\u{0020}messages\u{0020}to\u{0020}lure\u{0020}space\u{0020}travelers\u{0020}into\u{0020}unfamiliar\u{0020}star\u{0020}systems,\u{0020}and\u{0020}then...\nI\u{0020}want\u{0020}to\u{0020}investigate\u{0020}this,\u{0020}and\u{0020}I'd\u{0020}like\u{0020}you\u{0020}to\u{0020}join\u{0020}me,\u{0020}Navigator.\u{0020}We\u{0020}need\u{0020}to\u{0020}catch\u{0020}the\u{0020}ones\u{0020}behind\u{0020}this.\u{0020}But\u{0020}to\u{0020}avoid\u{0020}alerting\u{0020}them,\u{0020}it'll\u{0020}just\u{0020}be\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}acting\u{0020}quietly.\u{0020}We'll\u{0020}start\u{0020}with\u{0020}the\u{0020}amusement\u{0020}park,\u{0020}then\u{0020}the\u{0020}cinema,\u{0020}and\u{0020}finally,\u{0020}that\u{0020}restaurant.\u{0020}Free\u{0020}dessert?\u{0020}Come\u{0020}on!\u{0020}That's\u{0020}way\u{0020}too\u{0020}fishy.\nKeep\u{0020}a\u{0020}low\u{0020}profile\u{0020}and\u{0020}don't\u{0020}tell\u{0020}anyone\u{0020}else.\u{0020}Just\u{0020}the\u{0020}two\u{0020}of\u{0020}us,\u{0020}quietly...\u{0020}quietly...", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113021] = {id = 113021, name = "Hoshii\u{0020}Bernardini", head = "13021", type = 5, title = "Tell\u{0020}Me\u{0020}Your\u{0020}Wish", txt = "Hey,\u{0020}Navigator!\u{0020}It's\u{0020}Hoshii.\nCan\u{0020}you\u{0020}guess\u{0020}what\u{0020}today\u{0020}is?\u{0020}I'm\u{0020}sure\u{0020}you\u{0020}won't\u{0020}be\u{0020}able\u{0020}to.\nToday's\u{0020}my\u{0020}birthday!\u{0020}\nBut\u{0020}I\u{0020}know\u{0020}you\u{0020}probably\u{0020}won't\u{0020}make\u{0020}it\u{0020}to\u{0020}my\u{0020}birthday\u{0020}party…\u{0020}You're\u{0020}so\u{0020}busy\u{0020}and\u{0020}so\u{0020}far\u{0020}away.\nBy\u{0020}the\u{0020}way,\u{0020}is\u{0020}there\u{0020}anything\u{0020}you've\u{0020}been\u{0020}curious\u{0020}about?\u{0020}Every\u{0020}year\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}my\u{0020}divination\u{0020}powers\u{0020}are\u{0020}at\u{0020}their\u{0020}peak.\u{0020}Whatever\u{0020}I\u{0020}predict\u{0020}today\u{0020}will\u{0020}come\u{0020}true—100%!\u{0020}But\u{0020}there's\u{0020}only\u{0020}one\u{0020}chance.\u{0020}Normally,\u{0020}I'd\u{0020}use\u{0020}this\u{0020}for\u{0020}my\u{0020}family,\u{0020}but\u{0020}this\u{0020}year,\u{0020}I\u{0020}want\u{0020}to\u{0020}offer\u{0020}it\u{0020}to\u{0020}you,\u{0020}Navigator.\nDon't\u{0020}be\u{0020}shy!\u{0020}Tell\u{0020}me\u{0020}your\u{0020}wish.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302101] = {id = 11302101, name = "Hoshii\u{0020}Bernardini", head = "13021", type = 5, title = "Tell\u{0020}Me\u{0020}Your\u{0020}Wish", txt = "Hey,\u{0020}Navigator!\u{0020}It's\u{0020}Hoshii.\nCan\u{0020}you\u{0020}guess\u{0020}what\u{0020}today\u{0020}is?\u{0020}I'm\u{0020}sure\u{0020}you\u{0020}won't\u{0020}be\u{0020}able\u{0020}to.\nToday's\u{0020}my\u{0020}birthday!\u{0020}\nBut\u{0020}I\u{0020}know\u{0020}you\u{0020}probably\u{0020}won't\u{0020}make\u{0020}it\u{0020}to\u{0020}my\u{0020}birthday\u{0020}party…\u{0020}You're\u{0020}so\u{0020}busy\u{0020}and\u{0020}so\u{0020}far\u{0020}away.\nBy\u{0020}the\u{0020}way,\u{0020}is\u{0020}there\u{0020}anything\u{0020}you've\u{0020}been\u{0020}curious\u{0020}about?\u{0020}Every\u{0020}year\u{0020}on\u{0020}my\u{0020}birthday,\u{0020}my\u{0020}divination\u{0020}powers\u{0020}are\u{0020}at\u{0020}their\u{0020}peak.\u{0020}Whatever\u{0020}I\u{0020}predict\u{0020}today\u{0020}will\u{0020}come\u{0020}true—100%!\u{0020}But\u{0020}there's\u{0020}only\u{0020}one\u{0020}chance.\u{0020}Normally,\u{0020}I'd\u{0020}use\u{0020}this\u{0020}for\u{0020}my\u{0020}family,\u{0020}but\u{0020}this\u{0020}year,\u{0020}I\u{0020}want\u{0020}to\u{0020}offer\u{0020}it\u{0020}to\u{0020}you,\u{0020}Navigator.\nDon't\u{0020}be\u{0020}shy!\u{0020}Tell\u{0020}me\u{0020}your\u{0020}wish.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11302102] = {id = 11302102, name = "Hoshii\u{0020}Bernardini", head = "13021", type = 5, title = "My\u{0020}Wish\u{0020}Is\u{0020}to\u{0020}Have\u{0020}No\u{0020}Cavities", txt = "Dear\u{0020}Navigator,\u{0020}this\u{0020}is\u{0020}Hoshii.\u{0020}I'm\u{0020}writing\u{0020}to\u{0020}ask\u{0020}how\u{0020}you've\u{0020}been\u{0020}lately.\u{0020}\nHoshii\u{0020}hasn't\u{0020}been\u{0020}doing\u{0020}well\u{0020}at\u{0020}all\u{0020}recently.\u{0020}Hoshii\u{0020}has\u{0020}cavities—three\u{0020}of\u{0020}them.\u{0020}One\u{0020}is\u{0020}a\u{0020}sharp\u{0020}one\u{0020}on\u{0020}the\u{0020}upper\u{0020}jaw,\u{0020}and\u{0020}the\u{0020}other\u{0020}two\u{0020}are\u{0020}on\u{0020}the\u{0020}lower\u{0020}jaw,\u{0020}closer\u{0020}to\u{0020}the\u{0020}inside\u{0020}of\u{0020}the\u{0020}mouth.\u{0020}\nAlthough\u{0020}the\u{0020}damaged\u{0020}teeth\u{0020}have\u{0020}been\u{0020}pulled\u{0020}out\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}Kokorokami-nesan,\u{0020}today\u{0020}I\u{0020}can't\u{0020}eat\u{0020}birthday\u{0020}cake\u{0020}or\u{0020}ramen!\u{0020}\nActually,\u{0020}there\u{0020}were\u{0020}signs\u{0020}of\u{0020}these\u{0020}cavities\u{0020}beforehand.\u{0020}A\u{0020}few\u{0020}days\u{0020}ago,\u{0020}I\u{0020}used\u{0020}a\u{0020}crystal\u{0020}ball\u{0020}for\u{0020}a\u{0020}divination.\u{0020}In\u{0020}the\u{0020}divination,\u{0020}I\u{0020}saw\u{0020}deep\u{0020}within\u{0020}the\u{0020}clouds\u{0020}of\u{0020}a\u{0020}pink\u{0020}sky,\u{0020}a\u{0020}vortex\u{0020}kneading\u{0020}a\u{0020}huge\u{0020}dough.\u{0020}The\u{0020}ground\u{0020}was\u{0020}painted\u{0020}into\u{0020}an\u{0020}ocean\u{0020}by\u{0020}cream\u{0020}rain,\u{0020}colorful\u{0020}and\u{0020}strange\u{0020}candlefish\u{0020}flew\u{0020}in\u{0020}the\u{0020}flames,\u{0020}then\u{0020}melted\u{0020}into\u{0020}a\u{0020}ship,\u{0020}heading\u{0020}straight\u{0020}toward\u{0020}a\u{0020}distant\u{0020}white\u{0020}glacier...\u{0020}\nFor\u{0020}this\u{0020}year's\u{0020}birthday\u{0020}wish,\u{0020}please\u{0020}let\u{0020}Hoshii\u{0020}never\u{0020}have\u{0020}cavities\u{0020}again!", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[113022] = {id = 113022, name = "Monica", head = "13022", type = 5, title = "Law-Enforcement\u{0020}Plans", txt = "We\u{0020}have\u{0020}not\u{0020}known\u{0020}each\u{0020}other\u{0020}for\u{0020}very\u{0020}long.\u{0020}Still,\u{0020}as\u{0020}a\u{0020}competent\u{0020}superior,\u{0020}you\u{0020}should\u{0020}not\u{0020}need\u{0020}me\u{0020}to\u{0020}go\u{0020}out\u{0020}of\u{0020}my\u{0020}way\u{0020}to\u{0020}remind\u{0020}you\u{0020}of\u{0020}your\u{0020}subordinate's\u{0020}birthday,\u{0020}should\u{0020}you?\nThis\u{0020}is\u{0020}a\u{0020}rare\u{0020}opportunity,\u{0020}so\u{0020}I\u{0020}plan\u{0020}to\u{0020}take\u{0020}the\u{0020}chance\u{0020}to\u{0020}return\u{0020}to\u{0020}the\u{0020}city\u{0020}where\u{0020}I\u{0020}used\u{0020}to\u{0020}work.\nOf\u{0020}course,\u{0020}it\u{0020}is\u{0020}not\u{0020}merely\u{0020}for\u{0020}a\u{0020}vacation\u{0020}or\u{0020}to\u{0020}visit\u{0020}my\u{0020}former\u{0020}colleagues.\u{0020}That\u{0020}city\u{0020}had\u{0020}always\u{0020}been\u{0020}exceptionally\u{0020}naive,\u{0020}resting\u{0020}on\u{0020}the\u{0020}laurels\u{0020}of\u{0020}its\u{0020}good\u{0020}public-safety\u{0020}statistics.\u{0020}Now\u{0020}that\u{0020}Cheston\u{0020}has\u{0020}been\u{0020}hit\u{0020}by\u{0020}another\u{0020}major\u{0020}incident,\u{0020}who\u{0020}knows\u{0020}what\u{0020}the\u{0020}place\u{0020}has\u{0020}become?\nI\u{0020}am\u{0020}going\u{0020}back\u{0020}to\u{0020}do\u{0020}some\u{0020}pest\u{0020}control\u{0020}for\u{0020}them.\u{0020}Downtown,\u{0020}Gamlo\u{0020}Shopping\u{0020}Street,\u{0020}and\u{0020}the\u{0020}alleys\u{0020}around\u{0020}the\u{0020}city\u{0020}square\u{0020}-\u{0020}not\u{0020}one\u{0020}of\u{0020}the\u{0020}criminals\u{0020}who\u{0020}slipped\u{0020}in\u{0020}amid\u{0020}the\u{0020}chaos\u{0020}is\u{0020}getting\u{0020}away.\nNaturally,\u{0020}you\u{0020}are\u{0020}coming\u{0020}too.\nThe\u{0020}most\u{0020}stubborn\u{0020}scum\u{0020}among\u{0020}them\u{0020}have\u{0020}probably\u{0020}memorized\u{0020}my\u{0020}face\u{0020}by\u{0020}now,\u{0020}so\u{0020}I\u{0020}need\u{0020}you\u{0020}to\u{0020}provide\u{0020}cover.\nThis\u{0020}is\u{0020}your\u{0020}capable\u{0020}subordinate's\u{0020}birthday\u{0020}wish.\u{0020}You\u{0020}would\u{0020}not\u{0020}refuse,\u{0020}would\u{0020}you?", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
[11400101] = {id = 11400101, name = "Kosgaard", head = "14001", type = 5, title = "Morning\u{0020}in\u{0020}Poynred,\u{0020}Night\u{0020}on\u{0020}the\u{0020}Danube\u{0020}Ark", txt = "Greetings,\u{0020}Navigator.\u{0020}I\u{0020}hope\u{0020}you\u{0020}are\u{0020}opening\u{0020}this\u{0020}letter\u{0020}on\u{0020}a\u{0020}bright\u{0020}and\u{0020}gentle\u{0020}morning,\u{0020}in\u{0020}a\u{0020}clear\u{0020}and\u{0020}pleasant\u{0020}mood.\u{0020}If\u{0020}so,\u{0020}that\u{0020}alone\u{0020}would\u{0020}be\u{0020}the\u{0020}greatest\u{0020}comfort\u{0020}to\u{0020}me,\u{0020}here\u{0020}in\u{0020}Poynred.\u{0020}\nAt\u{0020}this\u{0020}moment,\u{0020}I\u{0020}am\u{0020}in\u{0020}Poynred\u{0020}celebrating\u{0020}my\u{0020}birthday\u{0020}with\u{0020}my\u{0020}family,\u{0020}perhaps\u{0020}dining\u{0020}at\u{0020}a\u{0020}family\u{0020}banquet,\u{0020}or\u{0020}maybe\u{0020}strolling\u{0020}through\u{0020}the\u{0020}garden.\u{0020}When\u{0020}night\u{0020}falls,\u{0020}I\u{0020}may\u{0020}already\u{0020}have\u{0020}returned\u{0020}to\u{0020}the\u{0020}Danube\u{0020}Ark...\u{0020}\nYou\u{0020}might\u{0020}scold\u{0020}me\u{0020}for\u{0020}being\u{0020}greedy.\u{0020}For\u{0020}a\u{0020}knight,\u{0020}this\u{0020}is\u{0020}indeed\u{0020}something\u{0020}shameful\u{0020}to\u{0020}admit.\u{0020}But\u{0020}I\u{0020}still\u{0020}hope\u{0020}that,\u{0020}when\u{0020}the\u{0020}time\u{0020}comes,\u{0020}you\u{0020}will\u{0020}spend\u{0020}the\u{0020}night\u{0020}with\u{0020}me...\u{0020}A\u{0020}birthday\u{0020}without\u{0020}you\u{0020}would\u{0020}be\u{0020}incomplete.", goods = "1_100000_100,1_110121_1", effective = -1, "0", "0", "0", "0", "0"},
