[90000000] = {id = 90000000, name = "Charlissa", head = "11000", type = 3, title = "You actually found it.", txt = "I didn't expect you to be quite smart. You can even solve such a complicated password. You're almost as smart as me.\nWell, let me give you some rewards.", goods = "1_100000_200,1_110091_20,1_100001_8888", effective = 720, "0", "0", "0", "0", "0"},
[700001] = {id = 700001, name = "Gia", head = "90000", type = 3, title = "Welcome to Haze Reverb! Claim Your Newcomer Rewards!", txt = "Dear Navigator,\nWelcome to Haze Reverb!\nTo celebrate your arrival, we’ve prepared a special Newcomer Reward Pack just for you.\nClaim your gifts and kickstart your journey!\nThank you for joining us—your adventure begins today.\n—AEGIS Logistics Division", goods = "1_110031_10,1_100001_150000,1_110050_100,1_110051_50", effective = 720, "0", "0", "0", "0", "0"},
[700002] = {id = 700002, name = "Gia", head = "90000", type = 3, title = "Welcome Back! Special Rewards Await You!", txt = "Dear Navigator,\nWe’ve missed you in Haze Reverb! As a warm welcome back, we’ve prepared Exclusive Return Rewards to help you dive right back into the action.\nClaim your gifts and continue your adventure with us.\nThank you for coming back—we’re glad to have you again!\n—AEGIS Logistics Division", goods = "1_110001_10,1_110031_20,1_110051_50", effective = 720, "0", "0", "0", "0", "0"},
[700003] = {id = 700003, name = "Gia", head = "90000", type = 3, title = "Thank You for Playing—Exclusive Rewards for Loyal Navigators!", txt = "Dear Navigator,\nYour continued support means the world to us.\nTo show our gratitude, we’ve prepared a set of Loyalty Rewards for you.\nClaim your gifts and enjoy the journey you’ve helped shape.\nThank you for being part of Haze Reverb—your dedication inspires us every day.\n—AEGIS Logistics Division", goods = "1_110031_10,1_110030_10,1_100001_50000,1_110020_100", effective = 720, "0", "0", "0", "0", "0"},
